INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jkrumm/hetzner-vps/cloudflare', 'community', 'jkrumm', 'hetzner-vps', 'jkrumm/hetzner-vps', 'cloudflare', 0, 0, 39, '2026-03-01T21:35:05Z', '2026-03-07T03:54:24.112Z', '6f4832608fac2e0d6a98af788efe7dbfa5e6e3e257e2476dec2e16ea6735fae6', '{"id":"jkrumm/hetzner-vps/cloudflare","name":"cloudflare","description":{"en":"The Cloudflare skill handles DNS and tunnel operations for VPS-hosted apps, benefiting developers and DevOps teams. It utilizes Doppler and SSH for secure API calls.","zh":"Cloudflare API Skill用于处理VPS主机应用程序的DNS和隧道操作，支持Traefik、Postgres和Valkey","ja":"Cloudflare API Skillは、VPSホストアプリケーションのDNSとトンネル操作を処理します。Traefik、Postgres、Valkeyをサポートしています","ko":"Cloudflare API Skill은 VPS 호스트 애플리케이션의 DNS 및 터널 운영을 처리하며 Traefik, Postgres 및 Valkey를 지원합니다","es":"Cloudflare es una herramienta para gestionar DNS y túneles para aplicaciones alojadas en VPS. Se integra con Docker Compose y Hetzner VPS","fr":"Cloudflare est un outil pour gérer les DNS et les tunnels pour les applications hébergées sur VPS. Il s''intègre avec Docker Compose et Hetzner VPS","de":"Cloudflare ist ein Tool zur Verwaltung von DNS und Tunneln für auf VPS gehostete Anwendungen. Es integriert sich mit Docker Compose und Hetzner VPS","pt":"O Cloudflare é uma ferramenta para gerenciar operações de DNS e túneis para aplicações hospedadas em VPS","ru":"Cloudflare - это инструмент для управления операциями DNS и туннелей для приложений, размещенных на VPS","ar":"كلاودفلير هو أداة لإدارة عمليات DNS والأنفاق لتطبيقات الخوادم الافتراضية"},"seo":{"title":{"en":"Cloudflare: Setup Guide for AI Agents | AI Agent Skill","zh":"Cloudflare Setup Guide: VPS隧道和DNS操作","ja":"Cloudflare設定ガイド: VPSトンネルとDNS操作","ko":"Cloudflare 설정 가이드: VPS 터널 및 DNS 운영","es":"Guía de configuración de Cloudflare para VPS","fr":"Guide de configuration de Cloudflare pour VPS","de":"Cloudflare-Setup-Anleitung für VPS","pt":"Guia de Configuração Cloudflare para VPS com Tunnel e DNS","ru":"Настройка Cloudflare для VPS с помощью ИИ Агентов","ar":"دليل إعداد كلاودفلير للخادم الافتراضي مع نفق و DNS"},"description":{"en":"Unlock Cloudflare''s potential with our AI agent skill, streamlining DNS and tunnel operations for VPS-hosted apps - get started now!","zh":"了解如何使用Cloudflare API Skill进行VPS隧道和DNS操作，包括Traefik、Postgres和Valkey的配置","ja":"Cloudflare API Skillを使用してVPSトンネルとDNS操作を実行する方法について説明します。Traefik、Postgres、Valkeyの設定も含みます","ko":"Cloudflare API Skill을 사용하여 VPS 터널 및 DNS 운영을 수행하는 방법에 대해 알아보세요. Traefik, Postgres 및 Valkey 구성 포함","es":"Aprende a configurar Cloudflare con Docker Compose y Hetzner VPS para una seguridad y rendimiento óptimos","fr":"Découvrez comment configurer Cloudflare avec Docker Compose et Hetzner VPS pour une sécurité et des performances optimales","de":"Erfahren Sie, wie Sie Cloudflare mit Docker Compose und Hetzner VPS für optimale Sicherheit und Leistung konfigurieren","pt":"Aprenda a configurar o Cloudflare para seu VPS com tunnel e DNS, utilizando a API e o Doppler para gerenciar operações","ru":"Узнайте, как настроить Cloudflare для вашего VPS с помощью туннеля и DNS, используя API и Doppler","ar":"تعرف على كيفية إعداد كلاودفلير لخادمك الافتراضي مع نفق و DNS، باستخدام واجهة برمجة التطبيقات ودوبلر"},"definition":{"en":"Cloudflare is a skill for managing Cloudflare DNS and tunnel operations via API calls on a VPS, using Doppler for secure token storage.","zh":"Cloudflare API Skill是一种用于处理VPS主机应用程序的DNS和隧道操作的AI工具","ja":"Cloudflare API Skillは、VPSホストアプリケーションのDNSとトンネル操作を処理するAIエージェントです","ko":"Cloudflare API Skill은 VPS 호스트 애플리케이션의 DNS 및 터널 운영을 처리하는 AI 도구입니다","es":"Cloudflare es un agente de AI que gestiona operaciones de DNS y túneles para aplicaciones en la nube","fr":"Cloudflare est un agent d''IA qui gère les opérations de DNS et de tunnels pour les applications dans le cloud","de":"Cloudflare ist ein KI-Agent, der DNS- und Tunneloperationen für Cloud-Anwendungen verwaltet","pt":"Cloudflare é uma plataforma que fornece serviços de segurança e desempenho para aplicações web","ru":"Cloudflare - это платформа, предоставляющая услуги безопасности и производительности для веб-приложений","ar":"كلاودفلير هي منصة توفر خدمات أمان واداء لتطبيقات الويب"},"features":{"en":["Executes Cloudflare API calls via SSH on a VPS using `doppler run`","Stores Cloudflare API token securely in Doppler as `CF_API_TOKEN`","Utilizes a single Cloudflare Tunnel with ID stored in Doppler as `CF_TUNNEL_ID`","Supports Postgres, Valkey, and OTel for comprehensive infrastructure management","Employs Traefik for reverse proxy and RollHook for automation"],"zh":["支持Traefik、Postgres和Valkey","使用Doppler进行配置管理","支持VPS隧道和DNS操作","使用SSH进行VPS连接","支持Cloudflare Tunnel和API Token"],"ja":["Traefik、Postgres、Valkeyをサポート","Dopplerを使用した設定管理","VPSトンネルとDNS操作をサポート","SSHを使用したVPS接続","Cloudflare TunnelとAPI Tokenをサポート"],"ko":["Traefik, Postgres 및 Valkey 지원","Doppler를 사용한 구성 관리","VPS 터널 및 DNS 운영 지원","SSH를 사용한 VPS 연결","Cloudflare Tunnel 및 API Token 지원"],"es":["Integración con Docker Compose","Soporte para Hetzner VPS","Gestión de túneles con Cloudflare Tunnel","Almacenamiento seguro de tokens de API con Doppler","Ejecución de comandos bash de forma segura"],"fr":["Intégration avec Docker Compose","Prise en charge de Hetzner VPS","Gestion des tunnels avec Cloudflare Tunnel","Stockage sécurisé des jetons d''API avec Doppler","Exécution de commandes bash de manière sécurisée"],"de":["Integration mit Docker Compose","Unterstützung für Hetzner VPS","Verwaltung von Tunneln mit Cloudflare Tunnel","Sichere Speicherung von API-Tokens mit Doppler","Ausführung von Bash-Befehlen auf sichere Weise"],"pt":["Integração com a API do Cloudflare para gerenciar operações de DNS e túneis","Utilização do Doppler para armazenar tokens de API e configurar o túnel","Suporte a VPS com túneis e DNS","Execução de comandos via SSH","Gerenciamento de operações de túneis e DNS com o Cloudflare"],"ru":["Интеграция с API Cloudflare для управления операциями DNS и туннелей","Использование Doppler для хранения токенов API и настройки туннеля","Поддержка VPS с туннелями и DNS","Выполнение команд через SSH","Управление операциями туннелей и DNS с помощью Cloudflare"],"ar":["التكامل مع واجهة برمجة التطبيقات كلاودفلير لإدارة عمليات DNS والأنفاق","استخدام دوبلر لتخزين رموز واجهة برمجة التطبيقات وتكوين النفق","دعم الخوادم الافتراضية مع الأنفاق و DNS","تنفيذ أوامر عبر SSH","إدارة عمليات الأنفاق و DNS مع كلاودفلير"]},"keywords":{"en":["how to use cloudflare","cloudflare setup guide","cloudflare vs AWS","cloudflare tunnel setup","cloudflare api token management","cloudflare dns management"],"zh":["Cloudflare API Skill","VPS隧道","DNS操作","Traefik","Postgres","Valkey","Doppler","SSH","Cloudflare Tunnel","API Token"],"ja":["Cloudflare API Skill","VPSトンネル","DNS操作","Traefik","Postgres","Valkey","Doppler","SSH","Cloudflare Tunnel","API Token"],"ko":["Cloudflare API Skill","VPS 터널","DNS 운영","Traefik","Postgres","Valkey","Doppler","SSH","Cloudflare Tunnel","API Token"],"es":["Cloudflare","Docker Compose","Hetzner VPS","Túneles de red","Seguridad de API","Doppler","Agentes de AI para VPS","Herramientas de DevOps","Seguridad en la nube"],"fr":["Cloudflare","Docker Compose","Hetzner VPS","Tunnels réseau","Sécurité de l''API","Doppler","Agents d''IA pour VPS","Outils de DevOps","Sécurité dans le cloud"],"de":["Cloudflare","Docker Compose","Hetzner VPS","Netztunnel","API-Sicherheit","Doppler","KI-Agenten für VPS","DevOps-Tools","Sicherheit in der Cloud"],"pt":["cloudflare","vps","tunnel","dns","doppler","api","ssh","segurança","desempenho"],"ru":["cloudflare","vps","туннель","dns","doppler","api","ssh","безопасность","производительность"],"ar":["كلاودفلير","خادم افتراضي","نفق","dns","دوبلر","واجهة برمجة التطبيقات","ssh","أمان","اداء"]}},"owner":"jkrumm","repo":"hetzner-vps","repoPath":"jkrumm/hetzner-vps","stars":0,"forks":0,"updatedAt":"2026-03-01T21:35:05Z","topics":[],"category":"community","skillMd":{"name":"cloudflare","description":"Cloudflare API operations for the VPS — DNS records, tunnel ingress config, multi-domain and multi-zone support. Never exposes the API token to Claude Code directly.","bodyPreview":"# Cloudflare API Skill\n\nHandle any Cloudflare DNS or tunnel operation for VPS-hosted apps.\n\n**Execution model:** All API calls run on the VPS via `ssh vps ''doppler run --project vps --config prod -- bash -c ''\"''\"''...''\"''\"''''`. The API token (`CF_API_TOKEN`) stays in Doppler — never passed as a CLI argument, never visible to Claude Code, never logged.\n\n---\n\n## Infrastructure Context\n\n### VPS Tunnel\n\nThe VPS has a single Cloudflare Tunnel. Its ID is stored in Doppler as `CF_TUNNEL_ID`.\n\n**Current tun","body":"# Cloudflare API Skill\n\nHandle any Cloudflare DNS or tunnel operation for VPS-hosted apps.\n\n**Execution model:** All API calls run on the VPS via `ssh vps ''doppler run --project vps --config prod -- bash -c ''\"''\"''...''\"''\"''''`. The API token (`CF_API_TOKEN`) stays in Doppler — never passed as a CLI argument, never visible to Claude Code, never logged.\n\n---\n\n## Infrastructure Context\n\n### VPS Tunnel\n\nThe VPS has a single Cloudflare Tunnel. Its ID is stored in Doppler as `CF_TUNNEL_ID`.\n\n**Current tunnel IDs visible in jkrumm.com DNS:**\n- `13f91961-...` — VPS (this server)\n- `f270cecf-...` — HomeLab\n- `b99c010f-...` — other server\n\n**Wildcard ingress rule:** `*.DOMAIN → https://traefik:443` (TLS verify: off)\n- Set once after provisioning\n- Catches all subdomains that have a CNAME DNS record pointing to this tunnel\n- Does NOT affect other Cloudflare tunnels — each tunnel evaluates its own ingress rules independently\n\n**To reach a new app publicly:**\n1. Add a DNS CNAME record pointing the subdomain to `${CF_TUNNEL_ID}.cfargotunnel.com`\n2. The wildcard ingress rule already routes it to Traefik\n3. Traefik routes based on the `Host()` label on the container\n\n### Doppler Secrets (project: vps, config: prod)\n\n| Secret | What it is |\n|-|-|\n| `CF_API_TOKEN` | API token — Zone:Read + DNS:Edit (all zones) + Tunnel:Edit (all accounts). Passed to Traefik as `CF_DNS_API_TOKEN` (lego requires that name) |\n| `CF_ACCOUNT_ID` | Cloudflare account ID (same for all zones/tunnels) |\n| `CF_ZONE_ID` | Zone ID for `DOMAIN` (jkrumm.com) |\n| `CF_TUNNEL_ID` | UUID of the VPS Cloudflare Tunnel |\n| `DOMAIN` | Primary domain |\n\n### Multi-Domain / Multi-Zone Support\n\nDomains accessible with this token: `basalt-ui.com`, `jkrumm.com`, `rollhook.com`, `shutterflow.app`. For any domain not stored as `CF_ZONE_ID`, look up its zone ID first (see below).\n\n---\n\n## Authentication Pattern\n\nUse single-quote wrapping so `${VARS}` are expanded by the VPS shell after doppler injects them:\n\n```bash\nssh vps ''doppler run --project vps --config prod -- bash -c ''\"''\"''\n  curl -s \"https://api.cloudflare.com/client/v4/zones\" \\\n    -H \"Authorization: Bearer ${CF_API_TOKEN}\" \\\n    | python3 -m json.tool\n''\"''\"''''\n```\n\n**Why:** Double-quote SSH commands cause the local shell to expand `${CF_API_TOKEN}` before it reaches the VPS (producing empty string and an auth error). The `''...'' ''\"''\"'' ''...''` pattern passes the inner string literally to the VPS where doppler has already injected the secrets.\n\n---\n\n## Common Operations\n\n### List all zones\n\n```bash\nssh vps ''doppler run --project vps --config prod -- bash -c ''\"''\"''curl -s \"https://api.cloudflare.com/client/v4/zones\" -H \"Authorization: Bearer ${CF_API_TOKEN}\" | python3 -c \"import json,sys; r=json.load(sys.stdin); [print(z[\\\"name\\\"],z[\\\"id\\\"]) for z in r[\\\"result\\\"]] if r[\\\"success\\\"] else print(\\\"ERR:\\\",r[\\\"errors\\\"])\"''\"''\"''''\n```\n\n### Check current tunnel ingress config\n\n```bash\nssh vps ''doppler run --project vps --config prod -- bash -c ''\"''\"''curl -s \"https://api.cloudflare.com/client/v4/accounts/${CF_ACCOUNT_ID}/cfd_tunnel/${CF_TUNNEL_ID}/configurations\" -H \"Authorization: Bearer ${CF_API_TOKEN}\" | python3 -c \"import json,sys; r=json.load(sys.stdin); [print(i.get(\\\"hostname\\\",\\\"catch-all\\\"),\\\"→\\\",i[\\\"service\\\"]) for i in r[\\\"result\\\"][\\\"config\\\"][\\\"ingress\\\"]] if r[\\\"success\\\"] else print(\\\"ERR:\\\",r[\\\"errors\\\"])\"''\"''\"''''\n```\n\n### List DNS records for a zone\n\n```bash\nssh vps ''doppler run --project vps --config prod -- bash -c ''\"''\"''curl -s \"https://api.cloudflare.com/client/v4/zones/${CF_ZONE_ID}/dns_records?per_page=100\" -H \"Authorization: Bearer ${CF_API_TOKEN}\" | python3 -c \"import json,sys; r=json.load(sys.stdin); [print(rec[\\\"type\\\"],rec[\\\"name\\\"],\\\"→\\\",rec[\\\"content\\\"]) for rec in r[\\\"result\\\"]] if r[\\\"success\\\"] else print(\\\"ERR:\\\",r[\\\"errors\\\"])\"''\"''\"''''\n```\n\n### Add a DNS CNAME record (new app subdomain on primary domain)\n\n```bash\nssh vps ''doppler run --project vps --config prod -- bash -c ''\"''\"''curl -s -X POST \"https://api.cloudflare.com/client/v4/zones/${CF_ZONE_ID}/dns_records\" -H \"Authorization: Bearer ${CF_API_TOKEN}\" -H \"Content-Type: application/json\" --data \"{\\\"type\\\":\\\"CNAME\\\",\\\"name\\\":\\\"SUBDOMAIN\\\",\\\"content\\\":\\\"${CF_TUNNEL_ID}.cfargotunnel.com\\\",\\\"proxied\\\":true}\" | python3 -c \"import json,sys; r=json.load(sys.stdin); print(\\\"OK:\\\",r[\\\"result\\\"][\\\"name\\\"]) if r[\\\"success\\\"] else print(\\\"ERR:\\\",r[\\\"errors\\\"])\"''\"''\"''''\n```\n\nReplace `SUBDOMAIN` with the actual subdomain before running.\n\n### Delete a DNS record\n\nFirst list records to find the ID, then:\n\n```bash\nssh vps ''doppler run --project vps --config prod -- bash -c ''\"''\"''curl -s -X DELETE \"https://api.cloudflare.com/client/v4/zones/${CF_ZONE_ID}/dns_records/RECORD_ID\" -H \"Authorization: Bearer ${CF_API_TOKEN}\" | python3 -c \"import json,sys; r=json.load(sys.stdin); print(\\\"OK\\\" if r[\\\"success\\\"] else r[\\\"errors\\\"])\"''\"''\"''''\n```\n\n### Look up Zone ID for a secondary domain\n\n```bash\nssh vps ''doppler run --project vps --config prod -- bash -c ''\"''\"''curl -s \"https://api.cloudflare.com/client/v4/zones?name=other-domain.com\" -H \"Authorization: Bearer ${CF_API_TOKEN}\" | python3 -c \"import json,sys; r=json.load(sys.stdin)[\\\"result\\\"]; print(r[0][\\\"id\\\"],r[0][\\\"name\\\"]) if r else print(\\\"not found\\\")\"''\"''\"''''\n```\n\n### Set/update wildcard tunnel ingress rule\n\n```bash\nssh vps ''doppler run --project vps --config prod -- bash -c ''\"''\"''curl -s -X PUT \"https://api.cloudflare.com/client/v4/accounts/${CF_ACCOUNT_ID}/cfd_tunnel/${CF_TUNNEL_ID}/configurations\" -H \"Authorization: Bearer ${CF_API_TOKEN}\" -H \"Content-Type: application/json\" --data \"{\\\"config\\\":{\\\"ingress\\\":[{\\\"hostname\\\":\\\"*.${DOMAIN}\\\",\\\"service\\\":\\\"https://traefik:443\\\",\\\"originRequest\\\":{\\\"noTLSVerify\\\":true}},{\\\"service\\\":\\\"http_status:404\\\"}]}}\" | python3 -c \"import json,sys; r=json.load(sys.stdin); print(\\\"OK — version\\\",r[\\\"result\\\"][\\\"version\\\"]) if r[\\\"success\\\"] else print(\\\"ERR:\\\",r[\\\"errors\\\"])\"''\"''\"''''\n```\n\n---\n\n## Workflow: Add a New Public App\n\n1. Deploy the app compose to VPS (confirm running: `make ps`)\n2. Add DNS CNAME record (subdomain → VPS tunnel)\n3. Verify: `curl -I https://myapp.<DOMAIN>/health`\n4. No tunnel config changes needed — wildcard ingress already catches it\n\n## Workflow: Add App on a Secondary Domain\n\n1. Look up the zone ID for the secondary domain\n2. Use it directly in the curl call — zone IDs are not secret (visible in the Cloudflare dashboard)\n3. If the secondary domain isn''t covered by the wildcard ingress, add a specific hostname rule to the tunnel config before the `http_status:404` catch-all\n\n---\n\n## Useful Reference\n\nCF API base: `https://api.cloudflare.com/client/v4`\n\n| Endpoint | Method | Purpose |\n|-|-|-|\n| `/zones` | GET | List zones (filter: `?name=domain.com`) |\n| `/zones/{zone_id}/dns_records` | GET | List DNS records |\n| `/zones/{zone_id}/dns_records` | POST | Create DNS record |\n| `/zones/{zone_id}/dns_records/{id}` | PUT | Update DNS record |\n| `/zones/{zone_id}/dns_records/{id}` | DELETE | Delete DNS record |\n| `/accounts/{account_id}/cfd_tunnel/{tunnel_id}/configurations` | GET | Get tunnel ingress config |\n| `/accounts/{account_id}/cfd_tunnel/{tunnel_id}/configurations` | PUT | Replace tunnel ingress config |\n| `/accounts/{account_id}/cfd_tunnel` | GET | List all tunnels |\n\nAll responses: `{\"success\": bool, \"result\": ..., \"errors\": [...]}`.\n"},"lastSynced":"2026-03-07T03:54:24.112Z","agentAnalysis":{"suitability":{"en":"Ideal for DevOps Agents requiring automated Cloudflare DNS and tunnel management for VPS-hosted applications.","zh":"适用于需要自动化Cloudflare DNS和隧道管理的DevOps代理，尤其是用于VPS托管的应用程序。","ja":"VPSホストされたアプリケーションに対するCloudflare DNSおよびトンネル管理の自動化を必要とするDevOpsエージェントに適しています。","ko":"VPS 호스팅된 애플리케이션에 대한 Cloudflare DNS 및 터널 관리를 자동화해야 하는 DevOps 에이전트에 적합합니다.","es":"Ideal para agentes de DevOps que requieren una gestión automatizada de DNS y túneles de Cloudflare para aplicaciones alojadas en VPS.","fr":"Idéal pour les agents DevOps nécessitant une gestion automatisée de DNS et de tunnels Cloudflare pour des applications hébergées sur VPS.","de":"Ideal für DevOps-Agents, die eine automatisierte Verwaltung von Cloudflare-DNS und -Tunneln für auf VPS gehostete Anwendungen erfordern.","pt":"Ideal para Agentes DevOps que requerem gerenciamento automatizado de DNS e túneis da Cloudflare para aplicações hospedadas em VPS.","ru":"Идеально подходит для агентов DevOps, требующих автоматизированного управления Cloudflare DNS и туннелями для приложений, размещенных на VPS.","ar":"مثالي لعميل DevOps الذي يتطلب إدارة DNS و隧اء Cloudflare آليًا للتطبيقات المضيفة على VPS."},"recommendation":{"en":"Empowers agents to securely handle Cloudflare API calls via Doppler and SSH, leveraging CF_API_TOKEN for authentication and CF_TUNNEL_ID for tunnel management, all while maintaining secure infrastructure operations via bash commands.","zh":"赋予代理通过Doppler和SSH安全处理Cloudflare API调用、利用CF_API_TOKEN进行身份验证、CF_TUNNEL_ID进行隧道管理的能力，同时通过bash命令维护安全的基础设施操作。","ja":"DopplerとSSHを介してCloudflare API呼び出しを安全に処理し、CF_API_TOKENを使用して認証し、CF_TUNNEL_IDを使用してトンネル管理を行い、bashコマンドを使用して安全なインフラストラクチャ操作を維持するエージェントを可能にします。","ko":"Doppler와 SSH를 통해 Cloudflare API 호출을 안전하게 처리하고, CF_API_TOKEN을 사용하여 인증하고, CF_TUNNEL_ID를 사용하여 터널 관리를 수행하며, bash 명령을 사용하여 보안 인프라 운영을 유지하는 에이전트를 가능하게 합니다.","es":"Habilita a los agentes a manejar de forma segura las llamadas a la API de Cloudflare a través de Doppler y SSH, utilizando CF_API_TOKEN para la autenticación y CF_TUNNEL_ID para la gestión de túneles, todo mientras mantiene operaciones de infraestructura seguras a través de comandos de bash.","fr":"Permet aux agents de gérer de manière sécurisée les appels d''API Cloudflare via Doppler et SSH, en utilisant CF_API_TOKEN pour l''authentification et CF_TUNNEL_ID pour la gestion des tunnels, le tout en maintenant des opérations d''infrastructure sécurisées via des commandes bash.","de":"Ermächtigt die Agents, Cloudflare-API-Anrufe über Doppler und SSH sicher zu handhaben, wobei CF_API_TOKEN für die Authentifizierung und CF_TUNNEL_ID für die Tunnelverwaltung verwendet werden, während gleichzeitig sichere Infrastrukturbetriebe über bash-Befehle aufrechterhalten werden.","pt":"Habilita os agentes a lidar de forma segura com chamadas de API da Cloudflare via Doppler e SSH, utilizando CF_API_TOKEN para autenticação e CF_TUNNEL_ID para gerenciamento de túneis, mantendo operações de infraestrutura seguras por meio de comandos bash.","ru":"Позволяет агентам безопасно обрабатывать вызовы API Cloudflare через Doppler и SSH, используя CF_API_TOKEN для аутентификации и CF_TUNNEL_ID для управления туннелями, сохраняя при этом безопасность инфраструктуры через команды bash.","ar":"تمكّن الوكيل من التعامل بأمان مع مكالمات API Cloudflare عبر Doppler و SSH، باستخدام CF_API_TOKEN للتحقق من الصحة و CF_TUNNEL_ID لإدارة النفق، مع الحفاظ على عمليات البنية التحتية آمنة من خلال أوامر bash."},"useCases":{"en":["Automating Cloudflare DNS updates for VPS-hosted apps","Configuring Cloudflare Tunnels for secure API access","Managing Cloudflare infrastructure via Doppler and SSH"],"zh":["自动化VPS托管应用程序的Cloudflare DNS更新","为安全的API访问配置Cloudflare隧道","通过Doppler和SSH管理Cloudflare基础设施"],"ja":["VPSホストされたアプリケーションのCloudflare DNS更新の自動化","セキュアなAPIアクセス用のCloudflareトンネルの構成","DopplerとSSHを使用したCloudflareインフラストラクチャの管理"],"ko":["VPS 호스팅된 애플리케이션에 대한 Cloudflare DNS 업데이트 자동화","보안 API 액세스를 위한 Cloudflare 터널 구성","Doppler와 SSH를 사용한 Cloudflare 인프라 관리"],"es":["Automatizar actualizaciones de DNS de Cloudflare para aplicaciones alojadas en VPS","Configurar túneles de Cloudflare para un acceso a la API segura","Gestionar la infraestructura de Cloudflare a través de Doppler y SSH"],"fr":["Automatiser les mises à jour de DNS Cloudflare pour les applications hébergées sur VPS","Configurer les tunnels Cloudflare pour un accès à l''API sécurisé","Gérer l''infrastructure Cloudflare via Doppler et SSH"],"de":["Automatisieren von Cloudflare-DNS-Updates für auf VPS gehostete Anwendungen","Konfigurieren von Cloudflare-Tunneln für sicheren API-Zugriff","Verwalten der Cloudflare-Infrastruktur über Doppler und SSH"],"pt":["Automatizar atualizações de DNS da Cloudflare para aplicativos hospedados em VPS","Configurar túneis da Cloudflare para acesso de API seguro","Gerenciar infraestrutura da Cloudflare via Doppler e SSH"],"ru":["Автоматизировать обновления DNS Cloudflare для приложений, размещенных на VPS","Настроить туннели Cloudflare для безопасного доступа к API","Управлять инфраструктурой Cloudflare через Doppler и SSH"],"ar":["توفير تحديثات DNS آليًا لبرامج Cloudflare المضيفة على VPS","تكوين نفق Cloudflare للوصول الآمن إلى API","إدارة بنية تحتية Cloudflare من خلال Doppler و SSH"]},"limitations":{"en":["Requires Doppler configuration","SSH access to VPS necessary","Cloudflare API token (CF_API_TOKEN) setup required"],"zh":["需要Doppler配置","需要VPS的SSH访问","需要Cloudflare API令牌（CF_API_TOKEN）设置"],"ja":["Dopplerの設定が必要","VPSへのSSHアクセスが必要","Cloudflare APIトークン（CF_API_TOKEN）の設定が必要"],"ko":["Doppler 구성이 필요합니다","VPS에 대한 SSH 액세스가 필요합니다","Cloudflare API 토큰（CF_API_TOKEN）설정이 필요합니다"],"es":["Requiere configuración de Doppler","Acceso SSH a VPS necesario","Configuración del token de API de Cloudflare (CF_API_TOKEN) requerida"],"fr":["Nécessite une configuration de Doppler","Accès SSH à VPS nécessaire","Configuration du jeton d''API Cloudflare (CF_API_TOKEN) requise"],"de":["Benötigt Doppler-Konfiguration","SSH-Zugriff auf VPS erforderlich","Einrichtung des Cloudflare-API-Tokens (CF_API_TOKEN) erforderlich"],"pt":["Requer configuração do Doppler","Acesso SSH ao VPS necessário","Configuração do token de API da Cloudflare (CF_API_TOKEN) necessária"],"ru":["Требует настройки Doppler","Требуется доступ SSH к VPS","Требуется настройка токена API Cloudflare (CF_API_TOKEN)"],"ar":["يتطلب تكوين Doppler","مطلوب الوصول إلى VPS عبر SSH","مطلوب إعداد رمز وصول API Cloudflare (CF_API_TOKEN)"]},"version":4},"contentHash":"6f4832608fac2e0d6a98af788efe7dbfa5e6e3e257e2476dec2e16ea6735fae6","qualityScore":39}');
