INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jkrumm/hetzner-vps/cloudflare', 'cloudflare', 'jkrumm', 'hetzner-vps', 'community', 'cloudflare jkrumm hetzner-vps community The Cloudflare skill handles DNS and tunnel operations for VPS-hosted apps, benefiting developers and DevOps teams. It utilizes Doppler and SSH for secure API calls. Cloudflare API Skill用于处理VPS主机应用程序的DNS和隧道操作，支持Traefik、Postgres和Valkey Cloudflare API Skillは、VPSホストアプリケーションのDNSとトンネル操作を処理します。Traefik、Postgres、Valkeyをサポートしています Cloudflare API Skill은 VPS 호스트 애플리케이션의 DNS 및 터널 운영을 처리하며 Traefik, Postgres 및 Valkey를 지원합니다 Cloudflare es una herramienta para gestionar DNS y túneles para aplicaciones alojadas en VPS. Se integra con Docker Compose y Hetzner VPS Cloudflare est un outil pour gérer les DNS et les tunnels pour les applications hébergées sur VPS. Il s''intègre avec Docker Compose et Hetzner VPS Cloudflare ist ein Tool zur Verwaltung von DNS und Tunneln für auf VPS gehostete Anwendungen. Es integriert sich mit Docker Compose und Hetzner VPS O Cloudflare é uma ferramenta para gerenciar operações de DNS e túneis para aplicações hospedadas em VPS Cloudflare - это инструмент для управления операциями DNS и туннелей для приложений, размещенных на VPS كلاودفلير هو أداة لإدارة عمليات DNS والأنفاق لتطبيقات الخوادم الافتراضية how to use cloudflare cloudflare setup guide cloudflare vs AWS cloudflare tunnel setup cloudflare api token management cloudflare dns management Cloudflare API Skill VPS隧道 DNS操作 Traefik Postgres Valkey Doppler SSH Cloudflare Tunnel API Token Executes Cloudflare API calls via SSH on a VPS using `doppler run` Stores Cloudflare API token securely in Doppler as `CF_API_TOKEN` Utilizes a single Cloudflare Tunnel with ID stored in Doppler as `CF_TUNNEL_ID` Supports Postgres, Valkey, and OTel for comprehensive infrastructure management Employs Traefik for reverse proxy and RollHook for automation Cloudflare is a skill for managing Cloudflare DNS and tunnel operations via API calls on a VPS, using Doppler for secure token storage.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('zenml-io/zenml-io-v2/blog-post-contributor', 'community', 'zenml-io', 'zenml-io-v2', 'zenml-io/zenml-io-v2', 'blog-post-contributor', 0, 0, 39, '2026-03-06T16:58:36Z', '2026-03-07T03:54:30.283Z', '47c4be434394b9b28dd32fd13674817756168505d738417d6e87158123f0f55c', '{"id":"zenml-io/zenml-io-v2/blog-post-contributor","name":"blog-post-contributor","description":{"en":"The blog-post-contributor skill automates blog post creation on the ZenML website, handling frontmatter, images, and taxonomy entries. It benefits developers and bloggers by simplifying content creation.","zh":"博客文章贡献者AIエージェント支持两种源工作流，并处理frontmatter、images、taxonomy entries和git分支等技术细节","ja":"ブログ投稿コントリビューターエージェントは2つのソースワークフローをサポートし、frontmatter、画像、taxonomyエントリ、Gitブランチなどの技術的な詳細を処理します","ko":"블로그 게시물 기여자 AI 에이전트는 두 가지 소스 워크플로를 지원하며 frontmatter, 이미지, 분류 항목 및 Git 분기 등의 기술적인 세부 사항을 처리합니다","es":"El contribuyente de publicaciones de blog es una habilidad que permite agregar nuevos contenidos al sitio web de ZenML de manera sencilla","fr":"Le contributeur de billets de blog est une compétence qui permet d''ajouter de nouveaux contenus au site web de ZenML de manière rapide","de":"Der Blog-Beitrag-Mitwirkende ist eine Fähigkeit, die es ermöglicht, neue Inhalte zur ZenML-Website hinzuzufügen","pt":"O Blog Post Contributor é uma habilidade que adiciona novos posts ao site ZenML, lidando com frontmatter, imagens e entradas de taxonomia.","ru":"ИИ Агент Blog Post Contributor - это навык, который добавляет новые посты на сайт ZenML, обрабатывая frontmatter, изображения и записи таксономии.","ar":"مساهم المنشورات على المدونة هو مهارة تضيف منشورات جديدة إلى موقع ZenML، وتتولى معالجة البيانات الوصفية، والصور، ومدخلات التصنيف."},"seo":{"title":{"en":"blog-post-contributor: Automated Blog Posting Setup Guide...","zh":"AIエージェント博客文章贡献者设置指南","ja":"AIエージェントブログ投稿コントリビューター設