INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('zenml-io/zenml-io-v2/blog-post-contributor', 'blog-post-contributor', 'zenml-io', 'zenml-io-v2', 'community', 'blog-post-contributor zenml-io zenml-io-v2 community The blog-post-contributor skill automates blog post creation on the ZenML website, handling frontmatter, images, and taxonomy entries. It benefits developers and bloggers by simplifying content creation. 博客文章贡献者AIエージェント支持两种源工作流，并处理frontmatter、images、taxonomy entries和git分支等技术细节 ブログ投稿コントリビューターエージェントは2つのソースワークフローをサポートし、frontmatter、画像、taxonomyエントリ、Gitブランチなどの技術的な詳細を処理します 블로그 게시물 기여자 AI 에이전트는 두 가지 소스 워크플로를 지원하며 frontmatter, 이미지, 분류 항목 및 Git 분기 등의 기술적인 세부 사항을 처리합니다 El contribuyente de publicaciones de blog es una habilidad que permite agregar nuevos contenidos al sitio web de ZenML de manera sencilla Le contributeur de billets de blog est une compétence qui permet d''ajouter de nouveaux contenus au site web de ZenML de manière rapide Der Blog-Beitrag-Mitwirkende ist eine Fähigkeit, die es ermöglicht, neue Inhalte zur ZenML-Website hinzuzufügen O Blog Post Contributor é uma habilidade que adiciona novos posts ao site ZenML, lidando com frontmatter, imagens e entradas de taxonomia. ИИ Агент Blog Post Contributor - это навык, который добавляет новые посты на сайт ZenML, обрабатывая frontmatter, изображения и записи таксономии. مساهم المنشورات على المدونة هو مهارة تضيف منشورات جديدة إلى موقع ZenML، وتتولى معالجة البيانات الوصفية، والصور، ومدخلات التصنيف. how to use blog-post-contributor blog-post-contributor setup guide automated blog posting with ZenML blog-post-contributor vs manual blogging what is blog-post-contributor blog-post-contributor install and configuration AIエージェント博客文章贡献者 博客文章创建工具 frontmatter处理 images处理 taxonomy entries处理 git分支处理 src/content.config.ts 博客内容目录 作者目录 分类目录 标签目录 Handles frontmatter configuration for blog posts Supports image management and integration Automates taxonomy entries for categorization Manages git branching for version control References schema source of truth from src/content.config.ts blog-post-contributor is a skill that automates the process of adding new blog posts to the ZenML website, supporting source workflows and handling technical details like schema configuration.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('marcusglee11/LifeOS/close-build', 'community', 'marcusglee11', 'LifeOS', 'marcusglee11/LifeOS', 'close-build', 0, 0, 39, '2026-03-02T21:18:45Z', '2026-03-07T03:56:01.448Z', 'b16067dc94546daac78ec1f294a858956459d8941e95ea340d8b1d55d88cb01d', '{"id":"marcusglee11/LifeOS/close-build","name":"close-build","description":{"en":"The close-build skill automates the merge to main and cleanup process for developers, utilizing python scripts and PreToolUse hooks. This skill benefits developers working with Git repositories.","zh":"Close Build 是 LifeOS 程序的一部分，用于自动化构建关闭和清理","ja":"Close Build は LifeOS プログラムの一部で、自動化されたビルドの終了とクリーンアップを行う","ko":"Close Build는 LifeOS 프로그램의 일부로 자동화된 빌드 종료와 클린업을 수행합니다","es":"Close-build es una herramienta que automatiza el proceso de cierre de flujos de trabajo, utilizando Python y CLI para mejorar la eficiencia del equipo.","fr":"Close-build est un outil qui automatise le processus de fermeture des flux de travail, en utilisant Python et CLI pour améliorer l''efficacité de l''équipe.","de":"Close-build ist ein Tool, das den Prozess des Workflowschließens automatisiert, indem es Python und CLI verwendet, um die Effizienz des Teams zu verbessern.","pt":"O Close-Build é uma ferramenta que automatiza o merge e limpeza no LifeOS Programme, utilizando scripts em Python e hooks de pré-uso.","ru":"Close-Build - это инструмент, который автоматизирует слияние и очистку в LifeOS Programme, используя скрипты Python и хуки предиспользования.","ar":"Close-Build هو أداة تلقيم الدمج والتنظيف في برنامج LifeOS ، باستخدام スクリプト Python و Hooks قبل الاستخدام"},"seo":{"title":{"en":"close-build: Automated Merge and Cleanup Setup Guide | AI...","zh":"Close Build 设置指南 - 自动化构建关闭","ja":"Close Build のベストプラクティス - AIエージェントを使用した自動化","ko":"Close Build 설정 가이드 - 자동화된 빌드 종료","es":"Guía de configuración de close-build para auto