INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('marcusglee11/LifeOS/close-build', 'close-build', 'marcusglee11', 'LifeOS', 'community', 'close-build marcusglee11 LifeOS community The close-build skill automates the merge to main and cleanup process for developers, utilizing python scripts and PreToolUse hooks. This skill benefits developers working with Git repositories. Close Build 是 LifeOS 程序的一部分，用于自动化构建关闭和清理 Close Build は LifeOS プログラムの一部で、自動化されたビルドの終了とクリーンアップを行う Close Build는 LifeOS 프로그램의 일부로 자동화된 빌드 종료와 클린업을 수행합니다 Close-build es una herramienta que automatiza el proceso de cierre de flujos de trabajo, utilizando Python y CLI para mejorar la eficiencia del equipo. Close-build est un outil qui automatise le processus de fermeture des flux de travail, en utilisant Python et CLI pour améliorer l''efficacité de l''équipe. Close-build ist ein Tool, das den Prozess des Workflowschließens automatisiert, indem es Python und CLI verwendet, um die Effizienz des Teams zu verbessern. O Close-Build é uma ferramenta que automatiza o merge e limpeza no LifeOS Programme, utilizando scripts em Python e hooks de pré-uso. Close-Build - это инструмент, который автоматизирует слияние и очистку в LifeOS Programme, используя скрипты Python и хуки предиспользования. Close-Build هو أداة تلقيم الدمج والتنظيف في برنامج LifeOS ، باستخدام スクリプト Python و Hooks قبل الاستخدام how to use close-build close-build setup guide automated merge and cleanup PreToolUse hooks tutorial close-build vs git flow close-build install what is close-build close-build alternative python scripts for git automation git repository management best practices Close Build 自动化构建关闭 LifeOS Python 3 squash 合并 PreToolUse hook AI 工具 自动化构建 Runs squash merge to main via python3 scripts/workflow/close_build.py Performs local cleanup, including branch deletion and active context clearing Utilizes PreToolUse hooks, such as .claude/hooks/close-build-gate.sh, for automated closure tests and doc stewardship Supports dry run mode for testing closure gates without committing changes Automates targeted closure tests and doc stewardship, eliminating manual invocation close-build is a skill that automates the process of merging to the main branch and cleaning up local repositories, utilizing scripts like close_build.py and hooks like .claude/hooks/close-build-gate.sh');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ivan-cavero/orbitaleden/godot-ui', 'community', 'ivan-cavero', 'orbitaleden', 'ivan-cavero/orbitaleden', 'godot-ui', 0, 0, 39, '2026-02-22T21:27:49Z', '2026-03-07T03:57:33.536Z', '496b023c4a5ac30984a61031bfee2eaf2468a2c6b3ff8ac9bc6b64b7a7f867cd', '{"id":"ivan-cavero/orbitaleden/godot-ui","name":"godot-ui","description":{"en":"The godot-ui skill enables developers to craft intuitive UI/UX experiences in Godot, leveraging the Control node hierarchy and responsive design principles. It benefits game developers and designers seeking to create engaging interfaces.","zh":"Godot UI 是一个强大的游戏 UI 设计工具，支持 Control 节点系统、主题自定义和响应式设计","ja":"Godot UI は、Control ノードシステム、テーマカスタマイズ、レスポンシブデザインをサポートする強力なゲーム UI デザインツールです","ko":"Godot UI는 Control 노드 시스템, 테마 커스터마이징, 반응형 디자인을 지원하는 강력한 게임 UI 디자인 툴입니다","es":"Godot UI es un sistema de interfaz de usuario para juegos, con una jerarquía de nodos Control y personalización de temas. Aprende a configurarlo","fr":"Godot UI est un système d''interface utilisateur pour jeux, avec une hiérarchie de nœuds Control et personnalisation de thèmes. Apprenez à le configurer","de":"Godot UI ist ein Benutzeroberflächensystem für Spiele, mit einer Knoten-Hierarchie Control und Theme-Anpassung. Lernen Sie, es zu konfigurieren","pt":"O Godot UI é uma ferramenta poderosa para criar interfaces de usuário personalizadas, com recursos como hierarquia de nodos de controle e design responsivo","ru":"Godot UI - это мощный инструмент для создания пользовательских интерфейсов, включающий иерархию узлов управления и адаптивный дизайн","ar":"Godot UI هو أداة قوية لإنشاء واجهات مستخدم مخصصة، مع ميزات مثل هرمية نоды التحكم والتصميم التفاعلي"},"seo":{"title":{"en":"godot-ui: Mastering Godot UI/UX Setup Guide | AI Agent Skill","zh":"Godot UI 设计指南：响应式设计和主题自定义","ja":"Godot UI 導入ガイド：レスポンシブデザインとテーマカスタマイズ","ko":"Godot UI 설정 가이드: 반응형 디자인과 테마 커스터마이징","es":"Guía de configuración de Godot UI: Mejores prácticas para...","fr":"Guide de configuration de Godot UI : Meilleures pratiques...","de":"Godot UI-Konfigurationsleitfaden: Best Practices für Cont...","pt":"Guia de Configuração do Godot UI","ru":"ИИ Агенты: Godot UI Настройка","ar":"إعداد واجهة المستخدم Godot UI"},"description":{"en":"Unlock the full potential of Godot''s Control node system and theme customization. Learn how to setup godot-ui for responsive design and common game UI patter...","zh":"了解 Godot UI 的 Control 节点系统、主题自定义和响应式设计，打造更好的游戏 UI 体验","ja":"Godot UI の Control ノードシステム、テーマカスタマイズ、レスポンシブデザインをマスターして、より良いゲーム UI 体験を実現する","ko":"Godot UI의 Control 노드 시스템, 테마 커스터마이징, 반응형 디자인을 익히고 더 나은 게임 UI 경험을 구축하세요","es":"Aprende a dominar Godot UI con nuestra guía de configuración y mejores prácticas para Control Node, incluyendo jerarquía de nodos y personalización de temas","fr":"Maîtrisez Godot UI avec notre guide de configuration et les meilleures pratiques pour Control Node, y compris la hiérarchie des nœuds et la personnalisation ...","de":"Lernen Sie, Godot UI mit unserem Konfigurationsleitfaden und Best Practices für Control Node zu meistern, einschließlich Knoten-Hierarchie und Theme-Anpassung","pt":"Aprenda a criar interfaces de usuário personalizadas com o Godot UI, incluindo hierarquia de nodos de controle e design responsivo","ru":"Исследуйте возможности Godot UI, включая иерархию узлов управления и настраиваемые темы","ar":"استكشف إمكانيات واجهة المستخدم Godot، بما في ذلك هرمية نоды التحكم والتصميم التفاعلي"},"definition":{"en":"godot-ui is a skill that encompasses expertise in Godot''s Control node system, theme customization, and responsive design for creating immersive game UI/UX experiences.","zh":"Godot UI 是一个游戏 UI 设计工具，用于创建响应式和自定义的游戏界面","ja":"Godot UI は、レスポンシブでカスタマイズ可能なゲーム UI を作成するためのゲーム UI デザインツールです","ko":"Godot UI는 반응형 및 커스터마이징 가능한 게임 UI를 생성하기 위한 게임 UI 디자인 툴입니다","es":"Godot UI es un sistema de interfaz de usuario para juegos que utiliza nodos Control para crear interfaces personalizadas","fr":"Godot UI est un système d''interface utilisateur pour jeux qui utilise des nœuds Control pour créer des interfaces personnalisées","de":"Godot UI ist ein Benutzeroberflächensystem für Spiele, das Control-Knoten verwendet, um personalisierte Oberflächen zu erstellen","pt":"Godot UI é um sistema de nodos de controle para criar interfaces de usuário personalizadas em jogos","ru":"Godot UI - это система узлов управления для создания пользовательских интерфейсов в играх","ar":"Godot UI هو نظام نоды تحكم لإنشاء واجهات مستخدم مخصصة في الألعاب"},"features":{"en":["Utilizes Control node hierarchy with anchor_* and offset_* properties for precise positioning","Customizes themes using size_flags_* and custom_minimum_size constraints","Implements responsive design principles for adaptable game UI","Handles mouse input with mouse_filter options (STOP, PASS)","Applies common game UI patterns for engaging user experiences"],"zh":["Control 节点系统","主题自定义","响应式设计","anchor_* 和 offset_* 属性","size_flags_* 和 custom_minimum_size 属性","mouse_filter 属性"],"ja":["Control ノードシステム","テーマカスタマイズ","レスポンシブデザイン","anchor_* と offset_* プロパティ","size_flags_* と custom_minimum_size プロパティ","mouse_filter プロパティ"],"ko":["Control 노드 시스템","테마 커스터마이징","반응형 디자인","anchor_*와 offset_* 속성","size_flags_*와 custom_minimum_size 속성","mouse_filter 속성"],"es":["Jerarquía de nodos Control para crear interfaces personalizadas","Personalización de temas para adaptar la apariencia de la interfaz","Diseño responsivo para adaptarse a diferentes pantallas y dispositivos","Control de eventos del mouse con mouse_filter","Configuración de tamaño mínimo con custom_minimum_size"],"fr":["Hiérarchie de nœuds Control pour créer des interfaces personnalisées","Personnalisation de thèmes pour adapter l''apparence de l''interface","Conception réactive pour s''adapter à différents écrans et appareils","Contrôle des événements de la souris avec mouse_filter","Configuration de la taille minimale avec custom_minimum_size"],"de":["Knoten-Hierarchie Control zum Erstellen personalisierter Oberflächen","Theme-Anpassung zur Anpassung des Erscheinungsbilds der Oberfläche","Responsives Design zum Anpassen an verschiedene Bildschirme und Geräte","Mauskontrolle mit mouse_filter","Größe-Mindestkonfiguration mit custom_minimum_size"],"pt":["Hierarquia de nodos de controle","Design responsivo","Customização de temas","Nodos de controle personalizados","Posicionamento relativo com anchor_*","Offset de pixels com offset_*"],"ru":["Иерархия узлов управления","Адаптивный дизайн","Настройка тем","Пользовательские узлы управления","Относительное позиционирование с anchor_*","Пиксельный офсет с offset_*"],"ar":["هرمية نоды التحكم","التصميم التفاعلي","تخصيص السمات","نоды تحكم مخصصة","التحديد النسبي باستخدام anchor_*","الحد الأقصى للبكسل باستخدام offset_*"]},"keywords":{"en":["how to use godot-ui","godot-ui setup guide","godot-ui vs Unity UI","godot-ui theme customization","godot-ui responsive design","godot-ui Control node hierarchy","godot-ui install","godot-ui tutorial"],"zh":["Godot UI 设计","游戏 UI 开发","响应式设计","主题自定义","Control 节点系统","Godot 游戏开发","UI 设计工具","游戏 UI 设计指南"],"ja":["Godot UI デザイン","ゲーム UI 開発","レスポンシブデザイン","テーマカスタマイズ","Control ノードシステム","Godot ゲーム開発","UI デザインツール","ゲーム UI デザインガイド"],"ko":["Godot UI 설계","게임 UI 개발","반응형 디자인","테마 커스터마이징","Control 노드 시스템","Godot 게임 개발","UI 디자인 툴","게임 UI 설계 가이드"],"es":["Godot UI","Control Node","jerarquía de nodos","personalización de temas","diseño responsivo","mouse_filter","custom_minimum_size","herramientas de desarrollo de juegos","interfaz de usuario para juegos"],"fr":["Godot UI","Control Node","hiérarchie de nœuds","personnalisation de thèmes","conception réactive","mouse_filter","custom_minimum_size","outils de développement de jeux","interface utilisateur pour jeux"],"de":["Godot UI","Control Node","Knoten-Hierarchie","Theme-Anpassung","responsives Design","mouse_filter","custom_minimum_size","Spiele-Entwicklungstools","Benutzeroberfläche für Spiele"],"pt":["godot ui","desenvolvimento de jogos","interfaces de usuário","design responsivo","nodos de controle","customização de temas","anchor_*","offset_*","tutoriais de godot ui"],"ru":["godot ui","разработка игр","пользовательские интерфейсы","адаптивный дизайн","узлы управления","настройка тем","anchor_*","offset_*","уроки по godot ui"],"ar":["godot ui","تطوير الألعاب","واجهات المستخدم","التصميم التفاعلي","نоды التحكم","تخصيص السمات","anchor_*","offset_*","دروس في godot ui"]}},"owner":"ivan-cavero","repo":"orbitaleden","repoPath":"ivan-cavero/orbitaleden","stars":0,"forks":0,"updatedAt":"2026-02-22T21:27:49Z","topics":[],"category":"community","skillMd":{"name":"godot-ui","description":"Expert knowledge of Godots UI system including Control nodes, themes, styling, responsive layouts, and common UI patterns for menus, HUDs, inventories, and dialogue systems. Use when working with Godot UI/menu creation or styling.","bodyPreview":"You are a Godot UI/UX expert with deep knowledge of Godot''s Control node system, theme customization, responsive design, and common game UI patterns.\n\n# Core UI Knowledge\n\n## Control Node Hierarchy\n\n**Base Control Node Properties:**\n- `anchor_*`: Positioning relative to parent edges (0.0 to 1.0)\n- `offset_*`: Pixel offset from anchor points\n- `size_flags_*`: How the node should grow/shrink\n- `custom_minimum_size`: Minimum size constraints\n- `mouse_filter`: Control mouse input handling (STOP, PAS","body":"You are a Godot UI/UX expert with deep knowledge of Godot''s Control node system, theme customization, responsive design, and common game UI patterns.\n\n# Core UI Knowledge\n\n## Control Node Hierarchy\n\n**Base Control Node Properties:**\n- `anchor_*`: Positioning relative to parent edges (0.0 to 1.0)\n- `offset_*`: Pixel offset from anchor points\n- `size_flags_*`: How the node should grow/shrink\n- `custom_minimum_size`: Minimum size constraints\n- `mouse_filter`: Control mouse input handling (STOP, PASS, IGNORE)\n- `focus_mode`: Keyboard/gamepad focus behavior\n\n**Common Control Nodes:**\n\n### Container Nodes (Layout Management)\n- **VBoxContainer**: Vertical stacking with automatic spacing\n- **HBoxContainer**: Horizontal arrangement with automatic spacing\n- **GridContainer**: Grid layout with columns\n- **MarginContainer**: Adds margins around children\n- **CenterContainer**: Centers a single child\n- **PanelContainer**: Container with panel background\n- **ScrollContainer**: Scrollable area for overflow content\n- **TabContainer**: Tabbed interface with multiple pages\n- **SplitContainer**: Resizable split between two children\n\n### Interactive Controls\n- **Button**: Standard clickable button\n- **TextureButton**: Button with custom textures for states\n- **CheckBox**: Toggle checkbox\n- **CheckButton**: Toggle switch style\n- **OptionButton**: Dropdown selection menu\n- **LineEdit**: Single-line text input\n- **TextEdit**: Multi-line text editor\n- **Slider/HSlider/VSlider**: Value adjustment sliders\n- **SpinBox**: Numeric input with increment buttons\n- **ProgressBar**: Visual progress indicator\n- **ItemList**: Scrollable list of items\n- **Tree**: Hierarchical tree view\n\n### Display Nodes\n- **Label**: Text display\n- **RichTextLabel**: Text with BBCode formatting, images, effects\n- **TextureRect**: Image display with scaling options\n- **NinePatchRect**: Scalable image using 9-slice method\n- **ColorRect**: Solid color rectangle\n- **VideoStreamPlayer**: Video playback in UI\n- **GraphEdit/GraphNode**: Node-graph interface\n\n### Advanced Controls\n- **Popup**: Modal/modeless popup window\n- **PopupMenu**: Context menu\n- **MenuBar**: Top menu bar\n- **FileDialog**: File picker\n- **ColorPicker**: Color selection\n- **SubViewport**: Embedded viewport for 3D-in-2D UI\n\n## Anchor & Container System\n\n**Anchor Presets:**\n```gdscript\n# Common anchor configurations\n# Top-left (default): anchor_left=0, anchor_top=0, anchor_right=0, anchor_bottom=0\n# Full rect: anchor_left=0, anchor_top=0, anchor_right=1, anchor_bottom=1\n# Top wide: anchor_left=0, anchor_top=0, anchor_right=1, anchor_bottom=0\n# Center: anchor_left=0.5, anchor_top=0.5, anchor_right=0.5, anchor_bottom=0.5\n```\n\n**Responsive Design Pattern:**\n```gdscript\n# In _ready() for responsive UI\nfunc _ready():\n    # Connect to viewport size changes\n    get_viewport().size_changed.connect(_on_viewport_size_changed)\n    _on_viewport_size_changed()\n\nfunc _on_viewport_size_changed():\n    var viewport_size = get_viewport_rect().size\n    # Adjust UI based on aspect ratio or screen size\n    if viewport_size.x / viewport_size.y < 1.5:  # Portrait or square\n        # Switch to mobile layout\n        pass\n    else:  # Landscape\n        # Use desktop layout\n        pass\n```\n\n## Theme System\n\n**Theme Structure:**\n- **StyleBoxes**: Background styles for controls (StyleBoxFlat, StyleBoxTexture)\n- **Fonts**: Font resources with size and variants\n- **Colors**: Named color values\n- **Icons**: Texture2D for icons and graphics\n- **Constants**: Numeric values (spacing, margins)\n\n**Creating Themes in Code:**\n```gdscript\n# Create a theme\nvar theme = Theme.new()\n\n# StyleBox for buttons\nvar style_normal = StyleBoxFlat.new()\nstyle_normal.bg_color = Color(0.2, 0.2, 0.2)\nstyle_normal.corner_radius_top_left = 5\nstyle_normal.corner_radius_top_right = 5\nstyle_normal.corner_radius_bottom_left = 5\nstyle_normal.corner_radius_bottom_right = 5\nstyle_normal.content_margin_left = 10\nstyle_normal.content_margin_right = 10\nstyle_normal.content_margin_top = 5\nstyle_normal.content_margin_bottom = 5\n\nvar style_hover = StyleBoxFlat.new()\nstyle_hover.bg_color = Color(0.3, 0.3, 0.3)\n# ... same corner radius and margins\n\nvar style_pressed = StyleBoxFlat.new()\nstyle_pressed.bg_color = Color(0.15, 0.15, 0.15)\n# ... same corner radius and margins\n\ntheme.set_stylebox(\"normal\", \"Button\", style_normal)\ntheme.set_stylebox(\"hover\", \"Button\", style_hover)\ntheme.set_stylebox(\"pressed\", \"Button\", style_pressed)\n\n# Apply to Control node\n$MyControl.theme = theme\n```\n\n**Theme Resources:**\nBest practice: Create .tres theme files and save them in `resources/themes/`\n- Allows visual editing in Inspector\n- Can be shared across multiple scenes\n- Supports inheritance (base theme + overrides)\n\n## Common UI Patterns\n\n### Main Menu\n```\nCanvasLayer\n├── MarginContainer (margins for screen edges)\n│   └── VBoxContainer (vertical menu layout)\n│       ├── TextureRect (logo)\n│       ├── VBoxContainer (button container)\n│       │   ├── Button (New Game)\n│       │   ├── Button (Continue)\n│       │   ├── Button (Settings)\n│       │   └── Button (Quit)\n│       └── Label (version info)\n```\n\n### Settings Menu\n```\nCanvasLayer\n├── ColorRect (semi-transparent overlay)\n└── PanelContainer (settings panel)\n    └── MarginContainer\n        └── VBoxContainer\n            ├── Label (Settings Header)\n            ├── TabContainer\n            │   ├── VBoxContainer (Graphics Tab)\n            │   │   ├── HBoxContainer\n            │   │   │   ├── Label (Resolution:)\n            │   │   │   └── OptionButton\n            │   │   └── HBoxContainer\n            │   │       ├── Label (Fullscreen:)\n            │   │       └── CheckBox\n            │   └── VBoxContainer (Audio Tab)\n            │       ├── HBoxContainer\n            │       │   ├── Label (Master Volume:)\n            │       │   └── HSlider\n            │       └── HBoxContainer\n            │           ├── Label (Music Volume:)\n            │           └── HSlider\n            └── HBoxContainer (button row)\n                ├── Button (Apply)\n                └── Button (Back)\n```\n\n### HUD (Heads-Up Display)\n```\nCanvasLayer (layer = 10 for top rendering)\n├── MarginContainer (screen margins)\n│   └── VBoxContainer\n│       ├── HBoxContainer (top bar)\n│       │   ├── TextureRect (health icon)\n│       │   ├── ProgressBar (health)\n│       │   ├── Control (spacer)\n│       │   ├── Label (score)\n│       │   └── TextureRect (coin icon)\n│       ├── Control (spacer - expands)\n│       └── HBoxContainer (bottom bar)\n│           ├── TextureButton (inventory)\n│           ├── TextureButton (map)\n│           └── TextureButton (pause)\n```\n\n### Inventory System\n```\nCanvasLayer\n├── ColorRect (overlay background)\n└── PanelContainer (inventory panel)\n    └── MarginContainer\n        └── VBoxContainer\n            ├── Label (Inventory Header)\n            ├── HBoxContainer (main area)\n            │   ├── GridContainer (item grid - columns=5)\n            │   │   ├── TextureButton (item slot)\n            │   │   ├── TextureButton (item slot)\n            │   │   └── ... (more slots)\n            │   └── PanelContainer (item details)\n            │       └── VBoxContainer\n            │           ├── TextureRect (item image)\n            │           ├── Label (item name)\n            │           ├── RichTextLabel (description)\n            │           └── Button (Use/Equip)\n            └── Button (Close)\n```\n\n### Dialogue System\n```\nCanvasLayer (layer = 5)\n├── Control (spacer)\n└── PanelContainer (dialogue box - anchored to bottom)\n    └── MarginContainer\n        └── VBoxContainer\n            ├── HBoxContainer (character info)\n            │   ├── TextureRect (character portrait)\n            │   └── Label (character name)\n            ├── RichTextLabel (dialogue text with BBCode)\n            └── VBoxContainer (choice container)\n                ├── Button (choice 1)\n                ├── Button (choice 2)\n                └── Button (choice 3)\n```\n\n### Pause Menu\n```\nCanvasLayer (layer = 100)\n├── ColorRect (semi-transparent overlay - modulate alpha)\n└── CenterContainer (full rect anchors)\n    └── PanelContainer (menu panel)\n        └── MarginContainer\n            └── VBoxContainer\n                ├── Label (PAUSED)\n                ├── Button (Resume)\n                ├── Button (Settings)\n                ├── Button (Main Menu)\n                └── Button (Quit)\n```\n\n## Common UI Scripting Patterns\n\n### Button Connections\n```gdscript\n@onready var start_button = $VBoxContainer/StartButton\n\nfunc _ready():\n    # Connect button signals\n    start_button.pressed.connect(_on_start_button_pressed)\n\n    # Or use Inspector to connect signals visually\n\nfunc _on_start_button_pressed():\n    # Handle button press\n    get_tree().change_scene_to_file(\"res://scenes/main_game.tscn\")\n```\n\n### Menu Navigation with Keyboard/Gamepad\n```gdscript\nfunc _ready():\n    # Set first focusable button\n    $VBoxContainer/StartButton.grab_focus()\n\n    # Configure focus neighbors for gamepad navigation\n    $VBoxContainer/StartButton.focus_neighbor_bottom = $VBoxContainer/SettingsButton.get_path()\n    $VBoxContainer/SettingsButton.focus_neighbor_top = $VBoxContainer/StartButton.get_path()\n    $VBoxContainer/SettingsButton.focus_neighbor_bottom = $VBoxContainer/QuitButton.get_path()\n```\n\n### Animated Transitions\n```gdscript\n# Fade in menu\nfunc show_menu():\n    modulate.a = 0\n    visible = true\n    var tween = create_tween()\n    tween.tween_property(self, \"modulate:a\", 1.0, 0.3)\n\n# Fade out menu\nfunc hide_menu():\n    var tween = create_tween()\n    tween.tween_property(self, \"modulate:a\", 0.0, 0.3)\n    tween.tween_callback(func(): visible = false)\n\n# Slide in from side\nfunc slide_in():\n    position.x = -get_viewport_rect().size.x\n    visible = true\n    var tween = create_tween()\n    tween.set_trans(Tween.TRANS_QUAD)\n    tween.set_ease(Tween.EASE_OUT)\n    tween.tween_property(self, \"position:x\", 0, 0.5)\n```\n\n### Dynamic Lists\n```gdscript\n# Populate ItemList dynamically\n@onready var item_list = $ItemList\n\nfunc populate_list(items: Array):\n    item_list.clear()\n    for item in items:\n        item_list.add_item(item.name, item.icon)\n        item_list.set_item_metadata(item_list.item_count - 1, item)\n\nfunc _on_item_list_item_selected(index: int):\n    var item = item_list.get_item_metadata(index)\n    # Do something with selected item\n```\n\n### Health Bar Updates\n```gdscript\n@onready var health_bar = $HealthBar\nvar current_health = 100\nvar max_health = 100\n\nfunc _ready():\n    health_bar.max_value = max_health\n    health_bar.value = current_health\n\nfunc take_damage(amount: int):\n    current_health = max(0, current_health - amount)\n\n    # Smooth tween to new value\n    var tween = create_tween()\n    tween.tween_property(health_bar, \"value\", current_health, 0.2)\n\n    # Change color based on health percentage\n    if current_health < max_health * 0.3:\n        health_bar.modulate = Color.RED\n    elif current_health < max_health * 0.6:\n        health_bar.modulate = Color.YELLOW\n    else:\n        health_bar.modulate = Color.GREEN\n```\n\n### Modal Popups\n```gdscript\n@onready var popup = $Popup\n\nfunc show_confirmation(message: String, on_confirm: Callable):\n    $Popup/VBoxContainer/Label.text = message\n    popup.popup_centered()\n\n    # Store callback\n    if not $Popup/VBoxContainer/HBoxContainer/ConfirmButton.pressed.is_connected(_on_confirm):\n        $Popup/VBoxContainer/HBoxContainer/ConfirmButton.pressed.connect(_on_confirm)\n\n    confirm_callback = on_confirm\n\nvar confirm_callback: Callable\n\nfunc _on_confirm():\n    popup.hide()\n    if confirm_callback:\n        confirm_callback.call()\n```\n\n## UI Performance Optimization\n\n**Best Practices:**\n1. **Use CanvasLayers for depth management** instead of z_index when possible\n2. **Clip content** in ScrollContainers with `clip_contents = true`\n3. **Limit RichTextLabel complexity** - BBCode parsing can be slow\n4. **Pool UI elements** - Reuse nodes instead of creating/destroying\n5. **Use TextureAtlas** for UI sprites to reduce draw calls\n6. **Batch similar elements** under same parent\n7. **Disable processing** when UI is hidden: `process_mode = PROCESS_MODE_DISABLED`\n8. **Use Control.clip_contents** to prevent rendering off-screen elements\n\n**Memory Management:**\n```gdscript\n# Free unused UI scenes\nfunc close_menu():\n    queue_free()  # Instead of just hiding\n\n# Object pooling for frequently created UI\nvar button_pool = []\nconst MAX_POOL_SIZE = 20\n\nfunc get_pooled_button():\n    if button_pool.is_empty():\n        return Button.new()\n    return button_pool.pop_back()\n\nfunc return_to_pool(button: Button):\n    if button_pool.size() < MAX_POOL_SIZE:\n        button.get_parent().remove_child(button)\n        button_pool.append(button)\n    else:\n        button.queue_free()\n```\n\n## Accessibility Features\n\n**Text Scaling:**\n```gdscript\n# Support text size preferences\nfunc apply_text_scale(scale: float):\n    for label in get_tree().get_nodes_in_group(\"scalable_text\"):\n        if label is Label or label is RichTextLabel:\n            label.add_theme_font_size_override(\"font_size\", int(16 * scale))\n```\n\n**Gamepad Support:**\n```gdscript\n# Ensure all interactive UI is gamepad-accessible\nfunc _ready():\n    # Set up focus chain\n    for i in range($ButtonContainer.get_child_count() - 1):\n        var current = $ButtonContainer.get_child(i)\n        var next = $ButtonContainer.get_child(i + 1)\n        current.focus_neighbor_bottom = next.get_path()\n        next.focus_neighbor_top = current.get_path()\n\n    # Grab focus on first button\n    if $ButtonContainer.get_child_count() > 0:\n        $ButtonContainer.get_child(0).grab_focus()\n```\n\n## MCP Tool Usage\n\nWhen creating UI elements, you should:\n\n1. **Use `mcp__godot__create_scene`** to create new UI scene files\n2. **Use `mcp__godot__add_node`** to build Control node hierarchies\n3. **Use `mcp__godot__save_scene`** to save after creating UI structure\n4. **Use Edit/Write tools** to create associated GDScript files for UI logic\n5. **Use `mcp__godot__load_sprite`** to import UI textures and icons\n\n**Example Workflow:**\n```\n1. create_scene(\"res://scenes/ui/main_menu.tscn\", \"CanvasLayer\")\n2. add_node(..., \"MarginContainer\")\n3. add_node(..., \"VBoxContainer\")\n4. add_node(..., \"Button\")\n5. save_scene(...)\n6. Write GDScript controller\n```\n\n## When to Activate This Skill\n\nActivate this skill when the user:\n- Asks about creating menus, HUDs, or UI screens\n- Mentions Control nodes, themes, or styling\n- Needs help with inventory, dialogue, or menu systems\n- Asks about responsive UI or screen resolution handling\n- Requests help with button navigation or gamepad support\n- Wants to create settings menus or pause screens\n- Asks about UI animation or transitions\n- Needs help with UI performance optimization\n- Mentions anchors, containers, or layout management\n\n## Important Reminders\n\n- Always consider **gamepad/keyboard navigation** in addition to mouse\n- Use **CanvasLayers** to manage rendering order and prevent z-fighting\n- **Anchor presets** are your friend for responsive design\n- **Themes** should be created as resources for reusability\n- **Signal connections** are the primary way to handle UI interactions\n- **Tweens** make UI feel polished with smooth animations\n- **Test on multiple resolutions** - use Project Settings > Display > Window settings\n"},"lastSynced":"2026-03-07T03:57:33.536Z","agentAnalysis":{"suitability":{"en":"Perfect for Game Development Agents needing advanced UI/UX design capabilities in Godot","zh":"非常适合需要高级 UI/UX 设计能力的 Godot 游戏开发代理","ja":"Godot で高度な UI/UX デザイン機能を必要とするゲーム開発エージェントに最適","ko":"고도한 UI/UX 디자인 기능이 필요한 Godot 게임 개발 에이전트에게 적합","es":"Perfecto para agentes de desarrollo de juegos que necesitan capacidades de diseño de UI/UX avanzadas en Godot","fr":"Parfait pour les agents de développement de jeux nécessitant des capacités de conception UI/UX avancées dans Godot","de":"Perfekt für Game-Development-Agents, die erweiterte UI/UX-Designfunktionen in Godot benötigen","pt":"Perfeito para Agentes de Desenvolvimento de Jogos que precisam de capacidades avançadas de design UI/UX no Godot","ru":"Идеально подходит для агентов разработки игр, которым необходимы продвинутые возможности проектирования UI/UX в Godot","ar":"مثالي لعميل تطوير الألعاب الذي يحتاج إلى قدرات تصميم UI/UX متقدمة في Godot"},"recommendation":{"en":"Empowers agents to craft intuitive UI/UX experiences using Godot''s Control node hierarchy, responsive design principles, and theme customization, while leveraging properties like anchor_* and size_flags_* for precise control","zh":"赋予代理创建直观的 UI/UX 体验的能力，使用 Godot 的 Control 节点层次、响应式设计原则和主题自定义，同时利用属性如 anchor_* 和 size_flags_* 进行精确控制","ja":"Godot の Control ノード階層、レスポンシブデザイン原則、テーマカスタマイズを使用して、直感的な UI/UX 体験を作成するエージェントの能力を強化し、anchor_* や size_flags_* などのプロパティを使用して精密な制御を行う","ko":"Godot의 Control 노드 계층, 반응형 디자인 원칙, 테마 커스터마이즈를 사용하여 직관적인 UI/UX 경험을を作成할 수 있는 에이전트의 능력을 강화하며, anchor_* 및 size_flags_* 등의 속성을 사용하여 정밀한 제어를 수행","es":"Habilita a los agentes a crear experiencias UI/UX intuitivas utilizando la jerarquía de nodos de Control de Godot, principios de diseño responsivo y personalización de temas, mientras aprovecha propiedades como anchor_* y size_flags_* para un control preciso","fr":"Permet aux agents de créer des expériences UI/UX intuitives en utilisant la hiérarchie des nœuds de contrôle de Godot, les principes de conception responsifs et la personnalisation des thèmes, tout en exploitant des propriétés comme anchor_* et size_flags_* pour un contrôle précis","de":"Ermächtigt Agenten, intuitive UI/UX-Erfahrungen zu erstellen, indem sie die Control-Node-Hierarchie von Godot, responsives Design und Theme-Anpassung nutzen und Eigenschaften wie anchor_* und size_flags_* für präzise Kontrolle verwenden","pt":"Habilita os agentes a criar experiências UI/UX intuitivas usando a hierarquia de nó de Controle do Godot, princípios de design responsivo e personalização de temas, aproveitando propriedades como anchor_* e size_flags_* para controle preciso","ru":"Наделяет агентов возможностью создавать интуитивно понятные trải n