INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('zomeru/rezumerai/web-accessibility', 'web-accessibility', 'zomeru', 'rezumerai', 'community', 'web-accessibility zomeru rezumerai community The web-accessibility skill enables developers to build accessible web applications that work for everyone, following WCAG 2.1 guidelines. It benefits developers and users with disabilities. 使用 AIエージェント 构建无障碍 Web 应用，实现 ARIA Patterns 和 WCAG 2.1 标准 AIエージェント を使用して、ARIA Patterns と WCAG 2.1 に準拠したアクセシブルな Web アプリケーションを構築 AI 에이전트를 사용하여 ARIA 패턴과 WCAG 2.1을 준수하는 웹 접근성 애플리케이션을 구축합니다 Construye aplicaciones web accesibles con AI Agents y sigue las pautas de accesibilidad web de WCAG 2.1 Créez des applications web accessibles avec des outils IA et suivez les directives d''accessibilité web de WCAG 2.1 Erstellen Sie zugängliche Webanwendungen mit KI-Tools und folgen Sie den Richtlinien für Web-Accessibility von WCAG 2.1 Construa aplicações web acessíveis com ARIA Patterns e WCAG 2.1, impulsionados por IA Создайте веб-приложения с доступностью, используя паттерны ARIA и WCAG 2.1, с помощью ИИ Агентов ابني تطبيقات ويب قابلة للوصول باستخدام نمطز ARIA و WCAG 2.1، مدعومة بالذكاء الاصطناعي how to use web-accessibility web-accessibility setup guide WCAG 2.1 compliance ARIA patterns for buttons modal dialog accessibility web-accessibility vs accessibility guidelines install web-accessibility web-accessibility best practices web-accessibility for developers accessible web applications Web Accessibility AIエージェント WCAG 2.1 ARIA Patterns TypeScript React 无障碍 Web 应用 アクセシブルな Web アプリケーション Implements ARIA patterns for buttons with aria-pressed and aria-disabled attributes Supports modal dialog accessibility with role=''dialog'' and aria-modal=''true'' Utilizes aria-labelledby and aria-describedby for modal dialog descriptions Enables toggle feature with onClick event handling Follows WCAG 2.1 guidelines for web accessibility Web-accessibility is the practice of making web applications usable for people with disabilities, following standards like WCAG 2.1 and using technologies like ARIA patterns.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('dawink5674/sovereign-vpn-core/Firebase Test Lab Specialist', 'community', 'dawink5674', 'sovereign-vpn-core', 'dawink5674/sovereign-vpn-core', 'Firebase Test Lab Specialist', 0, 0, 39, '2026-03-05T03:48:42Z', '2026-03-07T04:05:07.249Z', '1064f42828c46e31c0c239493e1d59e04405056660fe3c0b4a7f5870b8e299b1', '{"id":"dawink5674/sovereign-vpn-core/Firebase Test Lab Specialist","name":"Firebase Test Lab Specialist","description":{"en":"Firebase Test Lab Specialist helps developers test their apps on real and virtual Android devices, providing valuable insights and crash reports. It benefits developers working on Android apps, especially those using Google''s cloud infrastructure.","zh":"Firebase Test Lab Specialist 是一个用于测试 Android 应用的工具，支持 Robo 测试和虚拟设备测试","ja":"Firebase Test Lab Specialist は Android アプリをテストするツールです - Robo テストと仮想デバイス テストに対応","ko":"Firebase Test Lab Specialist 는 안드로이드 애플리케이션을 테스트하는 도구로서 Robo 테스트와 가상 디바이스 테스트를 지원합니다","es":"Firebase Test Lab es un mecanismo de testing para aplicaciones en dispositivos Android, proporcionando capturas de pantalla, registros y grabaciones de video","fr":"Firebase Test Lab est un mécanisme de test pour les applications sur les appareils Android, fournissant des captures d''écran, des journaux et des enregistrements vidéo","de":"Firebase Test Lab ist ein Testmechanismus für Anwendungen auf Android-Geräten, der Screenshots, Protokolle und Videoaufzeichnungen bereitstellt","pt":"O Firebase Test Lab Specialist é uma ferramenta de teste para aplicativos que roda testes em dispositivos reais e virtuais da Google.","ru":"Firebase Test Lab Specialist - это инструмент для тестирования приложений, который запускает тесты на реальных и виртуальных устройствах Google.","ar":"Firebase Test Lab Specialist هو أداة اختبار للتطبيقات التي تعمل على تشغيل الاختبارات على أجهزة حقيقية وافتراضية من جوجل"},"seo":{"title":{"en":"Firebase Test Lab Specialist: Setup Guide for AI Agents","zh":"Firebase Test Lab Specialist 设置指南","ja":"Firebase Test Lab Specialist 導入ガイド - AIエージェント","ko":"Firebase Test Lab Specialist 설정 가이드 - AIツール","es":"Guía de configuración de Firebase Test Lab Specialist","fr":"Guide de configuration de Firebase Test Lab Specialist","de":"Konfigurationsleitfaden für Firebase Test Lab Specialist","pt":"Guia de Configuração do Firebase Test Lab Specialist","ru":"Настройка Firebase Test Lab Specialist: Лучшие Практики","ar":"دليل إعداد Firebase Test Lab Specialist"},"description":{"en":"Unlock efficient testing with Firebase Test Lab Specialist - learn how to run Robo tests, analyze crash reports, and optimize your app''s performance on real ...","zh":"了解 Firebase Test Lab Specialist 的功能和特点，包括 Robo 测试和虚拟设备测试","ja":"Firebase Test Lab Specialist の機能と特徴を紹介します - Robo テストと仮想デバイス テスト","ko":"Firebase Test Lab Specialist 의 기능과 특징을 알아보세요 - Robo 테스트와 가상 디바이스 테스트","es":"Aprende a configurar y utilizar Firebase Test Lab para testing de aplicaciones en dispositivos Android reales y virtuales","fr":"Découvrez comment configurer et utiliser Firebase Test Lab pour tester des applications sur des appareils Android réels et virtuels","de":"Erfahren Sie, wie Sie Firebase Test Lab für das Testen von Anwendungen auf realen und virtuellen Android-Geräten konfigurieren und verwenden","pt":"Aprenda a configurar o Firebase Test Lab para testar aplicativos em dispositivos reais e virtuais da Google","ru":"Исследуйте возможности Firebase Test Lab для тестирования приложений на реальных и виртуальных устройствах Google","ar":"تعرف على كيفية إعداد Firebase Test Lab لاختبار التطبيقات على أجهزة حقيقية وافتراضية من جوجل"},"definition":{"en":"Firebase Test Lab Specialist is a testing mechanism that runs tests on real and virtual Android devices, providing screenshots, logs, video recordings, and crash reports for app development and optimization","zh":"Firebase Test Lab Specialist 是一种测试工具，用于在 Google 云基础设施上运行测试","ja":"Firebase Test Lab Specialist は Google クラウド インフラストラクチャ上でテストを実行するツールです","ko":"Firebase Test Lab Specialist 는 구글 클라우드 인프라에서 테스트를 실행하는 도구입니다","es":"Firebase Test Lab es una herramienta de testing para aplicaciones en la nube de Google","fr":"Firebase Test Lab est un outil de test pour les applications dans le cloud de Google","de":"Firebase Test Lab ist ein Testtool für Anwendungen in der Google-Cloud","pt":"O que é Firebase Test Lab Specialist? É uma ferramenta de teste para aplicativos que usa dispositivos reais e virtuais da Google.","ru":"Что такое Firebase Test Lab Specialist? Это инструмент для тестирования приложений, использующий реальные и виртуальные устройства Google.","ar":"ما هو Firebase Test Lab Specialist؟ إنه أداة اختبار للتطبيقات التي تستخدم أجهزة حقيقية وافتراضية من جوجل"},"features":{"en":["Runs Robo tests on real and virtual Android devices","Provides screenshots, logs, video recordings, and crash reports for app testing","Supports testing on physical devices like Pixel 10 Pro Fold","Automatically crawls app UI and detects crashes using Robo tests","Generates valuable insights for app development and optimization","Utilizes Google''s cloud infrastructure for scalable testing"],"zh":["支持 Robo 测试，无需测试代码","支持虚拟设备测试，包括 Pixel 10 Pro Fold","提供测试结果，包括截图、日志、视频录制和崩溃报告","支持在 Google 云基础设施上运行测试","支持 API 36 和物理设备测试"],"ja":["Robo テストをサポート、テスト コード不要","仮想デバイス テストをサポート、Pixel 10 Pro Fold など","テスト結果を提供、スクリーンショット、ログ、動画録画、クラッシュ レポートなど","Google クラウド インフラストラクチャ上でテストを実行","API 36 と物理デバイス テストをサポート"],"ko":["Robo 테스트 지원, 테스트 코드 필요없음","가상 디바이스 테스트 지원, Pixel 10 Pro Fold 등","테스트 결과 제공, 스크린샷, 로그, 동영상 녹화, 크래시 리포트 등","구글 클라우드 인프라에서 테스트 실행","API 36 및 물리적인 디바이스 테스트 지원"],"es":["Ejecución de pruebas Robo sin código de prueba","Testing en dispositivos Android reales y virtuales","Proporciona capturas de pantalla, registros y grabaciones de video","Soporte para dispositivos físicos como el Pixel 10 Pro Fold","Compatibilidad con API 36"],"fr":["Exécution de tests Robo sans code de test","Test sur des appareils Android réels et virtuels","Fournit des captures d''écran, des journaux et des enregistrements vidéo","Supporte les appareils physiques tels que le Pixel 10 Pro Fold","Compatibilité avec l''API 36"],"de":["Ausführung von Robo-Tests ohne Testcode","Testen auf realen und virtuellen Android-Geräten","Bietet Screenshots, Protokolle und Videoaufzeichnungen","Unterstützt physische Geräte wie das Pixel 10 Pro Fold","Kompatibilität mit API 36"],"pt":["Testes em dispositivos reais e virtuais da Google","Suporte a testes Robo sem código de teste","Relatórios de crash e logs detalhados","Gravação de vídeo e capturas de tela","Suporte a dispositivos físicos como o Pixel 10 Pro Fold"],"ru":["Тестирование на реальных и виртуальных устройствах Google","Поддержка тестов Robo без кода теста","Отчеты о крахе и подробные логи","Видеозапись и скриншоты","Поддержка физических устройств, таких как Pixel 10 Pro Fold"],"ar":["الاختبارات على الأجهزة الحقيقية والافتراضية من جوجل","دعم اختبارات روبو بدون kode اختبار","تقارير عن الانهيار وسجلات مفصلة","تسجيل الفيديو والصور الملتقطة","دعم الأجهزة المادية مثل Pixel 10 Pro Fold"]},"keywords":{"en":["how to use Firebase Test Lab Specialist","Firebase Test Lab Specialist setup guide","Firebase Test Lab Specialist alternative","Firebase Test Lab Specialist vs Appium","what is Firebase Test Lab Specialist","Firebase Test Lab Specialist install","Robo test automation","Android app testing on Google cloud","Firebase Test Lab Specialist tutorial","optimizing app performance with Firebase Test Lab Specialist"],"zh":["Firebase Test Lab Specialist","Robo 测试","虚拟设备测试","Google 云基础设施","API 36","物理设备测试","AI工具","测试工具","Android 测试"],"ja":["Firebase Test Lab Specialist","Robo テスト","仮想デバイス テスト","Google クラウド インフラストラクチャ","API 36","物理デバイス テスト","AIエージェント","テストツール","Android テスト"],"ko":["Firebase Test Lab Specialist","Robo 테스트","가상 디바이스 테스트","구글 클라우드 인프라","API 36","물리적인 디바이스 테스트","AIツール","테스트 도구","안드로이드 테스트"],"es":["Firebase Test Lab","testing de aplicaciones","dispositivos Android","pruebas Robo","Google Cloud","desarrollo de aplicaciones móviles","herramientas de testing","Pixel 10 Pro Fold","API 36"],"fr":["Firebase Test Lab","test d''applications","appareils Android","tests Robo","Google Cloud","développement d''applications mobiles","outils de test","Pixel 10 Pro Fold","API 36"],"de":["Firebase Test Lab","Anwendungstest","Android-Geräte","Robo-Tests","Google Cloud","Mobile-Anwendungsentwicklung","Testtools","Pixel 10 Pro Fold","API 36"],"pt":["Firebase Test Lab","Testes de aplicativos","Dispositivos reais e virtuais","Testes Robo","Relatórios de crash","Gravação de vídeo","Capturas de tela","Pixel 10 Pro Fold"],"ru":["Firebase Test Lab","Тестирование приложений","Реальные и виртуальные устройства","Тесты Robo","Отчеты о крахе","Видеозапись","Скриншоты","Pixel 10 Pro Fold"],"ar":["Firebase Test Lab","اختبار التطبيقات","الأجهزة الحقيقية والافتراضية","اختبارات روبو","تقارير عن الانهيار","تسجيل الفيديو","الصور الملتقطة","Pixel 10 Pro Fold"]}},"owner":"dawink5674","repo":"sovereign-vpn-core","repoPath":"dawink5674/sovereign-vpn-core","stars":0,"forks":0,"updatedAt":"2026-03-05T03:48:42Z","topics":[],"category":"community","skillMd":{"name":"Firebase Test Lab Specialist","description":"Automated Android testing via Firebase Test Lab — robo tests, instrumentation tests, device matrix configuration, and test result analysis.","bodyPreview":"# Firebase Test Lab Specialist\n\n## Overview\n\nFirebase Test Lab is the primary testing mechanism for the Dragon Scale VPN project. It runs tests on real and virtual Android devices in Google''s cloud infrastructure, providing screenshots, logs, video recordings, and crash reports.\n\n**Primary Test Device:** Pixel 10 Pro Fold (codename `rango`, API 36, physical device)\n\n## Core Commands\n\n### 1. Running Robo Tests (No Test Code Required)\n\nRobo tests automatically crawl the app UI and detect crashes,","body":"# Firebase Test Lab Specialist\n\n## Overview\n\nFirebase Test Lab is the primary testing mechanism for the Dragon Scale VPN project. It runs tests on real and virtual Android devices in Google''s cloud infrastructure, providing screenshots, logs, video recordings, and crash reports.\n\n**Primary Test Device:** Pixel 10 Pro Fold (codename `rango`, API 36, physical device)\n\n## Core Commands\n\n### 1. Running Robo Tests (No Test Code Required)\n\nRobo tests automatically crawl the app UI and detect crashes, layout issues, and ANRs.\n\n```bash\n# Primary: Pixel 10 Pro Fold (user''s actual device)\ngcloud firebase test android run --type=robo \\\n  --app=dragon-scale-vpn/app/build/outputs/apk/debug/app-debug.apk \\\n  --device \"model=rango,version=36,locale=en,orientation=portrait\" \\\n  --timeout=300s --project=cloud-vpn-12110\n\n# Secondary: Medium Phone virtual device (API 34, fast feedback)\ngcloud firebase test android run --type=robo \\\n  --app=dragon-scale-vpn/app/build/outputs/apk/debug/app-debug.apk \\\n  --device \"model=MediumPhone.arm,version=34\" \\\n  --timeout=300s --project=cloud-vpn-12110\n\n# Full matrix: Pixel 10 Pro Fold + Medium Phone + Pixel Fold (legacy foldable)\ngcloud firebase test android run --type=robo \\\n  --app=dragon-scale-vpn/app/build/outputs/apk/debug/app-debug.apk \\\n  --device \"model=rango,version=36\" \\\n  --device \"model=MediumPhone.arm,version=34\" \\\n  --device \"model=felix,version=34\" \\\n  --timeout=300s --project=cloud-vpn-12110\n```\n\n### 2. Running Instrumentation Tests\n\nFor targeted verification of specific features (GeoIP, NetworkMonitor, etc.).\n\n```bash\n# Build test APK first\n$env:JAVA_HOME = \"C:\\Program Files\\Android\\Android Studio\\jbr\"\n.\\gradlew assembleDebug assembleDebugAndroidTest\n\n# Run on Pixel 10 Pro Fold\ngcloud firebase test android run --type=instrumentation \\\n  --app=dragon-scale-vpn/app/build/outputs/apk/debug/app-debug.apk \\\n  --test=dragon-scale-vpn/app/build/outputs/apk/androidTest/debug/app-debug-androidTest.apk \\\n  --device \"model=rango,version=36\" \\\n  --timeout=600s --project=cloud-vpn-12110\n```\n\n### 3. Viewing Results\n\n```bash\n# List recent test runs\ngcloud firebase test android list --project=cloud-vpn-12110\n\n# Get detailed results (URL provided after test run)\ngcloud firebase test android results describe <TEST_MATRIX_ID> --project=cloud-vpn-12110\n```\n\n## Device Matrix\n\n| Priority | Model ID | Device Name | API | Type |\n|----------|----------|-------------|-----|------|\n| **Primary** | `rango` | Pixel 10 Pro Fold | 36 | Physical |\n| Secondary | `MediumPhone.arm` | Medium Phone 6.4\" | 34 | Virtual |\n| Foldable Legacy | `felix` | Pixel Fold | 34 | Physical |\n\n## Testing Strategy for Dragon Scale VPN\n\n### What Firebase CAN Test\n- **UI rendering** — Compose layouts, foldable adaptations, theme colors\n- **GeoIP fetch logic** — Network calls to ipapi.co (no VPN bypass needed)\n- **App stability** — Crash detection, ANR detection, memory leaks\n- **Navigation** — Drawer menu, pager swipes, button states\n- **Registration flow** — API calls to control plane (mock or real)\n- **Foldable posture** — Fold/unfold behavior on Pixel 10 Pro Fold\n\n### What Firebase CANNOT Test\n- **Active VPN tunnel** — `VpnService.prepare()` shows a system dialog that can''t be auto-dismissed\n- **VPN bypass networking** — Requires an active WireGuard tunnel\n- **Download/upload stats** — Requires live tunnel traffic\n\n## Integration with Dev Workflow\n\n### The Verification Gate\n\nWhen changes impact UI, networking, or stability:\n\n```bash\n# 1. Build APK\n$env:JAVA_HOME = \"C:\\Program Files\\Android\\Android Studio\\jbr\"; .\\gradlew assembleDebug\n\n# 2. Run robo test on Pixel 10 Pro Fold\ngcloud firebase test android run --type=robo \\\n  --app=dragon-scale-vpn/app/build/outputs/apk/debug/app-debug.apk \\\n  --device \"model=rango,version=36\" --project=cloud-vpn-12110\n\n# 3. Review the results URL in the output\n```\n\n### Senior Decision Logic\n\n1. **Discovery (Gemini):** Architect determines the minimal change required.\n2. **Implementation (Gemini):** Execute code changes locally.\n3. **Verification (Firebase):** Run robo/instrumentation tests on Pixel 10 Pro Fold to validate.\n4. **Manual Verification:** Sideload APK on physical Pixel 10 Pro Fold for VPN-specific testing.\n5. **Deployment:** Only push to GitHub after both automated and manual verification pass.\n"},"lastSynced":"2026-03-07T04:05:07.249Z","agentAnalysis":{"suitability":{"en":"Perfect for Mobile App Testing Agents needing comprehensive Android app testing on real and virtual devices","zh":"适合需要在真实和虚拟设备上进行全面Android应用测试的移动应用测试代理","ja":"モバイルアプリテストエージェントが実際のデバイスと仮想デバイスでの包括的なAndroidアプリテストを必要とする場合に最適","ko":"실제 기기와 가상 기기에서 종합적인 Android 앱 테스트가 필요한 모바일 앱 테스트 에이전트에게 적합","es":"Perfecto para agentes de prueba de aplicaciones móviles que necesitan pruebas de aplicaciones de Android integrales en dispositivos reales y virtuales","fr":"Parfait pour les agents de test d''applications mobiles ayant besoin de tests d''applications Android complets sur des appareils réels et virtuels","de":"Perfekt für Mobile App-Testagenten, die umfassende Android-App-Tests auf realen und virtuellen Geräten benötigen","pt":"Perfeito para Agentes de Teste de Aplicativos Móveis que necessitam de testes de aplicativos Android abrangentes em dispositivos reais e virtuais","ru":"Идеально подходит для агентов тестирования мобильных приложений, которым необходимы всесторонние тесты приложений Android на реальных и виртуальных устройствах","ar":"مثالي لعميل اختبار التطبيقات المحمولة التي تحتاج إلى اختبار تطبيقات Android الشامل على الأجهزة الحقيقية والافتراضية"},"recommendation":{"en":"Empowers agents to run Robo tests on Firebase Test Lab, providing valuable insights and crash reports through screenshots, logs, video recordings, and crash reports, utilizing Google''s cloud infrastructure and API 36","zh":"赋予代理运行Firebase Test Lab上的Robo测试的能力，通过截图、日志、视频录制和崩溃报告提供有价值的见解，利用Google的云基础设施和API 36","ja":"Firebase Test Lab上でRoboテストを実行するエージェントの能力を提供し、スクリーンショット、ログ、ビデオレコーディング、クラッシュレポートを通じて貴重な洞察を提供し、GoogleのクラウドインフラストラクチャとAPI 36を利用","ko":"에이전트가 Firebase Test Lab에서 Robo 테스트를 실행하는 능력을 부여하여 스크린샷, 로그, 비디오 녹화 및 충돌 보고서를 통해 유용한 통찰력을 제공하고 Google의 클라우드 인프라 및 API 36을 활용","es":"Habilita a los agentes a ejecutar pruebas de Robo en Firebase Test Lab, proporcionando información valiosa y informes de errores a través de capturas de pantalla, registros, grabaciones de video y informes de errores, utilizando la infraestructura en la nube de Google y API 36","fr":"Permet aux agents d''exécuter des tests Robo sur Firebase Test Lab, fournissant des informations précieuses et des rapports de plantage via des captures d''écran, des journaux, des enregistrements vidéo et des rapports de plantage, en utilisant l''infrastructure cloud de Google et l''API 36","de":"Ermöglicht es den Agenten, Robo-Tests auf Firebase Test Lab auszuführen und wertvolle Einblicke und Absturzberichte durch Screenshots, Protokolle, Videoaufzeichnungen und Absturzberichte bereitzustellen, wobei die Cloud-Infrastruktur von Google und API 36 verwendet wird","pt":"Habilita os agentes a executar testes Robo no Firebase Test Lab, fornecendo insights valiosos e relatórios de falhas por meio de capturas de tela, logs, gravações de vídeo e relatórios de falhas, utilizando a infraestrutura em nuvem do Google e a API 36","ru":"Наделяет агентов возможностью запускать тесты Robo в Firebase Test Lab, предоставляя ценные сведения и отчеты о сбоях через скриншоты, журналы, видеозаписи и отчеты о сбоях, используя облачную инфраструктуру Google и API 36","ar":"تمكين الوكيل من تشغيل الاختبارات الروبوتية في معمل الاختبار فيرايباس، وتقديم معلومات قيمة وتقارير عن الأعطال من خلال لقطات الشاشة وسجلات وتسجيلات الفيديو وتقارير الأعطال، باستخدام بنية تحتية سحابية من جوجل و API 36"},"useCases":{"en":["Automating Android app testing on physical devices like Pixel 10 Pro Fold","Generating crash reports and video recordings for app debugging","Validating app UI through Robo tests on virtual Android devices"],"zh":["在像Pixel 10 Pro Fold这样的物理设备上自动化Android应用测试","为应用程序调试生成崩溃报告和视频录制","通过虚拟Android设备上的Robo测试验证应用程序UI"],"ja":["Pixel 10 Pro Foldのような物理デバイスでのAndroidアプリテストの自動化","アプリデバッグのためのクラッシュレポートとビデオレコーディングの生成","仮想AndroidデバイスでのRoboテストによるアプリUIの検証"],"ko":["Pixel 10 Pro Fold와 같은 물리적 기기에서 Android 앱 테스트 자동화","애플리케이션 디버깅을 위한 충돌 보고서 및 비디오 녹화 생성","가상 Android 기기에서 Robo 테스트를 통해 애플리케이션 UI 유효성 검사"],"es":["Automatizar las pruebas de aplicaciones de Android en dispositivos físicos como Pixel 10 Pro Fold","Generar informes de errores y grabaciones de video para depurar aplicaciones","Validar la interfaz de usuario de la aplicación a través de pruebas de Robo en dispositivos virtuales de Android"],"fr":["Automatiser les tests d''applications Android sur des appareils physiques comme le Pixel 10 Pro Fold","Générer des rapports de plantage et des enregistrements vidéo pour déboguer les applications","Valider l''interface utilisateur de l''application via des tests Robo sur des appareils virtuels Android"],"de":["Automatisieren von Android-App-Tests auf physischen Geräten wie Pixel 10 Pro Fold","Generieren von Absturzberichten und Videoaufzeichnungen für die App-Debugging","Validieren der Benutzeroberfläche der App durch Robo-Tests auf virtuellen Android-Geräten"],"pt":["Automatizar testes de aplicativos Android em dispositivos físicos como o Pixel 10 Pro Fold","Gerar relatórios de falhas e gravações de vídeo para depuração de aplicativos","Validar a interface do usuário do aplicativo por meio de testes Robo em dispositivos Android virtuais"],"ru":["Автоматизировать тестирование приложений Android на физических устройствах, таких как Pixel 10 Pro Fold","Генерировать отчеты о сбоях и видеозаписи для отладки приложений","Проверять интерфейс пользователя приложения с помощью тестов Robo на виртуальных устройствах Android"],"ar":["تحسين اختبارات تطبيقات Android على الأجهزة المادية مثل Pixel 10 Pro Fold","توليد تقارير عن الأعطال وتسجيلات الفيديو لتصحيح الأخطاء في التطبيقات","التحقق من واجهة المستخدم للتطبيق من خلال الاختبارات الروبوتية على أجهزة Android الافتراضية"]},"limitations":{"en":["Requires Google cloud infrastructure access","Limited to Android app testing","Dependent on Firebase Test Lab services"],"zh":["需要Google云基础设施访问","仅限Android应用测试","依赖于Firebase Test Lab服务"],"ja":["Googleクラウドインフラストラクチャへのアクセスが必要","Androidアプリテストのみに限定","Firebase Test Labサービスに依存"],"ko":["Google 클라우드 인프라에 접근이 필요","Android 앱 테스트만으로 제한","Firebase Test Lab 서비스에 의존"],"es":["Requiere acceso a la infraestructura en la nube de Google","Limitado a pruebas de aplicaciones de Android","Dependiente de los servicios de Firebase Test Lab"],"fr":["Nécessite un accès à l''infrastructure cloud de Google","Limité aux tests d''applications Android","Dépendant des services de Firebase Test Lab"],"de":["Benötigt Zugriff auf die Cloud-Infrastruktur von Google","Begrenzt auf Android-App-Tests","Abhängig von den Diensten von Firebase Test Lab"],"pt":["Requer acesso à infraestrutura em nuvem do Google","Limitado ao teste de aplicativos Android","Dependente dos serviços do Firebase Test Lab"],"ru":["Требует доступа к облачной инфраструктуре Google","Ограничен тестированием приложений Android","Зависит от сервисов Firebase Test Lab"],"ar":["يتطلب الوصول إلى البنية التحتية السحابية لجوجل","محدود باختبار تطبيقات Android","يعتمد على خدمات معمل الاختبار فيرايباس"]},"version":4},"contentHash":"1064f42828c46e31c0c239493e1d59e04405056660fe3c0b4a7f5870b8e299b1","qualityScore":39}');
