INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dawink5674/sovereign-vpn-core/Firebase Test Lab Specialist', 'Firebase Test Lab Specialist', 'dawink5674', 'sovereign-vpn-core', 'community', 'Firebase Test Lab Specialist dawink5674 sovereign-vpn-core community Firebase Test Lab Specialist helps developers test their apps on real and virtual Android devices, providing valuable insights and crash reports. It benefits developers working on Android apps, especially those using Google''s cloud infrastructure. Firebase Test Lab Specialist 是一个用于测试 Android 应用的工具，支持 Robo 测试和虚拟设备测试 Firebase Test Lab Specialist は Android アプリをテストするツールです - Robo テストと仮想デバイス テストに対応 Firebase Test Lab Specialist 는 안드로이드 애플리케이션을 테스트하는 도구로서 Robo 테스트와 가상 디바이스 테스트를 지원합니다 Firebase Test Lab es un mecanismo de testing para aplicaciones en dispositivos Android, proporcionando capturas de pantalla, registros y grabaciones de video Firebase Test Lab est un mécanisme de test pour les applications sur les appareils Android, fournissant des captures d''écran, des journaux et des enregistrements vidéo Firebase Test Lab ist ein Testmechanismus für Anwendungen auf Android-Geräten, der Screenshots, Protokolle und Videoaufzeichnungen bereitstellt O Firebase Test Lab Specialist é uma ferramenta de teste para aplicativos que roda testes em dispositivos reais e virtuais da Google. Firebase Test Lab Specialist - это инструмент для тестирования приложений, который запускает тесты на реальных и виртуальных устройствах Google. Firebase Test Lab Specialist هو أداة اختبار للتطبيقات التي تعمل على تشغيل الاختبارات على أجهزة حقيقية وافتراضية من جوجل how to use Firebase Test Lab Specialist Firebase Test Lab Specialist setup guide Firebase Test Lab Specialist alternative Firebase Test Lab Specialist vs Appium what is Firebase Test Lab Specialist Firebase Test Lab Specialist install Robo test automation Android app testing on Google cloud Firebase Test Lab Specialist tutorial optimizing app performance with Firebase Test Lab Specialist Firebase Test Lab Specialist Robo 测试 虚拟设备测试 Google 云基础设施 API 36 物理设备测试 AI工具 测试工具 Android 测试 Runs Robo tests on real and virtual Android devices Provides screenshots, logs, video recordings, and crash reports for app testing Supports testing on physical devices like Pixel 10 Pro Fold Automatically crawls app UI and detects crashes using Robo tests Generates valuable insights for app development and optimization Utilizes Google''s cloud infrastructure for scalable testing Firebase Test Lab Specialist is a testing mechanism that runs tests on real and virtual Android devices, providing screenshots, logs, video recordings, and crash reports for app development and optimization');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('co-r-e/dexcode/graphic-recording', 'community', 'co-r-e', 'dexcode', 'co-r-e/dexcode', 'graphic-recording', 0, 0, 39, '2026-03-02T19:35:01Z', '2026-03-07T04:07:19.781Z', '63a20f41e22047312789f75a9fd1cbda7001054a767d814fa9976afaf8caaa7a', '{"id":"co-r-e/dexcode/graphic-recording","name":"graphic-recording","description":{"en":"The graphic-recording skill generates visual note illustrations from slide content using MDX and NextJS. It benefits developers creating engaging presentations.","zh":"图形记录技能用于生成图形记录风格的视觉笔记插图，从MDX内容开始。它重用了nanobanana-image技能的生成脚本","ja":"グラフィックレコーディングスキルは、MDXコンテンツからグラフィックレコーディングスタイルのビジュアルノートイラストを生成します。nanobanana-imageスキルの生成スクリプトを再利用します","ko":"그래픽 녹음 스킬은 MDX 콘텐츠에서 그래픽 녹음 스타일의 시각적 노트 삽화를 생성합니다. nanobanana-image 스킬의 생성 스크립트를 재사용합니다","es":"El entorno de creación de diapositivas de AI permite a los desarrolladores generar ilustraciones de notas visuales en estilo de grabación gráfica","fr":"L''environnement de création de diapositives IA permet aux développeurs de générer des illustrations de notes visuelles dans un style d''enregistrement graphique","de":"Die Umgebung für die Erstellung von KI-Präsentationen ermöglicht es Entwicklern, visuelle Notizen im Stil der grafischen Aufzeichnung zu generieren","pt":"O graphic-recording é um ambiente de criação de slides de IA para desenvolvedores que gera ilustrações de notas visuais a partir do conteúdo do slide.","ru":"Graphic-recording - это среда создания слайдов ИИ для разработчиков, которая генерирует иллюстрации визуальных заметок из содержимого слайда.","ar":"graphic-recording هو بيئة إنشاء شرائح_IA ل المطورين التي تولد رسومات ملاحظات بصرية من محتوى الشرائح."},"seo":{"title":{"en":"graphic-recording: AI Slide Creation Environment Setup Gu...","zh":"图形记录技能搭建指南 - AI Slide 创建环境","ja":"グラフィックレコーディングスキル設定ガイド - AIエージェントによるスライド作成環境","ko":"그래픽 녹음 스킬