INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('co-r-e/dexcode/graphic-recording', 'graphic-recording', 'co-r-e', 'dexcode', 'community', 'graphic-recording co-r-e dexcode community ai mdx nextjs presentation slides The graphic-recording skill generates visual note illustrations from slide content using MDX and NextJS. It benefits developers creating engaging presentations. 图形记录技能用于生成图形记录风格的视觉笔记插图，从MDX内容开始。它重用了nanobanana-image技能的生成脚本 グラフィックレコーディングスキルは、MDXコンテンツからグラフィックレコーディングスタイルのビジュアルノートイラストを生成します。nanobanana-imageスキルの生成スクリプトを再利用します 그래픽 녹음 스킬은 MDX 콘텐츠에서 그래픽 녹음 스타일의 시각적 노트 삽화를 생성합니다. nanobanana-image 스킬의 생성 스크립트를 재사용합니다 El entorno de creación de diapositivas de AI permite a los desarrolladores generar ilustraciones de notas visuales en estilo de grabación gráfica L''environnement de création de diapositives IA permet aux développeurs de générer des illustrations de notes visuelles dans un style d''enregistrement graphique Die Umgebung für die Erstellung von KI-Präsentationen ermöglicht es Entwicklern, visuelle Notizen im Stil der grafischen Aufzeichnung zu generieren O graphic-recording é um ambiente de criação de slides de IA para desenvolvedores que gera ilustrações de notas visuais a partir do conteúdo do slide. Graphic-recording - это среда создания слайдов ИИ для разработчиков, которая генерирует иллюстрации визуальных заметок из содержимого слайда. graphic-recording هو بيئة إنشاء شرائح_IA ل المطورين التي تولد رسومات ملاحظات بصرية من محتوى الشرائح. how to use graphic-recording graphic-recording setup guide MDX slide content visualization NextJS presentation creation graphic-recording alternative graphic-recording vs nanobanana-image install graphic-recording graphic-recording AI skill what is graphic-recording 图形记录技能 AI驱动的工具 MDX内容生成 Next.js集成 nanobanana-image技能 GEMINI_API_KEY环境变量 图形记录风格的视觉笔记插图 Reuses nanobanana-image skill''s generation scripts Supports MDX file content visualization Identifies target slide and insertion target Requires GEMINI_API_KEY set in .env.local Works with NextJS for presentation creation Generates graphic recording style visual note illustrations graphic-recording is a skill that generates graphic recording style visual note illustrations from slide content using AI technology');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('bitovi/context-generation-mvp/3-identifying-architecture', 'community', 'bitovi', 'context-generation-mvp', 'bitovi/context-generation-mvp', '3-identifying-architecture', 0, 0, 39, '2026-01-02T18:13:47Z', '2026-03-07T04:07:33.536Z', '28397b8eb89941c05c9f25e93b0558abb4530d3ac4d20ef914fbedd194d3c17c', '{"id":"bitovi/context-generation-mvp/3-identifying-architecture","name":"3-identifying-architecture","description":{"en":"3-identifying-architecture analyzes codebases to understand their structure and major concerns, benefiting developers and architects. It reviews tech stacks and categorized files for accurate results.","zh":"分析代码库以了解其结构和主要关注点，使用 tech stack 和文件分类来实现准确和完整的分析","ja":"コードベースを分析してその構造と主な懸念事項を理解し、tech stack とファイル分類を使用して正確な分析を実行します","ko":"코드베이스를 분석하여その 구조와 주요 관심사를 이해하고 tech stack과 파일 분류를 사용하여 정확한 분석을 수행합니다","es":"Esta habilidad permite analizar un codebase para entender su estructura y principales preocupaciones, utilizando un resumen de la pila tecnológica y categorización de archivos","fr":"Cette compétence permet d''analyser un codebase pour comprendre sa structure et ses principales préoccupations, en utilisant un résumé de la pile technologique et une catégorisation de fichiers","de":"Diese Fähigkeit ermöglicht die Analyse eines Codebases, um dessen Struktur und Hauptanliegen zu verstehen, unter Verwendung einer Zusammenfassung des Technologie-Stacks und einer Kategorisierung von Dateien","pt":"O skill 3-identifying-architecture é usado para analisar a estrutura de um código e identificar preocupações principais","ru":"Навык 3-identifying-architecture используется для анализа структуры кода и определения основных проблем","ar":"المهارة 3-identifying-architecture تستخدم لتحليل هيكل الكود وتحديد المخاوف الرئيسية"},"seo":{"title":{"en":"3-identifying-architecture: Codebase Analysis Setup Guide...","zh":"3-identifying-architecture 代码结构分析 Setup Guide","ja":"3-identifying-architecture コード構造分析ベストプラクティス - AIエージェント","ko":"3-identifying-architecture 코드 구조 분석 가이드 - AI 도구","es":"Guía de configuración para identificar arquitectura de có...","fr":"Guide de configuration pour identifier l''architecture de ...","de":"Konfigurationsleitfaden zur Identifizierung von Code-Arch...","pt":"Guia de Configuração para Identificação de Arquitetura de...","ru":"Настройка ИИ Агентов для Определения Архитектуры Кодовой ...","ar":"دليل إعداد وكيل الذكاء الاصطناعي لتحديد بنية الكود"},"description":{"en":"Unlock the structure of your codebase with 3-identifying-architecture. Review tech stacks and categorized files with ease. Get started now!","zh":"了解代码结构和主要关注点，使用 tech stack 和文件分类来分析代码库，实现准确和完整的分析","ja":"コード構造と主な懸念事項を理解するために、tech stack とファイル分類を使用してコードベースを分析します - AIエージェント","ko":"코드 구조와 주요 관심사를 이해하기 위해 tech stack과 파일 분류를 사용하여 코드베이스를 분석합니다 - AI 도구","es":"Aprende a analizar la estructura de un codebase y sus principales preocupaciones con nuestra guía de identificación de arquitectura","fr":"Découvrez comment analyser la structure d''un codebase et ses principales préoccupations avec notre guide d''identification d''architecture","de":"Erfahren Sie, wie Sie die Struktur eines Codebases und seine Hauptanliegen mit unserem Architektur-Identifizierungsleitfaden analysieren","pt":"Aprenda a configurar um agente de IA para identificar a arquitetura de um código com precisão e completude","ru":"Узнайте, как настроить ИИ Агент для определения архитектуры кодовой базы с точностью и полнотой","ar":"تعلم كيفية設定 وكيل الذكاء الاصطناعي لتحديد بنية الكود بدقة واكتمال"},"definition":{"en":"3-identifying-architecture is a code analysis skill that reviews tech stacks and categorized files to understand codebase structure and major concerns.","zh":"代码结构分析是了解代码库结构和主要关注点的过程","ja":"コード構造分析は、コードベースの構造と主な懸念事項を理解するプロセスです","ko":"코드 구조 분석은 코드베이스의 구조와 주요 관심사를 이해하는 과정입니다","es":"La identificación de arquitectura es el proceso de analizar un codebase para entender su estructura y principales preocupaciones","fr":"L''identification d''architecture est le processus d''analyse d''un codebase pour comprendre sa structure et ses principales préoccupations","de":"Die Architektur-Identifizierung ist der Prozess der Analyse eines Codebases, um dessen Struktur und Hauptanliegen zu verstehen","pt":"O que é identificação de arquitetura de código? É o processo de análise da estrutura de um código para entender sua organização","ru":"Что такое определение архитектуры кодовой базы? Это процесс анализа структуры кода для понимания его организации","ar":"ما هو تحديد بنية الكود؟ هو عملية تحليل هيكل الكود لفهم تنظيمه"},"features":{"en":["Reviews tech stacks summarized in ./{output-folder}/1-techstack.md","Analyzes categorized files listed in ./{output-folder}/2-file-categorization.json","Permits thorough review of codebase without time constraints","Ensures accuracy and completeness of results","Supports detailed analysis of codebase structure and major concerns"],"zh":["使用 tech stack 分析代码库","文件分类来识别代码结构","实现准确和完整的分析","支持长时间运行以确保准确性","不跳过文件或产生部分结果"],"ja":["tech stack を使用してコードベースを分析します","ファイル分類を使用してコード構造を識別します","正確な分析を実行します","長時間の実行をサポートして正確性を確保します","ファイルをスキップせず、部分的な結果を生成しません"],"ko":["tech stack을 사용하여 코드베이스를 분석합니다","파일 분류를 사용하여 코드 구조를 식별합니다","정확한 분석을 수행합니다","長時間의 실행을 지원하여 정확성을 보장합니다","파일을 생략하지 않고 부분적인 결과를 생성하지 않습니다"],"es":["Análisis de la estructura del codebase","Resumen de la pila tecnológica en un archivo JSON","Categorización de archivos en un formato JSON","Permite la revisión detallada de todos los archivos sin omitir ninguno","No requiere un tiempo límite para la análisis","Proporciona resultados precisos y completos"],"fr":["Analyse de la structure du codebase","Résumé de la pile technologique dans un fichier JSON","Catégorisation de fichiers dans un format JSON","Permet la révision détaillée de tous les fichiers sans en omettre aucun","N''a pas de limite de temps pour l''analyse","Fournit des résultats précis et complets"],"de":["Analyse der Struktur des Codebases","Zusammenfassung des Technologie-Stacks in einer JSON-Datei","Kategorisierung von Dateien im JSON-Format","Ermöglicht die detaillierte Überprüfung aller Dateien ohne Auslassung","Hat keine Zeitbegrenzung für die Analyse","Bietet präzise und vollständige Ergebnisse"],"pt":["Análise de código com precisão e completude","Identificação de tecnologias utilizadas no código","Categorização de arquivos em formato JSON","Suporte a revisão de código sem limites de tempo ou complexidade"],"ru":["Анализ кода с точностью и полнотой","Определение технологий, используемых в коде","Категоризация файлов в формате JSON","Поддержка ревизии кода без ограничений по времени или сложности"],"ar":["تحليل الكود بدقة واكتمال","تحديد التكنولوجيا المستخدمة في الكود","تصنيف الملفات بالشكل JSON","دعم مراجعة الكود بدون قيود زمنية أو تعقيد"]},"keywords":{"en":["how to use 3-identifying-architecture","what is 3-identifying-architecture","3-identifying-architecture alternative","3-identifying-architecture vs code analysis tools","3-identifying-architecture install","3-identifying-architecture setup guide","codebase analysis with 3-identifying-architecture","understanding code structure with 3-identifying-architecture"],"zh":["代码结构分析","tech stack","文件分类","代码库分析","AI工具","代码结构理解"],"ja":["コード構造分析","tech stack","ファイル分類","コードベース分析","AIエージェント","コード構造理解"],"ko":["코드 구조 분석","tech stack","파일 분류","코드베이스 분석","AI 도구","코드 구조 이해"],"es":["identificar arquitectura de código","análisis de codebase","Herramientas de Inteligencia Artificial","pila tecnológica","categorización de archivos","revisión de código","análisis de estructura","desarrollo de software","ingeniería de software"],"fr":["identifier l''architecture de code","analyse de codebase","Outils d''Intelligence Artificielle","pile technologique","catégorisation de fichiers","révision de code","analyse de structure","développement de logiciels","ingénierie de logiciels"],"de":["Identifizierung von Code-Architektur","Analyse von Codebases","KI-Tools","Technologie-Stack","Kategorisierung von Dateien","Code-Überprüfung","Strukturanalyse","Software-Entwicklung","Software-Ingenieurwesen"],"pt":["identificação de arquitetura de código","análise de código","tecnologias de código","categorização de arquivos","revisão de código","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["определение архитектуры кодовой базы","анализ кода","технологии кода","категоризация файлов","ревизия кода","разработка программного обеспечения","инструменты разработки"],"ar":["تحديد بنية الكود","تحليل الكود","تكنولوجيا الكود","تصنيف الملفات","مراجعة الكود","تطوير البرمجيات","أدوات التطوير"]}},"owner":"bitovi","repo":"context-generation-mvp","repoPath":"bitovi/context-generation-mvp","stars":0,"forks":0,"updatedAt":"2026-01-02T18:13:47Z","topics":[],"category":"community","skillMd":{"name":"3-identifying-architecture","description":"Third step in building instruction context for codebase","bodyPreview":"You''re analyzing a codebase with the goal of understanding its structure and major concerns. The tech stack is summarized in ./{output-folder}/1-techstack.md. Categorized files are listed in ./{output-folder}/2-file-categorization.json.\n\n> This task may take some time — that is expected and acceptable.\n> Do **not** skip files or produce partial results due to time or complexity. Accuracy and completeness are **mission-critical**.\n> You are permitted to take as long as necessary to:\n>\n> - Review","body":"You''re analyzing a codebase with the goal of understanding its structure and major concerns. The tech stack is summarized in ./{output-folder}/1-techstack.md. Categorized files are listed in ./{output-folder}/2-file-categorization.json.\n\n> This task may take some time — that is expected and acceptable.\n> Do **not** skip files or produce partial results due to time or complexity. Accuracy and completeness are **mission-critical**.\n> You are permitted to take as long as necessary to:\n>\n> - Review every relevant file\n> - Extract actual patterns and conventions\n> - Produce complete, high-fidelity output\n>   If a file is listed in ./{output-folder}/2-file-categorization.json or is part of a relevant domain, it **must** be included in your analysis.\n>   Do not optimize for speed or brevity. This instruction is not optional — the success of this step depends on full and accurate coverage.\n\nYour Task:\nDetermine which architectural domains are present in the project. Consider:\n\n- File structure and naming patterns\n- Framework conventions\n- Imports and usage patterns\n- Configuration files\n- Common architectural markers (e.g., components/, routes/, handlers/, services/, cli/, etc.)\n\n**Critical Analysis - Mandatory vs Optional Patterns:**\nFor each domain you identify, determine:\n\n- **REQUIRED**: Which services/hooks/patterns are consistently used across the codebase and appear to be architectural requirements?\n- **CONSTRAINTS**: What types of implementations are clearly expected? (e.g., \"all canvas work uses useCanvas hook\", \"all fractals use chaos game algorithms\")\n\nExample Domains to Detect:\nYou do not need to detect all of these — only include what''s truly present.\nThere may also be domains that aren''t listed here but are relevant to this specific project. Include any meaningful domains you identify.\n\nExamples:\n\n- ui: UI components, templates, or rendering logic\n- routing: App or API routing (e.g., Next.js routes, Express routers)\n- design-system: Shared visual styling patterns or design tokens\n- state-management: Any centralized or global state (Redux, Zustand, Context, etc.)\n- data-layer: Persistence and data-fetching (ORMs, REST clients, GraphQL)\n- auth: Authentication / access control logic\n\nOutput:\nWrite a JSON object to ./{output-folder}/3-architectural-domains.json like so:\n\n```json\n{\n  \"ui\": {\n    \"required_patterns\": {\n      \"canvas-rendering\": \"use useCanvas\",\n      \"mathematical-computing\": \"...\"\n    },\n    \"architectural_constraints\": {\n      \"canvas-rendering\": \"...\",\n      \"mathematical-computing\": \"...\"\n    }\n  }\n}\n```\n\nOnly include domains you find concrete evidence for based on the actual codebase.\n\nThis analysis will help ensure future additions follow the established architectural patterns rather than introducing inconsistent approaches.\n\nYou are a senior developer responsible for categorizing every file in the codebase. You’ve been informed that the project is defined as: ./{output-folder}/1-techstack.md (read this file first)\n\nAfter writing ./{output-folder}/3-file-categorization.json, continue to skill 4-domain-deep-dive and proceed accordingly with {output-folder} as the `output-folder`."},"lastSynced":"2026-03-07T04:07:33.536Z","agentAnalysis":{"suitability":{"en":"Ideal for Code Analysis Agents requiring comprehensive tech stack review and file categorization capabilities.","zh":"适用于需要对技术堆栈进行全面审查和文件分类的代码分析代理。","ja":"技術スタックの総合的なレビューとファイルのカテゴリ化の機能が必要なコード分析エージェントに最適です。","ko":"기술 스택에 대한 종합적인 검토 및 파일 분류 기능이 필요한 코드 분석 에이전트에 적합합니다.","es":"Ideal para Agentes de Análisis de Código que requieren una revisión exhaustiva de la pila tecnológica y capacidades de categorización de archivos.","fr":"Idéal pour les Agents d''Analyse de Code nécessitant un examen approfondi de la pile technologique et des capacités de catégorisation de fichiers.","de":"Ideal für Code-Analyse-Agents, die eine umfassende Tech-Stack-Überprüfung und Dateikategorisierungsfunktionen erfordern.","pt":"Ideal para Agentes de Análise de Código que requerem uma revisão abrangente da pilha de tecnologias e capacidades de categorização de arquivos.","ru":"Идеально подходит для Агентов анализа кода, требующих всестороннего обзора технологического стека и возможностей категоризации файлов.","ar":"مثالي لعمليات تحليل الشفرة التي تتطلب مراجعة شاملة للتقنيات وتمكين تصنيف الملفات."},"recommendation":{"en":"Empowers agents to thoroughly review codebases by analyzing tech stacks summarized in .md files and categorized files listed in .json formats, ensuring accurate and complete results through meticulous review of files without skipping or producing partial results.","zh":"使代理能够通过分析以 .md 文件和以 .json 格式列出的分类文件中总结的技术堆栈来彻底审查代码库，确保通过对文件的仔细审查而不跳过或产生部分结果，从而获得准确和完整的结果。","ja":"エージェントが.md ファイルと.json 形式のリストに分類されたファイルに要約されたテクノロジー スタックを分析することでコードベースを徹底的にレビューできるようにし、ファイルの抜け落ちや一部の結果を生成せずに、詳細なレビューを通じて正確で完全な結果を取得します。","ko":"에이전트가 .md 파일과 .json 형식의 목록에 분류된 파일에 요약된 기술 스택을 분석하여 코드베이스를 철저하게 검토할 수 있도록 하여 파일을 누락시키지 않고 부분 결과를 생성하지 않고 철저한 검토를 통해 정확하고 완전한 결과를 얻을 수 있습니다.","es":"Permite a los agentes revisar exhaustivamente las bases de código analizando las pilas tecnológicas resumidas en archivos .md y los archivos categorizados enumerados en formatos .json, garantizando resultados precisos y completos a través de una revisión minuciosa de los archivos sin omitir o producir resultados parciales.","fr":"Permet aux agents d''examiner soigneusement les bases de code en analysant les piles technologiques résumées dans des fichiers .md et les fichiers catégorisés énumérés dans des formats .json, garantissant des résultats précis et complets grâce à un examen attentif des fichiers sans les omettre ou produire des résultats partiels.","de":"Ermöglicht es den Agenten, Codebasen gründlich zu überprüfen, indem sie die in .md-Dateien zusammengefassten Technologiestacks und die in .json-Formaten aufgelisteten kategorisierten Dateien analysieren, und stellt so durch eine sorgfältige Überprüfung der Dateien ohne Auslassungen oder Teilergebnisse genaue und vollständige Ergebnisse sicher.","pt":"Permite que os agentes revisem minuciosamente as bases de código analisando pilhas de tecnologias resumidas em arquivos .md e arquivos categorizados listados em formatos .json, garantindo resultados precisos e completos por meio de uma revisão minuciosa dos arquivos sem pular ou produzir resultados parciais.","ru":"Позволяет агентам тщательно просматривать кодовые базы, анализируя технологические стеки, суммированные в файлах .md, и категоризированные файлы, перечисленные в форматах .json, обеспечивая точные и полные результаты благодаря тщательному просмотру файлов без пропуска или получения частичных результатов.","ar":"تمكن الوكلاء من استعراض شفرات البرامج بدقة من خلال تحليل مجموعة التقنيات الموجزة في ملفات .md والملفات المصنفة المحددة في تنسيقات .json، مما يضمن نتائج دقيقة وكاملة من خلال استعراض دقيق للملفات دون تخطي أو إنتاج نتائج جزئية."},"useCases":{"en":["Analyzing code structure for major concerns","Reviewing tech stacks for optimization opportunities","Categorizing files for efficient project organization"],"zh":["分析代码结构以识别主要问题","审查技术堆栈以找出优化机会","分类文件以实现项目的高效组织"],"ja":["メジャーな懸念に対するコード構造の分析","最適化の機会を探すためのテクノロジー スタックのレビュー","効率的なプロジェクト組織のためのファイルのカテゴリ化"],"ko":["주요 문제를 식별하기 위한 코드 구조 분석","최적화 기회를 찾기 위한 기술 스택 검토","효율적인 프로젝트 조직을 위한 파일 분류"],"es":["Analizar la estructura del código para preocupaciones importantes","Revisar las pilas tecnológicas para oportunidades de optimización","Categorizar archivos para una organización de proyectos eficiente"],"fr":["Analyser la structure du code pour les préoccupations majeures"," Examiner les piles technologiques pour les opportunités d''optimisation","Catégoriser les fichiers pour une organisation de projet efficace"],"de":["Analyse der Code-Struktur für wichtige Bedenken","Überprüfung der Technologiestacks auf Optimierungsmöglichkeiten","Kategorisierung von Dateien für eine effiziente Projektorganisation"],"pt":["Analisar a estrutura do código para preocupações principais","Revisar pilhas de tecnologias para oportunidades de otimização","Categorizar arquivos para organização de projetos eficiente"],"ru":["Анализировать структуру кода для основных проблем","Просматривать технологические стеки для возможностей оптимизации","Категоризировать файлы для эффективной организации проектов"],"ar":["تحليل هيكل الشفرة للقضايا الرئيسية","مراجعة حزمة التقنيات لفرص تحسين","تصنيف الملفات لتجنب التكدس في المشاريع"]},"limitations":{"en":["Requires access to codebase files","May require significant time for complex codebases","Needs output folder with 1-techstack.md and 2-file-categorization.json for accurate analysis"],"zh":["需要访问代码库文件","复杂的代码库可能需要大量时间","需要输出文件夹，包含 1-techstack.md 和 2-file-categorization.json，以进行准确的分析"],"ja":["コードベース ファイルへのアクセスが必要","複雑なコードベースの場合は、多くの時間が必要になる可能性があります","正確な分析を行うには、1-techstack.md と 2-file-categorization.json を含む出力フォルダが必要"],"ko":["코드베이스 파일에 대한 액세스가 필요함","복잡한 코드베이스의 경우 상당한 시간이 필요할 수 있음","정확한 분석을 수행하려면 1-techstack.md 및 2-file-categorization.json을 포함하는 출력 폴더가 필요함"],"es":["Requiere acceso a los archivos de la base de código","Puede requerir un tiempo significativo para bases de código complejas","Necesita una carpeta de salida con 1-techstack.md y 2-file-categorization.json para un análisis preciso"],"fr":["Nécessite un accès aux fichiers de la base de code","Peut nécessiter un temps significatif pour les bases de code complexes","Nécessite un dossier de sortie avec 1-techstack.md et 2-file-categorization.json pour une analyse précise"],"de":["Benötigt Zugriff auf die Codebasis-Dateien","Kann für komplexe Codebasen erhebliche Zeit erfordern","Benötigt einen Ausgabordner mit 1-techstack.md und 2-file-categorization.json für eine genaue Analyse"],"pt":["Requer acesso aos arquivos da base de código","Pode requerer tempo significativo para bases de código complexas","Necessita de uma pasta de saída com 1-techstack.md e 2-file-categorization.json para análise precisa"],"ru":["Требует доступа к файлам кодовой базы","Может требовать значительного времени для сложных кодовых баз","Требует папки вывода с 1-techstack.md и 2-file-categorization.json для точного анализа"],"ar":["يتطلب الوصول إلى ملفات قاعدة الشفرة","قد يتطلب وقتًا كبيرًا للشفرات البرمجية المعقدة","يحتاج إلى مجلد إخراج يحتوي على 1-techstack.md و 2-file-categorization.json لتحليل دقيق"]},"version":4},"contentHash":"28397b8eb89941c05c9f25e93b0558abb453