INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('bitovi/context-generation-mvp/3-identifying-architecture', '3-identifying-architecture', 'bitovi', 'context-generation-mvp', 'community', '3-identifying-architecture bitovi context-generation-mvp community 3-identifying-architecture analyzes codebases to understand their structure and major concerns, benefiting developers and architects. It reviews tech stacks and categorized files for accurate results. 分析代码库以了解其结构和主要关注点，使用 tech stack 和文件分类来实现准确和完整的分析 コードベースを分析してその構造と主な懸念事項を理解し、tech stack とファイル分類を使用して正確な分析を実行します 코드베이스를 분석하여その 구조와 주요 관심사를 이해하고 tech stack과 파일 분류를 사용하여 정확한 분석을 수행합니다 Esta habilidad permite analizar un codebase para entender su estructura y principales preocupaciones, utilizando un resumen de la pila tecnológica y categorización de archivos Cette compétence permet d''analyser un codebase pour comprendre sa structure et ses principales préoccupations, en utilisant un résumé de la pile technologique et une catégorisation de fichiers Diese Fähigkeit ermöglicht die Analyse eines Codebases, um dessen Struktur und Hauptanliegen zu verstehen, unter Verwendung einer Zusammenfassung des Technologie-Stacks und einer Kategorisierung von Dateien O skill 3-identifying-architecture é usado para analisar a estrutura de um código e identificar preocupações principais Навык 3-identifying-architecture используется для анализа структуры кода и определения основных проблем المهارة 3-identifying-architecture تستخدم لتحليل هيكل الكود وتحديد المخاوف الرئيسية how to use 3-identifying-architecture what is 3-identifying-architecture 3-identifying-architecture alternative 3-identifying-architecture vs code analysis tools 3-identifying-architecture install 3-identifying-architecture setup guide codebase analysis with 3-identifying-architecture understanding code structure with 3-identifying-architecture 代码结构分析 tech stack 文件分类 代码库分析 AI工具 代码结构理解 Reviews tech stacks summarized in ./{output-folder}/1-techstack.md Analyzes categorized files listed in ./{output-folder}/2-file-categorization.json Permits thorough review of codebase without time constraints Ensures accuracy and completeness of results Supports detailed analysis of codebase structure and major concerns 3-identifying-architecture is a code analysis skill that reviews tech stacks and categorized files to understand codebase structure and major concerns.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('danalexilewis/taskgraph/create-hook', 'community', 'danalexilewis', 'taskgraph', 'danalexilewis/taskgraph', 'create-hook', 0, 0, 39, '2026-03-03T12:49:15Z', '2026-03-07T04:09:35.366Z', '8aecc143d229b5bba50e69adbd6fa885bd9f8c3d8aab0c45e94c68f53f5f2f67', '{"id":"danalexilewis/taskgraph/create-hook","name":"create-hook","description":{"en":"The create-hook skill allows developers to add Cursor lifecycle hooks, enabling scripts to run on specific agent events. This utility skill is designed for Centaur Development and Task Graph projects.","zh":"Create Hook 是 Task Graph 中的 Utility 技能，用于添加 Cursor 生命周期钩子，实现特定事件触发的脚本运行","ja":"Create Hook は Task Graph のユーティリティ スキルで、Cursor ライフサイクル フックを追加し、特定のイベントが発生したときにスクリプトを実行します","ko":"Create Hook는 Task Graph의 Utility 스킬로 Cursor 라이프사이클 훅을 추가하여 특정 이벤트가 발생할 때 스크립트를 실행합니다","es":"Create-hook es una habilidad de utilidad que permite agregar scripts personalizados para eventos de ciclo de vida en Centaur Development","fr":"Create-hook est une compétence utilitaire qui permet d''ajouter des scripts personnalisés pour les événements de cycle de vie dans les Outils d''IA","de":"Create-hook ist eine Utility-Skill, die die Erstellung benutzerdefinierter Skripte für Lebenszyklusereignisse in der KI-Entwicklung ermöglicht","pt":"O Create Hook é uma habilidade de utilidade que permite criar scripts personalizados para eventos de ciclo de vida do Cursor. Ele adiciona um hook de ciclo de vida do Cursor.","ru":"Create Hook — это утилитарный навык, который позволяет создавать кастомные скрипты для событий жизненного цикла Cursor. Он добавляет хук жизненного цикла Cursor.","ar":"Create Hook هو مهارة من نوع الأدوات التي تمكن من إنشاء scripts مخصصة لأحداث دورة حياة Cursor. إنه يضيف hook دورة حياة Cursor."},"seo":{"title":{"en":"create-hook: Setup Guide for AI Agents | Utility Skill","zh":"Create Hook 设置指南 - Task Graph 中的 Centaur 开发工具","ja":"Create Hook 導入ガイド - Centaur 開発の Task Graph ユーティリティ","ko":"Create Hook 설정 가이드 - Task Graph의 Centaur 개발 도구","es":"Guía de configuración de create-hook para Agentes de IA","fr":"Configurer create-hook pour les Outils d''IA","de":"Einrichtungsleitfaden für create-hook in der KI-Entwicklung","pt":"Guia de Configuração do Create Hook para Desenvolvedores","ru":"Настройка Create Hook: Руководство для Разработчиков ИИ А...","ar":"دليل إعداد Create Hook لل.AI Tools"},"description":{"en":"Discover how to add Cursor lifecycle hooks with create-hook. Learn to register scripts for specific agent events and optimize your project workflow. Get star...","zh":"了解 Create Hook 的功能和使用方法，实现 Task Graph 中的 Centaur 开发自动化","ja":"Create Hook の機能と使い方を学び、Task Graph の Centaur 開発を自動化しましょう","ko":"Create Hook의 기능과 사용 방법을 알아보고 Task Graph의 Centaur 개발을 자동화하세요","es":"Aprende a crear hooks personalizados para eventos de ciclo de vida en Centaur Development con create-hook","fr":"Découvrez comment configurer des hooks pour les événements de cycle de vie avec create-hook pour les Outils d''IA","de":"Erfahren Sie, wie Sie benutzerdefinierte Hooks für Lebenszyklusereignisse in der KI-Entwicklung mit create-hook erstellen","pt":"Aprenda a criar hooks personalizados para eventos de ciclo de vida do Cursor com o Create Hook. Descubra como registrar hooks em projetos e melhorar a produt...","ru":"Узнайте, как создать кастомные хуки для событий жизненного цикла Cursor с помощью Create Hook. Откройте для себя, как регистрировать хуки в проектах и повыси...","ar":"تعلم كيفية إنشاء hooks مخصصة لأحداث دورة حياة Cursor باستخدام Create Hook. اكتشف كيفية تسجيل hooks في المشاريع وتحسين الإنتاجية لل.AI Tools"},"definition":{"en":"create-hook is a utility skill that adds a Cursor lifecycle hook, allowing scripts to run when specific agent events fire, and is used in project-level development.","zh":"Create Hook 是一种 Utility 技能，用于在 Task Graph 中添加 Cursor 生命周期钩子","ja":"Create Hook は、Task Graph で Cursor ライフサイクル フックを追加するユーティリティ スキルです","ko":"Create Hook는 Task Graph에서 Cursor 라이프사이클 훅을 추가하는 Utility 스킬입니다","es":"Create-hook es una habilidad que permite crear hooks personalizados para eventos de ciclo de vida en Centaur Development","fr":"Create-hook est une compétence qui permet de créer des hooks personnalisés pour les événements de cycle de vie","de":"Create-hook ist eine Skill, die die Erstellung benutzerdefinierter Hooks für Lebenszyklusereignisse ermöglicht","pt":"O Create Hook é uma habilidade que adiciona um hook de ciclo de vida do Cursor, permitindo a execução de scripts personalizados.","ru":"Create Hook — это навык, который добавляет хук жизненного цикла Cursor, позволяя выполнить кастомные скрипты.","ar":"Create Hook هو مهارة تضيف hook دورة حياة Cursor، مما يسمح بتنفيذ scripts مخصصة."},"features":{"en":["Adds a Cursor lifecycle hook to run scripts on specific agent events","Registers hooks under designated keys in hooks.json","Supports project-level development with .cursor/hooks/ and .cursor/hooks.json","Enables scripts to run when specific agent events fire","Designed for use in Centaur Development and Task Graph projects"],"zh":["添加 Cursor 生命周期钩子","支持特定事件触发的脚本运行","仅在项目级别运行（.cursor/hooks/ 和 .cursor/hooks.json）","支持多种事件注册（hooks.json）"],"ja":["Cursor ライフサイクル フックを追加","特定のイベントが発生したときにスクリプトを実行","プロジェクト レベルでのみ実行（.cursor/hooks/ と .cursor/hooks.json）","複数のイベント登録をサポート（hooks.json）"],"ko":["Cursor 라이프사이클 훅을 추가","특정 이벤트가 발생할 때 스크립트를 실행","프로젝트 레벨에서만 실행（.cursor/hooks/ 및 .cursor/hooks.json）","다중 이벤트 등록을 지원（hooks.json）"],"es":["Adición de hooks personalizados para eventos de ciclo de vida","Compatibilidad con Centaur Development","Soporte para scripts en formato JSON","Integración con el archivo hooks.json","Permite la creación de hooks a nivel de proyecto"],"fr":["Ajout de hooks personnalisés pour les événements de cycle de vie","Compatibilité avec les Outils d''IA","Prise en charge de scripts au format JSON","Intégration avec le fichier hooks.json","Permet la création de hooks au niveau du projet"],"de":["Hinzufügen benutzerdefinierter Hooks für Lebenszyklusereignisse","Kompatibilität mit der KI-Entwicklung","Unterstützung für Skripte im JSON-Format","Integration mit der Datei hooks.json","Ermöglicht die Erstellung von Hooks auf Projektebene"],"pt":["Adiciona um hook de ciclo de vida do Cursor","Permite a execução de scripts personalizados","Compatível com projetos do Cursor","Registra hooks em hooks.json","Suporta eventos de ciclo de vida do Cursor"],"ru":["Добавляет хук жизненного цикла Cursor","Позволяет выполнить кастомные скрипты","Компатибельный с проектами Cursor","Регистрирует хуки в hooks.json","Поддерживает события жизненного цикла Cursor для ИИ Агентов"],"ar":["يضيف hook دورة حياة Cursor","يسمح بتنفيذ scripts مخصصة","متوافق مع مشاريع Cursor","يسجل hooks في hooks.json","يدعم أحداث دورة حياة Cursor لل.AI Tools"]},"keywords":{"en":["how to use create-hook","create-hook setup guide","create-hook alternative","create-hook vs other utility skills","what is create-hook","create-hook install","create-hook for Centaur Development","Task Graph create-hook","create-hook for AI Agents"],"zh":["Create Hook","Task Graph","Centaur 开发","Cursor 生命周期钩子","AI工具","Utility 技能","项目级别运行"],"ja":["Create Hook","Task Graph","Centaur 開発","Cursor ライフサイクル フック","AIエージェント","ユーティリティ スキル","プロジェクト レベルでの実行"],"ko":["Create Hook","Task Graph","Centaur 개발","Cursor 라이프사이클 훅","AI 도구","Utility 스킬","프로젝트 레벨에서 실행"],"es":["create-hook","Agentes de IA","Centaur Development","hooks personalizados","eventos de ciclo de vida","scripts en JSON","configuración de create-hook","desarrollo de IA"],"fr":["create-hook","Outils d''IA","développement d''IA","hooks personnalisés","événements de cycle de vie","scripts au format JSON","configuration de create-hook","création de hooks"],"de":["create-hook","KI-Entwicklung","KI-Tools","benutzerdefinierte Hooks","Lebenszyklusereignisse","Skripte im JSON-Format","Konfiguration von create-hook","Erstellung von Hooks"],"pt":["Create Hook","Cursor","hooks de ciclo de vida","scripts personalizados","projetos do Cursor","desenvolvimento de software","utilidades de desenvolvimento"],"ru":["Create Hook","Cursor","хуки жизненного цикла","кастомные скрипты","проекты Cursor","разработка программного обеспечения","утилиты разработки для ИИ Агентов"],"ar":["Create Hook","Cursor","hooks دورة حياة","scripts مخصصة","مشاريع Cursor","تطوير البرمجيات","أدوات تطوير لل.AI Tools"]}},"owner":"danalexilewis","repo":"taskgraph","repoPath":"danalexilewis/taskgraph","stars":0,"forks":0,"updatedAt":"2026-03-03T12:49:15Z","topics":[],"category":"community","skillMd":{"name":"create-hook","description":"Creates or adds Cursor agent lifecycle hooks. Use when the user asks to create a hook, add a hook, set up a lifecycle hook, or automate something on agent stop, afterFileEdit, afterAgentResponse, or other Cursor hook events. Hooks live in .cursor/hooks/ and are registered in .cursor/hooks.json.","bodyPreview":"# Create Hook\n\n**You** (the lead) do the work. Do not dispatch sub-agents.\n\n**Type:** Utility skill (procedural, no agentic lead or sub-agents).\n\nAdds a Cursor lifecycle hook: a script that runs when a specific agent event fires. Hooks are project-level only (`.cursor/hooks/` and `.cursor/hooks.json`).\n\n## 1. Choose the lifecycle event\n\nRegister the hook under one of these keys in `hooks.json`:\n\n| Event                                           | When it runs                          |\n| -------","body":"# Create Hook\n\n**You** (the lead) do the work. Do not dispatch sub-agents.\n\n**Type:** Utility skill (procedural, no agentic lead or sub-agents).\n\nAdds a Cursor lifecycle hook: a script that runs when a specific agent event fires. Hooks are project-level only (`.cursor/hooks/` and `.cursor/hooks.json`).\n\n## 1. Choose the lifecycle event\n\nRegister the hook under one of these keys in `hooks.json`:\n\n| Event                                           | When it runs                          |\n| ----------------------------------------------- | ------------------------------------- |\n| `stop`                                          | When the agent stops (end of turn)    |\n| `afterFileEdit`                                 | After the agent edits a file          |\n| `afterAgentResponse`                            | After the agent sends a response      |\n| `beforeSubmitPrompt`                            | Before the user''s prompt is submitted |\n| `beforeReadFile` / `afterShellExecution` / etc. | See Cursor docs for full list         |\n\n## 2. Add the script\n\n- **Path**: `.cursor/hooks/<name>.js` (or `.sh` if shell). Use a clear name (e.g. `memory-reminder.js`, `on-stop.js`).\n- **Runtime**: Node.js is typical; command in `hooks.json` is run with Cursor''s working directory set so that `node hooks/<name>.js` resolves (run from `.cursor`).\n- **Input**: The hook receives a single JSON object on **stdin**. Read it like this:\n\n```javascript\nlet input = \"\";\nprocess.stdin.setEncoding(\"utf8\");\nprocess.stdin.on(\"data\", (chunk) => {\n  input += chunk;\n});\nprocess.stdin.on(\"end\", () => {\n  const payload = JSON.parse(input);\n  const roots = payload.workspace_roots || [process.cwd()];\n  const root = path.resolve(roots[0]); // repo root\n  // ... use root for paths like path.join(root, ''.cursor'', ''next-step.md'')\n});\n```\n\n- **Payload**: Often includes `workspace_roots` (array of repo roots). Use the first root as the project root for paths. Event-specific payloads may include `file_path`, `prompt`, etc.\n- **Output**: Hook can write files (e.g. `.cursor/next-step.md`), log to stderr, or exit; avoid writing to stdout if the protocol expects JSON there.\n- **Shebang**: Start Node scripts with `#!/usr/bin/env node`.\n\n## 3. Register in hooks.json\n\n- **Path**: `.cursor/hooks.json`\n- **Format**:\n\n```json\n{\n  \"version\": 1,\n  \"hooks\": {\n    \"stop\": [\n      { \"command\": \"node hooks/on-stop.js\" },\n      { \"command\": \"node hooks/my-new-hook.js\" }\n    ]\n  }\n}\n```\n\n- Append to the array for the chosen event; do not remove existing hooks unless the user asks to replace them.\n\n## Checklist\n\n- [ ] Script created under `.cursor/hooks/<name>.js` (or `.sh`)\n- [ ] Script reads JSON from stdin and uses `workspace_roots` for repo root when needed\n- [ ] Entry added to `.cursor/hooks.json` under the correct event key\n- [ ] Command is `node hooks/<name>.js` (or `./hooks/<name>.sh`); path is relative to `.cursor`\n\n## Reference\n\n- Existing hooks in this repo: `.cursor/hooks/on-stop.js`, `.cursor/hooks/after-file-edit.js`, `.cursor/hooks/memory-reminder.js` — use them as patterns for stdin handling and `path.join(root, ...)`.\n- Project memory (`.cursor/memory.md`) notes that new hooks should be added under `.cursor/hooks/` and registered in `.cursor/hooks.json`.\n"},"lastSynced":"2026-03-07T04:09:35.366Z","agentAnalysis":{"suitability":{"en":"Perfect for Centaur Development Agents needing customized lifecycle event handling.","zh":"适合于需要自定义生命周期事件处理的Centaur Development Agents。","ja":"Centaur Development Agents がカスタマイズされたライフサイクル イベント ハンドリングを必要とする場合に最適です。","ko":"사용자 지정 라이프사이클 이벤트 처리가 필요한 Centaur Development Agents 에 적합합니다.","es":"Perfecto para agentes de desarrollo Centaur que necesitan un control de eventos de ciclo de vida personalizado.","fr":"Parfait pour les agents de développement Centaur nécessitant une gestion d''événements de cycle de vie personnalisée.","de":"Perfekt für Centaur-Entwicklungsagenten, die eine benutzerdefinierte Lebenszyklusereignisverwaltung benötigen.","pt":"Perfeito para Agentes de Desenvolvimento Centaur que necessitam de tratamento de eventos de ciclo de vida personalizados.","ru":"Идеально подходит для агентов разработки Centaur, которым требуются настраиваемые обработчики событий жизненного цикла.","ar":"مثالي لوكلاء التطوير Centaur الذين يحتاجون إلى معالجة أحداث دورة الحياة المخصصة."},"recommendation":{"en":"Empowers agents to execute scripts on specific Cursor lifecycle events, such as agent initialization or task completion, using hooks defined in `.cursor/hooks/` and `.cursor/hooks.json`.","zh":"使代理能够在特定的 Cursor 生命周期事件（例如代理初始化或任务完成）上执行脚本，使用在 `.cursor/hooks/` 和 `.cursor/hooks.json` 中定义的钩子。","ja":"エージェントが特定の Cursor ライフサイクル イベント（たとえばエージェントの初期化またはタスクの完了）でスクリプトを実行できるようにし、`.cursor/hooks/` と `.cursor/hooks.json` で定義されたフックを使用します。","ko":"에이전트가 특정 Cursor 생명주기 이벤트(예: 에이전트 초기화 또는 작업 완료)에서 스크립트를 실행할 수 있도록 하며, `.cursor/hooks/` 및 `.cursor/hooks.json`에서 정의한 후크를 사용합니다.","es":"Habilita a los agentes a ejecutar scripts en eventos de ciclo de vida de Cursor específicos, como la inicialización del agente o la finalización de la tarea, utilizando ganchos definidos en `.cursor/hooks/` y `.cursor/hooks.json`.","fr":"Permet aux agents d''exécuter des scripts sur des événements de cycle de vie de Cursor spécifiques, tels que l''initialisation de l''agent ou l''achèvement d''une tâche, en utilisant des crochets définis dans `.cursor/hooks/` et `.cursor/hooks.json`.","de":"Ermächtigt Agenten, Skripte auf bestimmte Cursor-Lebenszyklusereignisse auszuführen, wie z. B. die Initialisierung des Agents oder die Aufgabenabgeschlossenheit, unter Verwendung von Haken, die in `.cursor/hooks/` und `.cursor/hooks.json` definiert sind.","pt":"Habilita os agentes a executar scripts em eventos de ciclo de vida específicos do Cursor, como inicialização do agente ou conclusão de tarefa, usando ganchos definidos em `.cursor/hooks/` e `.cursor/hooks.json`.","ru":"Позволяет агентам выполнять скрипты на конкретных событиях жизненного цикла Cursor, таких как инициализация агента или завершение задачи, используя хуки, определенные в `.cursor/hooks/` и `.cursor/hooks.json`.","ar":"يمكن الوكلاء من تشغيل البرامج النصية في أحداث دورة الحياة الخاصة bằng Cursor، مثل تهيئة الوكيل أو إكمال المهمة، باستخدام Hooks المحددة في `.cursor/hooks/` و `.cursor/hooks.json`."},"useCases":{"en":["Automating task setup with on-init hooks","Debugging agent crashes with on-error hooks","Triggering custom scripts on task completion"],"zh":["使用 on-init 钩子自动执行任务设置","使用 on-error 钩子调试代理崩溃","在任务完成时触发自定义脚本"],"ja":["on-init フックを使用してタスクの設定を自動化する","on-error フックを使用してエージェントのクラッシュをデバッグする","タスク完了時にカスタム スクリプトをトリガーする"],"ko":["on-init 후크를 사용하여 작업 설정 자동화","on-error 후크를 사용하여 에이전트 충돌 디버깅","작업 완료 시 사용자 지정 스크립트 트리거"],"es":["Automatización de la configuración de tareas con ganchos on-init","Depuración de fallos de agentes con ganchos on-error","Activación de scripts personalizados en la finalización de tareas"],"fr":["Automatisation de la configuration des tâches avec des crochets on-init","Débogage des plantages d''agents avec des crochets on-error","Déclenchement de scripts personnalisés à la fin des tâches"],"de":["Automatisierung der Aufgabeneinrichtung mit on-init-Haken","Fehlerbehebung bei Agentenabstürzen mit on-error-Haken","Auslösen benutzerdefinierter Skripte bei Aufgabenabschluss"],"pt":["Automatizar configuração de tarefas com ganchos on-init","Depurar falhas de agente com ganchos on-error","Acionar scripts personalizados na conclusão de tarefas"],"ru":["Автоматизация настройки задач с помощью хуков on-init","Отладка сбоев агента с помощью хуков on-error","Запуск пользовательских скриптов при завершении задач"],"ar":["تutomatizar إعداد المهام مع Hooks on-init","تصحيح أخطاء الوكيل مع Hooks on-error","تشغيل البرامج النصية المخصصة عند إكمال المهام"]},"limitations":{"en":["Project-level hooks only","Requires Cursor lifecycle event registration in `hooks.json`"],"zh":["仅支持项目级别的钩子","需要在 `hooks.json` 中注册 Cursor 生命周期事件"],"ja":["プロジェクト レベルのフックのみをサポートする","`hooks.json` に Cursor ライフサイクル イベントを登録する必要がある"],"ko":["프로젝트 수준의 후크만 지원","`hooks.json`에 Cursor 생명주기 이벤트를 등록해야 함"],"es":["Ganchos solo a nivel de proyecto","Requiere registro de eventos de ciclo de vida de Cursor en `hooks.json`"],"fr":["Crochets uniquement au niveau du projet","Nécessite l''enregistrement des événements de cycle de vie de Cursor dans `hooks.json`"],"de":["Haken nur auf Projektebene","Benötigt die Registrierung von Cursor-Lebenszyklusereignissen in `hooks.json`"],"pt":["Ganchos apenas no nível do projeto","Exige registro de eventos de ciclo de vida do Cursor em `hooks.json`"],"ru":["Хуки только на уровне проекта","Требует регистрации событий жизненного цикла Cursor в `hooks.json`"],"ar":["الHooks فقط على مستوى المشروع","يتطلب التسجيل في أحداث دورة الحياة من Cursor في `hooks.json`"]},"version":4},"contentHash":"8aecc143d229b5bba50e69adbd6fa885bd9f8c3d8aab0c45e94c68f53f5f2f67","qualityScore":39}');
