INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('danalexilewis/taskgraph/create-hook', 'create-hook', 'danalexilewis', 'taskgraph', 'community', 'create-hook danalexilewis taskgraph community The create-hook skill allows developers to add Cursor lifecycle hooks, enabling scripts to run on specific agent events. This utility skill is designed for Centaur Development and Task Graph projects. Create Hook 是 Task Graph 中的 Utility 技能，用于添加 Cursor 生命周期钩子，实现特定事件触发的脚本运行 Create Hook は Task Graph のユーティリティ スキルで、Cursor ライフサイクル フックを追加し、特定のイベントが発生したときにスクリプトを実行します Create Hook는 Task Graph의 Utility 스킬로 Cursor 라이프사이클 훅을 추가하여 특정 이벤트가 발생할 때 스크립트를 실행합니다 Create-hook es una habilidad de utilidad que permite agregar scripts personalizados para eventos de ciclo de vida en Centaur Development Create-hook est une compétence utilitaire qui permet d''ajouter des scripts personnalisés pour les événements de cycle de vie dans les Outils d''IA Create-hook ist eine Utility-Skill, die die Erstellung benutzerdefinierter Skripte für Lebenszyklusereignisse in der KI-Entwicklung ermöglicht O Create Hook é uma habilidade de utilidade que permite criar scripts personalizados para eventos de ciclo de vida do Cursor. Ele adiciona um hook de ciclo de vida do Cursor. Create Hook — это утилитарный навык, который позволяет создавать кастомные скрипты для событий жизненного цикла Cursor. Он добавляет хук жизненного цикла Cursor. Create Hook هو مهارة من نوع الأدوات التي تمكن من إنشاء scripts مخصصة لأحداث دورة حياة Cursor. إنه يضيف hook دورة حياة Cursor. how to use create-hook create-hook setup guide create-hook alternative create-hook vs other utility skills what is create-hook create-hook install create-hook for Centaur Development Task Graph create-hook create-hook for AI Agents Create Hook Task Graph Centaur 开发 Cursor 生命周期钩子 AI工具 Utility 技能 项目级别运行 Adds a Cursor lifecycle hook to run scripts on specific agent events Registers hooks under designated keys in hooks.json Supports project-level development with .cursor/hooks/ and .cursor/hooks.json Enables scripts to run when specific agent events fire Designed for use in Centaur Development and Task Graph projects create-hook is a utility skill that adds a Cursor lifecycle hook, allowing scripts to run when specific agent events fire, and is used in project-level development.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('endriwmsi/hub-ln/React-Query', 'community', 'endriwmsi', 'hub-ln', 'endriwmsi/hub-ln', 'React-Query', 0, 0, 39, '2026-03-02T19:57:01Z', '2026-03-07T04:10:09.171Z', 'ab7eb6d4393e98d5483c375dc6dec64956aaf46fca764ce56b0949bd948f752e', '{"id":"endriwmsi/hub-ln/React-Query","name":"React-Query","description":{"en":"React-Query is a skill that enables asynchronous data management using @tanstack/react-query v5. It benefits developers by simplifying data fetching, caching, and synchronization.","zh":"React Query 是一个用于管理异步数据的库，提供了数据缓存、错误处理和加载状态管理等功能","ja":"React Query は非同期データ管理を実装するためのライブラリです","ko":"React Query는 비동기 데이터 관리를 위한 라이브러리입니다","es":"React-Query es una biblioteca para gestionar datos asíncronos en aplicaciones React. Permite buscar datos del servidor, crear, actualizar o eliminar recursos y sincronizar el caché automáticamente.","fr":"React-Query est une bibliothèque pour gérer les données asynchrones dans les applications React. Elle permet de rechercher des données sur le serveur, de créer, de mettre à jour ou de supprimer des ressources et de synchroniser le cache automatiquement.","de":"React-Query ist eine Bibliothek zur Verwaltung asynchroner Daten in React-Anwendungen. Sie ermöglicht das Abrufen von Daten vom Server, das Erstellen, Aktualisieren oder Löschen von Ressourcen und die automatische Synchronisierung des Caches.","pt":"React-Query é uma biblioteca para gerenciamento de dados assíncronos que permite buscar dados do servidor, criar, atualizar ou deletar recursos e sincronizar cache automaticamente","ru":"React Query — это библиотека для управления асинхронными данными, которая позволяет запрашивать данные с сервера, создавать, обновлять или удалять ресурсы и синхронизировать кэш автоматически с помощью ИИ Агентов","ar":"React-Query هي مكتبة لإدارة البيانات غير المتزامنة التي تمكن من استعلام البيانات من الخادم، وإنشاء أو تحديث أو حذف الموارد وتنسيق الذاكرة المؤقتة تلقائيًا للأدوات الذكية"},"seo":{"title":{"en":"React-Query: Asynchronous Data Management Setup Guide | A...","zh":"React Query_setup_guide","ja":"React Query_Best_Practices","ko":"React Query_implementation_tutorial","es":"Guía de configuración de React-Query para gestión de datos","fr":"Guide de mise en place de React-Query pour la gestion de ...","de":"Einrichtungsanleitung für React-Query zur Datenverwaltung","pt":"Guia de Configuração do React-Query para Gerenciamento de...","ru":"Настройка React Query для управления асинхронными данными...","ar":"دليل إعداد React-Query لادارة البيانات غير المتزامنة للأد..."},"description":{"en":"Unlock efficient data fetching and caching with React-Query. Learn how to implement asynchronous data management and optimize your application''s performance....","zh":"使用 @tanstack/react-query v5 实现异步数据管理，包括数据缓存和错误处理","ja":"React Query を使用して非同期データ管理を実装する方法","ko":"React Query를 사용하여 비동기 데이터 관리 구현","es":"Aprende a implementar React-Query para gestionar datos asíncronos y mejorar la experiencia del usuario en tus aplicaciones","fr":"Découvrez comment mettre en place React-Query pour gérer les données asynchrones et améliorer l''expérience utilisateur dans vos applications","de":"Erfahren Sie, wie Sie React-Query implementieren, um asynchrone Daten zu verwalten und die Benutzererfahrung in Ihren Anwendungen zu verbessern","pt":"Aprenda a implementar o gerenciamento de dados assíncronos com React-Query, incluindo busca de dados, operações CRUD e sincronização de cache","ru":"Узнайте, как реализовать управление асинхронными данными с помощью React Query, включая запросы данных, операции CRUD и синхронизацию кэша, с помощью ИИ Агентов","ar":"تعلم كيفية تنفيذ إدارة البيانات غير المتزامنة مع React-Query، بما في ذلك استعلام البيانات وعمليات CRUD وتنسيق الذاكرة المؤقتة للأدوات الذكية"},"definition":{"en":"React-Query is a library for managing asynchronous data in React applications, providing features like automatic cache synchronization and feedback visualizations.","zh":"React Query 是一个 JavaScript 库，用于管理 React 应用中的异步数据","ja":"React Query は React アプリケーションの非同期データを管理するための JavaScript ライブラリです","ko":"React Query는 React 애플리케이션의 비동기 데이터를 관리하기 위한 JavaScript 라이브러리입니다","es":"React-Query es una biblioteca JavaScript para gestionar datos asíncronos en aplicaciones React","fr":"React-Query est une bibliothèque JavaScript pour gérer les données asynchrones dans les applications React","de":"React-Query ist eine JavaScript-Bibliothek zur Verwaltung asynchroner Daten in React-Anwendungen","pt":"React-Query é uma biblioteca JavaScript para gerenciamento de dados assíncronos que fornece uma forma eficiente de lidar com dados do servidor","ru":"React Query — это библиотека JavaScript для управления асинхронными данными, которая предоставляет эффективный способ работы с данными с сервера","ar":"React-Query هي مكتبة جافاسكريبت لإدارة البيانات غير المتزامنة التي توفر طريقة فعالة للتعامل مع البيانات من الخادم"},"features":{"en":["Implement asynchronous data fetching using @tanstack/react-query v5","Manage loading and error states for a better user experience","Automatically synchronize cache after mutations","Perform CRUD operations with feedback visualizations","Invalidate queries after mutations for data consistency","Optimize data pagination and listing with React-Query"],"zh":["使用 @tanstack/react-query v5 实现异步数据管理","数据缓存和自动失效","错误处理和加载状态管理","支持 CRUD 操作","支持数据分页"],"ja":["React Query を使用して非同期データ管理を実装する","データのキャッシュと自動失効","エラー処理とロード状態管理","CRUD 操作のサポート","データのページングのサポート"],"ko":["React Query를 사용하여 비동기 데이터 관리 구현","데이터 캐싱과 자동 만료","에러 처리와 로드 상태 관리","CRUD 연산 지원","데이터 페이지 지원"],"es":["Gestión de datos asíncronos con @tanstack/react-query v5","Búsqueda de datos del servidor","Creación, actualización o eliminación de recursos con operaciones CRUD","Sincronización automática del caché","Gestión de estados de carga y error"],"fr":["Gestion des données asynchrones avec @tanstack/react-query v5","Recherche de données sur le serveur","Création, mise à jour ou suppression de ressources avec des opérations CRUD","Synchronisation automatique du cache","Gestion des états de chargement et d''erreur"],"de":["Verwaltung asynchroner Daten mit @tanstack/react-query v5","Abrufen von Daten vom Server","Erstellen, Aktualisieren oder Löschen von Ressourcen mit CRUD-Operationen","Automatische Synchronisierung des Caches","Verwaltung von Lade- und Fehlerzuständen"],"pt":["Buscar dados do servidor com @tanstack/react-query","Realizar operações CRUD com feedback visual","Sincronizar cache automaticamente após mutations","Gerenciar loading/error states de forma eficiente","Implementar listagens, detalhes e dados paginados"],"ru":["Запрашивать данные с сервера с помощью @tanstack/react-query","Выполнять операции CRUD с визуальной обратной связью","Синхронизировать кэш автоматически после мутаций","Управлять состояниями загрузки/ошибок эффективно","Реализовывать списки, детали и постраничные данные"],"ar":["استعلام البيانات من الخادم باستخدام @tanstack/react-query","تنفيذ عمليات CRUD مع反馈 مرئي","تنسيق الذاكرة المؤقتة تلقائيًا بعد التحويلات","إدارة حالات التحميل/الأخطاء بفعالية","تنفيذ القوائم والتفاصيل والبيانات المُقسمة"]},"keywords":{"en":["how to use React-Query","React-Query vs Redux","React-Query setup guide","what is React-Query","React-Query alternative","React-Query install","asynchronous data management","React-Query caching","React-Query CRUD operations"],"zh":["React Query","异步数据管理","@tanstack/react-query","数据缓存","错误处理","加载状态管理","CRUD 操作","数据分页","React 开发","前端开发"],"ja":["React Query","非同期データ管理","@tanstack/react-query","データのキャッシュ","エラー処理","ロード状態管理","CRUD 操作","データのページング","React 開発","フロントエンド開発"],"ko":["React Query","비동기 데이터 관리","@tanstack/react-query","데이터 캐싱","에러 처리","로드 상태 관리","CRUD 연산","데이터 페이지","React 개발","프론트엔드 개발"],"es":["React-Query","gestión de datos asíncronos","@tanstack/react-query v5","búsqueda de datos del servidor","operaciones CRUD","sincronización del caché","gestión de estados de carga y error","desarrollo de aplicaciones React"],"fr":["React-Query","gestion des données asynchrones","@tanstack/react-query v5","recherche de données sur le serveur","opérations CRUD","synchronisation du cache","gestion des états de chargement et d''erreur","développement d''applications React"],"de":["React-Query","Verwaltung asynchroner Daten","@tanstack/react-query v5","Abrufen von Daten vom Server","CRUD-Operationen","Synchronisierung des Caches","Verwaltung von Lade- und Fehlerzuständen","Entwicklung von React-Anwendungen"],"pt":["react query","gerenciamento de dados assíncronos","busca de dados","operações CRUD","sincronização de cache","loading/error states","listagens","detalhes","dados paginados"],"ru":["react query","управление асинхронными данными","запрос данных","операции CRUD","синхронизация кэша","состояния загрузки/ошибок","списки","детали","постраничные данные","ИИ Агенты"],"ar":["react query","إدارة البيانات غير المتزامنة","استعلام البيانات","عمليات CRUD","تنسيق الذاكرة المؤقتة","حالات التحميل/الأخطاء","القوائم","التفاصيل","البيانات المُقسمة","الأدوات الذكية"]}},"owner":"endriwmsi","repo":"hub-ln","repoPath":"endriwmsi/hub-ln","stars":0,"forks":0,"updatedAt":"2026-03-02T19:57:01Z","topics":[],"category":"community","skillMd":{"name":"React-Query","description":"Especialista na implementação do Tanstack React-Query. Use quando solicitado a criação de tabelas ou na criação de componentes do lado do cliente.","bodyPreview":"# React Query (TanStack Query)\n\nEsta skill orienta a implementação de gerenciamento de dados assíncronos usando `@tanstack/react-query` v5, seguindo os padrões estabelecidos neste projeto.\n\n## Quando usar esta skill\n\n- **Buscar dados do servidor** - Listagens, detalhes, dados paginados\n- **Criar, atualizar ou deletar recursos** - Operações CRUD com feedback visual\n- **Sincronizar cache automaticamente** - Invalidar queries após mutations\n- **Gerenciar loading/error states** - Estados de carregam","body":"# React Query (TanStack Query)\n\nEsta skill orienta a implementação de gerenciamento de dados assíncronos usando `@tanstack/react-query` v5, seguindo os padrões estabelecidos neste projeto.\n\n## Quando usar esta skill\n\n- **Buscar dados do servidor** - Listagens, detalhes, dados paginados\n- **Criar, atualizar ou deletar recursos** - Operações CRUD com feedback visual\n- **Sincronizar cache automaticamente** - Invalidar queries após mutations\n- **Gerenciar loading/error states** - Estados de carregamento e erro de forma declarativa\n\n## Como usar\n\n### 1. Estrutura de Arquivos\n\nOs hooks de React Query devem seguir a estrutura feature-based:\n\n```\nsrc/features/{feature-name}/\n├── actions/         # Server actions (Next.js)\n    ├──action.ts\n├── schemas/         # Tipos e validações Zod\n    ├──schema.ts\n├── hooks/\n    ├── use-{entities}.ts        # Query para listar (ex: use-services.ts)\n    ├── use-create-{entity}.ts   # Mutation para criar\n    ├── use-update-{entity}.ts   # Mutation para atualizar\n    └── use-delete-{entity}.ts   # Mutation para deletar\n```\n\n### 2. Convenções de Nomenclatura\n\n| Tipo                 | Padrão              | Exemplo                   |\n| -------------------- | ------------------- | ------------------------- |\n| Query (listar)       | `use{Entities}`     | `useServices`, `useUsers` |\n| Query (detalhe)      | `use{Entity}`       | `useService`, `useUser`   |\n| Mutation (criar)     | `useCreate{Entity}` | `useCreateService`        |\n| Mutation (atualizar) | `useUpdate{Entity}` | `useUpdateService`        |\n| Mutation (deletar)   | `useDelete{Entity}` | `useDeleteService`        |\n\n### 3. Query Keys\n\nUse arrays estruturados para query keys:\n\n```typescript\n// ✅ Bom - permite invalidação granular\nqueryKey: [\"services\"]; // Lista todos\nqueryKey: [\"services\", { onlyActive: true }]; // Lista com filtro\nqueryKey: [\"services\", id]; // Detalhe por ID\n\n// ❌ Evitar - dificulta invalidação\nqueryKey: [\"all-services\"];\nqueryKey: [`service-${id}`];\n```\n\n### 4. Padrão de useQuery (Buscar Dados)\n\n```typescript\n\"use client\";\n\nimport { useQuery } from \"@tanstack/react-query\";\nimport { getEntities } from \"../actions\";\n\nexport function useEntities(filter?: boolean) {\n  return useQuery({\n    queryKey: [\"entities\", { filter }],\n    queryFn: () => getEntities(filter),\n  });\n}\n```\n\n### 5. Padrão de useMutation (Modificar Dados)\n\n```typescript\n\"use client\";\n\nimport { useMutation, useQueryClient } from \"@tanstack/react-query\";\nimport { toast } from \"sonner\";\nimport { createEntity } from \"../actions\";\nimport type { CreateEntityInput } from \"../schemas\";\n\nexport function useCreateEntity() {\n  const queryClient = useQueryClient();\n\n  return useMutation({\n    mutationFn: (data: CreateEntityInput) => createEntity(data),\n    onSuccess: (result) => {\n      if (result.success) {\n        toast.success(\"Criado com sucesso!\");\n        queryClient.invalidateQueries({ queryKey: [\"entities\"] });\n      } else {\n        toast.error(\"Erro ao criar\");\n      }\n    },\n    onError: () => {\n      toast.error(\"Erro ao criar\");\n    },\n  });\n}\n```\n\n### 6. Uso em Componentes\n\n```tsx\n\"use client\";\n\nimport { useEntities } from \"../hooks/use-entities\";\nimport { useCreateEntity } from \"../hooks/use-create-entity\";\n\nexport function EntitiesTable() {\n  const { data, isLoading, error } = useEntities();\n  const createMutation = useCreateEntity();\n\n  if (isLoading) return <Loading />;\n  if (error) return <Error message={error.message} />;\n\n  const handleCreate = (data: CreateEntityInput) => {\n    createMutation.mutate(data);\n  };\n\n  return <Table data={data} />;\n}\n```\n\n## Regras importantes\n\n> [!IMPORTANT]\n> Todos os hooks de React Query devem incluir `\"use client\"` no topo do arquivo.\n\n> [!TIP]\n> Sempre invalide queries relacionadas após uma mutation para manter o cache sincronizado.\n\n> [!WARNING]\n> Não use `queryClient.setQueryData` para modificar o cache diretamente, prefira `invalidateQueries` para garantir dados frescos.\n\n## Referências\n\n- [TanStack Query Docs](https://tanstack.com/query/latest)\n"},"lastSynced":"2026-03-07T04:10:09.171Z","agentAnalysis":{"suitability":{"en":"Ideal for Frontend Agents requiring efficient asynchronous data management and caching using @tanstack/react-query v5.","zh":"适用于需要高效异步数据管理和缓存的前端代理，使用@tanstack/react-query v5。","ja":"フロントエンドエージェントが効率的な非同期データ管理とキャッシングを必要とする場合に適しています。@tanstack/react-query v5を使用。","ko":"効率적인 비동기 데이터 관리와 캐싱이 필요한 프론트엔드 에이전트에 적합합니다. @tanstack/react-query v5를 사용합니다.","es":"Ideal para Agentes de Frontend que requieren una gestión de datos asíncrona eficiente y almacenamiento en caché utilizando @tanstack/react-query v5.","fr":"Idéal pour les agents Frontend nécessitant une gestion de données asynchrone efficace et un cache utilisant @tanstack/react-query v5.","de":"Ideal für Frontend-Agents, die eine effiziente asynchrone Datenverwaltung und Zwischenspeicherung unter Verwendung von @tanstack/react-query v5 erfordern.","pt":"Ideal para Agentes Frontend que necessitam de gerenciamento de dados assíncronos eficiente e cache utilizando @tanstack/react-query v5.","ru":"Идеально для Фронтенд-агентов, требующих эффективного асинхронного управления данными и кэширования с помощью @tanstack/react-query v5.","ar":"مثالي لعميل واجهة المستخدم الأمامية الذي يتطلب إدارة بيانات غير متزامنة فعالة وتخزين مؤقت باستخدام @tanstack/react-query v5."},"recommendation":{"en":"Empowers agents to simplify data fetching, caching, and synchronization with automatic cache invalidation after mutations, utilizing @tanstack/react-query v5 for seamless asynchronous data management, and managing loading and error states effectively.","zh":"赋予代理简化数据获取、缓存和同步的能力，自动在突变后缓存失效，利用@tanstack/react-query v5实现无缝的异步数据管理，并有效地管理加载和错误状态。","ja":"エージェントがデータの取得、キャッシング、同期を簡素化し、ミューテーションの後自動的にキャッシュ無効化を行う能力を提供します。@tanstack/react-query v5を使用してシームレスな非同期データ管理を行い、ロードとエラー状態を効果的に管理します。","ko":"에이전트가 데이터 가져오기, 캐싱, 동기화를 단순화하고 변이 후 자동으로 캐시 무효화를 수행할 수 있는 능력을 부여합니다. @tanstack/react-query v5를 사용하여 무결점의 비동기 데이터 관리를 수행하며 로딩 및 오류 상태를 효율적으로 관리합니다.","es":"Habilita a los agentes a simplificar la recuperación de datos, el almacenamiento en caché y la sincronización con una invalidación automática de caché después de mutaciones, utilizando @tanstack/react-query v5 para una gestión de datos asíncrona sin problemas y gestionando efectivamente los estados de carga y error.","fr":"Permet aux agents de simplifier la récupération de données, le cache et la synchronisation avec une invalidation automatique du cache après des mutations, en utilisant @tanstack/react-query v5 pour une gestion de données asynchrone transparente et en gérant efficacement les états de chargement et d''erreur.","de":"Ermöglicht es den Agenten, die Datenabfrage, Zwischenspeicherung und Synchronisation zu vereinfachen, mit automatischer Zwischenspeicherung nach Mutationen, unter Verwendung von @tanstack/react-query v5 für eine nahtlose asynchrone Datenverwaltung und effektives Management von Lade- und Fehlerzuständen.","pt":"Habilita os agentes a simplificar a captura de dados, cache e sincronização com invalidação automática de cache após mutações, utilizando @tanstack/react-query v5 para gerenciamento de dados assíncronos sem problemas, e gerenciando estados de carregamento e erro de forma eficaz.","ru":"Наделяет агентов возможностью упростить получение данных, кэширование и синхронизацию с автоматической инвалидацией кэша после мутаций, используя @tanstack/react-query v5 для бесперебойного асинхронного управления данными, и эффективно управляя состояниями загрузки и ошибок.","ar":"تمكّن الوكيل من تبسيط استرجاع البيانات وتخزينها المؤقت وتزامنها مع إلغاء التخزين المؤقت تلقائيًا بعد الطفرات، باستخدام @tanstack/react-query v5 لإدارة البيانات غير المتزامنة بسلاسة، وإدارة حالات التحميل والأخطاء بفعالية."},"useCases":{"en":["Fetching paginated data from servers","Implementing CRUD operations with visual feedback","Synchronizing cache automatically after data mutations","Managing loading and error states for improved user experience"],"zh":["从服务器获取分页数据","使用可视化反馈实现CRUD操作","在数据变异后自动同步缓存","管理加载和错误状态以改善用户体验"],"ja":["サーバーからのページングデータの取得","視覚的なフィードバックを使用したCRUD操作の実装","データのミューテーションの後自動的にキャッシュを同期","ユーザー体験の向上のためのロードとエラー状態の管理"],"ko":["서버에서 페이징 데이터를 가져오는 것","시각적 피드백을 사용한 CRUD 연산 구현","데이터 변이 후 자동으로 캐시를 동기화하는 것","사용자 경험을 개선하기 위한 로딩 및 오류 상태 관리"],"es":["Recuperación de datos paginados desde servidores","Implementación de operaciones CRUD con retroalimentación visual","Sincronización automática de caché después de mutaciones de datos","Gestión de estados de carga y error para una mejor experiencia del usuario"],"fr":["Récupération de données paginées depuis des serveurs","Mise en œuvre d''opérations CRUD avec une rétroaction visuelle","Synchronisation automatique du cache après des mutations de données","Gestion des états de chargement et d''erreur pour une meilleure expérience utilisateur"],"de":["Abruf paginierter Daten von Servern","Implementierung von CRUD-Operationen mit visueller Rückmeldung","Automatische Synchronisation von Cache nach Datenmutationen","Verwaltung von Lade- und Fehlerzuständen für eine verbesserte Benutzererfahrung"],"pt":["Recuperação de dados paginados de servidores","Implementação de operações CRUD com feedback visual","Sincronização automática do cache após mutações de dados","Gerenciamento de estados de carregamento e erro para melhorar a experiência do usuário"],"ru":["Получение постраничных данных с серверов","Реализация операций CRUD с визуальной обратной связью","Автоматическая синхронизация кэша после мутаций данных","Управление состояниями загрузки и ошибок для улучшения пользовательского опыта"],"ar":["استرجاع بيانات منقحة من الخوادم","تنفيذ عمليات CRUD مع ملاحظات بصرية","مزامنة التخزين المؤقت تلقائيًا بعد طفرات البيانات","إدارة حالات التحميل والأخطاء لتحسين تجربة المستخدم"]},"limitations":{"en":["Requires @tanstack/react-query v5 library","Limited to React-based applications"],"zh":["需要@tanstack/react-query v5库","仅限于基于React的应用程序"],"ja":["@tanstack/react-query v5ライブラリが必要","Reactベースのアプリケーションに限定"],"ko":["@tanstack/react-query v5 라이브러리가 필요합니다","React 기반의 애플리케이션으로 제한"],"es":["Requiere la biblioteca @tanstack/react-query v5","Limitado a aplicaciones basadas en React"],"fr":["Nécessite la bibliothèque @tanstack/react-query v5","Limité aux applications basées sur React"],"de":["Benötigt die Bibliothek @tanstack/react-query v5","Begrenzt auf React-basierte Anwendungen"],"pt":["Requer a biblioteca @tanstack/react-query v5","Limitado a aplicações baseadas em React"],"ru":["Требует библиотеку @tanstack/react-query v5","Ограничен для приложений на основе React"],"ar":["يتطلب مكتبة @tanstack/react-query v5","محدود للتطبيقات القائمة على React"]},"version":4},"contentHash":"ab7eb6d4393e98d5483c375dc6dec64956aaf46fca764ce56b0949bd948f752e","qualityScore":39}');
