INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('endriwmsi/hub-ln/React-Query', 'React-Query', 'endriwmsi', 'hub-ln', 'community', 'React-Query endriwmsi hub-ln community React-Query is a skill that enables asynchronous data management using @tanstack/react-query v5. It benefits developers by simplifying data fetching, caching, and synchronization. React Query 是一个用于管理异步数据的库，提供了数据缓存、错误处理和加载状态管理等功能 React Query は非同期データ管理を実装するためのライブラリです React Query는 비동기 데이터 관리를 위한 라이브러리입니다 React-Query es una biblioteca para gestionar datos asíncronos en aplicaciones React. Permite buscar datos del servidor, crear, actualizar o eliminar recursos y sincronizar el caché automáticamente. React-Query est une bibliothèque pour gérer les données asynchrones dans les applications React. Elle permet de rechercher des données sur le serveur, de créer, de mettre à jour ou de supprimer des ressources et de synchroniser le cache automatiquement. React-Query ist eine Bibliothek zur Verwaltung asynchroner Daten in React-Anwendungen. Sie ermöglicht das Abrufen von Daten vom Server, das Erstellen, Aktualisieren oder Löschen von Ressourcen und die automatische Synchronisierung des Caches. React-Query é uma biblioteca para gerenciamento de dados assíncronos que permite buscar dados do servidor, criar, atualizar ou deletar recursos e sincronizar cache automaticamente React Query — это библиотека для управления асинхронными данными, которая позволяет запрашивать данные с сервера, создавать, обновлять или удалять ресурсы и синхронизировать кэш автоматически с помощью ИИ Агентов React-Query هي مكتبة لإدارة البيانات غير المتزامنة التي تمكن من استعلام البيانات من الخادم، وإنشاء أو تحديث أو حذف الموارد وتنسيق الذاكرة المؤقتة تلقائيًا للأدوات الذكية how to use React-Query React-Query vs Redux React-Query setup guide what is React-Query React-Query alternative React-Query install asynchronous data management React-Query caching React-Query CRUD operations React Query 异步数据管理 @tanstack/react-query 数据缓存 错误处理 加载状态管理 CRUD 操作 数据分页 React 开发 前端开发 Implement asynchronous data fetching using @tanstack/react-query v5 Manage loading and error states for a better user experience Automatically synchronize cache after mutations Perform CRUD operations with feedback visualizations Invalidate queries after mutations for data consistency Optimize data pagination and listing with React-Query React-Query is a library for managing asynchronous data in React applications, providing features like automatic cache synchronization and feedback visualizations.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('kozyszoo/antigravity-handson/frame-inspect', 'community', 'kozyszoo', 'antigravity-handson', 'kozyszoo/antigravity-handson', 'frame-inspect', 0, 0, 39, '2026-03-03T16:04:35Z', '2026-03-07T04:12:09.958Z', '3d35c797bff7a5a24baf93250012e664b7e116f68a71bb0c21087475e96fdd39', '{"id":"kozyszoo/antigravity-handson/frame-inspect","name":"frame-inspect","description":{"en":"The frame-inspect skill is a unified toolkit for video frame extraction, Remotion rendering, and spec checks. It benefits developers working with video and image processing tasks.","zh":"frame-inspect 是一个集成工具包，提供视频帧抽取、Remotion 渲染和 CLI 脚本等功能，帮助开发者提高效率","ja":"frame-inspect は、動画フレーム抽出、Remotion レンダリング、CLI スクリプトなどを統合したツールキットです","ko":"frame-inspect는 비디오 프레임 추출, Remotion 렌더링, CLI 스크립트 등을 통합한 툴킷입니다","es":"frame-inspect es un kit de herramientas integrado para desarrolladores que permite extraer frames de vídeos, renderizar Remotion y verificar especificaciones","fr":"frame-inspect est un kit d''outils intégré pour les développeurs qui permet d''extraire des frames de vidéos, de rendre Remotion et de vérifier des spécifications","de":"frame-inspect ist ein integriertes Toolkit für Entwickler, das das Extrahieren von Frames aus Videos, das Rendern von Remotion und die Überprüfung von Spezifikationen ermöglicht","pt":"O frame-inspect é uma ferramenta de linha de comando para extrair frames de vídeo e renderizar Remotion. Aprenda a usá-lo com o nosso guia de configuração","ru":"Frame-inspect - это консольная утилита для извлечения кадров видео и рендеринга Remotion. Узнайте, как ее использовать с помощью нашего руководства для разработчиков ИИ Агентов","ar":"الإطار frame-inspect هو أداة سطر أوامر لاستخراج الإطارات من الفيديو وتحويل Remotion. تعلم كيفية إعدادها باستخدام دليلنا"},"seo":{"title":{"en":"frame-inspect: Video Frame Extraction and Remotion Render.