INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('kozyszoo/antigravity-handson/frame-inspect', 'frame-inspect', 'kozyszoo', 'antigravity-handson', 'community', 'frame-inspect kozyszoo antigravity-handson community The frame-inspect skill is a unified toolkit for video frame extraction, Remotion rendering, and spec checks. It benefits developers working with video and image processing tasks. frame-inspect 是一个集成工具包，提供视频帧抽取、Remotion 渲染和 CLI 脚本等功能，帮助开发者提高效率 frame-inspect は、動画フレーム抽出、Remotion レンダリング、CLI スクリプトなどを統合したツールキットです frame-inspect는 비디오 프레임 추출, Remotion 렌더링, CLI 스크립트 등을 통합한 툴킷입니다 frame-inspect es un kit de herramientas integrado para desarrolladores que permite extraer frames de vídeos, renderizar Remotion y verificar especificaciones frame-inspect est un kit d''outils intégré pour les développeurs qui permet d''extraire des frames de vidéos, de rendre Remotion et de vérifier des spécifications frame-inspect ist ein integriertes Toolkit für Entwickler, das das Extrahieren von Frames aus Videos, das Rendern von Remotion und die Überprüfung von Spezifikationen ermöglicht O frame-inspect é uma ferramenta de linha de comando para extrair frames de vídeo e renderizar Remotion. Aprenda a usá-lo com o nosso guia de configuração Frame-inspect - это консольная утилита для извлечения кадров видео и рендеринга Remotion. Узнайте, как ее использовать с помощью нашего руководства для разработчиков ИИ Агентов الإطار frame-inspect هو أداة سطر أوامر لاستخراج الإطارات من الفيديو وتحويل Remotion. تعلم كيفية إعدادها باستخدام دليلنا how to use frame-inspect frame-inspect setup guide video frame extraction tools Remotion rendering tutorial spec check for videos frame-inspect alternative frame-inspect vs FFmpeg install frame-inspect frame-inspect documentation frame-inspect 视频帧抽取 Remotion 渲染 CLI 脚本 AI 工具 开发效率 视频处理 Remotion Extracts video frames using the `frames` command in `video-tool.sh` Renders Remotion videos to MP4 format with the `render` command Performs spec checks on videos using the `check` command with customizable specs Creates GIFs from videos using the `gif` command with adjustable FPS Displays video information using the `info` command in `video-tool.sh` Supports still image rendering from Remotion with the `still` command frame-inspect is a technical skill that integrates video frame extraction, Remotion rendering, spec checks, and visual verification for developers.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('vig-os/fd5/worktree_pr', 'community', 'vig-os', 'fd5', 'vig-os/fd5', 'worktree_pr', 0, 2, 39, '2026-02-24T16:37:27Z', '2026-03-07T04:13:56.980Z', '4a20994ee325dc2697941a643eb9a741353a6cb94062a1b96aaa8cf048181eac', '{"id":"vig-os/fd5/worktree_pr","name":"worktree_pr","description":{"en":"worktree_pr creates autonomous pull requests for scientific data products using FAIR-principled data format on HDF5. It benefits developers by automating PR creation without user interaction.","zh":"worktree_pr 是一个自动化 PR 的工具，使用 FAIR 数据和 HDF5 格式优化科学数据产品。它可以自动生成 PR 文本并创建 pull request。","ja":"worktree_pr は自動 PR 作成ツールで、FAIR データと HDF5 形式を使用して科学データ製品を最適化します。PR 文字列を自動生成し、プルリクエストを作成できます。","ko":"worktree_pr은 자동화된 PR 생성 도구로 FAIR 데이터 및 HDF5 형식을 사용하여 과학 데이터 제품을 최적화합니다. PR 텍스트를 자동으로 생성하고 pull request를 생성할 수 있습니다.","es":"Worktree_pr es una herramienta para crear solicitudes de extracción automáticas para datos científicos FAIR, utilizando Git y principios de datos auto-descriptivos","fr":"Worktree_pr est un outil pour créer des demandes d''extraction automatiques pour les données scientifiques FAIR, en utilisant Git et des principes de données auto-descriptives","de":"Worktree_pr ist ein Tool zur Erstellung automatischer Pull-Requests für FAIR-Daten, das Git und selbstbeschreibende Datenprinzipien verwendet","pt":"O worktree_pr é uma ferramenta para criar pull requests automatizados com base em commits e issues, seguindo o padrão de nomeação de branches","ru":"worktree_pr - это инструмент для автоматического создания запросов на включение изменений на основе коммитов и задач, соблюдая конвенцию именования веток","ar":"worktree_pr هو أداة لإنشاء طلبات سحب автомية باستخدام الإلتزامات والمسائل، مع اتباع اتفاقية تسمية الفروع"},"seo":{"title":{"en":"worktree_pr: Autonomous PR Setup Guide | AI Agent Skill","zh":"worktree_pr 自动化 PR 指南 - 基于 FAIR 数据的 HDF5 格式","ja":"worktree_pr の自動 PR セットアップガイド - FAIR データを使用した HDF5 形式","ko":"worktree_pr 자동 PR 설정 가이드 - FAIR 데이터를 사용한 HDF5 형식","es":"Guía de configuración de worktree_pr para datos científic...","fr":"Configurer worktree_pr pour les données scientifiques FAIR","de":"Einrichtungsleitfaden für worktree_pr zur Verwaltung von ...","pt":"Guia de Configuração do worktree_pr para FAIR Data em HDF5","ru":"Настройка worktree_pr для ИИ Агентов: Работа с FAIR Data ...","ar":"دليل إعداد worktree_pr لبيانات FAIR على HDF5 باستخدام أدو..."},"description":{"en":"Discover how worktree_pr automates pull requests without user interaction. Learn to set up FAIR Data on HDF5 with this AI agent skill.","zh":"了解 worktree_pr 如何自动创建 PR，并使用 FAIR 数据和 HDF5 格式优化科学数据产品","ja":"worktree_pr が自動で PR を作成し、FAIR データと HDF5 形式を使用して科学データ製品を最適化する方法を学ぶ","ko":"worktree_pr 이 자동으로 PR을 생성하고 FAIR 데이터 및 HDF5 형식을 사용하여 과학 데이터 제품을 최적화하는 방법에 대해 알아보십시오","es":"Aprende a crear solicitudes de extracción automáticas con worktree_pr y a aplicar los principios FAIR a tus datos científicos","fr":"Découvrez comment créer des demandes d''extraction automatiques avec worktree_pr et appliquer les principes FAIR à vos données scientifiques","de":"Erfahren Sie, wie Sie automatische Pull-Requests mit worktree_pr erstellen und die FAIR-Prinzipien auf Ihre wissenschaftlichen Daten anwenden","pt":"Aprenda a configurar o worktree_pr para criar pull requests automatizados com base em commits e issues, seguindo o padrão de nomeação de branches","ru":"Узнайте, как настроить worktree_pr для автоматического создания запросов на включение изменений на основе коммитов и задач, соблюдая конвенцию именования веток","ar":"تعرف على كيفية إعداد worktree_pr لإنشاء طلبات سحب自动ية باستخدام الإلتزامات والمسائل، مع اتباع اتفاقية تسمية الفروع"},"definition":{"en":"worktree_pr is a skill that automates the creation of pull requests using FAIR data on HDF5, following a self-describing data format for scientific data products.","zh":"worktree_pr 是一个使用 FAIR 数据和 HDF5 格式的自动化 PR 工具","ja":"worktree_pr は FAIR データと HDF5 形式を使用する自動 PR ツールです","ko":"worktree_pr은 FAIR 데이터 및 HDF5 형식을 사용하는 자동화된 PR 도구입니다","es":"Worktree_pr es un agente de AI que crea solicitudes de extracción automáticas para datos científicos FAIR","fr":"Worktree_pr est un agent IA qui crée des demandes d''extraction automatiques pour les données scientifiques FAIR","de":"Worktree_pr ist ein KI-Agent, der automatische Pull-Requests für FAIR-Daten erstellt","pt":"O worktree_pr é uma ferramenta de automação de pull requests que segue o padrão de nomeação de branches","ru":"worktree_pr - это инструмент автоматизации запросов на включение изменений, следующий конвенцию именования веток","ar":"worktree_pr هو أداة لتحسين أداء الطلبات السحب التلقائي التي تتبع اتفاقية تسمية الفروع"},"features":{"en":["Automates pull request creation using git branch and issue data","Generates PR text from commits and issues without user feedback","Follows branch naming convention using <type>/<issue_number>-<summary> format","Runs using git branch --show-current command","Creates PRs based on issue branch data, matching specific naming conventions"],"zh":["自动创建 PR","使用 FAIR 数据和 HDF5 格式","自动生成 PR 文本","创建 pull request","支持 Git 分支命名约定","无需用户交互"],"ja":["自動 PR 作成","FAIR データと HDF5 形式を使用","PR 文字列の自動生成","プルリクエストの作成","Git ブランチ命名規約のサポート","ユーザーとのやり取りが不要"],"ko":["자동 PR 생성","FAIR 데이터 및 HDF5 형식 사용","PR 텍스트 자동 생성","pull request 생성","Git 브랜치命명 규약 지원","사용자 상호 작용이 필요하지 않음"],"es":["Creación automática de solicitudes de extracción","Integración con Git para ramas y commits","Aplicación de los principios FAIR a los datos científicos","Uso de datos auto-descriptivos en formato HDF5","Compatibilidad con la convención de nombramiento de ramas"],"fr":["Création automatique de demandes d''extraction","Intégration avec Git pour les branches et les commits","Application des principes FAIR aux données scientifiques","Utilisation de données auto-descriptives au format HDF5","Compatibilité avec la convention de nommage des branches"],"de":["Automatische Erstellung von Pull-Requests","Integration mit Git für Branches und Commits","Anwendung der FAIR-Prinzipien auf wissenschaftliche Daten","Verwendung von selbstbeschreibenden Daten im HDF5-Format","Kompatibilität mit der Branch-Namenskonvention"],"pt":["Criação de pull requests automatizados com base em commits e issues","Seguimento do padrão de nomeação de branches","Geração automática de texto de pull request a partir de commits e issues","Integração com o Git para automação de fluxos de trabalho","Suporte à criação de branches com nomeação personalizada"],"ru":["Автоматическое создание запросов на включение изменений на основе коммитов и задач","Соблюдение конвенции именования веток","Автоматическая генерация текста запроса на включение изменений из коммитов и задач","Интеграция с Git для автоматизации рабочих процессов","Поддержка создания веток с индивидуальной номенклатурой"],"ar":["إنشاء طلبات سحب تلقائية باستخدام الإلتزامات والمسائل","اتباع اتفاقية تسمية الفروع","توليد تلقائي لنص الطلب السحب من الإلتزامات والمسائل","التكامل مع جيت لتحسين تدفق العمل","دعم إنشاء فروع مع تسمية مخصصة"]},"keywords":{"en":["how to use worktree_pr","worktree_pr setup guide","FAIR data on HDF5","autonomous pull request creation","git branch automation","worktree_pr vs pr_create","worktree_pr install","what is worktree_pr","worktree_pr alternative"],"zh":["worktree_pr","自动化 PR","FAIR 数据","HDF5 格式","科学数据产品","Git 分支命名约定","自动化工具","AIエージェント","代码优化"],"ja":["worktree_pr","自動 PR","FAIR データ","HDF5 形式","科学データ製品","Git ブランチ命名規約","自動化ツール","AIエージェント","コード最適化"],"ko":["worktree_pr","자동 PR","FAIR 데이터","HDF5 형식","과학 데이터 제품","Git 브랜치命명 규약","자동화 도구","AI 에이전트","코드 최적화"],"es":["worktree_pr","datos científicos FAIR","solicitudes de extracción automáticas","Git","HDF5","datos auto-descriptivos","principios FAIR","agentes de AI","herramientas de desarrollo"],"fr":["worktree_pr","données scientifiques FAIR","demandes d''extraction automatiques","Git","HDF5","données auto-descriptives","principes FAIR","agents IA","outils de développement"],"de":["worktree_pr","FAIR-Daten","automatische Pull-Requests","Git","HDF5","selbstbeschreibende Daten","FAIR-Prinzipien","KI-Agenten","Entwicklungstools"],"pt":["worktree_pr","FAIR Data","HDF5","pull requests automatizados","nomeação de branches","Git","automação de fluxos de trabalho","criação de branches personalizados"],"ru":["worktree_pr","ИИ Агенты","FAIR Data","HDF5","автоматическое создание запросов на включение изменений","конвенция именования веток","Git","автоматизация рабочих процессов","создание веток с индивидуальной номенклатурой"],"ar":["worktree_pr","أدوات الذكاء الاصطناعي","بيانات FAIR","HDF5","طلبات سحب تلقائية","اتفاقية تسمية الفروع","جيت","تحسين تدفق العمل","إنشاء فروع مع تسمية مخصصة"]}},"owner":"vig-os","repo":"fd5","repoPath":"vig-os/fd5","stars":0,"forks":2,"updatedAt":"2026-02-24T16:37:27Z","topics":[],"category":"community","skillMd":{"name":"worktree_pr","description":"Autonomous PR creation from a worktree branch.","bodyPreview":"# Autonomous PR\n\nCreate a pull request **without user interaction**. This is the worktree variant of [pr_create](../pr_create/SKILL.md).\n\n**Rule: no blocking for feedback. Auto-generate PR text from commits and issue.**\n\n## Precondition: Issue Branch Required\n\n1. Run: `git branch --show-current`\n2. The branch name **must** match `<type>/<issue_number>-<summary>` (e.g. `feature/79-declarative-sync-manifest`). See [branch-naming.mdc](../../rules/branch-naming.mdc) for the full convention.\n3. Extra","body":"# Autonomous PR\n\nCreate a pull request **without user interaction**. This is the worktree variant of [pr_create](../pr_create/SKILL.md).\n\n**Rule: no blocking for feedback. Auto-generate PR text from commits and issue.**\n\n## Precondition: Issue Branch Required\n\n1. Run: `git branch --show-current`\n2. The branch name **must** match `<type>/<issue_number>-<summary>` (e.g. `feature/79-declarative-sync-manifest`). See [branch-naming.mdc](../../rules/branch-naming.mdc) for the full convention.\n3. Extract the `<issue_number>` from the branch name.\n\n## Workflow Steps\n\n### 1. Ensure clean state\n\n```bash\ngit status\ngit fetch origin\n```\n\n- If there are uncommitted changes, commit them first.\n- Push the branch: `git push -u origin HEAD`\n\n### 2. Determine base branch\n\nDetect whether this issue is a sub-issue and resolve the correct merge target:\n\n1. Determine the repo: `gh repo view --json nameWithOwner --jq ''.nameWithOwner''`\n2. Check for a parent issue:\n\n   ```bash\n   gh api repos/{owner}/{repo}/issues/{issue_number}/parent --jq ''.number''\n   ```\n\n3. If a parent exists, resolve its linked branch:\n\n   ```bash\n   gh issue develop --list <parent_number>\n   ```\n\n   - Use the parent''s branch as `<base_branch>`.\n   - If the parent has no linked branch, fall back to `dev`.\n\n4. If no parent exists, use `dev` as `<base_branch>`.\n\n### 3. Gather context\n\n```bash\ngit log <base_branch>..HEAD --oneline\ngit diff <base_branch>...HEAD --stat\ngh issue view <issue_number> --json title,body\n```\n\n- Read the issue title and acceptance criteria.\n- Summarize what the commits accomplish.\n\n### 4. Ensure CHANGELOG is updated\n\n- Check `CHANGELOG.md` for an entry under `## Unreleased` that covers the changes.\n- If missing, add the appropriate entry and commit.\n\n### 5. Generate PR text\n\n1. **Read the template**: `cat .github/pull_request_template.md`\n2. **Use it as the literal skeleton** — keep every heading, every checkbox line, every sub-heading. Strip only the HTML comments (`<!-- ... -->`).\n3. **Section-by-section mapping**:\n   - **Description**: Summarize what the PR does from the issue body and commit messages.\n   - **Type of Change**: Check the single box matching the branch type / commit types. Check `Breaking change` modifier only if commits contain `!`.\n   - **Changes Made**: List changed files with bullet sub-details (from `git diff --stat` and `git log`).\n   - **Changelog Entry**: Paste the exact `## Unreleased` diff from CHANGELOG.md. If no changelog update, write \"No changelog needed\" and explain.\n   - **Testing**: Check `Tests pass locally` if tests were run. Check `Manual testing performed` only if actually done. Fill `Manual Testing Details` or write \"N/A\".\n   - **Checklist**: Check only items that are genuinely true. Leave unchecked items unchecked — do not remove them.\n   - **Additional Notes**: Add design links, context, or write \"N/A\".\n   - **Refs**: `Refs: #<issue_number>`\n4. **Explicit prohibitions**: Do not invent new sections. Do not rename headings. Do not omit sections. Do not remove unchecked boxes.\n5. Write the body to `.github/pr-draft-<issue_number>.md`.\n\n### 6. Create PR\n\n```bash\n# Append reviewer if PR_REVIEWER is set in environment\nREVIEWER_ARG=\"\"\nif [ -n \"${PR_REVIEWER:-}\" ]; then\n  REVIEWER_ARG=\"--reviewer $PR_REVIEWER\"\nfi\n\ngh pr create --base <base_branch> --title \"<type>: <description> (#<issue_number>)\" \\\n  --body-file .github/pr-draft-<issue_number>.md \\\n  --assignee @me $REVIEWER_ARG\n```\n\nIf the `WORKTREE_REVIEWER` environment variable is set (populated by `just worktree-start`), add the reviewer:\n\n```bash\ngh pr create --base <base_branch> --title \"<type>: <description> (#<issue_number>)\" \\\n  --body-file .github/pr-draft-<issue_number>.md \\\n  --assignee @me \\\n  --reviewer \"$WORKTREE_REVIEWER\"\n```\n\nThe reviewer is the person who launched the worktree (their gh user login), not the agent.\n\n### 7. Clean up\n\n- Delete the draft file: `rm .github/pr-draft-<issue_number>.md`\n- Report the PR URL.\n\n## Delegation\n\nThe following steps SHOULD be delegated to reduce token consumption:\n\n- **Steps 1-2** (precondition check, ensure clean state, determine base branch): Spawn a Task subagent with `model: \"fast\"` that validates the branch name, runs `git status`/`git fetch`, pushes the branch, checks for a parent issue via `gh api`, resolves the base branch. Returns: issue number, base branch name, clean state confirmation.\n- **Step 3** (gather context): Spawn a Task subagent with `model: \"fast\"` that executes `git log`, `git diff`, `gh issue view` and returns the raw outputs. Returns: commit log, diff stat, issue title/body.\n- **Steps 6-7** (create PR, clean up): Spawn a Task subagent with `model: \"fast\"` that takes the PR title and body file path, executes `gh pr create`, deletes the draft file, and returns the PR URL.\n\nSteps 4-5 (ensure CHANGELOG updated, generate PR text) should remain in the main agent as they require understanding changes and writing structured content.\n\nReference: [subagent-delegation rule](../../rules/subagent-delegation.mdc)\n\n## Important Notes\n\n- Never block for user review of the PR text. Generate the best text from available context.\n- Base branch is auto-detected: parent issue''s branch for sub-issues, `dev` otherwise.\n- The PR title should follow commit message conventions: `type(scope): description (#issue)`.\n- **NEVER add ''Co-authored-by: Cursor <cursoragent@cursor.com>''** to commit messages.\n"},"lastSynced":"2026-03-07T04:13:56.980Z","agentAnalysis":{"suitability":{"en":"Perfect for DevOps Agents needing autonomous pull request creation for scientific data products in HDF5 format.","zh":"非常适合需要自动创建科学数据产品的pull request的DevOps代理，尤其是支持HDF5格式的数据产品。","ja":"DevOpsエージェントがHDF5形式の科学データ製品の自動プルリクエストを作成する必要がある場合に最適です。","ko":"HDF5 형식의 과학 데이터 제품에 대한 자동 풀 리퀘스트 생성이 필요한 DevOps 에이전트에 적합합니다.","es":"Perfecto para agentes de DevOps que necesitan la creación autónoma de solicitudes de extracción para productos de datos científicos en formato HDF5.","fr":"Parfait pour les agents DevOps ayant besoin de la création autonome de demandes d''extraction pour les produits de données scientifiques au format HDF5.","de":"Perfekt für DevOps-Agents, die eine autonome Erstellung von Pull-Requests für wissenschaftliche Datenprodukte im HDF5-Format benötigen.","pt":"Perfeito para agentes DevOps que necessitam de criação autônoma de solicitações de pull para produtos de dados científicos no formato HDF5.","ru":"Идеально подходит для агентов DevOps, которым требуется автономное создание запросов на принятие для научных данных в формате HDF5.","ar":"مثالي لعميل DevOps الذي يحتاج إلى إنشاء طلبات السحب ذاتية التشغيل لمنتجات البيانات العلمية بالتنسيق HDF5."},"recommendation":{"en":"Empowers agents to automate pull requests without user interaction, utilizing FAIR-principled data formats and generating PR text from commits and issues, leveraging Git branch naming conventions and HDF5 data format.","zh":"赋予代理自动创建pull request的能力，而无需用户交互，利用遵循FAIR原则的数据格式，并从提交和问题中生成PR文本，同时利用Git分支命名约定和HDF5数据格式。","ja":"エージェントがユーザーとのやり取りを必要とせずにプルリクエストを自動化できるようにし、FAIR原則に従ったデータ形式を利用し、コミットおよび問題からPRテキストを生成し、Gitブランチ命名規則およびHDF5データ形式を利用します。","ko":"에이전트가 사용자 상호 작용 없이 풀 리퀘스트를 자동화 할 수 있도록 하며, FAIR 원칙에 따라 데이터 형식을 사용하고, 커밋 및 문제에서 PR 텍스트를 생성하며, Git 브랜치命명 규칙 및 HDF5 데이터 형식을 활용합니다.","es":"Habilita a los agentes a automatizar las solicitudes de extracción sin interacción del usuario, utilizando formatos de datos basados en los principios FAIR y generando texto de PR a partir de confirmaciones y problemas, aprovechando las convenciones de nomenclatura de ramas de Git y el formato de datos HDF5.","fr":"Permet aux agents d''automatiser les demandes d''extraction sans interaction utilisateur, en utilisant des formats de données basés sur les principes FAIR et en générant du texte de PR à partir de validations et de problèmes, en exploitant les conventions de dénomination de branches Git et le format de données HDF5.","de":"Ermöglicht es Agenten, Pull-Requests ohne Benutzereingriff zu automatisieren, indem FAIR-Prinzip-basierte Datenformate verwendet und PR-Text aus Commits und Issues generiert werden, unter Ausnutzung von Git-Zweigbenennungskonventionen und HDF5-Datenformat.","pt":"Permite que os agentes automatem as solicitações de pull sem interação do usuário, utilizando formatos de dados baseados nos princípios FAIR e gerando texto de PR a partir de commits e problemas, aproveitando as convenções de nomenclatura de branch do Git e o formato de dados HDF5.","ru":"Позволяет агентам автоматизировать запросы на принятие без взаимодействия с пользователем, используя форматы данных, основанные на принципах FAIR, и генерируя текст PR из коммитов и проблем, используя соглашения об именах веток Git и формат данных HDF5.","ar":"يمكن للوكلاء توفير التutomatization لطلبات السحب دون تفاعل المستخدم، باستخدام تنسيقات البيانات المعتمدة على مبادئ FAIR وتوليد نص PR من الالتزامات وقضايا التتبع، بالاستفادة من الاتفاقيات المتبعة لاسم الفرع في Git وتنسيق بيانات HDF5."},"useCases":{"en":["Automating pull requests for scientific data updates","Generating PR text from commit messages and issue trackers","Streamlining data product deployment using FAIR principles"],"zh":["自动化科学数据更新的pull request","从提交消息和问题跟踪器生成PR文本","使用FAIR原则简化数据产品的部署"],"ja":["科学データの更新のプルリクエストを自動化する","コミットメッセージおよび問題トラッカーからPRテキストを生成する","FAIR原則を使用してデータ製品の展開を簡素化する"],"ko":["과학 데이터 업데이트를 위한 풀 리퀘스트 자동화","커밋 메시지 및 문제 추적기에서 PR 텍스트 생성","FAIR 원칙을 사용하여 데이터 제품 배포를 간소화"],"es":["Automatizar solicitudes de extracción para actualizaciones de datos científicos","Generar texto de PR a partir de mensajes de confirmación y seguimiento de problemas","Optimizar la implementación de productos de datos mediante principios FAIR"],"fr":["Automatiser les demandes d''extraction pour les mises à jour de données scientifiques","Générer du texte de PR à partir de messages de validation et de suivi de problèmes","Optimiser le déploiement de produits de données à l''aide de principes FAIR"],"de":["Automatisierung von Pull-Requests für wissenschaftliche Daten-Updates","Generierung von PR-Text aus Commit-Nachrichten und Issue-Trackern","Optimierung der Bereitstellung von Datenprodukten unter Verwendung von FAIR-Prinzipien"],"pt":["Automatizar solicitações de pull para atualizações de dados científicos","Gerar texto de PR a partir de mensagens de commit e rastreadores de problemas","Otimizar a implantação de produtos de dados usando princípios FAIR"],"ru":["Автоматизировать запросы на принятие для обновлений научных данных","Генерировать текст PR из сообщений коммитов и отслеживателей проблем","Оптимизировать развертывание продуктов данных, используя принципы FAIR"],"ar":["توفير Automatization لطلبات السحب لتحديثات البيانات العلمية","توليد نص PR من رسائل الالتزام وقضايا التتبع","تسهيل نشر منتجات البيانات باستخدام مبادئ FAIR"]},"limitations":{"en":["Requires Git repository access","Adherence to specific branch naming conventions","HDF5 data format compatibility"],"zh":["需要Git仓库访问权限","需要遵守特定的分支命名约定","需要HDF5数据格式兼容性"],"ja":["Gitリポジトリへのアクセスが必要","特定のブランチ命名規則に従う必要がある","HDF5データ形式との互換性が必要"],"ko":["Git 저장소 액세스 필요","특정 브랜치命명 규칙 준수 필요","HDF5 데이터 형식 호환성 필요"],"es":["Requiere acceso al repositorio Git","Adhesión a convenciones de nomenclatura de ramas específicas","Compatibilidad con el formato de datos HDF5"],"fr":["Nécessite un accès au référentiel Git","Adhésion à des conventions de dénomination de branches spécifiques","Compatibilité avec le format de données HDF5"],"de":["Erfordert Zugriff auf Git-Repository","Einhaltung spezifischer Zweigbenennungskonventionen","Kompatibilität mit dem HDF5-Datenformat"],"pt":["Requer acesso ao repositório Git","Adesão a convenções de nomenclatura de branch específicas","Compatibilidade com o formato de dados HDF5"],"ru":["Требуется доступ к репозиторию Git","Соблюдение определенных соглашений об именах веток","Совместимость с форматом данных HDF5"],"ar":["يتطلب الوصول إلى مستودع Git","الامتثال لاتفاقيات命名前 الفرع المحددة","التوافق مع تنسيق بيانات HDF5"]},"version":4},"contentHash":"4a20994ee325dc2697941a643eb9a741353a6cb94062a1b96aaa8cf048181eac","qualityScore":39}');
