INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('grgrwlkr/SimCity/simcity-start-game', 'community', 'grgrwlkr', 'SimCity', 'grgrwlkr/SimCity', 'simcity-start-game', 0, 0, 39, '2026-03-07T01:49:01.751Z', '2026-03-07T03:01:04.922Z', 'f35162e2ee77f136fcf26ee1db298da95953b21ea6bf841a55b36f9141f5f8a4', '{"id":"grgrwlkr/SimCity/simcity-start-game","name":"simcity-start-game","description":{"en":"The simcity-start-game skill automates the initialization of SimCity games, benefiting developers and gamers alike. It streamlines the process of checking for existing instances, stopping games, and running new instances.","zh":"SimCity Start Game 是一个用于启动 SimCity 游戏的 AIエージェント工具，通过运行 cargo 命令和监控终端输出来启动游戏","ja":"SimCity Start Game は、cargo コマンドを実行し、ターミナル出力を監視して SimCity ゲームを開始する AIエージェントです","ko":"SimCity Start Game은 Cargo 명령을 실행하고 터미널 출력을 모니터링하여 SimCity 게임을 시작하는 AI 에이전트입니다","es":"SimCity Start Game es un agente de IA que utiliza Cargo para iniciar el juego. Sigue nuestra guía para configurarlo correctamente","fr":"SimCity Start Game est un agent IA qui utilise Cargo pour démarrer le jeu. Suivez notre guide pour le configurer correctement","de":"SimCity Start Game ist ein IA-Agent, der Cargo verwendet, um das Spiel zu starten. Folgen Sie unserer Anleitung, um es richtig zu konfigurieren","pt":"O SimCity Start Game é uma habilidade que permite iniciar o jogo SimCity com configurações personalizadas. Siga nossa guia para aprender como iniciar o jogo.","ru":"SimCity Start Game - это навык, который позволяет запустить игру SimCity с настраиваемыми параметрами. Следуйте нашей инструкции, чтобы узнать, как начать игру с помощью ИИ Агентов","ar":"SimCity Start Game هو مهارة تسمح ببدء لعبة SimCity بإعدادات مخصصة. اتبع دليلنا لتعلم كيفية بدء اللعبة باستخدام أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"simcity-start-game: Automated Game Initialization Setup G...","zh":"SimCity Start Game 设置指南 - AIエージェント工具","ja":"SimCity Start Game セットアップガイド - AIエージェント","ko":"SimCity Start Game 설정 가이드 - AI 에이전트 도구","es":"Guía de configuración de SimCity Start Game con Cargo","fr":"Guide de démarrage de SimCity Start Game avec Cargo","de":"Einrichtungsleitfaden für SimCity Start Game mit Cargo","pt":"Guia de Configuração do SimCity Start Game","ru":"Начало игры SimCity: Руководство по настройке ИИ Агентов","ar":"دليل إعداد لعبة SimCity Start Game باستخدام أدوات الذكاء ..."},"description":{"en":"Discover how to automate SimCity game startup with the simcity-start-game skill. Learn to stop instances, run cargo, and monitor terminal output with ease. G...","zh":"了解如何使用 SimCity Start Game AIエージェント工具启动游戏，包括停止运行实例、运行 cargo 命令和监控终端输出","ja":"SimCity Start Game を開始する方法を学びます。実行中のインスタンスを停止し、cargo コマンドを実行し、ターミナル出力を監視します","ko":"SimCity Start Game을 시작하는 방법을 알아보세요. 실행 중인 인스턴스를停止하고 Cargo 명령을 실행하고 터미널 출력을 모니터링합니다","es":"Aprende a iniciar SimCity Start Game con Cargo y a resolver problemas comunes con nuestra guía paso a paso","fr":"Découvrez comment démarrer SimCity Start Game avec Cargo et résoudre les problèmes courants avec notre guide étape par étape","de":"Erfahren Sie, wie Sie SimCity Start Game mit Cargo starten und häufige Probleme lösen können, mit unserer Schritt-für-Schritt-Anleitung","pt":"Aprenda a iniciar o SimCity com nossa guia passo a passo, incluindo parar instâncias existentes e executar com cargo run","ru":"Узнайте, как запустить SimCity с нашей пошаговой инструкцией, включая остановку существующих экземпляров и запуск с помощью cargo run для ИИ Агентов","ar":"تعلم كيف تبدأ لعبة SimCity باتباع دليلنا خطوة بخطوة، بما في ذلك إيقاف مثيلات موجودة وتشغيلها باستخدام cargo run لأدوات الذكاء الاصطناعي"},"definition":{"en":"simcity-start-game is a skill that automates the startup of SimCity games, utilizing commands like pgrep, cargo run, and bash scripts to manage game instances.","zh":"SimCity Start Game 是一种 AIエージェント工具，用于自动启动 SimCity 游戏","ja":"SimCity Start Game は、SimCity ゲームを自動で開始する AIエージェントです","ko":"SimCity Start Game은 SimCity 게임을 자동으로 시작하는 AI 에이전트입니다","es":"SimCity Start Game es un agente de IA que inicia el juego SimCity utilizando comandos de Cargo","fr":"SimCity Start Game est un agent IA qui démarre le jeu SimCity en utilisant des commandes Cargo","de":"SimCity Start Game ist ein IA-Agent, der das Spiel SimCity mithilfe von Cargo-Befehlen startet","pt":"O que é SimCity Start Game? É uma habilidade que permite iniciar o jogo SimCity com configurações personalizadas","ru":"Что такое SimCity Start Game? Это навык, который позволяет запустить игру SimCity с настраиваемыми параметрами для ИИ Агентов","ar":"ما هو SimCity Start Game؟ هو مهارة تسمح ببدء لعبة SimCity بإعدادات مخصصة لأدوات الذكاء الاصطناعي"},"features":{"en":["Utilizes pgrep to check for existing SimCity game instances","Runs cargo with block_until_ms: 0 to background the game","Stops running instances using bash scripts like stop_game.sh","Monitors terminal output for game window creation","Retries list components with short sleeps to connect to MCP","Keeps the game running for at least 60 seconds before stopping"],"zh":["停止运行实例","运行 cargo 命令","监控终端输出","自动启动 SimCity 游戏","支持 block_until_ms 参数","实时监控游戏窗口创建"],"ja":["実行中のインスタンスを停止","cargo コマンドを実行","ターミナル出力を監視","SimCity ゲームを自動で開始","block_until_ms パラメータをサポート","ゲームウィンドウの作成をリアルタイムで監視"],"ko":["실행 중인 인스턴스를停止","Cargo 명령을 실행","터미널 출력을 모니터링","SimCity 게임을 자동으로 시작","block_until_ms 파라미터를 지원","게임 창의 생성을 실시간으로 모니터링"],"es":["Inicia el juego SimCity utilizando el comando `cargo run`","Detiene instancias del juego en ejecución con `./stop_game.sh`","Monitorea la salida del terminal hasta que se cree la ventana del juego","Conecta al juego con `list components` y espera hasta 60 segundos antes de detenerlo","Utiliza `pgrep -fl simcity` para buscar instancias del juego en ejecución","Ejecuta comandos en segundo plano con `block_until_ms: 0`"],"fr":["Démarre le jeu SimCity en utilisant la commande `cargo run`","Arrête les instances du jeu en cours d''exécution avec `./stop_game.sh`","Surveille la sortie du terminal jusqu''à ce que la fenêtre du jeu soit créée","Se connecte au jeu avec `list components` et attend jusqu''à 60 secondes avant de l''arrêter","Utilise `pgrep -fl simcity` pour rechercher les instances du jeu en cours d''exécution","Exécute des commandes en arrière-plan avec `block_until_ms: 0`"],"de":["Startet das Spiel SimCity mit dem Befehl `cargo run`","Beendet laufende Instanzen des Spiels mit `./stop_game.sh`","Überwacht die Terminalausgabe, bis das Spiel fenster erstellt ist","Verbindet sich mit dem Spiel mit `list components` und wartet bis zu 60 Sekunden, bevor es beendet","Verwendet `pgrep -fl simcity`, um laufende Instanzen des Spiels zu suchen","Führt Befehle im Hintergrund mit `block_until_ms: 0` aus"],"pt":["Iniciar o jogo SimCity com configurações personalizadas","Parar instâncias existentes do jogo","Executar o jogo com cargo run","Monitorar a saída do terminal","Conectar-se ao jogo após um tempo de espera","Manter o jogo em execução por pelo menos 60 segundos"],"ru":["Запуск игры SimCity с настраиваемыми параметрами для ИИ Агентов","Остановка существующих экземпляров игры","Запуск игры с помощью cargo run","Мониторинг терминального вывода","Подключение к игре после короткого времени ожидания","Поддержание игры в работе не менее 60 секунд"],"ar":["بدء لعبة SimCity بإعدادات مخصصة لأدوات الذكاء الاصطناعي","إيقاف مثيلات موجودة من اللعبة","تشغيل اللعبة باستخدام cargo run","مراقبةخرج الطرفية","الوصول إلى اللعبة بعد فترة انتظار قصيرة","الحفاظ على تشغيل اللعبة لمدة لا تقل عن 60 ثانية"]},"keywords":{"en":["how to use simcity-start-game","simcity-start-game setup guide","simcity-start-game alternative","simcity-start-game vs manual startup","what is simcity-start-game","simcity-start-game install","automated game initialization","simcity game startup","cargo run command","pgrep command"],"zh":["SimCity Start Game","AIエージェント工具","cargo 命令","终端输出监控","自动启动游戏","block_until_ms 参数","游戏窗口创建监控"],"ja":["SimCity Start Game","AIエージェント","cargo コマンド","ターミナル出力監視","自動ゲーム開始","block_until_ms パラメータ","ゲームウィンドウ作成監視"],"ko":["SimCity Start Game","AI 에이전트 도구","Cargo 명령","터미널 출력 모니터링","자동 게임 시작","block_until_ms 파라미터","게임 창 생성 모니터링"],"es":["SimCity Start Game","agente de IA","Cargo","iniciar juego","detener instancia","monitorear terminal","conectar al juego","comandos en segundo plano","pgrep","list components"],"fr":["SimCity Start Game","agent IA","Cargo","démarrer jeu","arrêter instance","surveiller terminal","se connecter au jeu","commandes en arrière-plan","pgrep","list components"],"de":["SimCity Start Game","IA-Agent","Cargo","Spiel starten","Instanz beenden","Terminal überwachen","Spiel verbinden","Befehle im Hintergrund","pgrep","list components"],"pt":["SimCity Start Game","iniciar jogo SimCity","configurações personalizadas","parar instâncias existentes","cargo run","monitorar saída do terminal","conectar-se ao jogo","manter jogo em execução","desenvolvedores de jogos","ferramentas de desenvolvimento de jogos"],"ru":["SimCity Start Game","запустить игру SimCity","настраиваемые параметры","остановка существующих экземпляров","cargo run","мониторинг терминального вывода","подключение к игре","поддержание игры в работе","разработчики игр","инструменты разработки игр для ИИ Агентов"],"ar":["SimCity Start Game","بدء لعبة SimCity","إعدادات مخصصة","إيقاف مثيلات موجودة","cargo run","مراقبةخرج الطرفية","الوصول إلى اللعبة","الحفاظ على تشغيل اللعبة","مطورو الألعاب","أدوات تطوير الألعاب لأدوات الذكاء الاصطناعي"]}},"owner":"grgrwlkr","repo":"SimCity","repoPath":"grgrwlkr/SimCity","stars":0,"forks":0,"updatedAt":"2026-03-07T01:49:01.751Z","topics":[],"category":"community","skillMd":{"name":"simcity-start-game","description":"Start the SimCity game via cargo run, ensure no existing instance, and wait for MCP connectivity. Use when starting the game, before MCP checks, or before live tests that need a running game. Russian triggers: запусти игру, стартани SimCity, подними игру перед MCP, перезапусти игру.","bodyPreview":"# SimCity Start Game\n\n## Quick Start\n1. Check for an existing instance (see terminals folder; use `pgrep -fl simcity`).\n2. Stop any running instance using `./stop_game.sh` (or `bash ./stop_game.sh`).\n3. Run `cargo run` from the repo root with `block_until_ms: 0` to background it.\n4. Monitor the terminal output until the game window is created.\n5. Wait for MCP: retry `list components` with short sleeps until connected.\n6. Keep the game running for at least 60 seconds before stopping or concluding","body":"# SimCity Start Game\n\n## Quick Start\n1. Check for an existing instance (see terminals folder; use `pgrep -fl simcity`).\n2. Stop any running instance using `./stop_game.sh` (or `bash ./stop_game.sh`).\n3. Run `cargo run` from the repo root with `block_until_ms: 0` to background it.\n4. Monitor the terminal output until the game window is created.\n5. Wait for MCP: retry `list components` with short sleeps until connected.\n6. Keep the game running for at least 60 seconds before stopping or concluding startup checks.\n\n## Russian Trigger Equivalents\n\n- запусти игру\n- стартани SimCity\n- подними игру перед MCP\n- перезапусти игру\n\n## Commands\n```bash\n./stop_game.sh\ncargo run\n```\n\n## MCP Wait Loop\n- Try `user-bevy-debugger-observe` with `list components`.\n- If not connected, `sleep 1–3s` and retry until it connects or you hit a reasonable timeout.\n\n## Notes\n- Always stop any previous instance before starting (R10.6).\n- Use the project root as the working directory.\n- Report the terminal file path and MCP readiness status.\n- Do not stop or restart the game earlier than 1 minute after successful startup, unless the user explicitly requests it."},"lastSynced":"2026-03-07T03:01:04.922Z","agentAnalysis":{"suitability":{"en":"Perfect for Gaming Agents needing automated SimCity game initialization and management capabilities.","zh":"非常适合需要自动初始化和管理 SimCity 游戏的游戏代理","ja":"SimCity ゲームの自動初期化と管理機能が必要なゲーミング エージェントに最適","ko":"자동으로 SimCity 게임을 초기화하고 관리할 수 있는 게임 에이전트에 적합","es":"Perfecto para agentes de juegos que necesitan capacidades de inicialización y gestión automatizadas del juego SimCity.","fr":"Parfait pour les agents de jeux ayant besoin de capacités d''initialisation et de gestion automatisées du jeu SimCity.","de":"Perfekt für Gaming-Agents, die automatisierte SimCity-Spiel-Initialisierungs- und Managementfunktionen benötigen.","pt":"Perfeito para Agentes de Jogo que necessitam de capacidades de inicialização e gerenciamento automatizados do jogo SimCity.","ru":"Идеально подходит для Игровых Агентов, которым необходимы автоматизированные возможности инициализации и управления игрой SimCity.","ar":"مثالي للوكلاء اللعبة الذين يحتاجون إلى قدرات автоматية لتثبيت وتشغيل لعبة SimCity."},"recommendation":{"en":"Empowers agents to streamline SimCity game startup using cargo run, pgrep, and bash scripting, while ensuring existing instances are properly stopped and monitored through terminal output and MCP component listing.","zh":"使得代理能够使用 cargo run、pgrep 和 bash 脚本简化 SimCity 游戏的启动，同时确保现有的实例被正确停止和监控，通过终端输出和 MCP 组件列表","ja":"エージェントが cargo run、pgrep、bash スクリプトを使用して SimCity ゲームの起動を簡素化することを可能にし、既存のインスタンスが正しく停止および監視されることを保証、ターミナル出力と MCP コンポーネントのリストを介して","ko":"에이전트가 cargo run, pgrep 및 bash 스크립트를 사용하여 SimCity 게임의 시작을 간소화할 수 있도록 하며, 기존 인스턴스가 올바르게 중지되고 터미널 출력 및 MCP 구성 요소 목록을 통해監视되는 것을 보장","es":"Permite a los agentes simplificar el inicio del juego SimCity utilizando cargo run, pgrep y scripting de bash, asegurando que las instancias existentes se detengan y se supervisen adecuadamente a través de la salida del terminal y la lista de componentes de MCP.","fr":"Permet aux agents de simplifier le démarrage du jeu SimCity en utilisant cargo run, pgrep et la scripting bash, en assurant que les instances existantes soient correctement arrêtées et surveillées via la sortie du terminal et la liste des composants MCP.","de":"Ermöglicht es Agenten, den SimCity-Spielstart mithilfe von cargo run, pgrep und bash-Scripting zu strukturieren, während sichergestellt wird, dass bestehende Instanzen ordnungsgemäß gestoppt und überwacht werden durch Terminalausgaben und MCP-Komponentenlisten.","pt":"Habilita os agentes a simplificar a inicialização do jogo SimCity usando cargo run, pgrep e script de bash, garantindo que as instâncias existentes sejam paradas e monitoradas corretamente por meio da saída do terminal e da lista de componentes do MCP.","ru":"Наделяет агентов возможностью упростить запуск игры SimCity с помощью cargo run, pgrep и скриптов bash, обеспечивая правильное остановку и мониторинг существующих экземпляров через вывод терминала и перечисление компонентов MCP.","ar":"يمكن الوكلاء من简ification بدء تشغيل لعبة SimCity باستخدام cargo run و pgrep وبرمجة bash، مع ضمان إيقاف تشغيل الحالات الحالية ومراقبتها بشكل صحيح من خلال إخراج الطرفية وقائمة مكونات MCP."},"useCases":{"en":["Automating SimCity game initialization for testing and development purposes","Stopping and restarting existing SimCity game instances using stop_game.sh scripts","Monitoring and managing SimCity game windows and MCP connections"],"zh":["自动初始化 SimCity 游戏以进行测试和开发","使用 stop_game.sh 脚本停止和重启现有的 SimCity 游戏实例","监控和管理 SimCity 游戏窗口和 MCP 连接"],"ja":["テストと開発のための SimCity ゲームの自動初期化","stop_game.sh スクリプトを使用して既存の SimCity ゲームインスタンスを停止および再起動","SimCity ゲームウィンドウと MCP 接続の監視と管理"],"ko":["테스트 및 개발을 위한 SimCity 게임 자동 초기화","stop_game.sh 스크립트를 사용하여 기존 SimCity 게임 인스턴스를 중지하고 재시작","SimCity 게임 창 및 MCP 연결을 모니터링하고 관리"],"es":["Automatizar la inicialización del juego SimCity para fines de prueba y desarrollo","Detener y reiniciar instancias existentes del juego SimCity utilizando scripts stop_game.sh","Supervisar y gestionar ventanas y conexiones de juego SimCity y MCP"],"fr":["Automatiser l''initialisation du jeu SimCity pour les besoins de test et de développement","Arrêter et redémarrer les instances existantes du jeu SimCity à l''aide de scripts stop_game.sh","Surveiller et gérer les fenêtres et les connexions du jeu SimCity et MCP"],"de":["Automatisierung der SimCity-Spiel-Initialisierung für Test- und Entwicklungszwecke","Anhalten und Neustarten bestehender SimCity-Spiel-Instanzen unter Verwendung von stop_game.sh-Skripten","Überwachung und Verwaltung von SimCity-Spiel-Fenstern und MCP-Verbindungen"],"pt":["Automatizar a inicialização do jogo SimCity para fins de teste e desenvolvimento","Parar e reiniciar instâncias existentes do jogo SimCity usando scripts stop_game.sh","Monitorar e gerenciar janelas do jogo SimCity e conexões MCP"],"ru":["Автоматизировать инициализацию игры SimCity для целей тестирования и разработки","Остановить и перезапустить существующие экземпляры игры SimCity с помощью скриптов stop_game.sh","Отслеживать и управлять окнами игры SimCity и подключениями MCP"],"ar":["تutomatizar بدء تشغيل لعبة SimCity لأغراض الاختبار والتنمية","إيقاف التشغيل وإعادة تشغيل الحالات الحالية من لعبة SimCity باستخدام سكريبتات stop_game.sh","مراقبة وإدارة نوافذ لعبة SimCity واتصالات MCP"]},"limitations":{"en":["Requires cargo and bash environment","Limited to SimCity game instances","Needs proper configuration of terminals folder and stop_game.sh scripts"],"zh":["需要 cargo 和 bash 环境","仅限 SimCity 游戏实例","需要正确配置终端文件夹和 stop_game.sh 脚本"],"ja":["cargo と bash 環境が必要","SimCity ゲームインスタンスのみ","ターミナルフォルダと stop_game.sh スクリプトの正しい構成が必要"],"ko":["cargo 및 bash 환경이 필요","SimCity 게임 인스턴스만 해당","터미널 폴더 및 stop_game.sh 스크립트의 올바른 구성이 필요"],"es":["Requiere un entorno de cargo y bash","Limitado a instancias de juego SimCity","Necesita una configuración adecuada de la carpeta de terminales y los scripts stop_game.sh"],"fr":["Nécessite un environnement cargo et bash","Limité aux instances du jeu SimCity","Nécessite une configuration appropriée du dossier des terminaux et des scripts stop_game.sh"],"de":["Benötigt eine cargo- und bash-Umgebung","Begrenzt auf SimCity-Spiel-Instanzen","Benötigt eine ordnungsgemäße Konfiguration des Terminals-Ordners und der stop_game.sh-Skripte"],"pt":["Exige ambiente cargo e bash","Limitado a instâncias do jogo SimCity","Necessita de configuração adequada da pasta de terminais e scripts stop_game.sh"],"ru":["Требует среды cargo и bash","Ограничен экземплярами игры SimCity","Требует правильной настройки папки терминалов и скриптов stop_game.sh"],"ar":["يتطلب بيئة cargo و bash","محدود بالحالات الحالية من لعبة SimCity","يحتاج إلى تكوين مناسب لمجلد الطرفية وسكريبتات stop_game.sh"]},"version":4},"contentHash":"f35162e2ee77f136fcf26ee1db298da95953b21ea6bf841a55b36f9141f5f8a4","qualityScore":39}');
