INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('grgrwlkr/SimCity/simcity-start-game', 'simcity-start-game', 'grgrwlkr', 'SimCity', 'community', 'simcity-start-game grgrwlkr SimCity community The simcity-start-game skill automates the initialization of SimCity games, benefiting developers and gamers alike. It streamlines the process of checking for existing instances, stopping games, and running new instances. SimCity Start Game 是一个用于启动 SimCity 游戏的 AIエージェント工具，通过运行 cargo 命令和监控终端输出来启动游戏 SimCity Start Game は、cargo コマンドを実行し、ターミナル出力を監視して SimCity ゲームを開始する AIエージェントです SimCity Start Game은 Cargo 명령을 실행하고 터미널 출력을 모니터링하여 SimCity 게임을 시작하는 AI 에이전트입니다 SimCity Start Game es un agente de IA que utiliza Cargo para iniciar el juego. Sigue nuestra guía para configurarlo correctamente SimCity Start Game est un agent IA qui utilise Cargo pour démarrer le jeu. Suivez notre guide pour le configurer correctement SimCity Start Game ist ein IA-Agent, der Cargo verwendet, um das Spiel zu starten. Folgen Sie unserer Anleitung, um es richtig zu konfigurieren O SimCity Start Game é uma habilidade que permite iniciar o jogo SimCity com configurações personalizadas. Siga nossa guia para aprender como iniciar o jogo. SimCity Start Game - это навык, который позволяет запустить игру SimCity с настраиваемыми параметрами. Следуйте нашей инструкции, чтобы узнать, как начать игру с помощью ИИ Агентов SimCity Start Game هو مهارة تسمح ببدء لعبة SimCity بإعدادات مخصصة. اتبع دليلنا لتعلم كيفية بدء اللعبة باستخدام أدوات الذكاء الاصطناعي how to use simcity-start-game simcity-start-game setup guide simcity-start-game alternative simcity-start-game vs manual startup what is simcity-start-game simcity-start-game install automated game initialization simcity game startup cargo run command pgrep command SimCity Start Game AIエージェント工具 cargo 命令 终端输出监控 自动启动游戏 block_until_ms 参数 游戏窗口创建监控 Utilizes pgrep to check for existing SimCity game instances Runs cargo with block_until_ms: 0 to background the game Stops running instances using bash scripts like stop_game.sh Monitors terminal output for game window creation Retries list components with short sleeps to connect to MCP Keeps the game running for at least 60 seconds before stopping simcity-start-game is a skill that automates the startup of SimCity games, utilizing commands like pgrep, cargo run, and bash scripts to manage game instances.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('tradewinds-center/rabbithole/components-guide', 'community', 'tradewinds-center', 'rabbithole', 'tradewinds-center/rabbithole', 'components-guide', 0, 0, 39, '2026-03-04T03:50:05Z', '2026-03-07T04:15:26.668Z', '7721be98908a4d17c1455e90f01c357c018e1e1bbbde2bdeb0c6810a8de8971b', '{"id":"tradewinds-center/rabbithole/components-guide","name":"components-guide","description":{"en":"The components-guide skill helps developers build maintainable, reusable backends by encapsulating features into self-contained mini-backends. It benefits developers looking to create scalable and organized backend architectures.","zh":"Convex组件是自包含的迷你后端，封装功能和数据。使用Convex组件构建可维护的后端","ja":"Convexコンポーネントは、機能とデータをカプセル化した自包含のミニバックエンドです。Convexコンポーネントを使用してメンテナンス可能なバックエンドを構築します","ko":"Convex 컴포넌트는 기능과 데이터를 캡슐화한 자체 포함된 미니 백엔드입니다. Convex 컴포넌트를 사용하여 유지 가능한 백엔드를 구축합니다","es":"Los componentes Convex son mini-backends autocontenidos que encapsulan su propia base de datos y funciones. Aprende a utilizarlos para crear backends mantenibles y reutilizables.","fr":"Les composants Convex sont des mini-backends autocontenidos qui encapsulent leur propre base de données et fonctions. Découvrez comment les utiliser pour créer des backends maintenables et réutilisables.","de":"Die Convex-Komponenten sind selbstenthaltene Mini-Backends, die ihre eigene Datenbank und Funktionen kapseln. Erfahren Sie, wie Sie sie verwenden können, um wiederverwendbare Backends zu erstellen.","pt":"Componentes Convex são mini-backends autônomos que encapsulam esquemas de banco de dados, funções e dados. Aprenda a usá-los para melhorar a manutenção e reutilização de backends.","ru":"Компоненты Convex являются自одостаточными мини-бэкендами, которые инкапсулируют схемы баз данных, функции и данные. Узнайте, как использовать их для улучшения поддержки и повторного использования бэкендов с помощью ИИ Агентов.","ar":"المكونات Convex هي خلفيات صغيرة مستقلة تحزم مخططات قواعد البيانات والوظائف والبيانات. تعلم كيفية استخدامها لتحسين الصيانة وإعادة استخدام الخلفيات"},"seo":{"title":{"en":"components-guide: Convex Components Setup Guide | AI Agen...","zh":"Convex组件指南：构建可维护的后端","ja":"Convexコンポーネントガイド：メンテナンス可能なバックエンドの構築","ko":"Convex 컴포넌트 가이드: 유지 가능한 백엔드 구축","es":"Guía de Componentes Convex: Crea Backends Reutilizables c...","fr":"Guide des Composants Convex: Créez des Backends Maintenab...","de":"Convex-Komponenten-Anleitung: Erstellen Sie wiederverwend...","pt":"Guia de Configuração de Componentes Convex: Práticas Reco...","ru":"Руководство по настройке компонентов Convex: Лучшие практ...","ar":"دليل إعداد مكونات Convex: إرشادات أفضل للمطورين"},"description":{"en":"Discover how to build maintainable backends with Convex Components. Learn to encapsulate features and create reusable mini-backends with clear API boundaries.","zh":"Convex组件是自包含的迷你后端，封装功能和数据。了解如何使用Convex组件构建可维护的后端","ja":"Convexコンポーネントは、機能とデータをカプセル化した自包含のミニバックエンドです。Convexコンポーネントを使用してメンテナンス可能なバックエンドを構築する方法について学びます","ko":"Convex 컴포넌트는 기능과 데이터를 캡슐화한 자체 포함된 미니 백엔드입니다. Convex 컴포넌트를 사용하여 유지 가능한 백엔드를 구축하는 방법에 대해 알아보세요","es":"Aprende a utilizar componentes para encapsular características y construir backends mantenibles y reutilizables con nuestra guía de componentes Convex y herr...","fr":"Découvrez comment utiliser des composants pour encapsuler des fonctionnalités et créer des backends maintenables et réutilisables avec notre guide des compos...","de":"Erfahren Sie, wie Sie Komponenten verwenden können, um Funktionen zu kapseln und wiederverwendbare Backends zu erstellen, mit unserer Convex-Komponenten-Anle...","pt":"Aprenda a usar componentes Convex para criar backends mantidos e reutilizáveis. Descubra como encapsular recursos e melhorar a escalabilidade.","ru":"Узнайте, как использовать компоненты Convex для создания поддерживаемых и повторно используемых бэкендов. Откройте для себя, как инкапсулировать функции и ул...","ar":"تعلم كيفية استخدام مكونات Convex لإنشاء خلفيات قابلة للصيانة وإعادة الاستخدام. اكتشف كيفية تعبئة الميزات وتحسين القدرة على النمو"},"definition":{"en":"components-guide is a skill that enables developers to create self-contained mini-backends, bundling database schema, functions, and data with clear API boundaries.","zh":"Convex组件是自包含的迷你后端，封装功能、数据库模式、函数和数据","ja":"Convexコンポーネントは、機能、データベーススキーマ、関数、データをカプセル化した自包含のミニバックエンド","ko":"Convex 컴포넌트는 기능, 데이터베이스 스키마, 함수 및 데이터를 캡슐화한 자체 포함된 미니 백엔드","es":"Un componente Convex es un mini-backend autocontenido que encapsula su propia base de datos, funciones y datos","fr":"Un composant Convex est un mini-backend autocontenid qui encapsule sa propre base de données, fonctions et données","de":"Ein Convex-Komponente ist ein selbstenthaltenes Mini-Backend, das seine eigene Datenbank, Funktionen und Daten kapselt","pt":"Componentes Convex são mini-backends autônomos que encapsulam recursos e melhoram a manutenção e reutilização de backends.","ru":"Компоненты Convex являются自одостаточными мини-бэкендами, которые инкапсулируют функции и улучшают поддержку и повторное использование бэкендов.","ar":"المكونات Convex هي خلفيات صغيرة مستقلة تحزم الميزات وتحسن الصيانة وإعادة استخدام الخلفيات"},"features":{"en":["Bundles own database schema for isolated data management","Includes own functions for queries, mutations, and actions","Provides clear API boundaries for microservices-like architecture","Enables creation of reusable and maintainable backend components","Supports isolated tables for data organization and security","Allows for npm package-like deployment without complexity"],"zh":["自包含的迷你后端","封装功能和数据","自己的数据库模式","自己的函数（查询、变异、操作）","清晰的API边界"],"ja":["自包含のミニバックエンド","機能とデータをカプセル化","独自のデータベーススキーマ","独自の関数（クエリ、ミューテーション、操作）","明確なAPIの境界"],"ko":["자체 포함된 미니 백엔드","기능과 데이터를 캡슐화","자체 데이터베이스 스키마","자체 함수（쿼리, 변이, 작업）","명확한 API 경계"],"es":["Encapsula su propia base de datos y esquema","Incluye sus propias funciones y queries","Permite la creación de backends mantenibles y reutilizables","Ofrece límites de API claros","Permite la isolación de datos en tablas","Es comparable a paquetes npm para backends"],"fr":["Encapsule sa propre base de données et schéma","Inclut ses propres fonctions et requêtes","Permet la création de backends maintenables et réutilisables","Offre des limites d''API claires","Permet l''isolation des données dans des tables","Est comparable à des paquets npm pour les backends"],"de":["Kapselt seine eigene Datenbank und Schema","Enthält seine eigenen Funktionen und Abfragen","Ermöglicht die Erstellung von wiederverwendbaren Backends","Bietet klare API-Grenzen","Ermöglicht die Isolation von Daten in Tabellen","Ist vergleichbar mit npm-Paketen für Backends"],"pt":["Encapsulamento de esquemas de banco de dados","Funções personalizadas (consultas, mutações, ações)","Dados isolados e tabelas","Limites de API claros","Melhoria da manutenção e reutilização de backends"],"ru":["Инкапсуляция схем баз данных","Пользовательские функции (запросы, мутации, действия)","Изолированные данные и таблицы","Ясные границы API","Улучшение поддержки и повторного использования бэкендов с помощью ИИ Агентов"],"ar":["تعبئة مخططات قواعد البيانات","وظائف مخصصة (استفسارات، طفرات، إجراءات)","بيانات معزولة وجداول","حدود واجهة برمجة التطبيقات واضحة","تحسين الصيانة وإعادة استخدام الخلفيات"]},"keywords":{"en":["how to use components-guide","what is components-guide","components-guide alternative","components-guide vs microservices","components-guide install","components-guide setup guide","convex components tutorial","backend architecture with components-guide"],"zh":["Convex组件","后端开发","可维护的后端","自包含的迷你后端","Convex","组件化","AIエージェント"," Convex组件指南"],"ja":["Convexコンポーネント","バックエンド開発","メンテナンス可能なバックエンド","自包含のミニバックエンド","Convex","コンポーネント化","AIエージェント","Convexコンポーネントガイド"],"ko":["Convex 컴포넌트","백엔드 개발","유지 가능한 백엔드","자체 포함된 미니 백엔드","Convex","컴포넌트화","AI 에이전트","Convex 컴포넌트 가이드"],"es":["componentes Convex","backends reutilizables","herramientas de inteligencia artificial","desarrollo de backends","bases de datos","funciones y queries","API claras","isolación de datos"],"fr":["composants Convex","backends réutilisables","outils d''intelligence artificielle","développement de backends","bases de données","fonctions et requêtes","API claires","isolation des données"],"de":["Convex-Komponenten","wiederverwendbare Backends","KI-Tools","Backend-Entwicklung","Datenbanken","Funktionen und Abfragen","klare API","Datenisolation"],"pt":["componentes Convex","guias de configuração","práticas recomendadas para desenvolvedores","backends mantidos","reutilização de backends","encapsulamento de recursos","esquemas de banco de dados","funções personalizadas"],"ru":["компоненты Convex","руководства по настройке","лучшие практики для разработчиков","поддерживаемые бэкенды","повторное использование бэкендов","инкапсуляция функций","схемы баз данных","пользовательские функции","ИИ Агенты"],"ar":["مكونات Convex","دلائل الإعداد","إرشادات أفضل للمطورين","خلفيات قابلة للصيانة","إعادة استخدام الخلفيات","تعبئة الميزات","مخططات قواعد البيانات","وظائف مخصصة","أدوات الذكاء الاصطناعي"]}},"owner":"tradewinds-center","repo":"rabbithole","repoPath":"tradewinds-center/rabbithole","stars":0,"forks":0,"updatedAt":"2026-03-04T03:50:05Z","topics":[],"category":"community","skillMd":{"name":"components-guide","description":"Guide to using Convex components for feature encapsulation. Learn about sibling components, creating your own, and when to use components vs monolithic code.","bodyPreview":"# Convex Components Guide\n\nUse components to encapsulate features and build maintainable, reusable backends.\n\n## What Are Convex Components?\n\n**Components are self-contained mini-backends** that bundle:\n- Their own database schema\n- Their own functions (queries, mutations, actions)\n- Their own data (isolated tables)\n- Clear API boundaries\n\n**Think of them as:** npm packages for your backend, or microservices without the deployment complexity.\n\n## Why Use Components?\n\n### Traditional Approach (Mo","body":"# Convex Components Guide\n\nUse components to encapsulate features and build maintainable, reusable backends.\n\n## What Are Convex Components?\n\n**Components are self-contained mini-backends** that bundle:\n- Their own database schema\n- Their own functions (queries, mutations, actions)\n- Their own data (isolated tables)\n- Clear API boundaries\n\n**Think of them as:** npm packages for your backend, or microservices without the deployment complexity.\n\n## Why Use Components?\n\n### Traditional Approach (Monolithic)\n```\nconvex/\n├── users.ts           (500 lines)\n├── files.ts           (600 lines - upload, storage, permissions, rate limiting)\n├── payments.ts        (400 lines - Stripe, webhooks, billing)\n├── notifications.ts   (300 lines)\n└── analytics.ts       (200 lines)\n\nTotal: One big codebase, everything mixed together\n```\n\n### Component Approach (Encapsulated)\n```\nconvex/\n├── components/\n│   ├── storage/      (File uploads - reusable)\n│   ├── billing/      (Payments - reusable)\n│   ├── notifications/ (Alerts - reusable)\n│   └── analytics/    (Tracking - reusable)\n├── convex.config.ts  (Wire components together)\n└── domain/           (Your actual business logic)\n    ├── users.ts      (50 lines - uses components)\n    └── projects.ts   (75 lines - uses components)\n\nTotal: Clean, focused, reusable\n```\n\n## Quick Start\n\n### 1. Install a Component\n\n```bash\n# Official components from npm\nnpm install @convex-dev/ratelimiter\n```\n\n### 2. Configure in convex.config.ts\n\n```typescript\nimport { defineApp } from \"convex/server\";\nimport ratelimiter from \"@convex-dev/ratelimiter/convex.config\";\n\nexport default defineApp({\n  components: {\n    ratelimiter,\n  },\n});\n```\n\n### 3. Use in Your Code\n\n```typescript\nimport { components } from \"./_generated/api\";\n\nexport const createPost = mutation({\n  handler: async (ctx, args) => {\n    // Use the component\n    await components.ratelimiter.check(ctx, {\n      key: `user:${ctx.user._id}`,\n      limit: 10,\n      period: 60000, // 10 requests per minute\n    });\n\n    return await ctx.db.insert(\"posts\", args);\n  },\n});\n```\n\n## Sibling Components Pattern\n\nMultiple components working together at the same level:\n\n```typescript\n// convex.config.ts\nexport default defineApp({\n  components: {\n    // Sibling components - each handles one concern\n    auth: authComponent,\n    storage: storageComponent,\n    payments: paymentsComponent,\n    emails: emailComponent,\n    analytics: analyticsComponent,\n  },\n});\n```\n\n### Example: Complete Feature Using Siblings\n\n```typescript\n// convex/subscriptions.ts\nimport { components } from \"./_generated/api\";\n\nexport const subscribe = mutation({\n  args: { plan: v.string() },\n  handler: async (ctx, args) => {\n    // 1. Verify authentication (auth component)\n    const user = await components.auth.getCurrentUser(ctx);\n\n    // 2. Create payment (payments component)\n    const subscription = await components.payments.createSubscription(ctx, {\n      userId: user._id,\n      plan: args.plan,\n      amount: getPlanAmount(args.plan),\n    });\n\n    // 3. Track conversion (analytics component)\n    await components.analytics.track(ctx, {\n      event: \"subscription_created\",\n      userId: user._id,\n      plan: args.plan,\n    });\n\n    // 4. Send confirmation (emails component)\n    await components.emails.send(ctx, {\n      to: user.email,\n      template: \"subscription_welcome\",\n      data: { plan: args.plan },\n    });\n\n    // 5. Store subscription in main app\n    await ctx.db.insert(\"subscriptions\", {\n      userId: user._id,\n      paymentId: subscription.id,\n      plan: args.plan,\n      status: \"active\",\n    });\n\n    return subscription;\n  },\n});\n```\n\n**What this achieves:**\n- ✅ Each component is single-purpose\n- ✅ Components are reusable across features\n- ✅ Easy to swap implementations (change email provider)\n- ✅ Can update components independently\n- ✅ Clear separation of concerns\n\n## Official Components\n\nBrowse [Component Directory](https://www.convex.dev/components):\n\n### Authentication\n- **@convex-dev/better-auth** - Better Auth integration\n\n### Storage\n- **@convex-dev/r2** - Cloudflare R2 file storage\n- **@convex-dev/storage** - File upload/download\n\n### Payments\n- **@convex-dev/polar** - Polar billing & subscriptions\n\n### AI\n- **@convex-dev/agent** - AI agent workflows\n- **@convex-dev/embeddings** - Vector storage & search\n\n### Backend Utilities\n- **@convex-dev/ratelimiter** - Rate limiting\n- **@convex-dev/aggregate** - Data aggregations\n- **@convex-dev/action-cache** - Cache action results\n- **@convex-dev/sharded-counter** - Distributed counters\n- **@convex-dev/migrations** - Schema migrations\n- **@convex-dev/workflow** - Workflow orchestration\n\n## Creating Your Own Component\n\n### When to Create a Component\n\n**Good reasons:**\n- Feature is self-contained\n- You''ll reuse it across projects\n- Want to share with team/community\n- Complex feature with its own data model\n- Third-party integration wrapper\n\n**Not good reasons:**\n- One-off business logic\n- Tightly coupled to main app\n- Simple utility functions\n\n### Structure\n\n```bash\nmkdir -p convex/components/notifications\n```\n\n```typescript\n// convex/components/notifications/convex.config.ts\nimport { defineComponent } from \"convex/server\";\n\nexport default defineComponent(\"notifications\");\n```\n\n```typescript\n// convex/components/notifications/schema.ts\nimport { defineSchema, defineTable } from \"convex/server\";\nimport { v } from \"convex/values\";\n\nexport default defineSchema({\n  notifications: defineTable({\n    userId: v.id(\"users\"),\n    message: v.string(),\n    read: v.boolean(),\n    createdAt: v.number(),\n  })\n    .index(\"by_user\", [\"userId\"])\n    .index(\"by_user_and_read\", [\"userId\", \"read\"]),\n});\n```\n\n```typescript\n// convex/components/notifications/send.ts\nimport { mutation } from \"./_generated/server\";\nimport { v } from \"convex/values\";\n\nexport const send = mutation({\n  args: {\n    userId: v.id(\"users\"),\n    message: v.string(),\n  },\n  handler: async (ctx, args) => {\n    await ctx.db.insert(\"notifications\", {\n      userId: args.userId,\n      message: args.message,\n      read: false,\n      createdAt: Date.now(),\n    });\n  },\n});\n\nexport const markRead = mutation({\n  args: { notificationId: v.id(\"notifications\") },\n  handler: async (ctx, args) => {\n    await ctx.db.patch(args.notificationId, { read: true });\n  },\n});\n```\n\n```typescript\n// convex/components/notifications/read.ts\nimport { query } from \"./_generated/server\";\nimport { v } from \"convex/values\";\n\nexport const list = query({\n  args: { userId: v.id(\"users\") },\n  handler: async (ctx, args) => {\n    return await ctx.db\n      .query(\"notifications\")\n      .withIndex(\"by_user\", q => q.eq(\"userId\", args.userId))\n      .order(\"desc\")\n      .collect();\n  },\n});\n\nexport const unreadCount = query({\n  args: { userId: v.id(\"users\") },\n  handler: async (ctx, args) => {\n    const unread = await ctx.db\n      .query(\"notifications\")\n      .withIndex(\"by_user_and_read\", q =>\n        q.eq(\"userId\", args.userId).eq(\"read\", false)\n      )\n      .collect();\n\n    return unread.length;\n  },\n});\n```\n\n### Use Your Component\n\n```typescript\n// convex.config.ts\nimport { defineApp } from \"convex/server\";\nimport notifications from \"./components/notifications/convex.config\";\n\nexport default defineApp({\n  components: {\n    notifications, // Your local component\n  },\n});\n```\n\n```typescript\n// convex/tasks.ts - main app code\nimport { components } from \"./_generated/api\";\n\nexport const completeTask = mutation({\n  args: { taskId: v.id(\"tasks\") },\n  handler: async (ctx, args) => {\n    const task = await ctx.db.get(args.taskId);\n\n    await ctx.db.patch(args.taskId, { completed: true });\n\n    // Use your component\n    await components.notifications.send(ctx, {\n      userId: task.userId,\n      message: `Task \"${task.title}\" completed!`,\n    });\n  },\n});\n```\n\n## Component Communication Patterns\n\n### ✅ Parent → Component (Good)\n\n```typescript\n// Main app calls component\nawait components.storage.upload(ctx, file);\nawait components.analytics.track(ctx, event);\n```\n\n### ✅ Parent → Multiple Siblings (Good)\n\n```typescript\n// Main app orchestrates multiple components\nawait components.auth.verify(ctx);\nconst file = await components.storage.upload(ctx, data);\nawait components.notifications.send(ctx, message);\n```\n\n### ✅ Component Receives Parent Data (Good)\n\n```typescript\n// Pass IDs from parent''s tables to component\nawait components.audit.log(ctx, {\n  userId: user._id,        // From parent''s users table\n  action: \"delete\",\n  resourceId: task._id,    // From parent''s tasks table\n});\n\n// Component stores these as strings/IDs\n// but doesn''t access parent tables directly\n```\n\n### ❌ Component → Parent Tables (Bad)\n\n```typescript\n// Inside component code - DON''T DO THIS\nconst user = await ctx.db.get(userId); // Error! Can''t access parent tables\n```\n\n### ❌ Sibling → Sibling (Bad)\n\nComponents can''t call each other directly. If you need this, they should be in the main app or refactor the design.\n\n## Real-World Examples\n\n### Multi-Tenant SaaS\n\n```typescript\n// convex.config.ts\nexport default defineApp({\n  components: {\n    auth: \"@convex-dev/better-auth\",\n    organizations: \"./components/organizations\",\n    billing: \"./components/billing\",\n    storage: \"@convex-dev/r2\",\n    analytics: \"./components/analytics\",\n    emails: \"./components/emails\",\n  },\n});\n```\n\nEach component:\n- `auth` - User authentication & sessions\n- `organizations` - Tenant isolation & permissions\n- `billing` - Stripe integration & subscriptions\n- `storage` - File uploads to R2\n- `analytics` - Event tracking & metrics\n- `emails` - Email sending via SendGrid\n\n### E-Commerce Platform\n\n```typescript\nexport default defineApp({\n  components: {\n    cart: \"./components/cart\",\n    inventory: \"./components/inventory\",\n    orders: \"./components/orders\",\n    payments: \"@convex-dev/polar\",\n    shipping: \"./components/shipping\",\n    recommendations: \"./components/recommendations\",\n  },\n});\n```\n\n### AI Application\n\n```typescript\nexport default defineApp({\n  components: {\n    agent: \"@convex-dev/agent\",\n    embeddings: \"./components/embeddings\",\n    documents: \"./components/documents\",\n    chat: \"./components/chat\",\n    workflow: \"@convex-dev/workflow\",\n  },\n});\n```\n\n## Migration from Monolithic\n\n**Step 1: Identify Features**\n```\nCurrent monolith:\n- File uploads (mixed with main app)\n- Rate limiting (scattered everywhere)\n- Analytics (embedded in functions)\n```\n\n**Step 2: Extract One Feature**\n```bash\n# Create component\nmkdir -p convex/components/storage\n\n# Move storage code to component\n# Update imports in main app\n```\n\n**Step 3: Test Independently**\n```bash\n# Component has its own tests\n# No coupling to main app\n```\n\n**Step 4: Repeat**\nExtract other features incrementally.\n\n## Best Practices\n\n### 1. Single Responsibility\nEach component does ONE thing well:\n- ✅ storage component handles files\n- ✅ auth component handles authentication\n- ❌ Don''t create \"utils\" component with everything\n\n### 2. Clear API Surface\n```typescript\n// Export only what''s needed\nexport { upload, download, delete } from \"./storage\";\n\n// Keep internals private\n// (Don''t export helper functions)\n```\n\n### 3. Minimal Coupling\n```typescript\n// ✅ Good: Pass data as arguments\nawait components.audit.log(ctx, {\n  userId: user._id,\n  action: \"delete\"\n});\n\n// ❌ Bad: Component accesses parent tables\n// (Not even possible, but shows the principle)\n```\n\n### 4. Version Your Components\n```json\n{\n  \"name\": \"@yourteam/notifications-component\",\n  \"version\": \"1.0.0\"\n}\n```\n\n### 5. Document Your Components\nInclude README with:\n- What the component does\n- How to install\n- How to use\n- API reference\n- Examples\n\n## Troubleshooting\n\n### Component not found\n```bash\n# Make sure component is in convex.config.ts\n# Run: npx convex dev\n```\n\n### Can''t access parent tables\n```\nThis is by design! Components are sandboxed.\nPass data as arguments instead.\n```\n\n### Component conflicts\n```\nEach component has isolated tables.\nComponents can''t see each other''s data.\n```\n\n## Learn More\n\n- [Components Documentation](https://docs.convex.dev/components)\n- [Component Directory](https://www.convex.dev/components)\n- [Using Components](https://docs.convex.dev/components/using)\n- [Authoring Components](https://docs.convex.dev/components/authoring)\n- [Stack: Backend Components](https://stack.convex.dev/backend-components)\n\n## Checklist\n\n- [ ] Browse [Component Directory](https://www.convex.dev/components) for existing solutions\n- [ ] Install components via npm: `npm install @convex-dev/component-name`\n- [ ] Configure in `convex.config.ts`\n- [ ] Use sibling components for feature encapsulation\n- [ ] Create your own components for reusable features\n- [ ] Keep components focused (single responsibility)\n- [ ] Test components in isolation\n- [ ] Document component APIs\n- [ ] Version your components properly\n\n**Remember:** Components are about encapsulation and reusability. When in doubt, prefer components over monolithic code!\n"},"lastSynced":"2026-03-07T04:15:26.668Z","agentAnalysis":{"suitability":{"en":"Perfect for Backend Agents needing modular and scalable architecture design.","zh":"非常适合需要模块化和可扩展架构设计的后端代理。","ja":"バックエンドエージェントがモジュラーでスケーラブルなアーキテクチャデザインを必要とする場合に最適です。","ko":"모듈화되고 확장 가능한 아키텍처 디자인을 필요로 하는 백엔드 에이전트에 적합합니다.","es":"Perfecto para agentes de Backend que necesitan un diseño de arquitectura modular y escalable.","fr":"Parfait pour les agents Backend nécessitant une conception d''architecture modulaire et évolutives.","de":"Perfekt für Backend-Agents, die ein modulares und skalierbares Architekturdesign benötigen.","pt":"Perfeito para Agents de Backend que precisam de um design de arquitetura modular e escalável.","ru":"Идеально подходит для агентов Backend, которым необходим модульный и масштабируемый архитектурный дизайн.","ar":"مثالي لعميل الخادم الخلفي الذي يحتاج إلى تصميم هندسة معمارية قابل للتوسيع والتعديل."},"recommendation":{"en":"Empowers agents to encapsulate features into self-contained mini-backends using Convex Components, providing clear API boundaries, isolated data, and reusable functions, thus enabling the creation of maintainable and organized backend architectures.","zh":"赋予代理将功能封装到使用Convex Components的自包含-mini后端中，提供明确的API边界、隔离的数据和可重用的函数，从而实现可维护和有序的后端架构的创建。","ja":"Convex Componentsを使用して機能を自己完結したミニバックエンドにカプセル化することで、エージェントに明確なAPIの境界、分離されたデータ、および再利用可能な関数を提供し、維持可能で整理されたバックエンドアーキテクチャの作成を可能にします。","ko":"Convex Components를 사용하여 기능을 자체적으로 완결된 미니 백엔드로 캡슐화하여 에이전트에明确한 API 경계, 분리된 데이터 및 재사용 가능한 함수를 제공하여 유지 가능하고 조직적인 백엔드 아키텍처의 생성을 가능하게 합니다.","es":"Habilita a los agentes a encapsular características en mini-Backends autocontenidos utilizando Convex Components, proporcionando límites de API claros, datos aislados y funciones reutilizables, lo que permite la creación de arquitecturas de Backend mantenibles y organizadas.","fr":"Permet aux agents d''encapsuler des fonctionnalités dans des mini-Backends autocontenus en utilisant Convex Components, fournissant des limites d''API claires, des données isolées et des fonctions réutilisables, permettant ainsi la création d''architectures de Backend maintenables et organisées.","de":"Ermöglicht es den Agents, Funktionen in selbstenthalte Mini-Backends mit Convex Components zu kapseln, wodurch klare API-Grenzen, isolierte Daten und wiederverwendbare Funktionen bereitgestellt werden, was die Erstellung von wartbaren und organisierten Backend-Architekturen ermöglicht.","pt":"Habilita os agentes a encapsular recursos em mini-servidores autônomos usando Componentes Convex, fornecendo limites de API claros, dados isolados e funções reutilizáveis, permitindo assim a criação de arquiteturas de backend mantidas e organizadas.","ru":"Наделяет агентов возможностью инкапсулировать функции в самодостаточные мини-бэкенды с помощью компонентов Convex, обеспечивая четкие границы API, изолированные данные и многократно используемые функции, тем самым ermögляя создание поддерживаемых и организованных бэкенд-архитектур.","ar":"تمكّن الوكلاء من تعبئة الميزات في خلفيات صغيرة منفصلة باستخدام مكونات Convex، مما يوفر حدود واضحة لبروتوكول الويب، بيانات معزولة، ودالات قابلة لإعادة الاستخدام، وبالتالي تمكن من إنشاء هياكل خلفية منسقة ومرتبة."},"useCases":{"en":["Building scalable and modular backend systems","Encapsulating features into reusable mini-backends","Defining clear API boundaries for microservices"],"zh":["构建可扩展和模块化的后端系统","将功能封装到可重用的mini后端中","为微服务定义明确的API边界"],"ja":["スケーラブルでモジュラーなバックエンドシステムの構築","機能を再利用可能なミニバックエンドにカプセル化する","マイクロサービスに明確なAPIの境界を定義する"],"ko":["확장 가능하고 모듈화된 백엔드 시스템 구축","기능을 재사용 가능한 미니 백엔드로 캡슐화","마이크로서비스에明确한 API 경계 정의"],"es":["Construcción de sistemas de Backend escalables y modulares","Encapsulación de características en mini-Backends reutilizables","Definición de límites de API claros para microservicios"],"fr":["Conception de systèmes de Backend évolutifs et modulaires","Encapsulation de fonctionnalités dans des mini-Backends réutilisables","Définition de limites d''API claires pour les microservices"],"de":["Erstellung von skalierbaren und modularen Backend-Systemen","Kapselung von Funktionen in wiederverwendbaren Mini-Backends","Definierung von klaren API-Grenzen für Microservices"],"pt":["Construção de sistemas de backend escaláveis e modulares","Encapsulamento de recursos em mini-servidores reutilizáveis","Definição de limites de API claros para microsserviços"],"ru":["Создание масштабируемых и модульных систем бэкенда","Инкапсуляция функций в многократно используемые мини-бэкенды","Определение четких границ API для микросервисов"],"ar":["بناء أنظمة الخادم الخلفي القابلة للتوسيع والتعديل","تعبئة الميزات في خلفيات صغيرة قابلة لإعادة الاستخدام","تحديد حدود واضحة لبروتوكول الويب لميكروسيرفس"]},"limitations":{"en":["Requires understanding of Convex Components and backend architecture","Limited to building backend systems with self-contained mini-backends"],"zh":["需要了解Convex Components和后端架构","仅限于使用自包含mini后端构建后端系统"],"ja":["Convex Componentsとバックエンドアーキテクチャの理解が必要","自己完結したミニバックエンドを使用してバックエンドシステムを構築することのみに限定"],"ko":["Convex Components와 백엔드 아키텍처에 대한 이해가 필요","자체적으로 완결된 미니 백엔드를 사용하여 백엔드 시스템을 구축하는 것만으로 제한"],"es":["Requiere comprensión de Convex Components y arquitectura de Backend","Limitado a la construcción de sistemas de Backend con mini-Backends autocontenidos"],"fr":["Nécessite une compréhension de Convex Components et d''architecture de Backend","Limité à la construction de systèmes de Backend avec des mini-Backends autocontenus"],"de":["Erfordert Verständnis von Convex Components und Backend-Architektur","Begrenzt auf den Bau von Backend-Systemen mit selbstenthalten Mini-Backends"],"pt":["Exige conhecimento de Componentes Convex e arquitetura de backend","Limitado à construção de sistemas de backend com mini-servidores autônomos"],"ru":["Требует понимания компонентов Convex и архитектуры бэкенда","Ограничен созданием систем бэкенда с самодостаточными мини-бэкендами"],"ar":["يتطلب فهم مكونات Convex وهندسة الخادم الخلفي","محدود ببناء أنظمة الخادم الخلفي بخلفيات صغيرة منفصلة"]},"version":4},"contentHash":"7721be98908a4d17c1455e90f01c357c018e1e1bbbde2bdeb0c6810a8de8971b","qualityScore":39}');
