INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('tradewinds-center/rabbithole/components-guide', 'components-guide', 'tradewinds-center', 'rabbithole', 'community', 'components-guide tradewinds-center rabbithole community The components-guide skill helps developers build maintainable, reusable backends by encapsulating features into self-contained mini-backends. It benefits developers looking to create scalable and organized backend architectures. Convex组件是自包含的迷你后端，封装功能和数据。使用Convex组件构建可维护的后端 Convexコンポーネントは、機能とデータをカプセル化した自包含のミニバックエンドです。Convexコンポーネントを使用してメンテナンス可能なバックエンドを構築します Convex 컴포넌트는 기능과 데이터를 캡슐화한 자체 포함된 미니 백엔드입니다. Convex 컴포넌트를 사용하여 유지 가능한 백엔드를 구축합니다 Los componentes Convex son mini-backends autocontenidos que encapsulan su propia base de datos y funciones. Aprende a utilizarlos para crear backends mantenibles y reutilizables. Les composants Convex sont des mini-backends autocontenidos qui encapsulent leur propre base de données et fonctions. Découvrez comment les utiliser pour créer des backends maintenables et réutilisables. Die Convex-Komponenten sind selbstenthaltene Mini-Backends, die ihre eigene Datenbank und Funktionen kapseln. Erfahren Sie, wie Sie sie verwenden können, um wiederverwendbare Backends zu erstellen. Componentes Convex são mini-backends autônomos que encapsulam esquemas de banco de dados, funções e dados. Aprenda a usá-los para melhorar a manutenção e reutilização de backends. Компоненты Convex являются自одостаточными мини-бэкендами, которые инкапсулируют схемы баз данных, функции и данные. Узнайте, как использовать их для улучшения поддержки и повторного использования бэкендов с помощью ИИ Агентов. المكونات Convex هي خلفيات صغيرة مستقلة تحزم مخططات قواعد البيانات والوظائف والبيانات. تعلم كيفية استخدامها لتحسين الصيانة وإعادة استخدام الخلفيات how to use components-guide what is components-guide components-guide alternative components-guide vs microservices components-guide install components-guide setup guide convex components tutorial backend architecture with components-guide Convex组件 后端开发 可维护的后端 自包含的迷你后端 Convex 组件化 AIエージェント Convex组件指南 Bundles own database schema for isolated data management Includes own functions for queries, mutations, and actions Provides clear API boundaries for microservices-like architecture Enables creation of reusable and maintainable backend components Supports isolated tables for data organization and security Allows for npm package-like deployment without complexity components-guide is a skill that enables developers to create self-contained mini-backends, bundling database schema, functions, and data with clear API boundaries.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('colmarius/colmarius.github.io/tmux', 'community', 'colmarius', 'colmarius.github.io', 'colmarius/colmarius.github.io', 'tmux', 0, 0, 39, '2026-03-06T12:59:22.256Z', '2026-03-06T14:50:42.830Z', '0e850390b584e5bacc81791d90cc132c0cc75a5b7b2f54c12651079591c88957', '{"id":"colmarius/colmarius.github.io/tmux","name":"tmux","description":{"en":"The tmux skill enables developers to manage background processes using tmux windows, allowing for efficient task management. It benefits developers who need to run multiple commands simultaneously.","zh":"tmux是一个用于管理背景进程的工具，允许您创建新窗口并运行命令","ja":"tmuxはバックグラウンドプロセスを管理するためのツールです","ko":"tmux는 백그라운드 프로세스를 관리하기 위한 도구입니다","es":"tmux es una herramienta para gestionar procesos en segundo plano. Permite crear ventanas y ejecutar comandos sin bloquear la terminal.","fr":"tmux est un outil pour gérer les processus en arrière-plan. Il permet de créer des fenêtres et d''exécuter des commandes sans bloquer le terminal.","de":"tmux ist ein Tool zur Verwaltung von Hintergrundprozessen. Es ermöglicht die Erstellung von Fenstern und die Ausführung von Befehlen ohne Blockierung der Terminal.","pt":"O Tmux é uma ferramenta de gerenciamento de processos em segundo plano que permite executar comandos sem bloquear o terminal.","ru":"Tmux - это инструмент для управления фоновыми процессами, который позволяет выполнять команды без блокировки терминала с помощью ИИ Агентов.","ar":"Tmux هو أداة لإدارة العمليات في الخلفية التي تسمح بتشغيل أوامر بدون حجز الطرفية باستخدام أدوات الذكاء الاصطناعي."},"seo":{"title":{"en":"tmux: Mastering Background Processes Setup Guide | AI Age...","zh":"tmux setBackground进程管理指南","ja":"tmuxバックグラウンドプロセス管理セットアップガイド","ko":"tmux 백그라운드 프로세스 관리 설정 가이드","es":"Guía de configuración de tmux para gestión de procesos en...","fr":"Guide de configuration de tmux pour la gestion de process...","de":"tmux-Konfigurationsleitfaden für die Verwaltung von Hinte...","pt":"Guia de Configuração do Tmux: Gerenciamento de Processos ...","ru":"Настройка Tmux: Управление фоновыми процессами с помощью ...","ar":"دليل إعداد Tmux: إدارة العمليات في الخلفية باستخدام أدوات..."},"description":{"en":"Discover how to manage background tasks with tmux. Learn to spawn new windows, run commands, and optimize your workflow. Get started with tmux today!","zh":"了解如何使用tmux管理背景进程，包括验证环境、spawn新窗口和运行命令","ja":"tmuxを使用してバックグラウンドプロセスを管理する方法について説明します","ko":"tmux를 사용하여 백그라운드 프로세스를 관리하는 방법을 알아보세요","es":"Aprende a utilizar tmux para gestionar procesos en segundo plano sin bloquear la terminal. Descubre cómo verificar el entorno y estado de tmux.","fr":"Découvrez comment utiliser tmux pour gérer les processus en arrière-plan sans bloquer le terminal. Apprenez à vérifier l''environnement et l''état de tmux.","de":"Erfahren Sie, wie Sie tmux verwenden, um Hintergrundprozesse zu verwalten, ohne die Terminal zu blockieren. Entdecken Sie, wie Sie die Umgebung und den Statu...","pt":"Aprenda a gerenciar processos em segundo plano com o Tmux, uma ferramenta poderosa para desenvolvedores. Confira nossos exemplos e dicas de configuração.","ru":"Узнайте, как управлять фоновыми процессами с помощью Tmux, мощного инструмента для разработчиков. Просмотрите наши примеры и советы по настройке с помощью ИИ...","ar":"تعلم كيفية إدارة العمليات في الخلفية باستخدام Tmux، أداة قوية للمطورين. استعرض أمثلتنا ونصائحنا حول إعداد أدوات الذكاء الاصطناعي."},"definition":{"en":"tmux is a terminal multiplexer that enables users to manage multiple windows and sessions, allowing for efficient background process management.","zh":"tmux是一种终端复用器，允许您管理背景进程","ja":"tmuxはターミナルのマルチプレクサです","ko":"tmux는 터미널의 멀티플렉서입니다","es":"tmux es una herramienta de línea de comandos para gestionar ventanas y procesos en segundo plano","fr":"tmux est un outil de ligne de commande pour gérer les fenêtres et les processus en arrière-plan","de":"tmux ist ein Kommandozeilen-Tool zur Verwaltung von Fenstern und Hintergrundprozessen","pt":"Tmux é um software de gerenciamento de janelas que permite executar processos em segundo plano.","ru":"Tmux - это программное обеспечение для управления окнами, которое позволяет выполнять процессы в фоновом режиме с помощью ИИ Агентов.","ar":"Tmux هو برنامج لإدارة النوافذ الذي يسمح بتشغيل العمليات في الخلفية باستخدام أدوات الذكاء الاصطناعي."},"features":{"en":["Manage background processes using tmux windows","Verify environment and check status with `tmux list-windows` command","Spawn new background processes with `tmux new-window` command","Run commands in detached mode using `-d` flag","Send keys to specific windows using `tmux send-keys` command"],"zh":["创建新窗口并运行命令","验证环境和检查状态","使用tmux list-windows列出现有窗口","使用tmux new-window创建新窗口","使用tmux send-keys发送命令到窗口"],"ja":["新しいウィンドウを作成してコマンドを実行する","環境を確認し、状態をチェックする","tmux list-windowsを使用して既存のウィンドウを一覧表示する","tmux new-windowを使用して新しいウィンドウを作成する","tmux send-keysを使用してウィンドウにコマンドを送信する"],"ko":["새로운 창을 생성하고 명령을 실행합니다","환경을 확인하고 상태를 체크합니다","tmux list-windows를 사용하여 기존 창을 나열합니다","tmux new-window를 사용하여 새로운 창을 생성합니다","tmux send-keys를 사용하여 창에 명령을 보냅니다"],"es":["Crear ventanas de tmux para ejecutar comandos en segundo plano","Verificar el entorno y estado de tmux con comandos como ''tmux list-windows''","Ejecutar comandos en ventanas de tmux con ''tmux send-keys''","Crear ventanas de tmux con nombres personalizados para fácil referencia","Ejecutar procesos en segundo plano sin bloquear la terminal"],"fr":["Créer des fenêtres tmux pour exécuter des commandes en arrière-plan","Vérifier l''environnement et l''état de tmux avec des commandes comme ''tmux list-windows''","Exécuter des commandes dans des fenêtres tmux avec ''tmux send-keys''","Créer des fenêtres tmux avec des noms personnalisés pour une référence facile","Exécuter des processus en arrière-plan sans bloquer le terminal"],"de":["Erstellen von tmux-Fenstern zur Ausführung von Befehlen im Hintergrund","Überprüfen der Umgebung und des Status von tmux mit Befehlen wie ''tmux list-windows''","Ausführen von Befehlen in tmux-Fenstern mit ''tmux send-keys''","Erstellen von tmux-Fenstern mit benutzerdefinierten Namen für einfache Referenz","Ausführen von Prozessen im Hintergrund ohne Blockierung der Terminal"],"pt":["Crie janelas em segundo plano com o comando ''tmux new-window''","Execute comandos em janelas em segundo plano com ''tmux send-keys''","Liste janelas existentes com ''tmux list-windows''","Nomeie janelas para fácil referência com ''-n''","Mantenha janelas em segundo plano com ''-d''"],"ru":["Создайте окна в фоновом режиме с помощью команды ''tmux new-window''","Выполните команды в окнах фоновом режиме с ''tmux send-keys''","Перечислите существующие окна с ''tmux list-windows''","Назовите окна для легкого-reference с ''-n''","Оставьте окна в фоновом режиме с ''-d'' с помощью ИИ Агентов"],"ar":["أنشئ نوافذ في الخلفية باستخدام الأمر ''tmux new-window''","تشغيل أوامر في نوافذ الخلفية باستخدام ''tmux send-keys''","استعراض النوافذ الحالية مع ''tmux list-windows''","تسمية النوافذ لسهولة الإشارة إليها مع ''-n''","إبقاء النوافذ في الخلفية مع ''-d'' باستخدام أدوات الذكاء الاصطناعي"]},"keywords":{"en":["how to use tmux","tmux setup guide","tmux alternative","tmux vs screen","tmux install","what is tmux","tmux tutorial","tmux commands","tmux windows management"],"zh":["tmux","背景进程管理","终端复用器","tmux list-windows","tmux new-window","tmux send-keys","Linux命令行工具"],"ja":["tmux","バックグラウンドプロセス管理","ターミナルのマルチプレクサ","tmux list-windows","tmux new-window","tmux send-keys","Linuxコマンドラインツール"],"ko":["tmux","백그라운드 프로세스 관리","터미널의 멀티플렉서","tmux list-windows","tmux new-window","tmux send-keys","Linux 명령어 라인 도구"],"es":["tmux","gestión de procesos en segundo plano","terminal","ventanas de tmux","comandos de tmux","Herramientas de línea de comandos","Desarrollo de software","Automatización de procesos"],"fr":["tmux","gestion de processus en arrière-plan","terminal","fenêtres tmux","commandes tmux","Outils de ligne de commande","Développement de logiciels","Automatisation de processus"],"de":["tmux","Verwaltung von Hintergrundprozessen","Terminal","tmux-Fenster","tmux-Befehle","Kommandozeilentools","Softwareentwicklung","Prozessautomatisierung"],"pt":["tmux","gerenciamento de processos","janelas em segundo plano","comandos tmux","configuração tmux","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["tmux","управление процессами","окна в фоновом режиме","команды tmux","настройка tmux","разработка программного обеспечения","инструменты для разработчиков","ИИ Агенты"],"ar":["tmux","إدارة العمليات","نوافذ في الخلفية","أوامر tmux","إعداد tmux","تطوير البرمجيات","أدوات التطوير","أدوات الذكاء الاصطناعي"]}},"owner":"colmarius","repo":"colmarius.github.io","repoPath":"colmarius/colmarius.github.io","stars":0,"forks":0,"updatedAt":"2026-03-06T12:59:22.256Z","topics":[],"category":"community","skillMd":{"name":"tmux","description":"Instructions for using tmux to spawn multiple processes, inspect them, and capture their output. Use when running servers, long-running tasks, or background processes.","bodyPreview":"# tmux\n\nManage background processes using tmux windows without blocking the terminal.\n\n## 1. Verify Environment & Check Status\n\nConfirm tmux is running and list existing windows:\n\n```bash\ntmux list-windows\n```\n\n## 2. Spawn a Background Process\n\nCreate a new tmux window and run a command:\n\n```bash\ntmux new-window -n \"my-server\" -d\ntmux send-keys -t \"my-server\" \"npm run dev\" C-m\n```\n\n- `-n \"my-server\"` names the window for easy reference\n- `-d` keeps it detached (runs in background)\n- `C-m` sends","body":"# tmux\n\nManage background processes using tmux windows without blocking the terminal.\n\n## 1. Verify Environment & Check Status\n\nConfirm tmux is running and list existing windows:\n\n```bash\ntmux list-windows\n```\n\n## 2. Spawn a Background Process\n\nCreate a new tmux window and run a command:\n\n```bash\ntmux new-window -n \"my-server\" -d\ntmux send-keys -t \"my-server\" \"npm run dev\" C-m\n```\n\n- `-n \"my-server\"` names the window for easy reference\n- `-d` keeps it detached (runs in background)\n- `C-m` sends Enter to execute the command\n\n## 3. Inspect Output (Read Logs)\n\n### Visible screen only\n\n```bash\ntmux capture-pane -p -t \"my-server\"\n```\n\n### Full scrollback history\n\n```bash\ntmux capture-pane -p -t \"my-server\" -S -1000\n```\n\n- `-S -1000` captures the last 1000 lines of scrollback\n\n## 4. Interact with the Process\n\n### Send Ctrl+C (interrupt)\n\n```bash\ntmux send-keys -t \"my-server\" C-c\n```\n\n### Kill the window\n\n```bash\ntmux kill-window -t \"my-server\"\n```\n\n## 5. Advanced: Chaining Commands\n\nRun multiple commands in sequence:\n\n```bash\ntmux new-window -n \"build\" -d && \\\ntmux send-keys -t \"build\" \"npm run build && npm run test\" C-m\n```\n\n## Quick Reference\n\n| Action | Command |\n| ------ | ------- |\n| Create window | `tmux new-window -n \"ID\" -d` |\n| Run command | `tmux send-keys -t \"ID\" \"CMD\" C-m` |\n| Read output | `tmux capture-pane -p -t \"ID\"` |\n| Send interrupt | `tmux send-keys -t \"ID\" C-c` |\n| Kill window | `tmux kill-window -t \"ID\"` |\n"},"lastSynced":"2026-03-06T14:50:42.830Z","agentAnalysis":{"suitability":{"en":"Perfect for Terminal-Based Agents needing efficient background process management using tmux windows.","zh":"非常适合需要使用tmux窗口进行高效背景进程管理的基于终端的Agent。","ja":"Terminalベースのエージェントがバックグラウンドプロセス管理を効率的に行う必要がある場合に最適です。tmuxウィンドウを使用します。","ko":"-tmux 윈도우를 사용하여 효율적인 백그라운드 프로세스 관리가 필요한 터미널 기반 에이전트에 적합합니다.","es":"Perfecto para agentes basados en Terminal que necesitan una gestión eficiente de procesos en segundo plano utilizando ventanas de tmux.","fr":"Parfait pour les agents basés sur Terminal nécessitant une gestion efficace des processus en arrière-plan en utilisant des fenêtres tmux.","de":"Perfekt für terminalbasierte Agenten, die eine effiziente Hintergrundprozessverwaltung mit tmux-Fenstern benötigen.","pt":"Perfeito para Agentes Baseados em Terminal que necessitam de gerenciamento eficiente de processos em segundo plano usando janelas do tmux.","ru":"Идеально подходит для Терминальных Агентов, которым требуется эффективное управление фоновыми процессами с помощью окон tmux.","ar":"مثالي لعميل الطرفية الذي يحتاج إلى إدارة عملية خلفية فعالة باستخدام نوافذ tmux."},"recommendation":{"en":"Empowers agents to manage multiple commands simultaneously, leveraging tmux''s detached mode and send-keys functionality for seamless background process execution, including protocols like sending keys with `C-m`.","zh":"赋予代理管理多个命令的能力，利用tmux的分离模式和send-keys功能实现无缝的背景进程执行，包括使用`C-m`发送键等协议。","ja":"エージェントに複数のコマンドを同時に管理する能力を与え、tmuxのデタッチモードとsend-keys機能を利用してバックグラウンドプロセスの実行をシームレスに行うことができます。例えば、`C-m`でキーシーケンスを送信するプロトコルなど。","ko":"에이전트가 여러 명령을 동시에 관리할 수 있는 능력을 부여하며, tmux의 분리 모드와 send-keys 기능을 활용하여 백그라운드 프로세스의 실행을 무중단으로 수행할 수 있습니다. 예를 들어 `C-m`으로 키 시퀀스를 보내는 프로토콜 등이 있습니다.","es":"Permite a los agentes gestionar varios comandos simultáneamente, aprovechando el modo desacoplado de tmux y la funcionalidad de envío de claves para una ejecución de procesos en segundo plano sin problemas, incluyendo protocolos como el envío de claves con `C-m`.","fr":"Permet aux agents de gérer plusieurs commandes simultanément, en exploitant le mode déconnecté de tmux et la fonctionnalité d''envoi de clés pour une exécution de processus en arrière-plan sans problème, y compris des protocoles tels que l''envoi de clés avec `C-m`.","de":"Ermöglicht es den Agenten, mehrere Befehle gleichzeitig zu verwalten, indem sie den abgekoppelten Modus von tmux und die Sendetasten-Funktionalität für eine nahtlose Ausführung von Hintergrundprozessen nutzen, einschließlich Protokollen wie dem Senden von Tasten mit `C-m`.","pt":"Habilita os agentes a gerenciar vários comandos simultaneamente, utilizando o modo desanexado do tmux e a funcionalidade de envio de teclas para execução de processos em segundo plano sem interrupção, incluindo protocolos como envio de teclas com `C-m`.","ru":"Наделяет агентов возможностью управлять несколькими командами одновременно, используя отсоединенный режим tmux и функциональность отправки клавиш для бесперебойного выполнения фоновых процессов, включая протоколы, такие как отправка клавиш с `C-m`.","ar":"يمنح الوكلاء القدرة على إدارة أوامر متعددة في نفس الوقت، باستخدام وضع الفصل في tmux ووظيفة إرسال المفاتيح للتشغيل الخلفي المتواصل، بما في ذلك البروتوكولات مثل إرسال المفاتيح مع `C-m`."},"useCases":{"en":["Automating server startup with `npm run dev`","Debugging background processes using `tmux list-windows`","Creating detached windows for long-running tasks"],"zh":["使用`npm run dev`自动执行服务器启动","使用`tmux list-windows`调试背景进程","为长时间运行任务创建分离窗口"],"ja":["`npm run dev`でサーバー起動を自動化する","`tmux list-windows`でバックグラウンドプロセスをデバッグする","ロングランニングタスク用にデタッチウィンドウを作成する"],"ko":["`npm run dev`로 서버 시작을 자동화하는 것","`tmux list-windows`로 백그라운드 프로세스를 디버깅하는 것","장시간 실행되는 작업을 위한 분리 창을 만드는 것"],"es":["Automatización del arranque del servidor con `npm run dev`","Depuración de procesos en segundo plano con `tmux list-windows`","Creación de ventanas desacopladas para tareas de ejecución prolongada"],"fr":["Automatisation du démarrage du serveur avec `npm run dev`","Débogage des processus en arrière-plan avec `tmux list-windows`","Création de fenêtres déconnectées pour des tâches à exécution longue"],"de":["Automatisierung des Server-Starts mit `npm run dev`","Fehlerbehebung von Hintergrundprozessen mit `tmux list-windows`","Erstellung abgekoppelter Fenster für lang laufende Aufgaben"],"pt":["Automatizar a inicialização do servidor com `npm run dev`","Depurar processos em segundo plano usando `tmux list-windows`","Criar janelas desanexadas para tarefas de longa duração"],"ru":["Автоматизировать запуск сервера с помощью `npm run dev`","Отлаживать фоновые процессы, используя `tmux list-windows`","Создавать отсоединенные окна для задач длительного выполнения"],"ar":["تحسين تشغيل الخادم مع `npm run dev`","تصحيح الأخطاء في العمليات الخلفية باستخدام `tmux list-windows`","إنشاء نوافذ منفصلة لمهام طويلة الأمد"]},"limitations":{"en":["Requires tmux installation","Terminal access needed"],"zh":["需要安装tmux","需要终端访问"],"ja":["tmuxのインストールが必要","ターミナルへのアクセスが必要"],"ko":["tmux 설치가 필요함","터미널 접근이 필요함"],"es":["Requiere instalación de tmux","Se necesita acceso a Terminal"],"fr":["Nécessite l''installation de tmux","L''accès au Terminal est nécessaire"],"de":["Benötigt tmux-Installation","Terminal-Zugriff erforderlich"],"pt":["Requer instalação do tmux","Acesso ao terminal necessário"],"ru":["Требуется установка tmux","Необходим доступ к терминалу"],"ar":["يتطلب تثبيت tmux","مطلوب الوصول إلى الطرفية"]},"version":4},"contentHash":"0e850390b584e5bacc81791d90cc132c0cc75a5b7b2f54c12651079591c88957","qualityScore":39}');
