INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('colmarius/colmarius.github.io/tmux', 'tmux', 'colmarius', 'colmarius.github.io', 'community', 'tmux colmarius colmarius.github.io community The tmux skill enables developers to manage background processes using tmux windows, allowing for efficient task management. It benefits developers who need to run multiple commands simultaneously. tmux是一个用于管理背景进程的工具，允许您创建新窗口并运行命令 tmuxはバックグラウンドプロセスを管理するためのツールです tmux는 백그라운드 프로세스를 관리하기 위한 도구입니다 tmux es una herramienta para gestionar procesos en segundo plano. Permite crear ventanas y ejecutar comandos sin bloquear la terminal. tmux est un outil pour gérer les processus en arrière-plan. Il permet de créer des fenêtres et d''exécuter des commandes sans bloquer le terminal. tmux ist ein Tool zur Verwaltung von Hintergrundprozessen. Es ermöglicht die Erstellung von Fenstern und die Ausführung von Befehlen ohne Blockierung der Terminal. O Tmux é uma ferramenta de gerenciamento de processos em segundo plano que permite executar comandos sem bloquear o terminal. Tmux - это инструмент для управления фоновыми процессами, который позволяет выполнять команды без блокировки терминала с помощью ИИ Агентов. Tmux هو أداة لإدارة العمليات في الخلفية التي تسمح بتشغيل أوامر بدون حجز الطرفية باستخدام أدوات الذكاء الاصطناعي. how to use tmux tmux setup guide tmux alternative tmux vs screen tmux install what is tmux tmux tutorial tmux commands tmux windows management tmux 背景进程管理 终端复用器 tmux list-windows tmux new-window tmux send-keys Linux命令行工具 Manage background processes using tmux windows Verify environment and check status with `tmux list-windows` command Spawn new background processes with `tmux new-window` command Run commands in detached mode using `-d` flag Send keys to specific windows using `tmux send-keys` command tmux is a terminal multiplexer that enables users to manage multiple windows and sessions, allowing for efficient background process management.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('wogsland/marius-agents/tmux', 'community', 'wogsland', 'marius-agents', 'wogsland/marius-agents', 'tmux', 0, 0, 39, '2026-03-06T12:59:22.256Z', '2026-03-06T14:50:58.993Z', '0e850390b584e5bacc81791d90cc132c0cc75a5b7b2f54c12651079591c88957', '{"id":"wogsland/marius-agents/tmux","name":"tmux","description":{"en":"The tmux skill allows developers to manage background processes using tmux windows without blocking the terminal. It benefits developers who need to run multiple commands simultaneously.","zh":"tmux是一种后台进程管理工具，允许您创建和管理窗口，运行命令","ja":"tmuxはバックグラウンドプロセスを管理するためのツールです","ko":"tmux는 배경 프로세스를 관리하기 위한 도구입니다","es":"tmux es una herramienta para administrar procesos en segundo plano. Permite crear ventanas y ejecutar comandos de forma remota.","fr":"tmux est un outil pour gérer les processus en arrière-plan. Il permet de créer des fenêtres et d''exécuter des commandes de manière distante.","de":"tmux ist ein Werkzeug zur Verwaltung von Hintergrundprozessen. Es ermöglicht die Erstellung von Fenstern und die Ausführung von Befehlen im Hintergrund.","pt":"O tmux é uma ferramenta de gerenciamento de processos em segundo plano que permite executar comandos em janelas em segundo plano sem bloquear o terminal","ru":"tmux - это инструмент для управления фоновыми процессами, который позволяет выполнять команды в фоновом режиме без блокировки терминала с помощью ИИ Агентов","ar":"tmux هو أداة لإدارة العمليات الخلفية التي تمكنك من تشغيل أوامر في نوافذ خلفية دون حجب الطرفية باستخدام أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"tmux: Background Process Management Setup Guide | AI Agen...","zh":"tmux 后台进程管理Setup Guide","ja":"tmux を使用したバックグラウンドプロセス管理ベストプラクティス","ko":"tmux 배경 프로세스 관리 설정 가이드","es":"Guía de configuración de tmux para administrar procesos e...","fr":"Guide de configuration de tmux pour gérer les processus e...","de":"Einrichtungsleitfaden für tmux zur Verwaltung von Hinterg...","pt":"Guia de Configuração do tmux: Gerenciamento de Processos ...","ru":"Настройка tmux: Управление фоновыми процессами с помощью ...","ar":"دليل إعداد tmux: إدارة العمليات الخلفية باستخدام أدوات ال..."},"description":{"en":"Discover how to manage background processes with tmux. Learn to spawn new windows, send keys, and detach sessions with our expert guide. Get started now!","zh":"了解tmux后台进程管理的技术细节，包括窗口管理和命令发送","ja":"tmuxを使用してバックグラウンドプロセスを管理する方法を学びましょう","ko":"tmux 배경 프로세스 관리의 기술적인 세부 정보를 알아보세요","es":"Aprende a utilizar tmux para administrar procesos en segundo plano sin bloquear la terminal. Descubre cómo crear ventanas y ejecutar comandos de forma remota.","fr":"Découvrez comment utiliser tmux pour gérer les processus en arrière-plan sans bloquer le terminal. Apprenez à créer des fenêtres et à exécuter des commandes ...","de":"Erfahren Sie, wie Sie tmux verwenden, um Hintergrundprozesse zu verwalten, ohne die Terminal zu blockieren. Entdecken Sie, wie Sie Fenster erstellen und Befe...","pt":"Aprenda a gerenciar processos em segundo plano com o tmux, incluindo a verificação do ambiente e a execução de comandos em janelas em segundo plano","ru":"Узнайте, как управлять фоновыми процессами с помощью tmux, включая проверку среды и выполнение команд в фоновом режиме с помощью ИИ Агентов","ar":"تعلم كيفية إدارة العمليات الخلفية باستخدام tmux، بما في ذلك التحقق من البيئة وتنفيذ الأوامر في نوافذ خلفية باستخدام أدوات الذكاء الاصطناعي"},"definition":{"en":"tmux is a terminal multiplexer that enables multiple windows and sessions to run in the background, allowing for efficient process management.","zh":"tmux是一种命令行工具，用于管理后台进程和窗口","ja":"tmuxはコマンドラインツールで、バックグラウンドプロセスとウィンドウを管理します","ko":"tmux는 명령줄 도구로 배경 프로세스와 창을 관리합니다","es":"tmux es una herramienta de gestión de terminal que permite administrar procesos en segundo plano","fr":"tmux est un outil de gestion de terminal qui permet de gérer les processus en arrière-plan","de":"tmux ist ein Terminal-Management-Werkzeug, das die Verwaltung von Hintergrundprozessen ermöglicht","pt":"O tmux é uma ferramenta de gerenciamento de processos em segundo plano que permite executar comandos em janelas em segundo plano","ru":"tmux - это инструмент для управления фоновыми процессами","ar":"tmux هو أداة لإدارة العمليات الخلفية"},"features":{"en":["Verify tmux environment and check status using `tmux list-windows` command","Spawn new background processes with `tmux new-window` and `tmux send-keys` commands","Detach sessions using the `-d` flag for unobtrusive process management","Send keys to specific windows using `tmux send-keys` with the `-t` option","Create named windows for easy reference using the `-n` flag"],"zh":["创建和管理窗口","运行命令和发送键盘输入","后台进程管理","窗口命名和引用","命令行接口"],"ja":["ウィンドウの作成と管理","コマンドの実行とキーボード入力の送信","バックグラウンドプロセスの管理","ウィンドウの命名と参照","コマンドラインインターフェース"],"ko":["창 생성 및 관리","명령어 실행 및 키보드 입력 전송","배경 프로세스 관리","창 이름 지정 및 참조","명령줄 인터페이스"],"es":["Crear ventanas de tmux para administrar procesos en segundo plano","Ejecutar comandos de forma remota utilizando tmux send-keys","Listar ventanas existentes con tmux list-windows","Crear ventanas con nombres personalizados utilizando -n","Ejecutar procesos en segundo plano con -d"],"fr":["Créer des fenêtres tmux pour gérer les processus en arrière-plan","Exécuter des commandes de manière distante en utilisant tmux send-keys","Lister les fenêtres existantes avec tmux list-windows","Créer des fenêtres avec des noms personnalisés en utilisant -n","Exécuter des processus en arrière-plan avec -d"],"de":["Erstellen von tmux-Fenstern zur Verwaltung von Hintergrundprozessen","Ausführen von Befehlen im Hintergrund mit tmux send-keys","Auflisten von bestehenden Fenstern mit tmux list-windows","Erstellen von Fenstern mit benutzerdefinierten Namen unter Verwendung von -n","Ausführen von Prozessen im Hintergrund mit -d"],"pt":["Verificação do ambiente e lista de janelas existentes","Criação de novas janelas em segundo plano","Execução de comandos em janelas em segundo plano","Nomeação de janelas para referência fácil","Modo desanexado para execução em segundo plano"],"ru":["Проверка среды и список существующих окон","Создание новых окон в фоновом режиме","Выполнение команд в фоновом режиме","Назначение имен окон для легкой ссылки","Отсоединенный режим для выполнения в фоновом режиме"],"ar":["التحقق من البيئة وقائمة النوافذ الحالية","إنشاء نوافذ جديدة في الخلفية","تشغيل الأوامر في نوافذ خلفية","تسمية النوافذ للgetReference السهل","الوضع المنفصل للتشغيل في الخلفية"]},"keywords":{"en":["how to use tmux","tmux alternative","tmux vs screen","tmux install","tmux setup guide","what is tmux","tmux background process","tmux window management","tmux detached sessions"],"zh":["tmux","后台进程管理","窗口管理","命令行工具","Linux","Unix","命令行接口"],"ja":["tmux","バックグラウンドプロセス管理","ウィンドウ管理","コマンドラインツール","Linux","Unix","コマンドラインインターフェース"],"ko":["tmux","배경 프로세스 관리","창 관리","명령줄 도구","Linux","Unix","명령줄 인터페이스"],"es":["tmux","gestión de procesos en segundo plano","terminal","ventanas de tmux","comandos remotos","Herramientas de desarrollo","terminal de línea de comandos","gestión de procesos","desarrollo de software"],"fr":["tmux","gestion des processus en arrière-plan","terminal","fenêtres tmux","commandes distantes","Outils de développement","terminal en ligne de commande","gestion des processus","développement de logiciels"],"de":["tmux","Verwaltung von Hintergrundprozessen","Terminal","tmux-Fenster","Remote-Befehle","Entwicklungstools","Terminal-Kommandozeile","Prozessverwaltung","Software-Entwicklung"],"pt":["tmux","gerenciamento de processos em segundo plano","janelas em segundo plano","comandos em segundo plano","terminal","ferramenta de gerenciamento","configuração do tmux","guia de configuração do tmux"],"ru":["tmux","управление фоновыми процессами","окна в фоновом режиме","команды в фоновом режиме","терминал","инструмент для управления","настройка tmux","ИИ Агенты","инструменты для управления фоновыми процессами"],"ar":["tmux","إدارة العمليات الخلفية","نوافذ خلفية","أوامر خلفية","الطرفية","أداة لإدارة العمليات الخلفية","إعداد tmux","أدوات الذكاء الاصطناعي","أدوات لإدارة العمليات الخلفية"]}},"owner":"wogsland","repo":"marius-agents","repoPath":"wogsland/marius-agents","stars":0,"forks":0,"updatedAt":"2026-03-06T12:59:22.256Z","topics":[],"category":"community","skillMd":{"name":"tmux","description":"Instructions for using tmux to spawn multiple processes, inspect them, and capture their output. Use when running servers, long-running tasks, or background processes.","bodyPreview":"# tmux\n\nManage background processes using tmux windows without blocking the terminal.\n\n## 1. Verify Environment & Check Status\n\nConfirm tmux is running and list existing windows:\n\n```bash\ntmux list-windows\n```\n\n## 2. Spawn a Background Process\n\nCreate a new tmux window and run a command:\n\n```bash\ntmux new-window -n \"my-server\" -d\ntmux send-keys -t \"my-server\" \"npm run dev\" C-m\n```\n\n- `-n \"my-server\"` names the window for easy reference\n- `-d` keeps it detached (runs in background)\n- `C-m` sends","body":"# tmux\n\nManage background processes using tmux windows without blocking the terminal.\n\n## 1. Verify Environment & Check Status\n\nConfirm tmux is running and list existing windows:\n\n```bash\ntmux list-windows\n```\n\n## 2. Spawn a Background Process\n\nCreate a new tmux window and run a command:\n\n```bash\ntmux new-window -n \"my-server\" -d\ntmux send-keys -t \"my-server\" \"npm run dev\" C-m\n```\n\n- `-n \"my-server\"` names the window for easy reference\n- `-d` keeps it detached (runs in background)\n- `C-m` sends Enter to execute the command\n\n## 3. Inspect Output (Read Logs)\n\n### Visible screen only\n\n```bash\ntmux capture-pane -p -t \"my-server\"\n```\n\n### Full scrollback history\n\n```bash\ntmux capture-pane -p -t \"my-server\" -S -1000\n```\n\n- `-S -1000` captures the last 1000 lines of scrollback\n\n## 4. Interact with the Process\n\n### Send Ctrl+C (interrupt)\n\n```bash\ntmux send-keys -t \"my-server\" C-c\n```\n\n### Kill the window\n\n```bash\ntmux kill-window -t \"my-server\"\n```\n\n## 5. Advanced: Chaining Commands\n\nRun multiple commands in sequence:\n\n```bash\ntmux new-window -n \"build\" -d && \\\ntmux send-keys -t \"build\" \"npm run build && npm run test\" C-m\n```\n\n## Quick Reference\n\n| Action | Command |\n| ------ | ------- |\n| Create window | `tmux new-window -n \"ID\" -d` |\n| Run command | `tmux send-keys -t \"ID\" \"CMD\" C-m` |\n| Read output | `tmux capture-pane -p -t \"ID\"` |\n| Send interrupt | `tmux send-keys -t \"ID\" C-c` |\n| Kill window | `tmux kill-window -t \"ID\"` |\n"},"lastSynced":"2026-03-06T14:50:58.993Z","agentAnalysis":{"suitability":{"en":"Ideal for Terminal-based Agents requiring efficient background process management using tmux windows.","zh":"适用于需要使用tmux窗口进行高效后台进程管理的基于终端的Agent。","ja":"tmuxウィンドウを使用した効率的なバックグラウンドプロセス管理を必要とするターミナルベースのエージェントに適しています。","ko":"tmux 창을 사용하여 효율적인 백그라운드 프로세스 관리가 필요한 터미널 기반 에이전트에 적합합니다.","es":"Ideal para agentes basados en Terminal que requieren una gestión eficiente de procesos en segundo plano utilizando ventanas de tmux.","fr":"Idéal pour les agents basés sur Terminal nécessitant une gestion efficace des processus en arrière-plan à l''aide de fenêtres tmux.","de":"Ideal für Terminal-basierte Agents, die eine effiziente Verwaltung von Hintergrundprozessen unter Verwendung von tmux-Fenstern erfordern.","pt":"Ideal para Agentes baseados em Terminal que exigem gerenciamento eficiente de processos em segundo plano usando janelas do tmux.","ru":"Идеально для терминальных агентов, требующих эффективного управления фоновыми процессами с помощью окон tmux.","ar":"مثالي للوكلاء المستندة إلى الطرفية التي تتطلب إدارة الخلفية الفعالة للعمليات باستخدام نوافذ tmux."},"recommendation":{"en":"Empowers agents to manage background processes using tmux windows without blocking the terminal, leveraging commands like `tmux new-window` and `tmux send-keys` for seamless execution of tasks like running servers or scripts in detached mode.","zh":"赋予代理管理后台进程使用tmux窗口而不阻塞终端的能力，利用诸如`tmux new-window`和`tmux send-keys`的命令来实现诸如运行服务器或脚本等任务的无缝执行。","ja":"エージェントがターミナルをブロックせずにtmuxウィンドウを使用してバックグラウンドプロセスを管理できるようにし、`tmux new-window`や`tmux send-keys`などのコマンドを使用してサーバーを実行したりスクリプトを実行したりするなどのタスクをシームレスに実行できるようにします。","ko":"에이전트가 터미널을 차단하지 않고 tmux 창을 사용하여 백그라운드 프로세스를 관리할 수 있도록 하며, `tmux new-window` 및 `tmux send-keys`와 같은 명령을 사용하여 서버를 실행하거나 스크립트를 실행하는 등의 작업을 무중단으로 실행할 수 있습니다.","es":"Habilita a los agentes a gestionar procesos en segundo plano utilizando ventanas de tmux sin bloquear la terminal, aprovechando comandos como `tmux new-window` y `tmux send-keys` para una ejecución fluida de tareas como la ejecución de servidores o scripts en modo desacoplado.","fr":"Permet aux agents de gérer les processus en arrière-plan à l''aide de fenêtres tmux sans bloquer le terminal, en exploitant des commandes comme `tmux new-window` et `tmux send-keys` pour une exécution fluide de tâches comme l''exécution de serveurs ou de scripts en mode détaché.","de":"Ermöglicht es Agents, Hintergrundprozesse mithilfe von tmux-Fenstern zu verwalten, ohne die Terminal zu blockieren, und nutzt Befehle wie `tmux new-window` und `tmux send-keys` für eine nahtlose Ausführung von Aufgaben wie dem Ausführen von Servern oder Skripten im abgekoppelten Modus.","pt":"Habilita os agentes a gerenciar processos em segundo plano usando janelas do tmux sem bloquear o terminal, aproveitando comandos como `tmux new-window` e `tmux send-keys` para a execução sem problemas de tarefas como a execução de servidores ou scripts no modo desanexado.","ru":"Наделяет агентов возможностью управлять фоновыми процессами с помощью окон tmux без блокирования терминала, используя команды типа `tmux new-window` и `tmux send-keys` для бесперебойного выполнения задач, таких как запуск серверов или сценариев в отсоединенном режиме.","ar":"تمكين الوكلاء من إدارة العمليات الخلفية باستخدام نوافذ tmux دون حجب الطرفية، واستخدام أوامر مثل `tmux new-window` و `tmux send-keys` لتنفيذ المهام بدون مشاكل، مثل تشغيل الخوادم أو البرامج النصية في وضع الفصل."},"useCases":{"en":["Automating server startups with `npm run dev`","Debugging background processes using `tmux list-windows`","Spawning new background tasks with `tmux new-window -d`"],"zh":["使用`npm run dev`自动启动服务器","使用`tmux list-windows`调试后台进程","使用`tmux new-window -d`生成新的后台任务"],"ja":["`npm run dev`を使用してサーバーを自動起動する","`tmux list-windows`を使用してバックグラウンドプロセスをデバッグする","`tmux new-window -d`を使用して新しいバックグラウンドタスクを生成する"],"ko":["`npm run dev`를 사용하여 서버를 자동으로 시작하는 것","`tmux list-windows`를 사용하여 백그라운드 프로세스를 디버깅하는 것","`tmux new-window -d`를 사용하여 새로운 백그라운드 작업을 생성하는 것"],"es":["Automatización de arranques de servidores con `npm run dev`","Depuración de procesos en segundo plano utilizando `tmux list-windows`","Creación de nuevas tareas en segundo plano con `tmux new-window -d`"],"fr":["Automatisation des démarrages de serveurs avec `npm run dev`","Débogage des processus en arrière-plan à l''aide de `tmux list-windows`","Création de nouvelles tâches en arrière-plan avec `tmux new-window -d`"],"de":["Automatisierung von Serverstarts mit `npm run dev`","Fehlerbehebung von Hintergrundprozessen unter Verwendung von `tmux list-windows`","Erzeugung neuer Hintergrundaufgaben mit `tmux new-window -d`"],"pt":["Automatizar a inicialização de servidores com `npm run dev`","Depurar processos em segundo plano usando `tmux list-windows`","Criar novas tarefas em segundo plano com `tmux new-window -d`"],"ru":["Автоматизировать запуск серверов с помощью `npm run dev`","Отлаживать фоновые процессы с помощью `tmux list-windows`","Создавать новые фоновые задачи с помощью `tmux new-window -d`"],"ar":["تأتمتة تشغيل الخوادم مع `npm run dev`","تصحيح الأخطاء في العمليات الخلفية باستخدام `tmux list-windows`","إنشاء مهام خلفية جديدة مع `tmux new-window -d`"]},"limitations":{"en":["Requires tmux installation","Terminal access necessary","Limited to command-line interface"],"zh":["需要安装tmux","需要终端访问","仅限于命令行接口"],"ja":["tmuxのインストールが必要","ターミナルアクセスが必要","コマンドラインインターフェースに限定される"],"ko":["tmux 설치가 필요합니다","터미널 액세스가 필요합니다","명령줄 인터페이스에만 제한됨"],"es":["Requiere instalación de tmux","Acceso a terminal necesario","Limitado a interfaz de línea de comandos"],"fr":["Nécessite l''installation de tmux","Accès terminal nécessaire","Limité à l''interface en ligne de commande"],"de":["Erfordert tmux-Installation","Terminal-Zugriff erforderlich","Begrenzt auf Kommandozeileninterface"],"pt":["Exige a instalação do tmux","Acesso ao terminal necessário","Limitado à interface de linha de comando"],"ru":["Требует установки tmux","Необходим доступ к терминалу","Ограничен интерфейсом командной строки"],"ar":["يتطلب تثبيت tmux","تحتاج الوصول إلى الطرفية","محدود ب واجهة سطر الأوامر"]},"version":4},"contentHash":"0e850390b584e5bacc81791d90cc132c0cc75a5b7b2f54c12651079591c88957","qualityScore":39}');
