INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('trotsky1997/My-Claude-Agent-Skills/github-cli', 'github-cli', 'trotsky1997', 'My-Claude-Agent-Skills', 'community', 'github-cli trotsky1997 My-Claude-Agent-Skills community The github-cli skill enables developers to manage GitHub repositories, issues, and pull requests from the terminal. It provides a range of commands for authentication, repository viewing, and issue management. GitHub CLI（gh）是一种终端交互工具，用于管理GitHub仓库、问题、拉取请求和发布 GitHub CLI（gh）は、GitHubのリポジトリ、課題、プルリクエスト、リリースを管理するためのターミナルベースのインタラクティブツールです GitHub CLI（gh）は GitHub 저장소, 문제, 풀 요청 및 릴리스를 관리하는 터미널 기반 상호 작용 도구입니다 GitHub CLI (gh) permite la interacción basada en terminal con GitHub para gestionar repositorios, problemas y solicitudes de extracción GitHub CLI (gh) permet l''interaction basée sur le terminal avec GitHub pour gérer des référentiels, des problèmes et des demandes d''extraction GitHub CLI (gh) ermöglicht die terminalbasierte Interaktion mit GitHub zur Verwaltung von Repositories, Problemen und Pull-Requests O GitHub CLI (gh) é uma ferramenta de linha de comando para interagir com o GitHub. Ele permite gerenciar repositórios, issues e pull requests de forma eficiente GitHub CLI (gh) - это инструмент командной строки для взаимодействия с GitHub. Он позволяет управлять репозиториями, проблемами и запросами на включение واجهة سطر الأوامر GitHub (gh) هي أداة سطر أوامر للتفاعل مع GitHub. وهي تسمح بإدارة المستودعات والقضايا والطلبات السحابية بفعالية how to use github-cli github-cli setup guide github-cli alternative github-cli vs git github-cli install github-cli authentication terminal-based github management github-cli commands github-cli tutorial GitHub CLI AI工具 终端交互 仓库管理 问题管理 拉取请求管理 GitHub命令行接口 Authenticate with GitHub using `gh auth login` and `gh auth status` commands View current repository details with `gh repo view` command List and manage pull requests using `gh pr list` and `gh pr create` commands List and manage issues using `gh issue list` command Supports terminal-based interaction for efficient GitHub management github-cli is a command-line tool that enables terminal-based interaction with GitHub for managing repositories, issues, pull requests, and releases.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('anntnzrb/agents/gh-discussions-answerer', 'community', 'anntnzrb', 'agents', 'anntnzrb/agents', 'gh-discussions-answerer', 0, 0, 39, '2026-03-08T01:57:15.266Z', '2026-03-08T01:59:58.121Z', '4621086a327532d50f910f4ab233a27ffc5e0d386a2fbca6dfb4e58fe8102d4a', '{"id":"anntnzrb/agents/gh-discussions-answerer","name":"gh-discussions-answerer","description":{"en":"The gh-discussions-answerer skill automates answering GitHub discussions using LLM harnesses, benefiting developers by providing efficient and accurate responses. It utilizes the gh CLI for 100% code verification.","zh":"GH 讨论回答器配置指南，使用 gh CLI 实现自动回答和代码验证","ja":"GitHub Discussions Answerer の設定ガイド。gh CLI を使用して自動回答とコード検証を実現する","ko":"GH 토론 답변자 설정 가이드. gh CLI를 사용하여 자동 답변 및 코드 검증을 구현합니다","es":"El gh-discussions-answerer es una herramienta de AI que responde discusiones en GitHub mediante configuraciones de LLM","fr":"L''outil gh-discussions-answerer est un outil d''IA qui répond aux discussions GitHub via des configurations de LLM","de":"Der gh-discussions-answerer ist ein KI-Tool, das GitHub-Diskussionen mithilfe von LLM-Konfigurationen beantwortet","pt":"O gh-discussions-answerer é uma ferramenta de IA que responde a discussões não respondidas no GitHub com configurações personalizadas e verificação de código via CLI.","ru":"ИИ Агент gh-discussions-answerer - это инструмент, который отвечает на неотвеченные обсуждения на GitHub с настраиваемыми конфигурациями и кодовой верификацией через CLI.","ar":"مرشح المناقشات على جيت هاب هو أداة ذكاء اصطناعي تُستخدم للاستجابة للنقاشات غير المُجابة على منصة جيت هاب مع إمكانية تخصيص الإعدادات والتحقق من الشفرة عبر واجهة سطر الأوامر"},"seo":{"title":{"en":"gh-discussions-answerer: Automated GitHub Discussions Ans...","zh":"GH 讨论回答器设置指南 - AIエージェント","ja":"GitHub Discussions Answerer Setup Guide - AIエージェント","ko":"GH 토론 답변자 