INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('anntnzrb/agents/gh-discussions-answerer', 'gh-discussions-answerer', 'anntnzrb', 'agents', 'community', 'gh-discussions-answerer anntnzrb agents community The gh-discussions-answerer skill automates answering GitHub discussions using LLM harnesses, benefiting developers by providing efficient and accurate responses. It utilizes the gh CLI for 100% code verification. GH 讨论回答器配置指南，使用 gh CLI 实现自动回答和代码验证 GitHub Discussions Answerer の設定ガイド。gh CLI を使用して自動回答とコード検証を実現する GH 토론 답변자 설정 가이드. gh CLI를 사용하여 자동 답변 및 코드 검증을 구현합니다 El gh-discussions-answerer es una herramienta de AI que responde discusiones en GitHub mediante configuraciones de LLM L''outil gh-discussions-answerer est un outil d''IA qui répond aux discussions GitHub via des configurations de LLM Der gh-discussions-answerer ist ein KI-Tool, das GitHub-Diskussionen mithilfe von LLM-Konfigurationen beantwortet O gh-discussions-answerer é uma ferramenta de IA que responde a discussões não respondidas no GitHub com configurações personalizadas e verificação de código via CLI. ИИ Агент gh-discussions-answerer - это инструмент, который отвечает на неотвеченные обсуждения на GitHub с настраиваемыми конфигурациями и кодовой верификацией через CLI. مرشح المناقشات على جيت هاب هو أداة ذكاء اصطناعي تُستخدم للاستجابة للنقاشات غير المُجابة على منصة جيت هاب مع إمكانية تخصيص الإعدادات والتحقق من الشفرة عبر واجهة سطر الأوامر how to use gh-discussions-answerer gh-discussions-answerer setup guide automated GitHub discussions answering gh-discussions-answerer vs other AI agent skills gh-discussions-answerer install what is gh-discussions-answerer gh-discussions-answerer alternative LLM harnesses for GitHub discussions gh CLI for automated answering GH 讨论回答器 AIエージェント 自动回答 代码验证 gh CLI GitHub Discussions 开发效率 自动化工具 Delegates work to general subagents for efficient processing Utilizes the gh CLI for 100% code-verified answers Auto-posts answers immediately after analysis Discards only uncertain answers to ensure accuracy Operates in read-only mode until Phase 3, using only GET/query operations gh-discussions-answerer is a GitHub discussions answerer skill that automates the process of finding and answering discussions using LLM harnesses and the gh CLI');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ronnycoding/.claude/secure-web-search', 'community', 'ronnycoding', '.claude', 'ronnycoding/.claude', 'secure-web-search', 0, 0, 39, '2026-03-08T01:57:15.267Z', '2026-03-08T01:59:58.626Z', '3ca615a4b2c5c8ebd6ab394ee003a63a340d9595cbe5131c9e431455b8b9cc74', '{"id":"ronnycoding/.claude/secure-web-search","name":"secure-web-search","description":{"en":"The secure-web-search skill helps developers perform secure web searches while protecting privacy and verifying sources, essential for research and fact-checking.","zh":"本技能帮助您执行安全的网络搜索，保护隐私，验证信息来源和准确性","ja":"このスキルは、プライバシーを保護し、情報源を検証し、情報の正確性を 確認するセキュアなウェブ検索を実行するのに役立ちます","ko":"이 스킬은 개인 정보를 보호하고 정보 출처를 검증하며 정보 정확성을 확인하는 보안 웹 검색을 수행하는 데 도움이 됩니다","es":"El skill de búsqueda web segura de Claude Code ayuda a realizar búsquedas en línea de manera segura y precisa. Utiliza Agentes de IA especializados para proteger la privacidad y verificar la exactitud de la información","fr":"La compétence de recherche web sécurisée de Claude Code aide à effectuer des recherches en ligne de manière sécurisée et précise. Elle utilise des Outils d''IA spécialisés pour protéger la vie privée et vérifier l''exactitude des informations","de":"Die Fähigkeit zur sicheren Web-Suche von Claude Code hilft bei der Durchführung von Online-Suchen auf sichere und genaue Weise. Sie verwendet KI-Agents, um die Privatsphäre zu schützen und die Genauigkeit von Informationen zu überprüfen","pt":"O skill secure-web-search permite realizar buscas seguras na web, protegendo a privacidade e verificando a precisão das informações. É essencial para pesquisas, checagem de fatos e coleta de informações confiáveis","ru":"Навык secure-web-search позволяет выполнять безопасные поисковые запросы в Интернете, защищая приватность и проверяя точность информации. Он необходим для исследований, проверки фактов и сбора 