INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('steinbeck/nmrxiv-downloader/nmrxiv', 'community', 'steinbeck', 'nmrxiv-downloader', 'steinbeck/nmrxiv-downloader', 'nmrxiv', 0, 0, 39, '2026-03-08T01:57:15.273Z', '2026-03-08T02:00:28.427Z', 'e8c886a39062e7ec9d8fc26d902682e5528c88f8e0720b531a9dca881d06a1f9', '{"id":"steinbeck/nmrxiv-downloader/nmrxiv","name":"nmrxiv","description":{"en":"nmrxiv is a Python CLI tool for searching and downloading NMR spectroscopy datasets from nmrxiv.org, benefiting developers and researchers in the field.","zh":"nmrxiv 下载器是一个 Python CLI 工具，用于搜索和下载 NMR 数据集。使用 pip 安装并运行 nmrxiv 命令","ja":"nmrxiv ダウンローダーは、NMR データセットを検索およびダウンロードする Python CLI ツールです。pip でインストールし、nmrxiv コマンドを実行します","ko":"nmrxiv 다운로드는 NMR 데이터셋을 검색하고 다운로드하는 Python CLI 도구입니다. pip를 사용하여 설치하고 nmrxiv 명령을 실행합니다","es":"nmrxiv es una herramienta de línea de comandos de Python para buscar y descargar conjuntos de datos de NMR de nmrxiv.org","fr":"nmrxiv est un outil de ligne de commande Python pour rechercher et télécharger des jeux de données NMR à partir de nmrxiv.org","de":"nmrxiv ist ein Python-CLI-Tool für die Suche und den Download von NMR-Datensätzen von nmrxiv.org","pt":"O nmrxiv é uma ferramenta de linha de comando Python para buscar e baixar conjuntos de dados de NMR do nmrxiv.org. Ele fornece comandos para listar projetos e conjuntos de dados, bem como buscar moléculas.","ru":"Nmrxiv - это инструмент командной строки Python для поиска и загрузки наборов данных ЯМР с nmrxiv.org. Он предоставляет команды для списка проектов и наборов данных, а также поиска молекул.","ar":"nmrxiv هو أداة سطر أوامر Python للبحث وتنزيل مجموعات بيانات NMR من nmrxiv.org. يوفر أوامر لlisting المشاريع ومجموعات البيانات، وكذلك البحث عن الجزيئات."},"seo":{"title":{"en":"nmrxiv: NMR Dataset Search & Download Setup Guide | AI Ag...","zh":"nmrxiv 下载器安装指南 - Python CLI 工具","ja":"nmrxiv ダウンローダー設定ガイド - Python CLI ツール","ko":"nmrxiv 다운로드 설정 가이드 - Python CLI 도구","es":"nmrxiv: Guía de configuración para búsqueda y descarga de...","fr":"nmrxiv: Guide de configuration pour la recherche et le té...","de":"nmrxiv: Einrichtungsanleitung für die Suche und den Downl...","pt":"Guia de Configuração do nmrxiv: Ferramenta de Linha de Co...","ru":"Настройка nmrxiv: Python CLI для поиска и загрузки наборо...","ar":"إعداد nmrxiv: أداة سطر أوامر Python للبحث وتنزيل مجموعات ..."},"description":{"en":"Discover how to install and use nmrxiv to search and download NMR datasets from nmrxiv.org - get started with the CLI tool today!","zh":"使用 nmrxiv 下载器搜索和下载 NMR 数据集。了解如何安装和使用此 Python CLI 工具来简化您的工作","ja":"nmrxiv ダウンローダーを使用して NMR データセットを検索およびダウンロードします。この Python CLI ツールのインストール方法と使い方を参照してください","ko":"nmrxiv 다운로드를 사용하여 NMR 데이터셋을 검색하고 다운로드합니다. 이 Python CLI 도구를 설치하고 사용하는 방법을 알아보세요","es":"Descubre cómo utilizar nmrxiv para buscar y descargar conjuntos de datos de NMR de nmrxiv.org con nuestra guía de configuración","fr":"Découvrez comment utiliser nmrxiv pour rechercher et télécharger des jeux de données NMR à partir de nmrxiv.org avec notre guide de configuration","de":"Erfahren Sie, wie Sie nmrxiv verwenden können, um NMR-Datensätze von nmrxiv.org zu suchen und herunterzuladen, mit unserer Einrichtungsanleitung","pt":"Aprenda a configurar e usar o nmrxiv, uma ferramenta de linha de comando Python para buscar e baixar conjuntos de dados de NMR do nmrxiv.org","ru":"Узнайте, как настроить и использовать nmrxiv, инструмент командной строки Python для поиска и загрузки наборов данных ЯМР с nmrxiv.org","ar":"تعلم كيفية إعداد واستخدام nmrxiv، أداة سطر أوامر Python للبحث وتنزيل مجموعات بيانات NMR من nmrxiv.org"},"definition":{"en":"nmrxiv is a command-line interface tool for searching and downloading NMR datasets from nmrxiv.org, utilizing Python and CLI commands.","zh":"nmrxiv 是一个用于搜索和下载 NMR 数据集的 Python CLI 工具","ja":"nmrxiv は、NMR データセットを検索およびダウンロードする Python CLI ツールです","ko":"nmrxiv는 NMR 데이터셋을 검색하고 다