INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('steinbeck/nmrxiv-downloader/nmrxiv', 'nmrxiv', 'steinbeck', 'nmrxiv-downloader', 'community', 'nmrxiv steinbeck nmrxiv-downloader community nmrxiv is a Python CLI tool for searching and downloading NMR spectroscopy datasets from nmrxiv.org, benefiting developers and researchers in the field. nmrxiv 下载器是一个 Python CLI 工具，用于搜索和下载 NMR 数据集。使用 pip 安装并运行 nmrxiv 命令 nmrxiv ダウンローダーは、NMR データセットを検索およびダウンロードする Python CLI ツールです。pip でインストールし、nmrxiv コマンドを実行します nmrxiv 다운로드는 NMR 데이터셋을 검색하고 다운로드하는 Python CLI 도구입니다. pip를 사용하여 설치하고 nmrxiv 명령을 실행합니다 nmrxiv es una herramienta de línea de comandos de Python para buscar y descargar conjuntos de datos de NMR de nmrxiv.org nmrxiv est un outil de ligne de commande Python pour rechercher et télécharger des jeux de données NMR à partir de nmrxiv.org nmrxiv ist ein Python-CLI-Tool für die Suche und den Download von NMR-Datensätzen von nmrxiv.org O nmrxiv é uma ferramenta de linha de comando Python para buscar e baixar conjuntos de dados de NMR do nmrxiv.org. Ele fornece comandos para listar projetos e conjuntos de dados, bem como buscar moléculas. Nmrxiv - это инструмент командной строки Python для поиска и загрузки наборов данных ЯМР с nmrxiv.org. Он предоставляет команды для списка проектов и наборов данных, а также поиска молекул. nmrxiv هو أداة سطر أوامر Python للبحث وتنزيل مجموعات بيانات NMR من nmrxiv.org. يوفر أوامر لlisting المشاريع ومجموعات البيانات، وكذلك البحث عن الجزيئات. how to use nmrxiv nmrxiv install nmrxiv setup guide nmrxiv alternative nmrxiv vs other NMR tools what is nmrxiv nmrxiv CLI tool NMR dataset search NMR spectroscopy datasets nmrxiv NMR 数据集 Python CLI pip 安装 搜索和下载 数据解析 JSON 路径 分子搜索 Installs via PyPI using pip install nmrxiv-downloader Verifies installation with nmrxiv --help command Lists projects using nmrxiv list --type project Lists datasets using nmrxiv list --type dataset Searches molecules using nmrxiv search command nmrxiv is a command-line interface tool for searching and downloading NMR datasets from nmrxiv.org, utilizing Python and CLI commands.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('cloudflare/moltworker/cloudflare-browser', 'community', 'cloudflare', 'moltworker', 'cloudflare/moltworker', 'cloudflare-browser', 0, 0, 39, '2026-03-08T01:57:15.274Z', '2026-03-08T02:00:31.941Z', '06f8f67410955ff10065b70d306e1c996a3cd12e429346099d495dfacec1f483', '{"id":"cloudflare/moltworker/cloudflare-browser","name":"cloudflare-browser","description":{"en":"The cloudflare-browser skill enables developers to control headless browsers via Cloudflare Workers using CDP over WebSocket, streamlining browser rendering and automation tasks.","zh":"Cloudflare 浏览器渲染控制允许您通过 CDP 协议控制 headless 浏览器。使用 OpenClaw 在 Cloudflare Workers 上运行您的浏览器渲染工作流程","ja":"Cloudflare ブラウザレンダリング制御は、CDP プロトコルを使用してヘッドレスブラウザを制御できるようにします。OpenClaw を使用して Cloudflare Workers 上でブラウザレンダリングワークフローを実行します","ko":"Cloudflare 브라우저 렌더링 제어를 사용하여 CDP 프로토콜을 통해 헤드리스 브라우저를 제어할 수 있습니다. OpenClaw를 사용하여 Cloudflare Workers에서 브라우저 렌더링 워크플ロー를 실행합니다","es":"Cloudflare Browser permite controlar navegadores headless mediante CDP y WebSocket. Configura tu entorno con OpenClaw y Workers de Cloudflare.","fr":"Cloudflare Browser permet de gérer les navigateurs headless via CDP et WebSocket. Configurez votre environnement avec OpenClaw et les Workers de Cloudflare.","de":"Cloudflare Browser ermöglicht die Steuerung von headless Browsern über CDP und WebSocket. Konfigurieren Sie Ihre Umgebung mit OpenClaw und Cloudflare Workers.","pt":"O Cloudflare Browser permite executar OpenClaw em Workers, utilizando o Chrome DevTools Protocol sobre WebSocket. Saiba como configurá-lo","ru":"Сloudflare Browser позволяет запускать OpenClaw на Workers, используя Chrome DevTools Protocol по WebSocket. Узнайте, как настроить","ar":"يسمح Cloudflare Browser بتشغيل OpenClaw على Workers، باستخدام Chrome DevTools Protocol عبر WebSocket. تعرف على كيفية الإعداد"},"seo":{"title":{"en":"cloudflare-browser: Control Headless Browsers via Cloudfl...","zh":"Cloudflare 浏览器渲染 Setup Guide - OpenClaw 集成","ja":"Cloudflare ブラウザレンダリングのベストプラクティス - OpenClaw を使用した AIエージェント","ko":"Cloudflare 브라우저 렌더링 설정 가이드 - OpenClaw와의 통합","es":"Guía de configuración de Cloudflare Browser para control ...","fr":"Guide de configuration de Cloudflare Browser pour la gest...","de":"Konfigurationsleitfaden für Cloudflare Browser zur Steuer...","pt":"Guia de Configuração do Cloudflare Browser para Desenvolv...","ru":"ИИ Агенты: Настройка Cloudflare Browser для Работы с Open...","ar":"دليل إعداد Cloudflare Browser لاستخدامه مع OpenClaw"},"description":{"en":"Unlock seamless browser rendering with cloudflare-browser. Learn how to set up and utilize this AI agent skill for efficient headless browsing","zh":"了解如何在 Cloudflare Workers 上运行 OpenClaw，实现浏览器渲染控制和 CDP 协议支持","ja":"Cloudflare Workers 上で OpenClaw を実行し、ブラウザレンダリング制御と CDP プロトコルをサポートする方法を学習します","ko":"Cloudflare Workers에서 OpenClaw를 실행하여 브라우저 렌더링 제어와 CDP 프로토콜 지원을 구현하는 방법을 알아보세요","es":"Aprende a configurar Cloudflare Browser para controlar navegadores headless con CDP y WebSocket","fr":"Découvrez comment configurer Cloudflare Browser pour gérer les navigateurs headless avec CDP et WebSocket","de":"Erfahren Sie, wie Sie Cloudflare Browser konfigurieren, um headless Browser mit CDP und WebSocket zu steuern","pt":"Aprenda a configurar o Cloudflare Browser para executar OpenClaw, incluindo a configuração do ambiente e a utilização do Chrome DevTools Protocol","ru":"Узнайте, как настроить Cloudflare Browser для работы с OpenClaw, включая установку переменных окружения и настройку профиля браузера","ar":"تعرف على كيفية إعداد Cloudflare Browser لاستخدامه مع OpenClaw، بما في ذلك إعداد المتغيرات البيئية وتكوين ملف تعريف المتصفح"},"definition":{"en":"cloudflare-browser is a skill that allows developers to leverage Cloudflare''s Browser Rendering service for controlling headless browsers via Chrome DevTools Protocol (CDP) over WebSocket","zh":"Cloudflare 浏览器渲染控制是一种使用 CDP 协议控制 headless 浏览器的技术","ja":"Cloudflare ブラウザレンダリング制御は、ヘッドレスブラウザを制御するために CDP プロトコルを使用する技術です","ko":"Cloudflare 브라우저 렌더링 제어는 헤드리스 브라우저를 제어하기 위해 CDP 프로토콜을 사용하는 기술입니다","es":"Cloudflare Browser es un servicio que permite controlar navegadores headless mediante CDP y WebSocket","fr":"Cloudflare Browser est un service qui permet de gérer les navigateurs headless via CDP et WebSocket","de":"Cloudflare Browser ist ein Dienst, der die Steuerung von headless Browsern über CDP und WebSocket ermöglicht","pt":"O Cloudflare Browser é um serviço que permite controlar navegadores headless via Chrome DevTools Protocol","ru":"Cloudflare Browser - это сервис, позволяющий управлять headless-браузерами через Chrome DevTools Protocol","ar":"Cloudflare Browser هو خدمة تسمح بالتحكم في المتصفحات الخفية عبر Chrome DevTools Protocol"},"features":{"en":["Utilizes Chrome DevTools Protocol (CDP) for browser control","Supports WebSocket protocol for real-time communication","Requires CDP_SECRET environment variable setup","Configures browser profiles in openclaw.json for customized settings","Enables headless browsing via Cloudflare Workers","Uses JSON format for configuring browser profiles"],"zh":["使用 CDP 协议控制 headless 浏览器","在 Cloudflare Workers 上运行 OpenClaw","支持 WebSocket 连接","配置浏览器-profile 以使用 cdpUrl","实现浏览器渲染控制和截图功能","支持 Cloudflare Workers 的安全性和可扩展性"],"ja":["CDP プロトコルを使用してヘッドレスブラウザを制御","Cloudflare Workers 上で OpenClaw を実行","WebSocket 接続をサポート","ブラウザプロファイルを cdpUrl で構成","ブラウザレンダリング制御とスクリーンショット機能を実現","Cloudflare Workers のセキュリティとスケーラビリティをサポート"],"ko":["CDP 프로토콜을 사용하여 헤드리스 브라우저를 제어","Cloudflare Workers에서 OpenClaw를 실행","WebSocket 연결을 지원","브라우저 프로파일을 cdpUrl로 구성","브라우저 렌더링 제어와 스크린샷 기능을 구현","Cloudflare Workers의 보안性과 확장성을 지원"],"es":["Control de navegadores headless mediante CDP","Conexión segura con WebSocket","Configuración de perfiles de navegador en openclaw.json","Compatibilidad con Workers de Cloudflare","Uso de la variable de entorno CDP_SECRET","Soporte para la toma de capturas de pantalla"],"fr":["Gestion de navigateurs headless via CDP","Connexion sécurisée avec WebSocket","Configuration de profils de navigateur dans openclaw.json","Compatibilité avec les Workers de Cloudflare","Utilisation de la variable d''environnement CDP_SECRET","Prise en charge de la capture d''écran"],"de":["Steuerung von headless Browsern über CDP","Sichere Verbindung mit WebSocket","Konfiguration von Browser-Profilen in openclaw.json","Kompatibilität mit Cloudflare Workers","Verwendung der Umgebungsvariable CDP_SECRET","Unterstützung für Screenshot-Erfassung"],"pt":["Execução de OpenClaw em Workers","Utilização do Chrome DevTools Protocol sobre WebSocket","Configuração de perfil de navegador em openclaw.json","Suporte à variável de ambiente CDP_SECRET","Integração com Cloudflare Workers"],"ru":["Запуск OpenClaw на Workers","Использование Chrome DevTools Protocol по WebSocket","Настройка профиля браузера в openclaw.json","Поддержка переменной окружения CDP_SECRET","Интеграция с Cloudflare Workers"],"ar":["تشغيل OpenClaw على Workers","استخدام Chrome DevTools Protocol عبر WebSocket","تكوين ملف تعريف المتصفح في openclaw.json","دعم متغير البيئة CDP_SECRET","التكامل مع Cloudflare Workers"]},"keywords":{"en":["how to use cloudflare-browser","cloudflare-browser setup guide","cloudflare-browser vs puppeteer","cloudflare-browser install","what is cloudflare-browser","cloudflare-browser alternative","cloudflare-browser tutorial","cloudflare-browser and CDP","cloudflare-browser WebSocket setup"],"zh":["Cloudflare 浏览器渲染控制","OpenClaw","CDP 协议","headless 浏览器","Cloudflare Workers","WebSocket","浏览器渲染","截图功能","浏览器-profile"],"ja":["Cloudflare ブラウザレンダリング制御","OpenClaw","CDP プロトコル","ヘッドレスブラウザ","Cloudflare Workers","WebSocket","ブラウザレンダリング","スクリーンショット機能","ブラウザプロファイル"],"ko":["Cloudflare 브라우저 렌더링 제어","OpenClaw","CDP 프로토콜","헤드리스 브라우저","Cloudflare Workers","WebSocket","브라우저 렌더링","스크린샷 기능","브라우저 프로파일"],"es":["Cloudflare Browser","control de navegadores headless","CDP","WebSocket","OpenClaw","Workers de Cloudflare","configuración de navegador","captura de pantalla","desarrollo web","herramientas de desarrollo"],"fr":["Cloudflare Browser","gestion de navigateurs headless","CDP","WebSocket","OpenClaw","Workers de Cloudflare","configuration de navigateur","capture d''écran","développement web","outils de développement"],"de":["Cloudflare Browser","Steuerung von headless Browsern","CDP","WebSocket","OpenClaw","Cloudflare Workers","Browser-Konfiguration","Screenshot-Erfassung","Webentwicklung","Entwicklungstools"],"pt":["Cloudflare Browser","OpenClaw","Chrome DevTools Protocol","Workers","headless browser","CDP_SECRET","openclaw.json","desenvolvimento web","ferramentas de desenvolvimento"],"ru":["Cloudflare Browser","OpenClaw","Chrome DevTools Protocol","Workers","headless-браузер","CDP_SECRET","openclaw.json","веб-разработка","инструменты разработки","ИИ Агенты"],"ar":["Cloudflare Browser","OpenClaw","Chrome DevTools Protocol","Workers","متصفح خفي","CDP_SECRET","openclaw.json","تطوير الويب","أدوات التطوير","وكلاء الذكاء الاصطناعي"]}},"owner":"cloudflare","repo":"moltworker","repoPath":"cloudflare/moltworker","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.274Z","topics":[],"category":"community","skillMd":{"name":"cloudflare-browser","description":"Control headless Chrome via Cloudflare Browser Rendering CDP WebSocket. Use for screenshots, page navigation, scraping, and video capture when browser automation is needed in a Cloudflare Workers environment. Requires CDP_SECRET env var and cdpUrl configured in browser.profiles.","bodyPreview":"# Cloudflare Browser Rendering\n\nControl headless browsers via Cloudflare''s Browser Rendering service using CDP (Chrome DevTools Protocol) over WebSocket.\n\n## Prerequisites\n\n- `CDP_SECRET` environment variable set\n- Browser profile configured in openclaw.json with `cdpUrl` pointing to the worker endpoint:\n  ```json\n  \"browser\": {\n    \"profiles\": {\n      \"cloudflare\": {\n        \"cdpUrl\": \"https://your-worker.workers.dev/cdp?secret=...\"\n      }\n    }\n  }\n  ```\n\n## Quick Start\n\n### Screenshot\n```bas","body":"# Cloudflare Browser Rendering\n\nControl headless browsers via Cloudflare''s Browser Rendering service using CDP (Chrome DevTools Protocol) over WebSocket.\n\n## Prerequisites\n\n- `CDP_SECRET` environment variable set\n- Browser profile configured in openclaw.json with `cdpUrl` pointing to the worker endpoint:\n  ```json\n  \"browser\": {\n    \"profiles\": {\n      \"cloudflare\": {\n        \"cdpUrl\": \"https://your-worker.workers.dev/cdp?secret=...\"\n      }\n    }\n  }\n  ```\n\n## Quick Start\n\n### Screenshot\n```bash\nnode /path/to/skills/cloudflare-browser/scripts/screenshot.js https://example.com output.png\n```\n\n### Multi-page Video\n```bash\nnode /path/to/skills/cloudflare-browser/scripts/video.js \"https://site1.com,https://site2.com\" output.mp4\n```\n\n## CDP Connection Pattern\n\nThe worker creates a page target automatically on WebSocket connect. Listen for Target.targetCreated event to get the targetId:\n\n```javascript\nconst WebSocket = require(''ws'');\nconst CDP_SECRET = process.env.CDP_SECRET;\nconst WS_URL = `wss://your-worker.workers.dev/cdp?secret=${encodeURIComponent(CDP_SECRET)}`;\n\nconst ws = new WebSocket(WS_URL);\nlet targetId = null;\n\nws.on(''message'', (data) => {\n  const msg = JSON.parse(data.toString());\n  if (msg.method === ''Target.targetCreated'' && msg.params?.targetInfo?.type === ''page'') {\n    targetId = msg.params.targetInfo.targetId;\n  }\n});\n```\n\n## Key CDP Commands\n\n| Command | Purpose |\n|---------|---------|\n| Page.navigate | Navigate to URL |\n| Page.captureScreenshot | Capture PNG/JPEG |\n| Runtime.evaluate | Execute JavaScript |\n| Emulation.setDeviceMetricsOverride | Set viewport size |\n\n## Common Patterns\n\n### Navigate and Screenshot\n```javascript\nawait send(''Page.navigate'', { url: ''https://example.com'' });\nawait new Promise(r => setTimeout(r, 3000)); // Wait for render\nconst { data } = await send(''Page.captureScreenshot'', { format: ''png'' });\nfs.writeFileSync(''out.png'', Buffer.from(data, ''base64''));\n```\n\n### Scroll Page\n```javascript\nawait send(''Runtime.evaluate'', { expression: ''window.scrollBy(0, 300)'' });\n```\n\n### Set Viewport\n```javascript\nawait send(''Emulation.setDeviceMetricsOverride'', {\n  width: 1280,\n  height: 720,\n  deviceScaleFactor: 1,\n  mobile: false\n});\n```\n\n## Creating Videos\n\n1. Capture frames as PNGs during navigation\n2. Use ffmpeg to stitch: `ffmpeg -framerate 10 -i frame_%04d.png -c:v libx264 -pix_fmt yuv420p output.mp4`\n\n## Troubleshooting\n\n- **No target created**: Race condition - wait for Target.targetCreated event with timeout\n- **Commands timeout**: Worker may have cold start delay; increase timeout to 30-60s\n- **WebSocket hangs**: Verify CDP_SECRET matches worker configuration\n"},"lastSynced":"2026-03-08T02:00:31.941Z","agentAnalysis":{"suitability":{"en":"Ideal for Automation Agents requiring seamless headless browser control via Cloudflare Workers and Chrome DevTools Protocol (CDP) over WebSocket.","zh":"适用于需要通过Cloudflare Workers和Chrome DevTools Protocol (CDP)实现无缝headless浏览器控制的自动化代理。","ja":"Cloudflare WorkersおよびChrome DevTools Protocol (CDP)を介してシームレスなヘッドレスブラウザ制御を必要とする自動化エージェントに最適です。","ko":"Cloudflare Workers 및 Chrome DevTools Protocol (CDP)를 통해 무결점 헤드리스 브라우저 제어가 필요한 자동화 에이전트에 적합합니다.","es":"Ideal para Agentes de Automatización que requieren un control de navegador headless sin problemas a través de Cloudflare Workers y Chrome DevTools Protocol (CDP) sobre WebSocket.","fr":"Idéal pour les agents d''automatisation nécessitant un contrôle de navigateur headless sans interruption via Cloudflare Workers et Chrome DevTools Protocol (CDP) sur WebSocket.","de":"Ideal für Automatisierungsagenten, die eine nahtlose headless-Browser-Steuerung über Cloudflare Workers und Chrome DevTools Protocol (CDP) über WebSocket erfordern.","pt":"Ideal para Agentes de Automação que requerem controle de navegador headless sem interrupções via Cloudflare Workers e Chrome DevTools Protocol (CDP) sobre WebSocket.","ru":"Идеально подходит для агентов автоматизации, требующих бесшовного управления безголовым браузером через Cloudflare Workers и Chrome DevTools Protocol (CDP) по WebSocket.","ar":"مثالي لعميل التلقين الذي يتطلب التحكم في متصفح رأس بدون انقطاع عبر Cloudflare Workers و Chrome DevTools Protocol (CDP) عبر WebSocket."},"recommendation":{"en":"Empowers agents to streamline browser rendering and automation tasks using Cloudflare''s Browser Rendering service, leveraging CDP for advanced browser control and WebSocket for efficient communication.","zh":"赋予代理流程浏览器渲染和自动化任务的能力，利用Cloudflare的浏览器渲染服务，通过CDP实现高级浏览器控制，通过WebSocket实现高效通信。","ja":"Cloudflareのブラウザレンダリングサービスを利用し、CDPを介して高度なブラウザ制御を行い、WebSocketを介して効率的な通信を行うことで、エージェントがブラウザレンダリングおよび自動化タスクを스트リーミングすることを可能にします。","ko":"Cloudflare의 브라우저 렌더링 서비스를 활용하여 CDP를 통해 고급 브라우저 제어와 WebSocket을 통해 효율적인 통신을 수행함으로써 에이전트가 브라우저 렌더링 및 자동화 작업을 최적화할 수 있도록 합니다.","es":"Permite a los agentes simplificar las tareas de renderizado y automatización del navegador utilizando el servicio de renderizado de navegador de Cloudflare, aprovechando CDP para un control de navegador avanzado y WebSocket para una comunicación eficiente.","fr":"Permet aux agents de simplifier les tâches de rendu et d''automatisation du navigateur en utilisant le service de rendu de navigateur Cloudflare, en exploitant CDP pour un contrôle avancé du navigateur et WebSocket pour une communication efficace.","de":"Ermächtigt Agenten, Browser-Rendering- und Automatisierungsaufgaben mithilfe des Cloudflare-Browser-Rendering-Dienstes zu rationalisieren, der CDP für erweiterte Browsersteuerung und WebSocket für effiziente Kommunikation nutzt.","pt":"Habilita os agentes a simplificar as tarefas de renderização e automação do navegador usando o serviço de Renderização de Navegador da Cloudflare, aproveitando o CDP para controle avançado do navegador e WebSocket para comunicação eficiente.","ru":"Наделяет агентов возможностью оптимизировать задачи рендеринга и автоматизации браузера с помощью сервиса рендеринга браузера от Cloudflare, используя CDP для расширенного управления браузером и WebSocket для эффективного обмена данными.","ar":"يمكن للوكلاء تبسيط مهام العرض والتلقين للمتصفح باستخدام خدمة عرض المتصفح من Cloudflare، وتحقيق البروتوكول CDP للتحكم المتقدم في المتصفح و WebSocket للاتصال الفعال."},"useCases":{"en":["Automating browser interactions for web scraping and data extraction","Rendering web pages for screenshot generation and visual testing","Debugging web applications using Chrome DevTools Protocol over WebSocket"],"zh":["用于网页抓取和数据提取的浏览器交互自动化","用于截图生成和可视化测试的网页渲染","使用Chrome DevTools Protocol通过WebSocket进行网页应用调试"],"ja":["Webスクレイピングおよびデータ抽出のためのブラウザ操作の自動化","スクリーンショット生成および視覚テストのためのWebページのレンダリング","Chrome DevTools Protocolを介してWebSocket上でWebアプリケーションのデバッグを行う"],"ko":["웹 스크레이핑 및 데이터 추출을 위한 브라우저 상호작용 자동화","스크린샷 생성 및 시각적 테스트를 위한 웹 페이지 렌더링","Chrome DevTools Protocol을 통해 WebSocket에서 웹 애플리케이션 디버깅"],"es":["Automatizar interacciones del navegador para web scraping y extracción de datos","Renderizar páginas web para la generación de capturas de pantalla y pruebas visuales","Depurar aplicaciones web utilizando Chrome DevTools Protocol sobre WebSocket"],"fr":["Automatiser les interactions du navigateur pour le scraping web et l''extraction de données","Rendre les pages web pour la génération d''captures d''écran et les tests visuels","Déboguer les applications web en utilisant Chrome DevTools Protocol sur WebSocket"],"de":["Automatisieren von Browser-Interaktionen für Web-Scraping und Datenextraktion","Rendern von Webseiten für die Erzeugung von Screenshots und visuellen Tests","Debuggen von Webanwendungen unter Verwendung von Chrome DevTools Protocol über WebSocket"],"pt":["Automatizar interações do navegador para extração de dados da web e scraping","Renderizar páginas da web para geração de capturas de tela e testes visuais","Depurar aplicações da web usando Chrome DevTools Protocol sobre WebSocket"],"ru":["Автоматизировать взаимодействия браузера для веб-скрейпинга и извлечения данных","Отображать веб-страницы для генерации скриншотов и визуального тестирования","Отлаживать веб-приложения, используя Chrome DevTools Protocol по WebSocket"],"ar":["التلقين التلقائي للتفاعلات المتصفح للخلاصات والاستخراج البيانات من الويب","عرض صفحات الويب لتوليد لقطة شاشة واختبارات بصرية","تصحيح الأخطاء في تطبيقات الويب باستخدام بروتوكول Chrome DevTools عبر WebSocket"]},"limitations":{"en":["Requires CDP_SECRET environment variable set","Needs browser profile configured in openclaw.json with cdpUrl pointing to the worker endpoint","Dependent on Cloudflare Workers and Chrome DevTools Protocol compatibility"],"zh":["需要设置CDP_SECRET环境变量","需要在openclaw.json中配置浏览器配置文件，且cdpUrl指向工作端点","依赖于Cloudflare Workers和Chrome DevTools Protocol的兼容性"],"ja":["CDP_SECRET環境変数を設定する必要がある","openclaw.jsonにブラウザプロファイルを構成し、cdpUrlがワーカーエンドポイントを指す","Cloudflare WorkersおよびChrome DevTools Protocolの互換性に依存する"],"ko":["CDP_SECRET 환경 변수를 설정해야 함","openclaw.json에 브라우저 프로필을 구성하고 cdpUrl이 작업자 엔드포인트를 가리키도록 해야 함","Cloudflare Workers 및 Chrome DevTools Protocol의 호환성에 의존"],"es":["Requiere la variable de entorno CDP_SECRET configurada","Necesita un perfil de navegador configurado en openclaw.json con cdpUrl que apunta al punto de conexión del trabajador","Depende de la compatibilidad de Cloudflare Workers y Chrome DevTools Protocol"],"fr":["Nécessite la variable d''environnement CDP_SECRET configurée","Nécessite un profil de navigateur configuré dans openclaw.json avec cdpUrl pointant vers le point de terminaison du worker","Dépend de la compatibilité de Cloudflare Workers et Chrome DevTools Protocol"],"de":["Benötigt die Umgebungsvariable CDP_SECRET, die konfiguriert ist","Benötigt ein Browser-Profil, das in openclaw.json mit cdpUrl konfiguriert ist, der auf den Worker-Endpunkt verweist","Hängt von der Kompatibilität von Cloudflare Workers und Chrome DevTools Protocol ab"],"pt":["Requer a variável de ambiente CDP_SECRET definida","Necessita de perfil de navegador configurado em openclaw.json com cdpUrl apontando para o endpoint do trabalhador","Dependente da compatibilidade de Cloudflare Workers e Chrome DevTools Protocol"],"ru":["Требует настройки переменной среды CDP_SECRET","Требует настройки профиля браузера в openclaw.json с cdpUrl, указывающим на конечную точку работника","Зависит от совместимости Cloudflare Workers и Chrome DevTools Protocol"],"ar":["يتطلب تعريف متغير بيئة CDP_SECRET","يحتاج إلى تكوين ملف تعريف المتصفح في openclaw.json مع cdpUrl الذي يشير إلى نقطة النهاية للعامل","يعتمد على توافق Cloudflare Workers وبروتوكول Chrome DevTools"]},"version":4},"contentHash":"06f8f67410955ff10065b70d306e1c996a3cd12e429346099d495dfacec1f483","qualityScore":39}');
