INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('elbwalker/walkerOS/walkeros-understanding-flow', 'walkeros-understanding-flow', 'elbwalker', 'walkerOS', 'community', 'walkeros-understanding-flow elbwalker walkerOS community walkeros-understanding-flow is an open-source tag manager for developers, enabling modular event processing via a Source → Collector → Destination(s) architecture. It benefits developers seeking composable and replaceable components walkerOS Flow 是一个开源的标签管理器，采用 Source → Collector → Destination(s) 的架构实现可组合的事件处理 walkerOS Flow は、Source → Collector → Destination(s) のアーキテクチャを採用したオープンソースのタグマネージャーであり、組み合わせ可能なイベント処理を実現します walkerOS Flow 는 Source → Collector → Destination(s) 의 아키텍처를採用한 개발자를 위한 오픈소스 태그 관리자로, 조합 가능한 이벤트 처리를 구현합니다 walkerOS Flow es un gestor de etiquetas de código abierto que sigue una arquitectura de procesamiento de eventos modular y componible walkerOS Flow est un gestionnaire de balises open-source qui suit une architecture de traitement d''événements modulaire et composable walkerOS Flow ist ein Open-Source-Tag-Manager, der eine modulare und komponierbare Ereignisverarbeitungsarchitektur verwendet O walkerOS Flow é um gerenciador de tags de código aberto que segue uma arquitetura modular, permitindo a separação de preocupações e a composição de componentes walkerOS Flow - это открытый тег-менеджер, который следует модульной архитектуре, обеспечивающей разделение проблем и композицию компонентов walkerOS Flow هو مدير تعريف مفتوح المصدر يتبع هندسة معمارية قابلة للتعديل، مما يسمح بفصل الاهتمامات وتركيب المكونات how to use walkeros-understanding-flow walkeros-understanding-flow alternative walkeros-understanding-flow setup guide what is walkeros-understanding-flow walkeros-understanding-flow vs tag managers walkeros-understanding-flow install modular event processing with walkeros-understanding-flow walkeros-understanding-flow documentation walkeros-understanding-flow use cases walkerOS Flow 开源标签管理 事件处理 模块化开发 Source → Collector → Destination(s) Pre-Transformers Post-Transformers Separation of concerns Implements Source → Collector → Destination(s) architecture for composable event processing Supports Pre-Transformers and Post-Transformers for data validation and processing Enables replaceable and composable components for modular event handling Follows a core principle of Separation of concerns for each component Allows for capture and delivery of events via Destinations walkeros-understanding-flow is an open-source tag manager that follows a Source → Collector → Destination(s) architecture for composable event processing');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mrexodia/ida-pro-mcp/idapython', 'community', 'mrexodia', 'ida-pro-mcp', 'mrexodia/ida-pro-mcp', 'idapython', 0, 0, 39, '2026-03-08T01:57:15.282Z', '2026-03-08T02:00:52.547Z', '421e209611d04299458034e03d9ff214d443f5bfef0403f3ffbebf35c79c61b1', '{"id":"mrexodia/ida-pro-mcp/idapython","name":"idapython","description":{"en":"idapython is an AI-powered reverse engineering assistant that integrates IDA Pro with language models via MCP, benefiting developers and security researchers. It provides a modern interface using ida_* modules.","zh":"IDAPython是AI驱动的逆向工程助手，通过MCP将IDA Pro与语言模型连接起来。它提供了现代ida_*模块，包括ida_bytes、ida_funcs、ida_name、ida_typeinf和ida_hexrays等","ja":"IDAPythonは、MCPを介してIDA Proと言語モデルを接続するAI駆動の逆向工学アシスタントです。最新のida_*モジュールを提供し、ida_bytes、ida_funcs、ida_name、ida_typeinf、ida_hexraysなどをサポートします","ko":"IDAPython은 MCP를 통해 IDA Pro와 언어 모델을 연결하는 AI 파워드 리버스 엔지니어링 어시스턴트입니다. 최신 ida_* 모듈을 제공하며, ida_bytes, ida_funcs, ida_name, ida_typeinf, ida_hexrays 등을 지원합니다","es":"Idapython es un asistente de ingeniería inversa basado en IA que conecta IDA Pro con modelos de lenguaje a través de MCP, mejorando la análisis de código","fr":"Idapython est un assistant de reverse engineering basé sur l''IA qui relie IDA Pro aux modèles de langage via MCP pour améliorer l''analyse de code","de":"Idapython ist ein KI-basiertes Reverse-Engineering-Tool, das IDA Pro mit Sprachmodellen über MCP verbindet, um die Codeanalyse zu verbessern","pt":"O IDAPython é uma ferramenta de engenharia reversa que combina IDA Pro com modelos de linguagem para análise avançada de bytes e funções","ru":"IDAPython - это инструмент обратной инженерии, который объединяет IDA Pro с языковыми моделями для advanced анализа байтов и функций","ar":"IDAPython هو أداة هندسة معكوسة تجمع بين IDA Pro و نماذج اللغة لتحليل متقدم للبايتات و الدوال"},"seo":{"title":{"en":"idapython: AI-Powered Reverse Engineering Setup Guide | A...","zh":"IDAPython 集成指南：AI驱动的逆向工程助手","ja":"IDAPython Setup Guide: AIエージェントによる逆向工学アシスタント","ko":"IDAPython 설정 가이드: AI 파워드 리버스 엔지니어링 어시스턴트","es":"Guía de configuración de idapython para ingenieros de seg...","fr":"Configurer idapython pour le reverse engineering avec les...","de":"Idapython-Setup-Anleitung für Reverse-Engineering mit KI-...","pt":"Guia de Configuração do IDAPython: Ferramenta de Engenhar...","ru":"Настройка IDAPython: ИИ Агент для Обратной Инженерии","ar":"دليل إعداد IDAPython: أداة هندسة معكوسة مدعومة بالذكاء ال..."},"description":{"en":"Unlock the full potential of IDA Pro with idapython. Learn how to bridge language models through MCP and streamline your reverse engineering workflow today!","zh":"了解IDAPython如何通过MCP将IDA Pro与语言模型连接起来，实现高效的逆向工程","ja":"IDAPythonを使用してIDA Proと言語モデルをMCP経由で接続し、効率的な逆向工学を実現する","ko":"MCP를 통해 IDA Pro와 언어 모델을 연결하여 효율적인 리버스 엔지니어링을实现하는 IDAPython에 대해 알아보세요","es":"Aprende a utilizar idapython para mejorar tus habilidades de reverse engineering con la integración de IDA Pro y modelos de lenguaje","fr":"Découvrez comment idapython facilite le reverse engineering en reliant IDA Pro aux modèles de langage pour une analyse plus approfondie","de":"Entdecken Sie, wie idapython das Reverse-Engineering durch die Integration von IDA Pro und KI-Modellen verbessert","pt":"Aprenda a utilizar o IDAPython, uma ferramenta de engenharia reversa que combina IDA Pro com modelos de linguagem através do MCP","ru":"Узнайте, как использовать IDAPython, инструмент обратной инженерии, который объединяет IDA Pro с языковыми моделями через MCP","ar":"تعرف على كيفية استخدام IDAPython، أداة هندسة معكوسة تجمع بين IDA Pro و نماذج اللغة من خلال MCP"},"definition":{"en":"idapython is an AI-powered reverse engineering assistant that bridges IDA Pro with language models through MCP, enabling advanced code analysis and automation.","zh":"IDAPython是一种AI驱动的逆向工程助手，用于连接IDA Pro和语言模型","ja":"IDAPythonは、IDA Proと言語モデルを接続するAI駆動の逆向工学アシスタントです","ko":"IDAPython은 IDA Pro와 언어 모델을 연결하는 AI 파워드 리버스 엔지니어링 어시스턴트입니다","es":"Idapython es un asistente de ingeniería inversa que utiliza IA para mejorar la análisis de código","fr":"Idapython est un outil de reverse engineering qui utilise l''IA pour améliorer l''analyse de code","de":"Idapython ist ein Reverse-Engineering-Tool, das KI verwendet, um die Codeanalyse zu verbessern","pt":"O que é IDAPython? É uma ferramenta de engenharia reversa que utiliza modelos de linguagem para análise de código","ru":"Что такое IDAPython? Это инструмент обратной инженерии, который использует языковые модели для анализа кода","ar":"ما هو IDAPython؟ هو أداة هندسة معكوسة تستخدم نماذج اللغة لتحليل الكود"},"features":{"en":["Utilizes modern ida_* modules for improved functionality","Provides access to bytes and memory through ida_bytes module","Enables function management using ida_funcs module","Supports name management and demangling through ida_name module","Offers type information and parsing through ida_typeinf module","Integrates with ida_hexrays for decompilation capabilities"],"zh":["现代ida_*模块支持","ida_bytes模块用于字节和内存操作","ida_funcs模块用于函数操作","ida_name模块用于名称管理","ida_typeinf模块用于类型信息管理","ida_hexrays模块用于反编译"],"ja":["最新のida_*モジュールをサポート","ida_bytesモジュールを使用したバイトとメモリ操作","ida_funcsモジュールを使用した関数操作","ida_nameモジュールを使用した名前管理","ida_typeinfモジュールを使用した型情報管理","ida_hexraysモジュールを使用したデコンパイル"],"ko":["최신 ida_* 모듈 지원","ida_bytes 모듈을 사용한 바이트와 메모리操作","ida_funcs 모듈을 사용한 함수操作","ida_name 모듈을 사용한 이름 관리","ida_typeinf 모듈을 사용한 타입 정보 관리","ida_hexrays 모듈을 사용한 디컴파일"],"es":["Integración con IDA Pro para análisis de código avanzado","Uso de módulos ida_* para funciones de bytes y memoria","Soporte para funciones y nombres a través de ida_funcs y ida_name","Análisis de tipos con ida_typeinf","Descompilación con ida_hexrays"],"fr":["Intégration avec IDA Pro pour une analyse de code avancée","Utilisation des modules ida_* pour les fonctions de bytes et de mémoire","Prise en charge des fonctions et des noms via ida_funcs et ida_name","Analyse de types avec ida_typeinf","Décompilation avec ida_hexrays"],"de":["Integration mit IDA Pro für erweiterte Codeanalyse","Verwendung der ida_*-Module für Byte- und Speicherfunktionen","Unterstützung für Funktionen und Namen über ida_funcs und ida_name","Typenanalyse mit ida_typeinf","Entschlüsselung mit ida_hexrays"],"pt":["Utiliza módulos modernos `ida_*` para análise de bytes e funções","Suporta a criação de funções e obtenção de nomes de funções","Permite a aplicação de informações de tipo e análise de declarações","Inclui recursos de descompilação avançados com `ida_hexrays`","Oferece funcionalidades de manipulação de bytes e memória com `ida_bytes`","Suporta a definição e obtenção de nomes com `ida_name`"],"ru":["Использует современные модули `ida_*` для анализа байтов и функций","Поддерживает создание функций и получение имён функций","Позволяет применять информацию о типах и анализировать декларации","Включает в себя advanced возможности декомпиляции с `ida_hexrays`","Предоставляет функциональность манипуляции байтами и памятью с `ida_bytes`","Поддерживает определение и получение имён с `ida_name`"],"ar":["يستخدم وحدات حديثة `ida_*` لتحليل البايتات و الدوال","يدعم إنشاء الدوال و الحصول على أسماء الدوال","يسمح بتطبيق معلومات النوع و تحليل الإعلانات","يشتمل على إمكانيات فك التشفير المتقدمة مع `ida_hexrays`","يقدم إمكانيات التعامل مع البايتات و الذاكرة مع `ida_bytes`","يدعم تعريف و الحصول على الأسماء مع `ida_name`"]},"keywords":{"en":["how to use idapython","idapython setup guide","idapython alternative","idapython vs ghidra","idapython install","what is idapython","idapython tutorial","idapython reverse engineering","idapython MCP integration"],"zh":["IDAPython","IDA Pro","语言模型","MCP","逆向工程","AI驱动","ida_bytes","ida_funcs","ida_name","ida_typeinf","ida_hexrays"],"ja":["IDAPython","IDA Pro","言語モデル","MCP","逆向工学","AI駆動","ida_bytes","ida_funcs","ida_name","ida_typeinf","ida_hexrays","AIエージェント"],"ko":["IDAPython","IDA Pro","언어 모델","MCP","리버스 엔지니어링","AI 파워드","ida_bytes","ida_funcs","ida_name","ida_typeinf","ida_hexrays","AI 어시스턴트"],"es":["idapython","ingeniería inversa","IDA Pro","modelos de lenguaje","análisis de código","seguridad informática","herramientas de seguridad","desarrollo de software","ingenieros de seguridad"],"fr":["idapython","reverse engineering","IDA Pro","modèles de langage","analyse de code","sécurité informatique","outils de sécurité","développement de logiciels","ingénieurs de sécurité"],"de":["idapython","Reverse-Engineering","IDA Pro","Sprachmodelle","Codeanalyse","IT-Sicherheit","Sicherheitswerkzeuge","Softwareentwicklung","Sicherheitsingenieure"],"pt":["IDAPython","engenharia reversa","análise de bytes","análise de funções","modelos de linguagem","IDA Pro","MCP","descompilação","tipos de dados","manipulação de memória"],"ru":["IDAPython","обратная инженерия","анализ байтов","анализ функций","языковые модели","IDA Pro","MCP","декомпиляция","типы данных","манипуляция памятью"],"ar":["IDAPython","هندسة معكوسة","تحليل البايتات","تحليل الدوال","نماذج اللغة","IDA Pro","MCP","فك التشفير","أنواع البيانات","التعامل مع الذاكرة"]}},"owner":"mrexodia","repo":"ida-pro-mcp","repoPath":"mrexodia/ida-pro-mcp","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.282Z","topics":[],"category":"community","skillMd":{"name":"idapython","description":"IDA Pro Python scripting for reverse engineering. Use when writing IDAPython scripts, analyzing binaries, working with IDAs API for disassembly, decompilation (Hex-Rays), type systems, cross-references, functions, segments, or any IDA database manipulation. Covers ida_* modules (50+), idautils iterators, and common patterns.","bodyPreview":"# IDAPython\n\nUse modern `ida_*` modules. Avoid legacy `idc` module.\n\n## Module Router\n\n| Task | Module | Key Items |\n|------|--------|-----------|\n| Bytes/memory | `ida_bytes` | `get_bytes`, `patch_bytes`, `get_flags`, `create_*` |\n| Functions | `ida_funcs` | `func_t`, `get_func`, `add_func`, `get_func_name` |\n| Names | `ida_name` | `set_name`, `get_name`, `demangle_name` |\n| Types | `ida_typeinf` | `tinfo_t`, `apply_tinfo`, `parse_decl` |\n| Decompiler | `ida_hexrays` | `decompile`, `cfunc_t`, `","body":"# IDAPython\n\nUse modern `ida_*` modules. Avoid legacy `idc` module.\n\n## Module Router\n\n| Task | Module | Key Items |\n|------|--------|-----------|\n| Bytes/memory | `ida_bytes` | `get_bytes`, `patch_bytes`, `get_flags`, `create_*` |\n| Functions | `ida_funcs` | `func_t`, `get_func`, `add_func`, `get_func_name` |\n| Names | `ida_name` | `set_name`, `get_name`, `demangle_name` |\n| Types | `ida_typeinf` | `tinfo_t`, `apply_tinfo`, `parse_decl` |\n| Decompiler | `ida_hexrays` | `decompile`, `cfunc_t`, `lvar_t`, ctree visitor |\n| Segments | `ida_segment` | `segment_t`, `getseg`, `add_segm` |\n| Xrefs | `ida_xref` | `xrefblk_t`, `add_cref`, `add_dref` |\n| Instructions | `ida_ua` | `insn_t`, `op_t`, `decode_insn` |\n| Stack frames | `ida_frame` | `get_frame`, `define_stkvar` |\n| Iteration | `idautils` | `Functions()`, `Heads()`, `XrefsTo()`, `Strings()` |\n| UI/dialogs | `ida_kernwin` | `msg`, `ask_*`, `jumpto`, `Choose` |\n| Database info | `ida_ida` | `inf_get_*`, `inf_is_64bit()` |\n| Analysis | `ida_auto` | `auto_wait`, `plan_and_wait` |\n| Flow graphs | `ida_gdl` | `FlowChart`, `BasicBlock` |\n| Register tracking | `ida_regfinder` | `find_reg_value`, `reg_value_info_t` |\n\n## Core Patterns\n\n### Iterate functions\n```python\nfor ea in idautils.Functions():\n    name = ida_funcs.get_func_name(ea)\n    func = ida_funcs.get_func(ea)\n```\n\n### Iterate instructions in function\n```python\nfor head in idautils.FuncItems(func_ea):\n    insn = ida_ua.insn_t()\n    if ida_ua.decode_insn(insn, head):\n        print(f\"{head:#x}: {insn.itype}\")\n```\n\n### Cross-references\n```python\nfor xref in idautils.XrefsTo(ea):\n    print(f\"{xref.frm:#x} -> {xref.to:#x} type={xref.type}\")\n```\n\n### Read/write bytes\n```python\ndata = ida_bytes.get_bytes(ea, size)\nida_bytes.patch_bytes(ea, b\"\\x90\\x90\")\n```\n\n### Names\n```python\nname = ida_name.get_name(ea)\nida_name.set_name(ea, \"new_name\", ida_name.SN_NOCHECK)\n```\n\n### Decompile function\n```python\ncfunc = ida_hexrays.decompile(ea)\nif cfunc:\n    print(cfunc)  # pseudocode\n    for lvar in cfunc.lvars:\n        print(f\"{lvar.name}: {lvar.type()}\")\n```\n\n### Walk ctree (decompiled AST)\n```python\nclass MyVisitor(ida_hexrays.ctree_visitor_t):\n    def visit_expr(self, e):\n        if e.op == ida_hexrays.cot_call:\n            print(f\"Call at {e.ea:#x}\")\n        return 0\n\ncfunc = ida_hexrays.decompile(ea)\nMyVisitor().apply_to(cfunc.body, None)\n```\n\n### Apply type\n```python\ntif = ida_typeinf.tinfo_t()\nif ida_typeinf.parse_decl(tif, None, \"int (*)(char *, int)\", 0):\n    ida_typeinf.apply_tinfo(ea, tif, ida_typeinf.TINFO_DEFINITE)\n```\n\n### Create structure\n```python\nudt = ida_typeinf.udt_type_data_t()\nm = ida_typeinf.udm_t()\nm.name = \"field1\"\nm.type = ida_typeinf.tinfo_t(ida_typeinf.BTF_INT32)\nm.offset = 0\nm.size = 4\nudt.push_back(m)\ntif = ida_typeinf.tinfo_t()\ntif.create_udt(udt, ida_typeinf.BTF_STRUCT)\ntif.set_named_type(ida_typeinf.get_idati(), \"MyStruct\")\n```\n\n### Strings list\n```python\nfor s in idautils.Strings():\n    print(f\"{s.ea:#x}: {str(s)}\")\n```\n\n### Wait for analysis\n```python\nida_auto.auto_wait()  # Block until autoanalysis completes\n```\n\n## Key Constants\n\n| Constant | Value/Use |\n|----------|-----------|\n| `BADADDR` | Invalid address sentinel |\n| `ida_name.SN_NOCHECK` | Skip name validation |\n| `ida_typeinf.TINFO_DEFINITE` | Force type application |\n| `o_reg`, `o_mem`, `o_imm`, `o_displ`, `o_near` | Operand types |\n| `dt_byte`, `dt_word`, `dt_dword`, `dt_qword` | Data types |\n| `fl_CF`, `fl_CN`, `fl_JF`, `fl_JN`, `fl_F` | Code xref types |\n| `dr_R`, `dr_W`, `dr_O` | Data xref types |\n\n## Critical Rules\n\n1. **NEVER convert hex/decimal manually** — use `int_convert` MCP tool\n2. **Wait for analysis**: Call `ida_auto.auto_wait()` before reading results\n3. **Thread safety**: IDA SDK calls must run on main thread (use `@idasync`)\n4. **64-bit addresses**: Always assume `ea_t` can be 64-bit\n\n## Anti-Patterns\n\n| Avoid | Do Instead |\n|-------|------------|\n| `idc.*` functions | Use `ida_*` modules |\n| Hardcoded addresses | Use names, patterns, or xrefs |\n| Manual hex conversion | Use `int_convert` tool |\n| Blocking main thread | Use `execute_sync()` for long ops |\n| Guessing at types | Derive from disassembly/decompilation |\n\n## Detailed API Reference\n\nFor comprehensive documentation on any module, read `docs/<module>.md`:\n- **High-use**: `ida_bytes`, `ida_funcs`, `ida_hexrays`, `ida_typeinf`, `ida_name`, `idautils`\n- **Medium-use**: `ida_segment`, `ida_xref`, `ida_ua`, `ida_frame`, `ida_kernwin`\n- **Specialized**: `ida_dbg` (debugger), `ida_nalt` (netnode storage), `ida_regfinder` (register tracking)\n\nFull RST sources from hex-rays.com available at `docs/<module>.rst`.\n"},"lastSynced":"2026-03-08T02:00:52.547Z","agentAnalysis":{"suitability":{"en":"Perfect for Reverse Engineering Agents needing advanced IDA Pro integration and Python scripting capabilities.","zh":"非常适合需要高级IDA Pro集成和Python脚本编写能力的逆向工程代理。","ja":"IDA Proの高度な統合とPythonスクリプトの作成能力が必要な逆向きエンジニアリングエージェントに最適です。","ko":"고급 IDA Pro 통합 및 Python 스크립팅 기능이 필요한 역공학 에이전트에 적합합니다.","es":"Perfecto para agentes de ingeniería inversa que necesitan una integración avanzada de IDA Pro y capacidades de scripting en Python.","fr":"Parfait pour les agents d''ingénierie inverse nécessitant une intégration avancée d''IDA Pro et des capacités de scripting Python.","de":"Perfekt für Reverse-Engineering-Agents, die eine erweiterte IDA-Pro-Integration und Python-Scripting-Fähigkeiten benötigen.","pt":"Perfeito para Agentes de Engenharia Reversa que necessitam de integração avançada do IDA Pro e capacidades de script em Python.","ru":"Идеально подходит для агентов обратного инжиниринга, которым необходима расширенная интеграция с IDA Pro и возможности скриптинга на Python.","ar":"مثالي للوكلاء الهندسيين العكسيين الذين يحتاجون إلى 통합 متقدم من IDA Pro وقدرات البرمجة النصية بال파이썬."},"recommendation":{"en":"Empowers agents to leverage ida_* modules for tasks like bytes and memory manipulation via ida_bytes, function analysis with ida_funcs, and decompilation using ida_hexrays, enhancing their reverse engineering superpower with modern interfaces and language model integration via MCP.","zh":"赋予代理使用ida_*模块的能力，用于任务如通过ida_bytes进行字节和内存操作，通过ida_funcs进行函数分析，使用ida_hexrays进行反编译，并通过MCP增强其逆向工程超能力，整合现代接口和语言模型。","ja":"エージェントにida_*モジュールを使用する能力を与え、ida_bytesを使用したバイトとメモリ操作、ida_funcsを使用した関数分析、ida_hexraysを使用したデコンパイルなどを実行し、MCPを介してmodernなインターフェースと言語モデルを統合して、逆向きエンジニアリングの超能力を強化します。","ko":"에이전트가 ida_* 모듈을 사용할 수 있는 능력을 부여하여 ida_bytes를 사용한 바이트 및 메모리 조작, ida_funcs를 사용한 함수 분석, ida_hexrays를 사용한 디컴파일 등과 같은 작업을 수행하고, MCP를 통해 현대적인 인터페이스 및 언어 모델을 통합하여 역공학의超 능력을 강화합니다.","es":"Habilita a los agentes a aprovechar los módulos ida_* para tareas como la manipulación de bytes y memoria mediante ida_bytes, el análisis de funciones con ida_funcs y la descompilación mediante ida_hexrays, mejorando su superpoder de ingeniería inversa con interfaces modernas y la integración de modelos de lenguaje a través de MCP.","fr":"Permet aux agents d''utiliser les modules ida_* pour des tâches comme la manipulation d''octets et de mémoire via ida_bytes, l''analyse de fonctions avec ida_funcs et la désassemblage en utilisant ida_hexrays, améliorant leur superpuissance d''ingénierie inverse avec des interfaces modernes et l''intégration de modèles de langage via MCP.","de":"Ermächtigt die Agenten, die ida_*-Module für Aufgaben wie die Manipulation von Bytes und Speicher über ida_bytes, die Funktionsanalyse mit ida_funcs und die Dekompilierung mit ida_hexrays zu nutzen, und verbessert ihre Reverse-Engineering-Superkraft mit modernen Schnittstellen und der Integration von Sprachmodellen über MCP.","pt":"Habilita os agentes a utilizar módulos ida_* para tarefas como manipulação de bytes e memória via ida_bytes, análise de funções com ida_funcs e descompilação usando ida_hexrays, melhorando seu superpoder de engenharia reversa com interfaces modernas e integração de modelo de linguagem via MCP.","ru":"Позволяет агентам использовать модули ida_* для задач, таких как манипуляция байтами и памятью через ida_bytes, анализ функций с ida_funcs и декомпиляция с помощью ida_hexrays, повышая их суперспособность обратного инжиниринга с современными интерфейсами и интеграцией языковой модели через MCP.","ar":"يمكن الوكلاء من استخدام الوحدات ida_* لأداء مهام مثل مаниبуля션 البايتات والذاكرة عبر ida_bytes، وتحليل الدوال باستخدام ida_funcs، وفك التشفير باستخدام ida_hexrays، مما يعزز قوتهم الخارقة للهندسة العكسية مع الواجهات الحديثة وتكامل نموذج اللغة عبر MCP."},"useCases":{"en":["Decompiling binaries with ida_hexrays","Analyzing functions using ida_funcs","Manipulating bytes and memory with ida_bytes","Applying type information with ida_typeinf"],"zh":["使用ida_hexrays进行二进制反编译","使用ida_funcs进行函数分析","使用ida_bytes进行字节和内存操作","使用ida_typeinf应用类型信息"],"ja":["ida_hexraysを使用したバイナリのデコンパイル","ida_funcsを使用した関数分析","ida_bytesを使用したバイトとメモリ操作","ida_typeinfを使用したタイプ情報の適用"],"ko":["ida_hexrays를 사용한 바이너리 디컴파일","ida_funcs를 사용한 함수 분석","ida_bytes를 사용한 바이트 및 메모리 조작","ida_typeinf를 사용한 유형 정보 적용"],"es":["Descompilar binarios con ida_hexrays","Analizar funciones utilizando ida_funcs","Manipular bytes y memoria con ida_bytes","Aplicar información de tipo con ida_typeinf"],"fr":["Désassembler des binaires avec ida_hexrays","Analyser des fonctions en utilisant ida_funcs","Manipuler des octets et de la mémoire avec ida_bytes","Appliquer des informations de type avec ida_typeinf"],"de":["Binärdateien mit ida_hexrays dekompilieren","Funktionen mit ida_funcs analysieren","Bytes und Speicher mit ida_bytes manipulieren","Typinformationen mit ida_typeinf anwenden"],"pt":["Descompilando binários com ida_hexrays","Analizando funções usando ida_funcs","Manipulando bytes e memória com ida_bytes","Aplicando informações de tipo com ida_typeinf"],"ru":["Декомпиляция бинарных файлов с помощью ida_hexrays","Анализ функций с помощью ida_funcs","Манипуляция байтами и памятью с помощью ida_bytes","Применение информации о типах с помощью ida_typeinf"],"ar":["فك تشفير الثنائيات باستخدام ida_hexrays","تحليل الدوال باستخدام ida_funcs","معالجة البايتات والذاكرة باستخدام ida_bytes","تطبيق معلومات النوع باستخدام ida_typeinf"]},"limitations":{"en":["Requires IDA Pro installation","Python knowledge necessary","Avoids legacy idc module"],"zh":["需要IDA Pro安装","需要Python知识","避免使用遗留的idc模块"],"ja":["IDA Proのインストールが必要","Pythonの知識が必要","レガシーのidcモジュールを避ける"],"ko":["IDA Pro 설치가 필요합니다.","Python 지식이 필요합니다.","레거시 idc 모듈을 피함"],"es":["Requiere la instalación de IDA Pro","Conocimientos de Python necesarios","Evita el módulo idc heredado"],"fr":["Nécessite l''installation d''IDA Pro","Connaissances en Python nécessaires","Évite le module idc hérité"],"de":["Erfordert die Installation von IDA Pro","Python-Kenntnisse erforderlich","Vermeidet das veraltete idc-Modul"],"pt":["Requer instalação do IDA Pro","Conhecimento de Python necessário","Evita o módulo idc legado"],"ru":["Требуется установка IDA Pro","Необходимо знание Python","Избегает устаревший модуль idc"],"ar":["يتطلب تثبيت IDA Pro","معلومات بال파이썬 ضرورية","يتجنب وحدة idc القديمة"]},"version":4},"contentHash":"421e209611d04299458034e03d9ff214d443f5bfef0403f3ffbebf35c79c61b1","qualityScore":39}');
DELETE FROM skills_fts WHERE id = 'mrexodia/ida-pro-mcp/idapython';
INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mrexodia/ida-pro-mcp/idapython', 'idapython', 'mrexodia', 'ida-pro-mcp', 'community', 'idapython mrexodia ida-pro-mcp community idapython is an AI-powered reverse engineering assistant that integrates IDA Pro with language models via MCP, benefiting developers and security researchers. It provides a modern interface using ida_* modules. IDAPython是AI驱动的逆向工程助手，通过MCP将IDA Pro与语言模型连接起来。它提供了现代ida_*模块，包括ida_bytes、ida_funcs、ida_name、ida_typeinf和ida_hexrays等 IDAPythonは、MCPを介してIDA Proと言語モデルを接続するAI駆動の逆向工学アシスタントです。最新のida_*モジュールを提供し、ida_bytes、ida_funcs、ida_name、ida_typeinf、ida_hexraysなどをサポートします IDAPython은 MCP를 통해 IDA Pro와 언어 모델을 연결하는 AI 파워드 리버스 엔지니어링 어시스턴트입니다. 최신 ida_* 모듈을 제공하며, ida_bytes, ida_funcs, ida_name, ida_typeinf, ida_hexrays 등을 지원합니다 Idapython es un asistente de ingeniería inversa basado en IA que conecta IDA Pro con modelos de lenguaje a través de MCP, mejorando la análisis de código Idapython est un assistant de reverse engineering basé sur l''IA qui relie IDA Pro aux modèles de langage via MCP pour améliorer l''analyse de code Idapython ist ein KI-basiertes Reverse-Engineering-Tool, das IDA Pro mit Sprachmodellen über MCP verbindet, um die Codeanalyse zu verbessern O IDAPython é uma ferramenta de engenharia reversa que combina IDA Pro com modelos de linguagem para análise avançada de bytes e funções IDAPython - это инструмент обратной инженерии, который объединяет IDA Pro с языковыми моделями для advanced анализа байтов и функций IDAPython هو أداة هندسة معكوسة تجمع بين IDA Pro و نماذج اللغة لتحليل متقدم للبايتات و الدوال how to use idapython idapython setup guide idapython alternative idapython vs ghidra idapython install what is idapython idapython tutorial idapython reverse engineering idapython MCP integration IDAPython IDA Pro 语言模型 MCP 逆向工程 AI驱动 ida_bytes ida_funcs ida_name ida_typeinf ida_hexrays Utilizes modern ida_* modules for improved functionality Provides access to bytes and memory through ida_bytes module Enables function management using ida_funcs module Supports name management and demangling through ida_name module Offers type information and parsing through ida_typeinf module Integrates with ida_hexrays for decompilation capabilities idapython is an AI-powered reverse engineering assistant that bridges IDA Pro with language models through MCP, enabling advanced code analysis and automation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Yeachan-Heo/oh-my-claudecode/ultrawork', 'community', 'Yeachan-Heo', 'oh-my-claudecode', 'Yeachan-Heo/oh-my-claudecode', 'ultrawork', 0, 0, 39, '2026-03-08T01:57:15.282Z', '2026-03-08T02:00:52.746Z', 'a5ca384b8ae5e556296420adb712e41cc6ab2e49088960469d874b587634550e', '{"id":"Yeachan-Heo/oh-my-claudecode/ultrawork","name":"ultrawork","description":{"en":"Ultrawork is a teams-first multi-agent orchestration component for Claude Code, enabling parallel execution of independent tasks. It benefits developers who need to run multiple agents simultaneously.","zh":"Ultrawork 是一个并行执行引擎，允许同时运行多个独立任务，适用于 Claude Code 的多agent 管理","ja":"Ultrawork は、複数の独立したタスクを同時に実行する並列実行エンジンであり、AIエージェントのパフォーマンスを向上させる","ko":"Ultrawork 는 Claude Code의 다중 에이전트를 최적화하는 병렬 실행 엔진으로 독립적인 태스크를 동시에 실행","es":"Ultrawork es un motor de ejecución paralela que permite ejecutar múltiples agentes de forma simultánea para tareas independientes","fr":"Ultrawork est un moteur d''exécution parallèle qui permet d''exécuter plusieurs agents en simultané pour des tâches indépendantes","de":"Ultrawork ist ein paralleler Ausführungsmotor, der die Ausführung mehrerer Agents simultan für unabhängige Aufgaben ermöglicht","pt":"O Ultrawork é um mecanismo de execução paralela que executa vários agentes simultaneamente para tarefas independentes. Ele fornece paralelismo e roteamento de modelo inteligente.","ru":"Ultrawork - это механизм параллельного выполнения, который запускает несколько агентов одновременно для независимых задач. Он обеспечивает параллелизм и умное маршрутизация модели.","ar":"Ultrawork هو ميكانيكي تنفيذ موازي يقوم بتشغيل وحدات متعددة في نفس الوقت للمهام المستقلة. يوفر التمويل الموازي وتوجيه النموذج الذكي"},"seo":{"title":{"en":"Ultrawork: Parallel Execution Engine for AI Agents | AI A...","zh":"Ultrawork 并行执行引擎设置指南","ja":"Ultrawork の並列実行エンジンを使用した AIエージェントの最適化","ko":"Ultrawork 병렬 실행 엔진 구축 및 최적화","es":"Guía de configuración de Ultrawork para Agentes de IA","fr":"Guide de démarrage rapide d''Ultrawork pour Outils d''IA","de":"Ultrawork-Setup-Anleitung für KI-Agents","pt":"Guia de Configuração do Ultrawork: Orquestração de Agente...","ru":"Настройка Ultrawork: Мультй-Агентная Оркестрация для ИИ А...","ar":"دليل إعداد Ultrawork: تنسيق وحدات متعددة بشكل مواز"},"description":{"en":"Unlock simultaneous task execution with ultrawork. Learn how to delegate work to multiple agents at once and boost productivity with this parallel execution ...","zh":"了解 Ultrawork 的并行执行引擎，实现多个独立任务的同时运行，适用于 Claude Code 的多agent 管理","ja":"Ultrawork の並列実行エンジンを使用して、複数の独立したタスクを同時に実行し、AIエージェントのパフォーマンスを向上させる","ko":"Ultrawork 병렬 실행 엔진을 사용하여 Claude Code의 다중 에이전트를 최적화하고 독립적인 태스크를 동시에 실행하는 방법","es":"Aprende a utilizar Ultrawork para ejecutar múltiples agentes de forma paralela y mejorar la eficiencia de tus tareas de desarrollo","fr":"Découvrez comment utiliser Ultrawork pour exécuter plusieurs agents en parallèle et améliorer l''efficacité de vos tâches de développement","de":"Erfahren Sie, wie Sie Ultrawork verwenden können, um mehrere Agents parallel auszuführen und die Effizienz Ihrer Entwicklungsaufgaben zu verbessern","pt":"Aprenda a configurar o Ultrawork para executar tarefas independentes em paralelo com agentes múltiplos. Descubra como delegar trabalho e aproveitar a execuçã...","ru":"Узнайте, как настроить Ultrawork для параллельного выполнения независимых задач с помощью нескольких агентов. Откройте для себя, как делегировать работу и ис...","ar":"تعرف على كيفية إعداد Ultrawork لتشغيل المهام المستقلة بشكل مواز مع وحدات متعددة. اكتشف كيفية تفويض العمل والاستفادة من التنفيذ المتوازي"},"definition":{"en":"Ultrawork is a parallel execution engine that runs multiple agents simultaneously for independent tasks, providing parallelism and smart model routing.","zh":"Ultrawork 是一个并行执行引擎，用于同时运行多个独立任务","ja":"Ultrawork は、複数の独立したタスクを同時に実行する並列実行エンジン","ko":"Ultrawork 는 독립적인 태스크를 동시에 실행하는 병렬 실행 엔진","es":"Ultrawork es un componente de orquestación de agentes que permite la ejecución paralela de tareas","fr":"Ultrawork est un composant d''orchestration d''agents qui permet l''exécution parallèle de tâches","de":"Ultrawork ist ein Komponente zur Orchestrierung von Agents, die die parallele Ausführung von Aufgaben ermöglicht","pt":"O que é Ultrawork? É um mecanismo de execução paralela para tarefas independentes com agentes múltiplos.","ru":"Что такое Ultrawork? Это механизм параллельного выполнения для независимых задач с помощью нескольких агентов.","ar":"ما هو Ultrawork؟ هو ميكانيكي تنفيذ موازي للمهام المستقلة مع وحدات متعددة"},"features":{"en":["Runs multiple agents simultaneously for independent tasks","Provides parallelism and smart model routing","Enables delegation of work to multiple agents at once","Supports concurrent execution of tasks","Compatible with Claude Code","Triggered by commands ''ulw'', ''ultrawork'', or parallel execution requests"],"zh":["并行执行多个独立任务","智能模型路由"," Claude Code 多agent 管理","同时运行多个agent","提高任务执行效率"],"ja":["複数の独立したタスクの並列実行","スマートモデルルーティング","AIエージェントの多agent 管理","複数のエージェントの同時実行","タスク実行の効率化"],"ko":["독립적인 태스크의 병렬 실행","스마트 모델 라우팅","다중 에이전트 관리","複数의 에이전트의 동시 실행","태스크 실행 효율성 향상"],"es":["Ejecución paralela de múltiples agentes","Enrutamiento inteligente de modelos","Delegación de trabajo a múltiples agentes","Beneficios de concurrencia para tareas","Compatibilidad con Claude Code"],"fr":["Exécution parallèle de plusieurs agents","Enrutamiento intelligent de modèles","Délégation de travail à plusieurs agents","Avantages de la concurrence pour les tâches","Compatibilité avec Claude Code"],"de":["Parallele Ausführung mehrerer Agents","Intelligente Modell-Weiterleitung","Delegierung von Arbeit an mehrere Agents","Vorteile der Konkurrenz für Aufgaben","Kompatibilität mit Claude Code"],"pt":["Execução paralela de tarefas independentes","Roteamento de modelo inteligente","Delegação de trabalho para múltiplos agentes","Aproveitamento da execução concorrente","Integração com Claude Code"],"ru":["Параллельное выполнение независимых задач","Умное маршрутизация модели","Делегирование работы нескольким агентам","Использование преимуществ конкьюренции","Интеграция с Claude Code"],"ar":["التنفيذ الموازي للمهام المستقلة","توجيه النموذج الذكي","تفويض العمل لوحدات متعددة","الاستفادة من التنفيذ المتوازي","التكامل مع Claude Code"]},"keywords":{"en":["how to use ultrawork","what is ultrawork","ultrawork alternative","ultrawork vs claude code","ultrawork install","ultrawork setup guide","parallel execution engine","multi-agent orchestration","claude code integration"],"zh":["Ultrawork","并行执行引擎"," Claude Code","多agent 管理","AI工具","并行计算","智能模型路由"],"ja":["Ultrawork","並列実行エンジン","AIエージェント","多agent 管理","AIツール","並列計算","スマートモデルルーティング"],"ko":["Ultrawork","병렬 실행 엔진","다중 에이전트","Claude Code","AI도구","병렬計算","스마트 모델 라우팅"],"es":["Ultrawork","Agentes de IA","Ejecución paralela","Orquestación de agentes","Desarrollo de software","Herramientas de desarrollo","Claude Code","Inteligencia artificial"],"fr":["Ultrawork","Outils d''IA","Exécution parallèle","Orchestration d''agents","Développement de logiciels","Outils de développement","Claude Code","Intelligence artificielle"],"de":["Ultrawork","KI-Agents","Parallele Ausführung","Orchestrierung von Agents","Software-Entwicklung","Entwicklungstools","Claude Code","Künstliche Intelligenz"],"pt":["Ultrawork","orquestração de agentes","execução paralela"," Claude Code","desenvolvimento de software","engenharia de software","ferramentas de AI","tecnologias de IA","programação paralela"],"ru":["Ultrawork","Мультй-Агентная Оркестрация","параллельное выполнение"," Claude Code","разработка программного обеспечения","инженерия программного обеспечения","ИИ Агенты","ИИ инструменты","параллельное программирование"],"ar":["Ultrawork","تنسيق وحدات متعددة","التنفيذ الموازي"," Claude Code","تطوير البرمجيات","هندسة البرمجيات","أدوات الذكاء الاصطناعي","تكنولوجيا الذكاء الاصطناعي","برمجة موازية"]}},"owner":"Yeachan-Heo","repo":"oh-my-claudecode","repoPath":"Yeachan-Heo/oh-my-claudecode","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.282Z","topics":[],"category":"community","skillMd":{"name":"ultrawork","description":"Parallel execution engine for high-throughput task completion","bodyPreview":"<Purpose>\nUltrawork is a parallel execution engine that runs multiple agents simultaneously for independent tasks. It is a component, not a standalone persistence mode -- it provides parallelism and smart model routing but not persistence, verification loops, or state management.\n</Purpose>\n\n<Use_When>\n- Multiple independent tasks can run simultaneously\n- User says \"ulw\", \"ultrawork\", or wants parallel execution\n- You need to delegate work to multiple agents at once\n- Task benefits from concurre","body":"<Purpose>\nUltrawork is a parallel execution engine that runs multiple agents simultaneously for independent tasks. It is a component, not a standalone persistence mode -- it provides parallelism and smart model routing but not persistence, verification loops, or state management.\n</Purpose>\n\n<Use_When>\n- Multiple independent tasks can run simultaneously\n- User says \"ulw\", \"ultrawork\", or wants parallel execution\n- You need to delegate work to multiple agents at once\n- Task benefits from concurrent execution but the user will manage completion themselves\n</Use_When>\n\n<Do_Not_Use_When>\n- Task requires guaranteed completion with verification -- use `ralph` instead (ralph includes ultrawork)\n- Task requires a full autonomous pipeline -- use `autopilot` instead (autopilot includes ralph which includes ultrawork)\n- There is only one sequential task with no parallelism opportunity -- delegate directly to an executor agent\n- User needs session persistence for resume -- use `ralph` which adds persistence on top of ultrawork\n</Do_Not_Use_When>\n\n<Why_This_Exists>\nSequential task execution wastes time when tasks are independent. Ultrawork enables firing multiple agents simultaneously and routing each to the right model tier, reducing total execution time while controlling token costs. It is designed as a composable component that ralph and autopilot layer on top of.\n</Why_This_Exists>\n\n<Execution_Policy>\n- Fire all independent agent calls simultaneously -- never serialize independent work\n- Always pass the `model` parameter explicitly when delegating\n- Read `docs/shared/agent-tiers.md` before first delegation for agent selection guidance\n- Use `run_in_background: true` for operations over ~30 seconds (installs, builds, tests)\n- Run quick commands (git status, file reads, simple checks) in the foreground\n</Execution_Policy>\n\n<Steps>\n1. **Read agent reference**: Load `docs/shared/agent-tiers.md` for tier selection\n2. **Classify tasks by independence**: Identify which tasks can run in parallel vs which have dependencies\n3. **Route to correct tiers**:\n   - Simple lookups/definitions: LOW tier (Haiku)\n   - Standard implementation: MEDIUM tier (Sonnet)\n   - Complex analysis/refactoring: HIGH tier (Opus)\n4. **Fire independent tasks simultaneously**: Launch all parallel-safe tasks at once\n5. **Run dependent tasks sequentially**: Wait for prerequisites before launching dependent work\n6. **Background long operations**: Builds, installs, and test suites use `run_in_background: true`\n7. **Verify when all tasks complete** (lightweight):\n   - Build/typecheck passes\n   - Affected tests pass\n   - No new errors introduced\n</Steps>\n\n<Tool_Usage>\n- Use `Task(subagent_type=\"oh-my-claudecode:executor\", model=\"haiku\", ...)` for simple changes\n- Use `Task(subagent_type=\"oh-my-claudecode:executor\", model=\"sonnet\", ...)` for standard work\n- Use `Task(subagent_type=\"oh-my-claudecode:executor\", model=\"opus\", ...)` for complex work\n- Use `run_in_background: true` for package installs, builds, and test suites\n- Use foreground execution for quick status checks and file operations\n</Tool_Usage>\n\n<Examples>\n<Good>\nThree independent tasks fired simultaneously:\n```\nTask(subagent_type=\"oh-my-claudecode:executor\", model=\"haiku\", prompt=\"Add missing type export for Config interface\")\nTask(subagent_type=\"oh-my-claudecode:executor\", model=\"sonnet\", prompt=\"Implement the /api/users endpoint with validation\")\nTask(subagent_type=\"oh-my-claudecode:executor\", model=\"sonnet\", prompt=\"Add integration tests for the auth middleware\")\n```\nWhy good: Independent tasks at appropriate tiers, all fired at once.\n</Good>\n\n<Good>\nCorrect use of background execution:\n```\nTask(subagent_type=\"oh-my-claudecode:executor\", model=\"sonnet\", prompt=\"npm install && npm run build\", run_in_background=true)\nTask(subagent_type=\"oh-my-claudecode:executor\", model=\"haiku\", prompt=\"Update the README with new API endpoints\")\n```\nWhy good: Long build runs in background while short task runs in foreground.\n</Good>\n\n<Bad>\nSequential execution of independent work:\n```\nresult1 = Task(executor, \"Add type export\")  # wait...\nresult2 = Task(executor, \"Implement endpoint\")     # wait...\nresult3 = Task(executor, \"Add tests\")              # wait...\n```\nWhy bad: These tasks are independent. Running them sequentially wastes time.\n</Bad>\n\n<Bad>\nWrong tier selection:\n```\nTask(subagent_type=\"oh-my-claudecode:executor\", model=\"opus\", prompt=\"Add a missing semicolon\")\n```\nWhy bad: Opus is expensive overkill for a trivial fix. Use executor with Haiku instead.\n</Bad>\n</Examples>\n\n<Escalation_And_Stop_Conditions>\n- When ultrawork is invoked directly (not via ralph), apply lightweight verification only -- build passes, tests pass, no new errors\n- For full persistence and comprehensive architect verification, recommend switching to `ralph` mode\n- If a task fails repeatedly across retries, report the issue rather than retrying indefinitely\n- Escalate to the user when tasks have unclear dependencies or conflicting requirements\n</Escalation_And_Stop_Conditions>\n\n<Final_Checklist>\n- [ ] All parallel tasks completed\n- [ ] Build/typecheck passes\n- [ ] Affected tests pass\n- [ ] No new errors introduced\n</Final_Checklist>\n\n<Advanced>\n## Relationship to Other Modes\n\n```\nralph (persistence wrapper)\n \\-- includes: ultrawork (this skill)\n     \\-- provides: parallel execution only\n\nautopilot (autonomous execution)\n \\-- includes: ralph\n     \\-- includes: ultrawork (this skill)\n```\n\nUltrawork is the parallelism layer. Ralph adds persistence and verification. Autopilot adds the full lifecycle pipeline.\n</Advanced>\n"},"lastSynced":"2026-03-08T02:00:52.746Z","agentAnalysis":{"suitability":{"en":"Perfect for Multi-Agent Systems needing parallel execution of independent tasks with Claude Code integration.","zh":"非常适合需要并行执行独立任务并集成Claude Code的多Agent系统。","ja":"Claude Codeを統合して独立したタスクを並行して実行する必要があるマルチエージェントシステムに最適です。","ko":"클라우드 코드를 통합하여 독립적인 태스크를 병렬로 실행해야 하는 멀티 에이전트 시스템에 적합합니다.","es":"Perfecto para Sistemas de Multiagentes que necesitan ejecución paralela de tareas independientes con integración de Claude Code.","fr":"Parfait pour les systèmes multi-agents nécessitant l''exécution parallèle de tâches indépendantes avec intégration de Claude Code.","de":"Perfekt für Multi-Agenten-Systeme, die eine parallele Ausführung von unabhängigen Aufgaben mit Claude Code-Integration benötigen.","pt":"Perfeito para Sistemas Multi-Agente que necessitam de execução paralela de tarefas independentes com integração do Claude Code.","ru":"Идеально подходит для Многоагентных Систем, требующих параллельного выполнения независимых задач с интеграцией Claude Code.","ar":"مثالي لنظام متعدد الوكلاء الذي يحتاج إلى تنفيذ متوازي للمهام المستقلة مع دمج Claude Code."},"recommendation":{"en":"Empowers agents to execute multiple tasks concurrently using smart model routing, providing parallelism for improved efficiency and productivity with multi-agent orchestration, leveraging ultrawork''s teams-first approach.","zh":"使得Agent能够使用智能模型路由同时执行多个任务，为多Agent编排提供并行性，从而提高效率和生产力，同时利用Ultrawork的团队优先方法。","ja":"スマートモデルルーティングを使用してエージェントが同時に複数のタスクを実行できるようにし、マルチエージェントオーケストレーションに並列性を提供して効率と生産性を向上させ、Ultraworkのチーム優先アプローチを活用します。","ko":"스마트 모델 라우팅을 사용하여 에이전트가 동시에 여러 태스크를 실행할 수 있도록 하여 멀티 에이전트 오케스트레이션에 병렬성을 제공하고 효율성과 생산성을 향상시키며 Ultrawork의 팀 우선 접근 방식을 활용합니다.","es":"Habilita a los agentes a ejecutar múltiples tareas de forma concurrente utilizando enrutamiento de modelos inteligentes, proporcionando paralelismo para mejorar la eficiencia y la productividad con orquestación de multiagentes, aprovechando el enfoque de equipos de ultrawork.","fr":"Permet aux agents d''exécuter plusieurs tâches de manière concurrente en utilisant un routage de modèles intelligents, fournissant un parallélisme pour améliorer l''efficacité et la productivité avec une orchestration multi-agents, en exploitant l''approche d''équipe d''ultrawork.","de":"Ermöglicht es Agenten, mehrere Aufgaben gleichzeitig auszuführen, indem sie intelligente Modellrouting verwenden, wodurch Parallelismus für eine verbesserte Effizienz und Produktivität mit Multiagenten-Orchestrierung bereitgestellt wird, wobei der teamsorientierte Ansatz von ultrawork genutzt wird.","pt":"Habilita os agentes a executar várias tarefas simultaneamente usando roteamento de modelo inteligente, fornecendo paralelismo para melhor eficiência e produtividade com orquestração de multi-agente, aproveitando a abordagem de equipes primeiro da ultrawork.","ru":"Наделяет агентов возможностью выполнять несколько задач одновременно с помощью умного маршрутизации модели, обеспечивая параллелизм для повышения эффективности и производительности с помощью оркестровки многоагентных систем, используя командно-ориентированный подход ultrawork.","ar":"يُمكّن الوكلاء من تشغيل مهام متعددة في نفس الوقت باستخدام маршーティنغ ذكي للنموذج، مما يوفر موازاة لتحسين الفعالية والإنتاجية مع أوركسترا متعددة الوكلاء، مستفيداً من نهج فرق أولاً من ultrawork."},"useCases":{"en":["Delegating work to multiple agents simultaneously","Executing independent tasks in parallel","Enhancing productivity with concurrent task execution"],"zh":["同时将工作委托给多个Agent","并行执行独立任务","通过并发任务执行提高生产力"],"ja":["複数のエージェントに同時に作業を委託する","独立したタスクを並行して実行する","並行タスク実行による生産性の向上"],"ko":["여러 에이전트에게 동시에 작업을 위임하는 것","독립적인 태스크를 병렬로 실행하는 것","병렬 태스크 실행을 통한 생산성 향상"],"es":["Delegar trabajo a varios agentes simultáneamente","Ejecutar tareas independientes en paralelo","Mejorar la productividad con la ejecución de tareas concurrentes"],"fr":["Déléguer des tâches à plusieurs agents simultanément","Exécuter des tâches indépendantes en parallèle","Améliorer la productivité avec l''exécution de tâches concurrentes"],"de":["Arbeit an mehrere Agenten gleichzeitig delegieren","Unabhängige Aufgaben parallel ausführen","Produktivität durch gleichzeitige Aufgabenausführung verbessern"],"pt":["Delegar trabalho a vários agentes simultaneamente","Executar tarefas independentes em paralelo","Aumentar a produtividade com execução de tarefas concorrente"],"ru":["Делегировать работу нескольким агентам одновременно","Выполнять независимые задачи параллельно","Повысить производительность с помощью параллельного выполнения задач"],"ar":["تفويض العمل إلى عدة وكلاء في نفس الوقت","تنفيذ مهام مستقلة بالتوازي","تعزيز الإنتاجية من خلال تنفيذ المهام المتزامن"]},"limitations":{"en":["Does not provide persistence","Does not include verification loops","Does not manage state"],"zh":["不提供持久化","不包含验证循环","不管理状态"],"ja":["永続化を提供しない","検証ループを含まない","状態を管理しない"],"ko":["영속성을 제공하지 않음","검증 루프를 포함하지 않음","상태를 관리하지 않음"],"es":["No proporciona persistencia","No incluye bucles de verificación","No gestiona el estado"],"fr":["Ne fournit pas de persistance","N''inclut pas de boucles de vérification","Ne gère pas l''état"],"de":["Bietet keine Persistenz","Enthält keine Überprüfungsschleifen","Verwaltet keinen Zustand"],"pt":["Não fornece persistência","Não inclui loops de verificação","Não gerencia estado"],"ru":["Не обеспечивает сохранность","Не включает петли проверки","Не управляет состоянием"],"ar":["لا يوفر استمرارية","لا يتضمن حلقات التحقق","لا يدير الحالة"]},"version":4},"contentHash":"a5ca384b8ae5e556296420adb712e41cc6ab2e49088960469d874b587634550e","qualityScore":39}');
