INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Yeachan-Heo/oh-my-claudecode/ultrawork', 'ultrawork', 'Yeachan-Heo', 'oh-my-claudecode', 'community', 'ultrawork Yeachan-Heo oh-my-claudecode community Ultrawork is a teams-first multi-agent orchestration component for Claude Code, enabling parallel execution of independent tasks. It benefits developers who need to run multiple agents simultaneously. Ultrawork 是一个并行执行引擎，允许同时运行多个独立任务，适用于 Claude Code 的多agent 管理 Ultrawork は、複数の独立したタスクを同時に実行する並列実行エンジンであり、AIエージェントのパフォーマンスを向上させる Ultrawork 는 Claude Code의 다중 에이전트를 최적화하는 병렬 실행 엔진으로 독립적인 태스크를 동시에 실행 Ultrawork es un motor de ejecución paralela que permite ejecutar múltiples agentes de forma simultánea para tareas independientes Ultrawork est un moteur d''exécution parallèle qui permet d''exécuter plusieurs agents en simultané pour des tâches indépendantes Ultrawork ist ein paralleler Ausführungsmotor, der die Ausführung mehrerer Agents simultan für unabhängige Aufgaben ermöglicht O Ultrawork é um mecanismo de execução paralela que executa vários agentes simultaneamente para tarefas independentes. Ele fornece paralelismo e roteamento de modelo inteligente. Ultrawork - это механизм параллельного выполнения, который запускает несколько агентов одновременно для независимых задач. Он обеспечивает параллелизм и умное маршрутизация модели. Ultrawork هو ميكانيكي تنفيذ موازي يقوم بتشغيل وحدات متعددة في نفس الوقت للمهام المستقلة. يوفر التمويل الموازي وتوجيه النموذج الذكي how to use ultrawork what is ultrawork ultrawork alternative ultrawork vs claude code ultrawork install ultrawork setup guide parallel execution engine multi-agent orchestration claude code integration Ultrawork 并行执行引擎 Claude Code 多agent 管理 AI工具 并行计算 智能模型路由 Runs multiple agents simultaneously for independent tasks Provides parallelism and smart model routing Enables delegation of work to multiple agents at once Supports concurrent execution of tasks Compatible with Claude Code Triggered by commands ''ulw'', ''ultrawork'', or parallel execution requests Ultrawork is a parallel execution engine that runs multiple agents simultaneously for independent tasks, providing parallelism and smart model routing.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mitsuhiko/agent-stuff/openscad', 'community', 'mitsuhiko', 'agent-stuff', 'mitsuhiko/agent-stuff', 'openscad', 0, 0, 39, '2026-03-08T01:57:15.283Z', '2026-03-08T02:00:52.924Z', 'e49b7c056c4f9cee67b6e3fa4620915ccdddf12278159db9073cc063ee957799', '{"id":"mitsuhiko/agent-stuff/openscad","name":"openscad","description":{"en":"OpenSCAD is a 3D modeling tool that supports parameter customization and STL export. It can be installed via Homebrew","zh":"OpenSCAD是一种3D建模工具，支持参数定制和STL导出。可以通过Homebrew安装","ja":"OpenSCADは3Dモデリングツールで、パラメータカスタマイズとSTL出力に対応しています。Homebrew経由でインストールできます","ko":"OpenSCAD는 파라미터 커스터마이징과 STL 내보내기 기능을 지원하는 3D 모델링 도구입니다. Homebrew를 통해 설치할 수 있습니다","es":"OpenSCAD es una herramienta para crear y exportar modelos 3D. Soporta la personalización de parámetros y la previsualización de modelos desde múltiples ángulos","fr":"OpenSCAD est un outil pour créer et exporter des modèles 3D. Il prend en charge la personnalisation de paramètres et la prévisualisation de modèles depuis plusieurs angles","de":"OpenSCAD ist ein Tool zum Erstellen und Exportieren von 3D-Modellen. Es unterstützt die Anpassung von Parametern und die Vorschau von Modellen aus mehreren Perspektiven","pt":"O OpenSCAD é uma ferramenta poderosa para criar e validar modelos 3D, com recursos de pré-visualização e exportação para STL","ru":"OpenSCAD - это мощный инструмент для создания и проверки 3D-моделей, с функциями предварительного просмотра и экспорта в STL","ar":"OpenSCAD هو أداة قوية لإنشاء وتحقق نماذج 3D، مع ميزات المعاينة والتصدير إلى STL"},"seo":{"title":{"en":"OpenSCAD Setup Guide for 3D Modeling","zh":"OpenSCAD 3D建模工具安装指南","ja":"OpenSCAD 3Dモデリングツールの設定方法 - AIエージェント","ko":"OpenSCAD 3D 모델링 도구 설정 가이드 - 인공지능 에이전트","es":"Guía de configuración de OpenSCAD para agentes de IA","fr":"Guide de configuration d''OpenSCAD pour les outils d''IA","de":"