INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mitsuhiko/agent-stuff/openscad', 'openscad', 'mitsuhiko', 'agent-stuff', 'community', 'openscad mitsuhiko agent-stuff community OpenSCAD is a 3D modeling tool that supports parameter customization and STL export. It can be installed via Homebrew OpenSCAD是一种3D建模工具，支持参数定制和STL导出。可以通过Homebrew安装 OpenSCADは3Dモデリングツールで、パラメータカスタマイズとSTL出力に対応しています。Homebrew経由でインストールできます OpenSCAD는 파라미터 커스터마이징과 STL 내보내기 기능을 지원하는 3D 모델링 도구입니다. Homebrew를 통해 설치할 수 있습니다 OpenSCAD es una herramienta para crear y exportar modelos 3D. Soporta la personalización de parámetros y la previsualización de modelos desde múltiples ángulos OpenSCAD est un outil pour créer et exporter des modèles 3D. Il prend en charge la personnalisation de paramètres et la prévisualisation de modèles depuis plusieurs angles OpenSCAD ist ein Tool zum Erstellen und Exportieren von 3D-Modellen. Es unterstützt die Anpassung von Parametern und die Vorschau von Modellen aus mehreren Perspektiven O OpenSCAD é uma ferramenta poderosa para criar e validar modelos 3D, com recursos de pré-visualização e exportação para STL OpenSCAD - это мощный инструмент для создания и проверки 3D-моделей, с функциями предварительного просмотра и экспорта в STL OpenSCAD هو أداة قوية لإنشاء وتحقق نماذج 3D، مع ميزات المعاينة والتصدير إلى STL OpenSCAD installation 3D modeling software STL export 3D printing platform MakerWorld Homebrew installation CLI tool parameter customization visual preview OpenSCAD安装 3D建模软件 STL导出 3D打印平台 MakerWorld Homebrew安装 CLI工具 参数定制 视觉预览 Parameter customization STL export for 3D printing Visual preview from multiple angles Support for MakerWorld 3D printing platform Installation via Homebrew Preview generation using CLI tool OpenSCAD is a free software for creating 3D models');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('barefootford/buttercut/roughcut', 'community', 'barefootford', 'buttercut', 'barefootford/buttercut', 'roughcut', 0, 0, 39, '2026-03-08T01:57:15.292Z', '2026-03-08T02:01:03.102Z', 'fd2ebc6b090934c74cc3c49506dc9687142f2765a158e69bd3cdb7ebf9afc759', '{"id":"barefootford/buttercut/roughcut","name":"roughcut","description":{"en":"The roughcut skill handles the editorial process of creating rough cut timeline scripts from transcribed video footage, benefiting developers and video editors. It analyzes transcripts and exports to Final Cut Pro XML format.","zh":"roughcut 技术用于创建粗剪辑时间轴脚本，输出 YAML rough cut 并导出到 Final Cut Pro XML 格式","ja":"roughcut は粗剪輯タイムラインスクリプトを作成し、YAML rough cut を出力して Final Cut Pro XML 形式でエクスポートする","ko":"roughcut 기술은粗剪辑 시간대 스크립트를 생성하고 YAML rough cut를 출력하여 Final Cut Pro XML 형식으로 내보내기","es":"Roughcut es una habilidad que edita video con Claude Code, creando guiones de línea de tiempo de edición rough cut a partir de transcripciones de metraje de video","fr":"Roughcut est une compétence qui édite des vidéos avec Claude Code, créant des scripts de ligne de temps de montage rough cut à partir de transcriptions de footage vidéo","de":"Roughcut ist eine Fähigkeit, die Videos mit Claude Code bearbeitet, indem sie Timeline-Skripte für den Rough-Cut aus Video-Transkriptionen erstellt","pt":"O roughcut é uma habilidade que edita vídeo com Claude Code, criando um script de linha do tempo de edição bruta","ru":"Roughcut - это навык, который редактирует видео с помощью ИИ Агентов, создавая сценарий монтажа","ar":"Roughcut هو مهارة لتحرير الفيديو مع Claude Code، لإنشاء سيناريو تحرير أولي"},"seo":{"title":{"en":"roughcut: Create Rough Cut Timeline Scripts for AI Agents...","zh":"roughcut 编辑视频设置指南","ja":"roughcut ビデオ編集ベストプラクティス - AIエージェント","ko":"roughcut 비디오 편집 가이드 - AI 도구","es":"Guía de configuración de roughcut: Edición de video con C...","fr":"Mise en place de roughcut: Édition vidéo avec Claude Code","de":"Roughcut-Setup-Anleitung: Video-Bearbeitung mit Claude Code","pt":"Guia de Configuração do Roughcut: Edição de Vídeo com Cla...","ru":"Настройка Roughcut: Создание Сценария Монтажа с помощью И...","ar":"دليل إعداد Roughcut: تحرير الفيديو مع Claude Code"},"description":{"en":"Discover how to edit video with Claude Code using roughcut. Learn to launch a specialized agent for editorial decisions and export to Final Cut Pro XML format.","zh":"了解 roughcut 技术，使用 Claude Code 编辑视频，输出 YAML rough cut 并导出到 Final Cut Pro XML 格式","ja":"roughcut を使用してビデオを編集し、YAML rough cut を出力して Final Cut Pro XML 形式でエクスポートする","ko":"roughcut 기술을 사용하여 비디오를 편집하고 YAML rough cut를 출력하여 Final Cut Pro XML 형식으로 내보내기","es":"Aprende a utilizar roughcut para editar videos con Claude Code y mejora tu flujo de trabajo de edición","fr":"Découvrez comment utiliser roughcut pour éditer des vidéos avec Claude Code et améliorez votre flux de travail d''édition","de":"Erfahren Sie, wie Sie roughcut verwenden, um Videos mit Claude Code zu bearbeiten und Ihren Bearbeitungsprozess zu optimieren","pt":"Aprenda a configurar o roughcut para edição de vídeo com Claude Code e melhore sua produtividade","ru":"Узнайте, как настроить roughcut для создания сценария монтажа с помощью ИИ Агентов","ar":"تعرف على كيفية إعداد Roughcut لتحرير الفيديو مع Claude Code وزيادة إنتاجيتك"},"definition":{"en":"roughcut is a specialized AI agent skill that creates rough cut timeline scripts from transcribed video footage, outputting a structured YAML rough cut.","zh":"roughcut 是一种编辑视频的技术，使用 Claude Code 创建粗剪辑时间轴脚本","ja":"roughcut はビデオを編集する技術で、Claude Code を使用して粗剪輯タイムラインスクリプトを作成する","ko":"roughcut는 비디오를 편집하는 기술로 Claude Code를 사용하여粗剪辑 시간대 스크립트를 생성","es":"Roughcut es una herramienta de edición de video que utiliza Claude Code para crear guiones de edición rough cut","fr":"Roughcut est un outil d''édition de vidéo qui utilise Claude Code pour créer des scripts de montage rough cut","de":"Roughcut ist ein Video-Bearbeitungstool, das Claude Code verwendet, um Rough-Cut-Skripte zu erstellen","pt":"Roughcut é uma habilidade de edição de vídeo que cria scripts de linha do tempo de edição bruta","ru":"Roughcut - это навык редактирования видео, создающий сценарий монтажа","ar":"Roughcut هو مهارة لتحرير الفيديو التي تنشئ سيناريوهات تحرير أولية"},"features":{"en":["Analyzes transcripts to make editorial decisions","Outputs a structured YAML rough cut","Exports to Final Cut Pro XML format","Handles full-length rough cuts and short sequences","Launches a specialized agent for editorial processing","Supports both multiple minutes and 30-60 second video sequences"],"zh":["使用 Claude Code 编辑视频","输出 YAML rough cut","导出到 Final Cut Pro XML 格式","支持多分钟和 30-60 秒的视频编辑","自动分析转录并做出编辑决策"],"ja":["Claude Code を使用してビデオを編集","YAML rough cut を出力","Final Cut Pro XML 形式でエクスポート","複数分と 30-60 秒のビデオ編集をサポート","自動で転写を分析して編集決定を下す"],"ko":["Claude Code를 사용하여 비디오를 편집","YAML rough cut를 출력","Final Cut Pro XML 형식으로 내보내기","다중 분과 30-60초의 비디오 편집을 지원","자동으로 전사를 분석하여 편집 결정"],"es":["Análisis de transcripciones de video","Toma de decisiones editoriales","Salida de guiones de edición rough cut en formato YAML","Exportación a Final Cut Pro XML","Compatibilidad con secuencias largas y cortas"],"fr":["Analyse de transcriptions de vidéo","Prise de décisions éditoriales","Sortie de scripts de montage rough cut au format YAML","Exportation vers Final Cut Pro XML","Compatibilité avec des séquences longues et courtes"],"de":["Analyse von Video-Transkriptionen","Editorische Entscheidungen","Ausgabe von Rough-Cut-Skripten im YAML-Format","Export in Final Cut Pro XML","Kompatibilität mit langen und kurzen Sequenzen"],"pt":["Análise de transcrições de vídeo","Tomada de decisões editoriais","Saída de script de linha do tempo de edição bruta em YAML","Exportação para Final Cut Pro XML","Suporte a vídeos de longa duração e sequências curtas"],"ru":["Анализ транскрипций видео","Принятие редакторских решений","Выходной сценарий монтажа в формате YAML","Экспорт в формат Final Cut Pro XML","Поддержка видео длительностью несколько минут и коротких последовательностей"],"ar":["تحليل نسخ الفيديو","اتخاذ قرارات تحريرية","إخراج سيناريو تحرير أولي في تنسيق YAML","تصدير إلى تنسيق Final Cut Pro XML","دعم الفيديوهات الطويلة والمتوالية القصيرة"]},"keywords":{"en":["how to use roughcut","roughcut alternative","roughcut setup guide","what is roughcut","roughcut vs Final Cut Pro","roughcut install","roughcut YAML output","roughcut video editing","roughcut Claude Code"],"zh":["roughcut 编辑视频","Claude Code","YAML rough cut","Final Cut Pro XML","视频编辑技术","AI 编辑视频","roughcut 技术","视频编辑软件"],"ja":["roughcut ビデオ編集","Claude Code","YAML rough cut","Final Cut Pro XML","ビデオ編集技術","AI ビデオ編集","roughcut 技術","ビデオ編集ソフト"],"ko":["roughcut 비디오 편집","Claude Code","YAML rough cut","Final Cut Pro XML","비디오 편집 기술","AI 비디오 편집","roughcut 기술","비디오 편집 소프트웨어"],"es":["roughcut","edición de video","Claude Code","guiones de edición rough cut","transcripciones de video","Final Cut Pro XML","herramientas de edición de video","AI Agentes","edición de video con AI"],"fr":["roughcut","édition de vidéo","Claude Code","scripts de montage rough cut","transcriptions de vidéo","Final Cut Pro XML","outils d''édition de vidéo","Agents IA","édition de vidéo avec IA"],"de":["roughcut","Video-Bearbeitung","Claude Code","Rough-Cut-Skripte","Video-Transkriptionen","Final Cut Pro XML","Video-Bearbeitungstools","KI-Agents","Video-Bearbeitung mit KI"],"pt":["edição de vídeo","roughcut","Claude Code","script de linha do tempo","YAML","Final Cut Pro XML","vídeo de longa duração","sequências curtas"],"ru":["редактирование видео","roughcut","ИИ Агенты","сценарий монтажа","YAML","Final Cut Pro XML","видео длительностью несколько минут","короткие последовательности"],"ar":["تحرير الفيديو","Roughcut","Claude Code","سيناريو تحرير أولي","YAML","Final Cut Pro XML","فيديو طويل","متواليات قصيرة"]}},"owner":"barefootford","repo":"buttercut","repoPath":"barefootford/buttercut","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.292Z","topics":[],"category":"community","skillMd":{"name":"roughcut","description":"Creates video rough cut yaml file for use with Buttercut gem. Concatenates visual transcripts with file markers, creates a roughcut yaml with clip selections, then exports to XML format. Use this skill when users want a roughcut, sequence or scene generated. These are all the same thing, just with different lengths.","bodyPreview":"# Skill: Create Rough Cut\n\nThis skill handles the editorial process of creating rough cut timeline scripts from transcribed video footage. It launches a specialized agent that analyzes transcripts, makes editorial decisions, outputs a structured YAML rough cut, and exports it to Final Cut Pro XML format.\n\n**Note:** This skill is used for both full-length rough cuts (multiple minutes) and short sequences (30-60 seconds).\n\n## Prerequisites Check\n\nBefore launching the roughcut agent, verify all tra","body":"# Skill: Create Rough Cut\n\nThis skill handles the editorial process of creating rough cut timeline scripts from transcribed video footage. It launches a specialized agent that analyzes transcripts, makes editorial decisions, outputs a structured YAML rough cut, and exports it to Final Cut Pro XML format.\n\n**Note:** This skill is used for both full-length rough cuts (multiple minutes) and short sequences (30-60 seconds).\n\n## Prerequisites Check\n\nBefore launching the roughcut agent, verify all transcripts are complete:\n\n1. **Check library exists:**\n   ```bash\n   ls libraries/[library-name]/library.yaml\n   ```\n\n2. **Verify visual transcripts:**\n   Read `libraries/[library-name]/library.yaml` and check that every video entry has both:\n   - `transcript` populated (audio transcript filename)\n   - `visual_transcript` populated (visual descriptions filename)\n\n   If any visual transcripts are missing:\n   - Inform user that transcript processing must be completed first\n   - Ask if they want Claude to finish transcript processing using the `transcribe-audio` and `analyze-video` skills\n   - Do not proceed with roughcut creation until all transcripts are complete\n\n## Launch Roughcut Agent\n\nOnce prerequisites are verified, launch the roughcut creation agent using the Task tool:\n\n```\nTask tool with:\n- subagent_type: \"general-purpose\"\n- description: \"Create rough cut from visual transcripts\"\n- prompt: [See agent prompt template below]\n```\n\n### Agent Prompt Template\n\nWhen launching the agent, provide a detailed prompt with all necessary context:\n\n```\nYou are a video editor AI agent creating a rough cut or sequence for the \"{library_name}\" library.\n\nUSER REQUEST: {what_user_asked_for}\n\nLIBRARY CONTEXT:\n{paste relevant content from library.yaml - footage_summary, user_context, etc.}\n\nYOUR TASK:\n1. Read the roughcut creation instructions from .claude/skills/roughcut/agent_instructions.md\n2. Follow those instructions to create the rough cut\n3. Return the paths to the created YAML and XML files when complete\n\nDELIVERABLES:\n- Rough cut YAML file at: libraries/{library_name}/roughcuts/{roughcut_name}_{datetime}.yaml\n- Exported XML file for user''s chosen video editor\n- Backup created via backup-library skill\n\nBegin by reading the agent instructions file.\n```\n\n## After Agent Completes\n\nWhen the agent returns:\n1. Inform the user of the created roughcut file (the xml file, not the yaml file) and its location\n2. Confirm the rough cut is ready to import into their video editor\n"},"lastSynced":"2026-03-08T02:01:03.102Z","agentAnalysis":{"suitability":{"en":"Perfect for Video Editing Agents needing automated rough cut timeline script creation from transcribed video footage.","zh":"非常适合需要从转录的视频片段自动创建粗略剪辑时间轴脚本的视频编辑代理。","ja":"映像編集エージェントがトランスクライブされた映像の粗いカットのタイムラインスクリプトを作成する必要がある場合に最適です。","ko":"자동으로 자막이 달린 비디오 프레임에서粗略한 편집 타임라인 스크립트를 생성해야 하는 비디오 편집 에이전트에 적합합니다.","es":"Perfecto para Agentes de Edición de Video que necesitan la creación automática de guiones de líneas de tiempo de corte brusco a partir de metraje de video transcrito.","fr":"Parfait pour les Agents de Montage Vidéo ayant besoin de la création automatisée de scripts de ligne de temps de montage brut à partir de footage vidéo transcrit.","de":"Perfekt für Video-Bearbeitungsagenten, die die automatisierte Erstellung von Rohschnitt-Zeitachsen-Skripten aus transkribiertem Videomaterial benötigen.","pt":"Perfeito para Agentes de Edição de Vídeo que precisam de criação automatizada de script de linha do tempo de corte bruto a partir de footagem de vídeo transcrita.","ru":"Идеально подходит для агентов видеомонтажа, которым необходима автоматизированная создание сценария чернового монтажа видеозаписи из транскрибированной видеозаписи.","ar":"مثالي لعميل تحرير الفيديو الذي يحتاج إلى إنشاء سيناريو آلي للخط الزمني للقص الاولي من مقاطع الفيديو المنسوخة."},"recommendation":{"en":"Empowers agents to analyze transcripts, make editorial decisions, and export structured YAML rough cuts to Final Cut Pro XML format, streamlining the video editing process with advanced transcript analysis and XML formatting capabilities.","zh":"赋予代理分析转录内容、做出编辑决策，并以Final Cut Pro XML格式导出结构化的YAML粗略剪辑，通过高级转录分析和XML格式化功能简化视频编辑流程。","ja":"エージェントがトランスクライプを分析し、編集上の決定を下し、Final Cut Pro XML形式で構造化されたYAMLの粗いカットをエクスポートできるようにし、高度なトランスクライプ分析とXMLフォーマット機能でビデオ編集プロセスを合理化します。","ko":"에이전트가 자막을 분석하고 편집 결정하고, 구조화된 YAML로 粗略한 편집을 Final Cut Pro XML 형식으로 내보내는 것을 가능하게 해주어, 고급 자막 분석 및 XML 포맷팅 기능으로 비디오 편집 과정을 간소화합니다.","es":"Habilita a los agentes a analizar transcritos, tomar decisiones editoriales y exportar YAML estructurado de montajes brutos en formato Final Cut Pro XML, simplificando el proceso de edición de video con capacidades de análisis de transcritos y formato XML avanzados.","fr":"Permet aux agents d''analyser les transcriptions, de prendre des décisions éditoriales et d''exporter des montages brut structurés au format Final Cut Pro XML, rationalisant le processus de montage vidéo avec des capacités d''analyse de transcription et de mise en forme XML avancées.","de":"Ermächtigt Agenten, Transkripte zu analysieren, redaktionelle Entscheidungen zu treffen und strukturierte YAML-Rohschnitte im Final Cut Pro XML-Format zu exportieren, wodurch der Videobearbeitungsprozess mit erweiterten Transkriptanalyse- und XML-Formatierungsfunktionen rationalisiert wird.","pt":"Habilita os agentes a analisar transcrições, tomar decisões editoriais e exportar cortes brutos estruturados no formato YAML para o formato XML do Final Cut Pro, agilizando o processo de edição de vídeo com capacidades avançadas de análise de transcrição e formatação XML.","ru":"Наделяет агентов возможностью анализировать транскрипты, принимать редакторские решения и экспортировать структурированные черновые монтажи в формате YAML в формат XML Final Cut Pro, оптимизируя процесс видеомонтажа с помощью расширенных возможностей анализа транскриптов и форматирования XML.","ar":"يمكن الوكلاء من تحليل النصوص المنسوخة واتخاذ قرارات تحريرية وتصدير قصات اولية منظمات في تنسيق YAML إلى تنسيق XML لبرنامج Final Cut Pro، ويعمل على تسريع عملية تحرير الفيديو باستخدام تحليل متقدم للنصوص المنسوخة وقدرات التنسيق XML."},"useCases":{"en":["Automating rough cut creation for full-length videos","Generating short sequence rough cuts for social media","Exporting rough cuts to Final Cut Pro for further editing"],"zh":["为全长视频自动创建粗略剪辑","为社交媒体生成短序列粗略剪辑","将粗略剪辑导出到Final Cut Pro进行进一步编辑"],"ja":["フルレングスビデオの粗いカットを自動的に作成する","ソーシャルメディア用の短いシーケンスの粗いカットを生成する","Final Cut Proでさらに編集するために粗いカットをエクスポートする"],"ko":["전체 길이 비디오에 대한粗略한 편집을 자동으로 생성하는 것","소셜 미디어를 위한 짧은 시퀀스의 粗略한 편집 생성","추가 편집을 위해 粗略한 편집을 Final Cut Pro로 내보내기"],"es":["Automatizar la creación de montajes brutos para videos de larga duración","Generar secuencias cortas de montajes brutos para redes sociales","Exportar montajes brutos a Final Cut Pro para una edición posterior"],"fr":["Automatiser la création de montages bruts pour des vidéos longues","Générer des séquences courtes de montages bruts pour les réseaux sociaux","Exporter des montages bruts vers Final Cut Pro pour une édition ultérieure"],"de":["Automatisierung der Erstellung von Rohschnitten für Vollvideos","Generierung kurzer Sequenzen von Rohschnitten für soziale Medien","Exportieren von Rohschnitten zu Final Cut Pro für weitere Bearbeitung"],"pt":["Automação da criação de corte bruto para vídeos de comprimento total","Geração de sequências curtas de corte bruto para mídias sociais","Exportação de cortes brutos para o Final Cut Pro para edição adicional"],"ru":["Автоматизация создания чернового монтажа для полнометражных видео","Генерация коротких последовательностей чернового монтажа для социальных сетей","Экспорт черновых монтажей в Final Cut Pro для дальнейшего редактирования"],"ar":["التنفيذ الآلي لإنشاء قص الاولي للفيديوهات الكاملة","إنشاء تسلسلات قصيرة من قص الاولي للوسائط الاجتماعية","تصدير قص الاولي إلى برنامج Final Cut Pro للمعالجة الإضافية"]},"limitations":{"en":["Requires transcribed video footage","Exports only to Final Cut Pro XML format","Limited to creating rough cuts for video editing purposes"],"zh":["需要转录的视频片段","仅导出到Final Cut Pro XML格式","仅限创建视频编辑用途的粗略剪辑"],"ja":["トランスクライブされた映像が必要","Final Cut Pro XML形式のみにエクスポート","ビデオ編集目的の粗いカットの作成のみ"],"ko":["자막이 달린 비디오 프레임이 필요","Final Cut Pro XML 형식으로만 내보내기","비디오 편집 목적의 粗略한 편집 생성만"],"es":["Requiere metraje de video transcrito","Exporta solo al formato Final Cut Pro XML","Limitado a la creación de montajes brutos para fines de edición de video"],"fr":["Nécessite un footage vidéo transcrit","N''exporte qu''au format Final Cut Pro XML","Limité à la création de montages bruts pour des fins de montage vidéo"],"de":["Benötigt transkribiertes Videomaterial","Exportiert nur im Final Cut Pro XML-Format","Begrenzt auf die Erstellung von Rohschnitten für Videobearbeitungszwecke"],"pt":["Exige footagem de vídeo transcrita","Exporta apenas para o formato XML do Final Cut Pro","Limitado à criação de cortes brutos para fins de edição de vídeo"],"ru":["Требует транскрибированной видеозаписи","Экспортирует только в формат XML Final Cut Pro","Ограничен созданием черновых монтажей для целей видеомонтажа"],"ar":["يتطلب مقاطع فيديو منسوخة","يصدر فقط إلى تنسيق XML لبرنامج Final Cut Pro","محدود بإنشاء قصات اولية لغرض تحرير الفيديو"]},"version":4},"contentHash":"fd2ebc6b090934c74cc3c49506dc9687142f2765a158e69bd3cdb7ebf9afc759","qualityScore":39}');
