INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('barefootford/buttercut/roughcut', 'roughcut', 'barefootford', 'buttercut', 'community', 'roughcut barefootford buttercut community The roughcut skill handles the editorial process of creating rough cut timeline scripts from transcribed video footage, benefiting developers and video editors. It analyzes transcripts and exports to Final Cut Pro XML format. roughcut 技术用于创建粗剪辑时间轴脚本，输出 YAML rough cut 并导出到 Final Cut Pro XML 格式 roughcut は粗剪輯タイムラインスクリプトを作成し、YAML rough cut を出力して Final Cut Pro XML 形式でエクスポートする roughcut 기술은粗剪辑 시간대 스크립트를 생성하고 YAML rough cut를 출력하여 Final Cut Pro XML 형식으로 내보내기 Roughcut es una habilidad que edita video con Claude Code, creando guiones de línea de tiempo de edición rough cut a partir de transcripciones de metraje de video Roughcut est une compétence qui édite des vidéos avec Claude Code, créant des scripts de ligne de temps de montage rough cut à partir de transcriptions de footage vidéo Roughcut ist eine Fähigkeit, die Videos mit Claude Code bearbeitet, indem sie Timeline-Skripte für den Rough-Cut aus Video-Transkriptionen erstellt O roughcut é uma habilidade que edita vídeo com Claude Code, criando um script de linha do tempo de edição bruta Roughcut - это навык, который редактирует видео с помощью ИИ Агентов, создавая сценарий монтажа Roughcut هو مهارة لتحرير الفيديو مع Claude Code، لإنشاء سيناريو تحرير أولي how to use roughcut roughcut alternative roughcut setup guide what is roughcut roughcut vs Final Cut Pro roughcut install roughcut YAML output roughcut video editing roughcut Claude Code roughcut 编辑视频 Claude Code YAML rough cut Final Cut Pro XML 视频编辑技术 AI 编辑视频 roughcut 技术 视频编辑软件 Analyzes transcripts to make editorial decisions Outputs a structured YAML rough cut Exports to Final Cut Pro XML format Handles full-length rough cuts and short sequences Launches a specialized agent for editorial processing Supports both multiple minutes and 30-60 second video sequences roughcut is a specialized AI agent skill that creates rough cut timeline scripts from transcribed video footage, outputting a structured YAML rough cut.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('macro-inc/macro/qc', 'community', 'macro-inc', 'macro', 'macro-inc/macro', 'qc', 0, 0, 39, '2026-03-08T01:57:15.293Z', '2026-03-08T02:01:06.589Z', '422324a264f6f1a5578591e4174a9594747a6d20b2e532b6f88b4f9d250c888e', '{"id":"macro-inc/macro/qc","name":"qc","description":{"en":"qc is a unified system for managing email, messaging, tasks, documents, and files. It benefits developers and teams by providing a centralized platform for collaboration and contribution.","zh":"QC 是一个集成的系统，用于管理代码审查、任务和文档。它提供了代码审查、任务管理和文档存储等功能。","ja":"QC はコードレビュー、タスク、ドキュメントを管理する統合システムです。コードレビュー、タスク管理、ドキュメントストレージなどの機能を提供します。","ko":"QC는 코드 리뷰, 작업, 문서를 관리하는 통합 시스템입니다. 코드 리뷰, 작업 관리, 문서 저장소 등의 기능을 제공합니다.","es":"QC es un sistema que integra correo electrónico, mensajería, tareas y documentos en una sola plataforma. Aprende a configurarlo para mejorar tu productividad.","fr":"QC est un système qui intègre l''e-mail, la messagerie, les tâches et les documents en une seule plateforme. Découvrez comment le configurer pour améliorer votre productivité.","de":"QC ist ein System, das E-Mail, Messaging, Aufgaben und Dokumente in einer einzigen Plattform integriert. Erfahren Sie, wie Sie es konfigurieren, um Ihre Produktivität zu steigern.","pt":"O QC é uma ferramenta de revisão de código que ajuda a melhorar a qualidade do código. Ele verifica se o código segue as melhores práticas de desenvolvimento.","ru":"QC — это инструмент код-ревью, который помогает улучшить качество кода. Он проверяет, соответствует ли код лучшим практикам разработки.","ar":"QC هو أداة مراجعة الكود التي تساعد على تحسين جودة الكود. إنه يتحقق من是否 يتبع الكود أفضل الممارسات للتطوير."},"seo":{"title":{"en":"qc: Setup Guide for AI Agents | AI Agent Skill","zh":"QC Setup 指南：代码审查和任务管理","ja":"QC セットアップ ガイド：コード レビューとタスク管理","ko":"QC 설정 가이드: 코드 리뷰와 작업 관리","es":"Guía de Configuración de 